import {
  Chip,
  Drawer,
  List,
  ListItemButton,
  ListItemText,
  ListSubheader,
} from "@mui/material";

import { Box } from "@mui/material";
import { jwtDecode } from "jwt-decode";

import { useState, useEffect } from "react";

import Collapse from "@mui/material/Collapse";

import ExpandLess from "@mui/icons-material/ExpandLess";
import ExpandMore from "@mui/icons-material/ExpandMore";
import DashboardIcon from "@mui/icons-material/Dashboard";
import SettingsIcon from "@mui/icons-material/Settings";
import PaymentsIcon from "@mui/icons-material/Payments";
import SchoolIcon from "@mui/icons-material/School";
import DirectionsCarIcon from "@mui/icons-material/DirectionsCar";
import FactCheckIcon from "@mui/icons-material/FactCheck";
import AssessmentIcon from "@mui/icons-material/Assessment";
import PeopleIcon from "@mui/icons-material/People";
import SchoolOutlinedIcon from "@mui/icons-material/SchoolOutlined";
import DirectionsCarFilledIcon from "@mui/icons-material/DirectionsCarFilled";
import LocalOfferIcon from "@mui/icons-material/LocalOffer";
import MenuBookIcon from "@mui/icons-material/MenuBook";
import QuizIcon from "@mui/icons-material/Quiz";
import ArticleIcon from "@mui/icons-material/Article";
import ReceiptLongIcon from "@mui/icons-material/ReceiptLong";
import EventNoteIcon from "@mui/icons-material/EventNote";
import GroupIcon from "@mui/icons-material/Group";
import AssignmentIcon from "@mui/icons-material/Assignment";
import CommuteIcon from "@mui/icons-material/Commute";
import EditDocumentIcon from "@mui/icons-material/EditDocument";

import TrendingUpIcon from "@mui/icons-material/TrendingUp";
import OndemandVideoIcon from "@mui/icons-material/OndemandVideo";
import MenuBookOutlinedIcon from "@mui/icons-material/MenuBookOutlined";
import TaskAltIcon from "@mui/icons-material/TaskAlt";
import TrafficIcon from "@mui/icons-material/Traffic";
import CalendarMonthIcon from "@mui/icons-material/CalendarMonth";
import AssignmentOutlinedIcon from "@mui/icons-material/AssignmentOutlined";
import DriveEtaIcon from "@mui/icons-material/DriveEta";
import ShoppingCartIcon from "@mui/icons-material/ShoppingCart";
import CreditCardIcon from "@mui/icons-material/CreditCard";
import ReceiptIcon from "@mui/icons-material/Receipt";
import DescriptionIcon from "@mui/icons-material/Description";
import NewReleasesIcon from "@mui/icons-material/NewReleases";

import { matriculasService } from "../../services/matriculasService";
import { notificacionesService } from "../../services/notificacionesService";
import { dashboardService } from "../../services/dashboardService";

const drawerWidth = 300;

const normalizeRole = (role) => {
  if (role === "GESTOR") {
    return "SOPORTE";
  }

  return role;
};

const menus = {
  ADMIN: [
    {
      label: "Dashboard",
      icon: <DashboardIcon />,
      path: "/dashboard",
    },
    {
      label: "Notificaciones",
      icon: <NewReleasesIcon />,
      path: "/notificaciones",
    },

    {
      label: "Gestión",
      icon: <SettingsIcon />,
      children: [
        {
          label: "Alumnos",
          path: "/alumnos",
          icon: <PeopleIcon fontSize="small" />,
        },
        {
          label: "Profesores",
          path: "/profesores",
          icon: <SchoolOutlinedIcon fontSize="small" />,
        },
        {
          label: "Vehículos",
          path: "/vehiculos",
          icon: <DirectionsCarFilledIcon fontSize="small" />,
        },
        {
          label: "Documentación",
          path: "/documentos-alumno-admin",
          icon: <DescriptionIcon fontSize="small" />,
        },
        {
          label: "Convocatorias",
          path: "/convocatorias-examen",
          icon: <CalendarMonthIcon fontSize="small" />,
        },

        {
          label: "Otros Usuarios",
          path: "/otros-usuarios",
          icon: <GroupIcon fontSize="small" />,
        },
      ],
    },

    {
      label: "Precios",
      icon: <PaymentsIcon />,
      children: [
        {
          label: "Tarifas matricula",
          path: "/tarifas-matricula",
          icon: <LocalOfferIcon fontSize="small" />,
        },
        {
          label: "Tarifas por permisos",
          path: "/tarifas-concepto",
          icon: <LocalOfferIcon fontSize="small" />,
        },
        {
          label: "Bonos",
          path: "/bonos",
          icon: <LocalOfferIcon fontSize="small" />,
        },
        {
          label: "Promociones",
          path: "/promociones",
          icon: <LocalOfferIcon fontSize="small" />,
        },
      ],
    },

    {
      label: "Teórica",
      icon: <SchoolIcon />,
      children: [
        {
          label: "Temarios",
          path: "/temarios",
          icon: <MenuBookIcon fontSize="small" />,
        },
        // {
        //   label: "Clases En Directo",
        //   path: "/admin-clases-directo",
        //   icon: <SchoolIcon fontSize="small" />,
        // },
        // {
        //   label: "Test por tema",
        //   path: "/test-por-tema",
        //   icon: <QuizIcon fontSize="small" />,
        // },
        {
          label: "Preguntas Test DGT",
          path: "/test-dgt",
          icon: <QuizIcon fontSize="small" />,
        },
      ],
    },

    {
      label: "Práctica",
      icon: <DirectionsCarIcon />,
      children: [
        {
          label: "Hojas de Ruta",
          path: "/hojas-ruta",
          icon: <AssignmentIcon fontSize="small" />,
        },
        {
          label: "Agendas",
          path: "/agendas",
          icon: <EventNoteIcon fontSize="small" />,
        },
      ],
    },

    {
      label: "Evaluación",
      icon: <FactCheckIcon />,
      children: [
        {
          label: "Exámenes",
          path: "/examenes",
          icon: <QuizIcon fontSize="small" />,
        },
      ],
    },

    {
      label: "Contabilidad",
      icon: <AssessmentIcon />,
      children: [
        {
          label: "Ingresos y facturas",
          path: "/facturas",
          icon: <ReceiptLongIcon fontSize="small" />,
        },
        {
          label: "Gastos",
          path: "/gastos",
          icon: <ReceiptIcon fontSize="small" />,
        },
        {
          label: "Nominas",
          path: "/nominas",
          icon: <ArticleIcon fontSize="small" />,
        },
        {
          label: "Informes",
          path: "/informes",
          icon: <AssessmentIcon fontSize="small" />,
        },
      ],
    },
  ],

  ADMINISTRATIVO: [
    {
      label: "Dashboard",
      icon: <DashboardIcon />,
      path: "/dashboard",
    },
    {
      label: "Notificaciones",
      icon: <NewReleasesIcon />,
      path: "/notificaciones",
    },
    {
      label: "Gestión",
      icon: <SettingsIcon />,
      children: [
        {
          label: "Alumnos",
          path: "/alumnos",
          icon: <PeopleIcon fontSize="small" />,
        },
        {
          label: "Profesores",
          path: "/profesores",
          icon: <SchoolOutlinedIcon fontSize="small" />,
        },
        {
          label: "Vehículos",
          path: "/vehiculos",
          icon: <DirectionsCarFilledIcon fontSize="small" />,
        },
        {
          label: "Documentación",
          path: "/documentos-alumno-admin",
          icon: <DescriptionIcon fontSize="small" />,
        },
        {
          label: "Convocatorias",
          path: "/convocatorias-examen",
          icon: <CalendarMonthIcon fontSize="small" />,
        },
      ],
    },
    {
      label: "Precios",
      icon: <PaymentsIcon />,
      children: [
        {
          label: "Tarifas matricula",
          path: "/tarifas-matricula",
          icon: <LocalOfferIcon fontSize="small" />,
        },
        {
          label: "Tarifas por permisos",
          path: "/tarifas-concepto",
          icon: <LocalOfferIcon fontSize="small" />,
        },
        {
          label: "Bonos",
          path: "/bonos",
          icon: <LocalOfferIcon fontSize="small" />,
        },
        {
          label: "Promociones",
          path: "/promociones",
          icon: <LocalOfferIcon fontSize="small" />,
        },
      ],
    },
    {
      label: "Teórica",
      icon: <SchoolIcon />,
      children: [
        {
          label: "Temarios",
          path: "/temarios",
          icon: <MenuBookIcon fontSize="small" />,
        },
        {
          label: "Preguntas Test DGT",
          path: "/test-dgt",
          icon: <QuizIcon fontSize="small" />,
        },
      ],
    },
    {
      label: "Práctica",
      icon: <DirectionsCarIcon />,
      children: [
        {
          label: "Hojas de Ruta",
          path: "/hojas-ruta",
          icon: <AssignmentIcon fontSize="small" />,
        },
        {
          label: "Agendas",
          path: "/agendas",
          icon: <EventNoteIcon fontSize="small" />,
        },
      ],
    },
    {
      label: "Evaluación",
      icon: <FactCheckIcon />,
      children: [
        {
          label: "Exámenes",
          path: "/examenes",
          icon: <QuizIcon fontSize="small" />,
        },
      ],
    },
    {
      label: "Contabilidad",
      icon: <AssessmentIcon />,
      children: [
        {
          label: "Ingresos y facturas",
          path: "/facturas",
          icon: <ReceiptLongIcon fontSize="small" />,
        },
        {
          label: "Nominas",
          path: "/nominas",
          icon: <ArticleIcon fontSize="small" />,
        },
      ],
    },
  ],

  SOPORTE: [
    {
      label: "Dashboard",
      icon: <DashboardIcon />,
      path: "/dashboard",
    },
    {
      label: "Notificaciones",
      icon: <NewReleasesIcon />,
      path: "/notificaciones",
    },
    {
      label: "Gestión de Usuarios",
      icon: <GroupIcon />,
      path: "/otros-usuarios",
    },
  ],

  PROFESOR: [
    {
      label: "Dashboard",
      icon: <DashboardIcon />,
      path: "/dashboard",
    },

    {
      label: "Notificaciones",
      icon: <NewReleasesIcon />,
      path: "/notificaciones",
    },

    {
      label: "Agenda",
      icon: <EventNoteIcon />,
      path: "/agenda",
    },

    {
      label: "Alumnos",
      icon: <GroupIcon />,
      path: "/profesor-alumnos",
    },

    {
      label: "Clases prácticas",
      icon: <DirectionsCarFilledIcon />,
      path: "/clases-practicas",
    },

    {
      label: "Hoja de Ruta",
      icon: <AssignmentIcon />,
      path: "/hojas-ruta",
    },

    {
      label: "Vehículos",
      icon: <CommuteIcon />,
      path: "/profesor-vehiculos",
    },
    {
      label: "Gastos",
      icon: <ReceiptIcon />,
      path: "/gastos",
    },
    {
      label: "Nominas",
      icon: <ArticleIcon />,
      path: "/nominas",
    },
  ],

  ALUMNO: [
    {
      label: "Mi progreso",
      icon: <TrendingUpIcon />,
      path: "/dashboard",
    },
    {
      label: "Mis documentos",
      icon: <DescriptionIcon />,
      path: "/mis-documentos",
    },
    {
      label: "Notificaciones",
      icon: <NewReleasesIcon />,
      path: "/notificaciones",
    },

    {
      label: "Clases teóricas",
      icon: <SchoolIcon />,
      children: [
        // {
        //   label: "Clases En Directo",
        //   path: "/clases-directo",
        //   icon: <OndemandVideoIcon fontSize="small" />,
        // },
        {
          label: "Material de apoyo",
          path: "/temario",
          icon: <MenuBookOutlinedIcon fontSize="small" />,
        },
        // {
        //   label: "Test Teóricos",
        //   path: "/test-teoricos",
        //   icon: <TaskAltIcon fontSize="small" />,
        // },
        {
          label: "Test DGT",
          path: "/test-dgt",
          icon: <TrafficIcon fontSize="small" />,
        },
      ],
    },

    {
      label: "Clases prácticas",
      icon: <DirectionsCarIcon />,
      children: [
        {
          label: "Solicitud Clase",
          path: "/reservar-clase",
          icon: <CalendarMonthIcon fontSize="small" />,
        },
        {
          label: "Hoja Ruta",
          path: "/hojas-ruta",
          icon: <AssignmentOutlinedIcon fontSize="small" />,
        },
      ],
    },

    {
      label: "Convocatorias",
      icon: <FactCheckIcon />,
      children: [
        {
          label: "Examen Teórico",
          path: "/examen-teorico",
          icon: <SchoolOutlinedIcon fontSize="small" />,
        },
        {
          label: "Examen Práctico",
          path: "/examen-practico",
          icon: <DriveEtaIcon fontSize="small" />,
        },
      ],
    },

    {
      label: "Compras",
      icon: <ShoppingCartIcon />,
      children: [
        {
          label: "Bonos",
          path: "/bonos",
          icon: <LocalOfferIcon fontSize="small" />,
        },
        // {
        //   label: "Promociones",
        //   path: "/promociones",
        //   icon: <LocalOfferIcon fontSize="small" />,
        // },
        {
          label: "Mis Facturas",
          path: "/mis-facturas",
          icon: <ReceiptLongIcon fontSize="small" />,
        },
      ],
    },
  ],
};

export default function Sidebar({ navigate, location }) {
  const token = localStorage.getItem("token");
  const [openMenus, setOpenMenus] = useState(() => {
    const saved = localStorage.getItem("sidebarAdminState");

    if (saved) {
      return JSON.parse(saved);
    }

    return {};
  });

  const [matriculaPagada, setMatriculaPagada] = useState(true);
  const [licenciaObtenida, setLicenciaObtenida] = useState(false);
  const [teoricoAptoHistorico, setTeoricoAptoHistorico] = useState(false);
  const [unreadNotifications, setUnreadNotifications] = useState(0);

  const loadUnreadNotifications = async () => {
    try {
      const unread = await notificacionesService.getMine(true);
      setUnreadNotifications(Array.isArray(unread) ? unread.length : 0);
    } catch (error) {
      setUnreadNotifications(0);
    }
  };

  const toggleMenu = (label) => {
    setOpenMenus((prev) => ({
      ...prev,
      [label]: !prev[label],
    }));
  };
  useEffect(() => {
    localStorage.setItem("sidebarAdminState", JSON.stringify(openMenus));
  }, [openMenus]);

  let role = "ALUMNO";

  if (token) {
    try {
      const user = jwtDecode(token);

      role = normalizeRole(user.rol);
    } catch (error) {
      console.error("Error leyendo JWT:", error);
    }
  }

  useEffect(() => {
    const loadStudentState = async () => {
      if (role !== "ALUMNO") {
        return;
      }

      try {
        const [matricula, dashboard] = await Promise.all([
          matriculasService.getMine(),
          dashboardService.getStudentDashboard(),
        ]);

        setMatriculaPagada(matricula?.estado === "PAGADA");
        setLicenciaObtenida(
          String(dashboard?.estadoAlumno?.codigo || "").toUpperCase() ===
            "LICENCIA_OBTENIDA",
        );

        const hasTheoreticalApto = Array.isArray(dashboard?.examenes?.teoricos)
          ? dashboard.examenes.teoricos.some((item) =>
              ["APTO", "APROBADO"].includes(
                String(item?.estado || "").toUpperCase(),
              ),
            )
          : false;

        setTeoricoAptoHistorico(hasTheoreticalApto);
      } catch (error) {
        console.error(error);
        setLicenciaObtenida(false);
        setTeoricoAptoHistorico(false);
      }
    };

    loadStudentState();
  }, [role]);

  useEffect(() => {
    loadUnreadNotifications();
  }, [location.pathname]);

  useEffect(() => {
    const onNotificationsUpdated = () => {
      loadUnreadNotifications();
    };

    window.addEventListener("notificaciones:updated", onNotificationsUpdated);

    return () => {
      window.removeEventListener(
        "notificaciones:updated",
        onNotificationsUpdated,
      );
    };
  }, []);

  useEffect(() => {
    const stream = notificacionesService.createStream();

    if (!stream) {
      return undefined;
    }

    const onRealtime = () => {
      loadUnreadNotifications();
    };

    stream.addEventListener("notification:created", onRealtime);
    stream.addEventListener("notification:updated", onRealtime);
    stream.addEventListener("notification:bulk-updated", onRealtime);

    return () => {
      stream.close();
    };
  }, []);

  let menu = menus[role];

  if (role === "ALUMNO" && licenciaObtenida) {
    menu = [
      {
        label: "Mi progreso",
        icon: <TrendingUpIcon />,
        path: "/dashboard",
      },
      {
        label: "Mis documentos",
        icon: <DescriptionIcon />,
        path: "/mis-documentos",
      },
      {
        label: "Notificaciones",
        icon: <NewReleasesIcon />,
        path: "/notificaciones",
      },
      {
        label: "Facturas",
        icon: <ReceiptLongIcon />,
        path: "/mis-facturas",
      },
      {
        label: "Nueva licencia",
        icon: <DriveEtaIcon />,
        path: "/nueva-licencia",
      },
    ];
  }

  if (role === "ALUMNO" && !licenciaObtenida && !matriculaPagada) {
    menu = [
      {
        label: "Mi progreso",
        icon: <TrendingUpIcon />,
        path: "/dashboard",
      },
      {
        label: "Notificaciones",
        icon: <EventNoteIcon />,
        path: "/notificaciones",
      },

      {
        label: "Clases teóricas",
        icon: <SchoolIcon />,
        children: [
          // {
          //   label: "Clases En Directo",
          //   path: "/clases-directo",
          //   icon: <OndemandVideoIcon fontSize="small" />,
          // },
          {
            label: "Material de apoyo",
            path: "/temario",
            icon: <MenuBookOutlinedIcon fontSize="small" />,
          },
          // {
          //   label: "Test Teóricos",
          //   path: "/test-teoricos",
          //   icon: <TaskAltIcon fontSize="small" />,
          // },
          {
            label: "Test DGT",
            path: "/test-dgt",
            icon: <TrafficIcon fontSize="small" />,
          },
        ],
      },

      {
        label: "Pago matrícula",
        icon: <CreditCardIcon />,
        path: "/pago-matricula",
      },
    ];
  }

  if (role === "ALUMNO" && matriculaPagada && !teoricoAptoHistorico) {
    menu = (menu || []).filter((item) => item.label !== "Clases prácticas");
  }

  const renderPrimaryLabel = (label) => {
    const isNotificationsLabel = label === "Notificaciones";

    if (!isNotificationsLabel) {
      return label;
    }

    return (
      <Box
        sx={{
          width: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          gap: 1,
        }}
      >
        <span>{label}</span>
        {unreadNotifications > 0 ? (
          <Chip
            label={unreadNotifications}
            size="small"
            sx={{
              height: 20,
              minWidth: 24,
              backgroundColor: "#dc2626",
              color: "#fff",
              fontWeight: 700,
            }}
          />
        ) : null}
      </Box>
    );
  };

  const renderChildPrimaryLabel = (child) => {
    const isNotificationsChild = child.path === "/notificaciones";

    if (!isNotificationsChild) {
      return child.label;
    }

    return (
      <Box
        sx={{
          width: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          gap: 1,
        }}
      >
        <span>{child.label}</span>
        {unreadNotifications > 0 ? (
          <Chip
            label={unreadNotifications}
            size="small"
            sx={{
              height: 20,
              minWidth: 24,
              backgroundColor: "#dc2626",
              color: "#fff",
              fontWeight: 700,
            }}
          />
        ) : null}
      </Box>
    );
  };
  if (!menu) {
    return null;
  }
  return (
    <Drawer
      variant="permanent"
      sx={{
        width: drawerWidth,
        flexShrink: 0,

        "& .MuiDrawer-paper": {
          width: drawerWidth,
          boxSizing: "border-box",
          marginTop: "64px",
          borderRight: "1px solid #e5e7eb",
          backgroundColor: "#ffffff",
        },

        "& .MuiListItemButton-root": {
          borderRadius: "8px",
          margin: "2px 8px",
        },

        "& .MuiListItemButton-root:hover": {
          backgroundColor: "#f3f4f6",
        },

        "& .MuiListSubheader-root": {
          fontWeight: 700,
          fontSize: "0.75rem",
          color: "#64748b",
          backgroundColor: "#fff",
          lineHeight: "24px",
          paddingTop: "8px",
        },

        "& .Mui-selected": {
          backgroundColor: "#dbeafe !important",
          borderRight: "4px solid #2563eb",
        },

        "& .Mui-selected .MuiListItemText-primary": {
          fontWeight: 600,
          color: "#1d4ed8",
        },
      }}
    >
      <List>
        {role === "ADMIN" || role === "ADMINISTRATIVO"
          ? menu.map((item) => (
              <Box key={item.label}>
                {item.children ? (
                  <>
                    <ListItemButton onClick={() => toggleMenu(item.label)}>
                      {item.icon}

                      <ListItemText
                        primary={item.label}
                        sx={{
                          ml: 2,
                          "& .MuiListItemText-primary": {
                            fontSize: "0.95rem",
                            fontWeight: 500,
                          },
                        }}
                      />

                      {openMenus[item.label] ? <ExpandLess /> : <ExpandMore />}
                    </ListItemButton>

                    <Collapse
                      in={openMenus[item.label]}
                      timeout="auto"
                      unmountOnExit
                    >
                      <List component="div" disablePadding>
                        {item.children?.map((child) => (
                          <ListItemButton
                            key={child.path}
                            sx={{
                              pl: 5,
                              color: child.disabled ? "#374151" : "inherit",
                              cursor: child.disabled
                                ? "not-allowed"
                                : "pointer",
                              "& .MuiListItemText-primary": {
                                color: child.disabled ? "#374151" : "inherit",
                              },
                              "&:hover": {
                                backgroundColor: child.disabled
                                  ? "transparent"
                                  : undefined,
                              },
                            }}
                            selected={
                              !child.disabled &&
                              location.pathname === child.path
                            }
                            onClick={() => {
                              if (!child.disabled) navigate(child.path);
                            }}
                          >
                            <>
                              {child.icon}

                              <ListItemText
                                primary={renderChildPrimaryLabel(child)}
                                sx={{ ml: 1 }}
                              />
                            </>
                          </ListItemButton>
                        ))}
                      </List>
                    </Collapse>
                  </>
                ) : (
                  <ListItemButton
                    selected={location.pathname === item.path}
                    onClick={() => navigate(item.path)}
                  >
                    {item.icon}

                    <ListItemText
                      primary={renderPrimaryLabel(item.label)}
                      sx={{ ml: 2 }}
                    />
                  </ListItemButton>
                )}
              </Box>
            ))
          : role === "PROFESOR"
            ? menu.map((item) => (
                <ListItemButton
                  sx={{
                    borderRadius: 2,
                    mx: 1,
                  }}
                  key={item.path}
                  selected={location.pathname === item.path}
                  onClick={() => navigate(item.path)}
                >
                  {item.icon}

                  <ListItemText
                    primary={renderPrimaryLabel(item.label)}
                    sx={{
                      ml: 2,
                      "& .MuiListItemText-primary": {
                        fontSize: "0.95rem",
                        fontWeight: 500,
                      },
                    }}
                  />
                </ListItemButton>
              ))
            : menu.map((item) => (
