    open: false,
    action: null,
    alumnoId: null,
    alumnoNombre: "",
    title: "",
    message: "",
  });

  const closeConfirmDialog = () => {
    setConfirmDialog({
      open: false,
      action: null,
      alumnoId: null,
      alumnoNombre: "",
      title: "",
      message: "",
    });
  };

  const handleConfirmAction = async () => {
    if (!confirmDialog.alumnoId || !confirmDialog.action) {
      closeConfirmDialog();
      return;
    }

    try {
      if (confirmDialog.action === "deactivate") {
        await alumnosService.deactivate(confirmDialog.alumnoId);
      }

      if (confirmDialog.action === "activate") {
        await alumnosService.activate(confirmDialog.alumnoId);
      }

      loadAlumnos();

      setNotification({
        open: true,
        message:
          confirmDialog.action === "deactivate"
            ? "Alumno desactivado correctamente"
            : "Alumno activado correctamente",
        severity: "success",
      });
    } catch (error) {
      console.error(error);

      setNotification({
        open: true,
        message:
          confirmDialog.action === "deactivate"
            ? "Error desactivando alumno"
            : "Error activando alumno",
        severity: "error",
      });
    } finally {
      closeConfirmDialog();
    }
  };

  const columns = [
    {
      field: "nombre",
      headerName: "Nombre",
      flex: 1,

      valueGetter: (_, row) => row.usuario?.nombre || "",
    },

    {
      field: "email",
      headerName: "Email",
      flex: 1.5,

      valueGetter: (_, row) => row.usuario?.email || "",
    },

    {
      field: "tipoLicenciaObjetivo",
      headerName: "Licencia",
      flex: 1,
      renderCell: (params) => (
        <LicenseChip value={params.row.tipoLicenciaObjetivo} />
      ),
    },

    {
      field: "faseActual",
      headerName: "Estado Expediente",
      flex: 1.2,
      renderCell: (params) => (
        <ExpedientePhaseChip
          code={params.row.faseActualCodigo}
          label={params.row.faseActual}
        />
      ),
    },

    {
      field: "horasPracticasCompletadas",
      headerName: "Horas Prácticas",
      flex: 1,
      valueGetter: (_, row) =>
        row.horasPracticasCompletadasTexto ||
        `${Number(row.horasPracticasCompletadas || 0).toFixed(2)} h`,
    },

    {
      field: "profesorAsignado",
      headerName: "Profesor",
      flex: 1,
      renderCell: (params) => {
        const matriculaPagada = obtenerEstadoMatricula(params.row) === "PAGADA";
        const sinProfesor = !params.row.profesorAsignado?.usuario?.nombre;
        const pendienteAsignar = matriculaPagada && sinProfesor;

        return (
          <Box
            sx={{
              width: "100%",
              height: "100%",
              display: "flex",
              alignItems: "center",
              px: 1,
              backgroundColor: pendienteAsignar ? "#fff8d6" : "transparent",
              borderRadius: 1,
            }}
          >
            <Typography
              variant="body2"
              sx={{ fontWeight: pendienteAsignar ? 700 : 400 }}
            >
              {params.row.profesorAsignado?.usuario?.nombre || "Sin asignar"}
            </Typography>
          </Box>
        );
      },
    },
    {
      field: "telefono",
      headerName: "Teléfono",
      flex: 1,

      valueGetter: (_, row) => row.usuario?.telefono || "",
    },
    {
      field: "activo",
      headerName: "Estado",
      width: 130,
      renderCell: (params) => (
        <Chip
          label={(params.row.activo ?? true) ? "Activo" : "Inactivo"}
          size="small"
          sx={{
            // 1. Estilos si está Activo
            ...((params.row.activo ?? true) && {
              backgroundColor: "#e8f5e9", // Fondo verde claro
              color: "#2e7d32", // Texto verde oscuro
              border: "1px solid #2e7d32", // Borde verde
            }),
            // 2. Estilos si está Inactivo
            ...(!(params.row.activo ?? true) && {
              backgroundColor: "#ffebee", // Fondo rojo claro
              color: "#c62828", // Texto rojo oscuro
              border: "1px solid #c62828", // Borde rojo
            }),
            fontWeight: "bold", // Estilo común para ambos estados (opcional)
          }}
        />
      ),
    },

    {
      field: "acciones",
      headerName: "Acciones",
      width: 120,

      renderCell: (params) => (
        <>
          <Tooltip title="Editar" arrow>
            <IconButton
              color="primary"
              onClick={(event) => {
                event.stopPropagation();
                handleEdit(params.row);
              }}
            >
              <EditIcon />
            </IconButton>
          </Tooltip>

          <Tooltip title={params.row.activo ? "Desactivar" : "Activar"} arrow>
            {params.row.activo ? (
              <IconButton
                color="warning"
                onClick={(event) => {
                  event.stopPropagation();
                  handleDeactivate(params.row);
                }}
              >
                <ToggleOffIcon />
              </IconButton>
            ) : (
              <IconButton
                color="success"
                onClick={(event) => {
                  event.stopPropagation();
                  handleActivate(params.row);
                }}
              >
                <ToggleOnIcon />
              </IconButton>
            )}
          </Tooltip>
        </>
      ),
    },
  ];

  const [open, setOpen] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [openDetail, setOpenDetail] = useState(false);
  const [loadingDetail, setLoadingDetail] = useState(false);
  const [selectedAlumno, setSelectedAlumno] = useState(null);
  const [extendedSummary, setExtendedSummary] = useState(null);
  const [showExtendedSummary, setShowExtendedSummary] = useState(false);
  const [promocionMatricula, setPromocionMatricula] = useState(null);
  const [resumenPromocionOculto, setResumenPromocionOculto] = useState(false);

  const [newAlumno, setNewAlumno] = useState({
    nombre: "",
    email: "",
    password: "",
    telefono: "",
    dni: "",
    fechaNacimiento: "",
    tipoLicencia: "B",
    profesorAsignadoId: "",
    esEstudiante: false,
    promocionId: "",
  });

  const [promocionesElegibles, setPromocionesElegibles] = useState([]);
  const [loadingPromociones, setLoadingPromociones] = useState(false);
  const [profesoresElegibles, setProfesoresElegibles] = useState([]);
  const [loadingProfesoresElegibles, setLoadingProfesoresElegibles] =
    useState(false);
  const [puedeAsignarProfesor, setPuedeAsignarProfesor] = useState(false);

  const [fieldTouched, setFieldTouched] = useState({
    dni: false,
    fechaNacimiento: false,
    telefono: false,
  });

  const [notification, setNotification] = useState({
    open: false,
    message: "",
    severity: "success",
  });

  const [exportAnchor, setExportAnchor] = useState(null);

  const dniIncompleto = fieldTouched.dni && !esDniCompleto(newAlumno.dni);
  const fechaIncompleta =
    fieldTouched.fechaNacimiento &&
    !esFechaCompletaValida(newAlumno.fechaNacimiento);
  const telefonoIncompleto =
    fieldTouched.telefono && !esTelefonoValido(newAlumno.telefono);

  const handleEdit = async (row) => {
    setEditingId(row.id);

    const matriculaActual = row?.matriculas?.[0] || null;
    const matriculaPagada = matriculaActual?.estado === "PAGADA";

    setNewAlumno({
      nombre: row.usuario?.nombre || "",
      email: row.usuario?.email || "",
      password: "",
      telefono: row.usuario?.telefono || "",
      dni: normalizarDniFormulario(row.usuario?.dni || ""),
      fechaNacimiento: formatearFechaParaFormulario(row.fechaNacimiento),
      tipoLicencia: row.tipoLicenciaObjetivo || "B",
      profesorAsignadoId: row.profesorAsignado?.id || "",
      esEstudiante: false,
      promocionId: "",
    });

    setPromocionesElegibles([]);
    setProfesoresElegibles([]);
    setPuedeAsignarProfesor(matriculaPagada);
    setResumenPromocionOculto(false);

    setFieldTouched({
      dni: false,
      fechaNacimiento: false,
      telefono: false,
    });

    setPromocionMatricula(row?.matriculas?.[0]?.promocion || null);

    setOpen(true);

    if (!matriculaPagada) {
      return;
    }

    setLoadingProfesoresElegibles(true);

    try {
      const elegibles = await alumnosService.getEligibleProfesores(row.id);
      setProfesoresElegibles(elegibles);
    } catch (error) {
      console.error(error);
      setProfesoresElegibles([]);
      setNotification({
        open: true,
        message:
          error.response?.data?.message ||
          "No se pudieron cargar los profesores elegibles",
        severity: "error",
      });
    } finally {
      setLoadingProfesoresElegibles(false);
    }
  };

  const openExportMenu = (event) => {
    setExportAnchor(event.currentTarget);
  };

  const closeExportMenu = () => {
    setExportAnchor(null);
  };

  const handleExportExcel = () => {
    exportAlumnosExcel(rows);

    closeExportMenu();
  };

  const handleExportPdf = () => {
    exportAlumnosPdf(rows);

    closeExportMenu();
  };

  const handleOpenDetail = async (row) => {
    setOpenDetail(true);
    setLoadingDetail(true);

    try {
      const detalle = await alumnosService.getById(row.id);

      setSelectedAlumno({
        ...detalle,
        horasPracticasCompletadas:
          row?.horasPracticasCompletadas ?? detalle?.horasPracticasCompletadas,
        horasPracticasCompletadasTexto:
          row?.horasPracticasCompletadasTexto ||
          detalle?.horasPracticasCompletadasTexto,
      });
      setPromocionMatricula(detalle?.matriculas?.[0]?.promocion || null);
      setExtendedSummary(null);
      setShowExtendedSummary(false);
    } catch (error) {
      console.error(error);

      setNotification({
        open: true,
        message: "No se pudo cargar el detalle del alumno",
        severity: "error",
      });
    } finally {
      setLoadingDetail(false);
    }
  };

  const cargarPromocionesElegibles = async () => {
    const licencia = newAlumno.tipoLicencia?.trim();
    const dni = limpiarDni(newAlumno.dni);
    const fechaNacimiento = newAlumno.fechaNacimiento?.trim();

    if (!licencia || !dni || !esFechaCompletaValida(fechaNacimiento)) {
      setPromocionesElegibles([]);
      return;
    }

    setLoadingPromociones(true);

    if (editingId && !puedeAsignarProfesor) {
      setResumenPromocionOculto(true);
      setPromocionMatricula(null);
    }

    try {
      const promociones = await alumnosService.getEligiblePromotions({
        tipoLicenciaObjetivo: licencia,
        dni,
        fechaNacimiento: formatearFechaParaApi(fechaNacimiento),
        esEstudiante: Boolean(newAlumno.esEstudiante),
      });

      setPromocionesElegibles(promociones);

      if (
        newAlumno.promocionId &&
        !promociones.some((promocion) => promocion.id === newAlumno.promocionId)
      ) {
        setNewAlumno((prev) => ({ ...prev, promocionId: "" }));
      }
    } catch (error) {
      console.error(error);
      setPromocionesElegibles([]);
      setNotification({
        open: true,
        message:
          error.response?.data?.message ||
          "No se pudieron evaluar las promociones elegibles",
        severity: "error",
      });
    } finally {
      setLoadingPromociones(false);
    }
  };

  const readOnlyFieldSx = {
    "& .MuiInputBase-input": {
      cursor: "default",
      caretColor: "transparent",
      userSelect: "none",
    },
    "& .MuiOutlinedInput-root": {
      backgroundColor: "action.hover",
    },
  };

  return (
    <Box>
      <Typography variant="h4" fontWeight="bold" mb={4}>
        Gestión de Alumnos
      </Typography>
      <Typography color="text.secondary" sx={{ mb: 2 }}>
        Administra los alumnos registrados en la Autoescuela Eguskilore y el
        progreso en los permisos de conducir de cada estudiante.
      </Typography>
      <Box
        sx={{
          display: "flex",
          alignItems: "center",
          gap: 4,
          mb: 3,
          flexWrap: "wrap",
        }}
      >
        <Button
          variant="contained"
          onClick={() => {
            setEditingId(null);
            setPromocionMatricula(null);
            setResumenPromocionOculto(false);

            setNewAlumno({
              nombre: "",
              email: "",
              password: "",
              telefono: "",
              dni: "",
              fechaNacimiento: "",
              tipoLicencia: "B",
              profesorAsignadoId: "",
              esEstudiante: false,
              promocionId: "",
            });

            setPromocionesElegibles([]);
            setProfesoresElegibles([]);
            setPuedeAsignarProfesor(false);

            setFieldTouched({
              dni: false,
              fechaNacimiento: false,
              telefono: false,
            });

            setOpen(true);
          }}
        >
          Nuevo Alumno
        </Button>

        <RadioGroup
          row
          value={estadoFiltro}
          onChange={(e) => setEstadoFiltro(e.target.value)}
        >
          <FormControlLabel
            value="activos"
            control={<Radio />}
            label="Activos"
          />

          <FormControlLabel
            value="inactivos"
            control={<Radio />}
            label="Inactivos"
          />

          <FormControlLabel value="todos" control={<Radio />} label="Todos" />
        </RadioGroup>

        <TextField
          select
          size="small"
          label="Buscar por profesor"
          value={profesorFiltro}
          onChange={(e) => setProfesorFiltro(e.target.value)}
          sx={{ width: 320 }}
        >
          <MenuItem value="">Todos los profesores</MenuItem>

          {profesores.map((profesor) => (
            <MenuItem key={profesor.id} value={profesor.id}>
              {profesor.usuario?.nombre}
            </MenuItem>
          ))}
        </TextField>

        <TextField
          select
          size="small"
          label="Estado expediente"
          value={faseExpedienteFiltro}
          onChange={(e) => setFaseExpedienteFiltro(e.target.value)}
          sx={{ width: 300 }}
        >
          <MenuItem value="">Todos los estados</MenuItem>
          {EXPEDIENTE_PHASE_OPTIONS.map((estado) => (
            <MenuItem key={estado.code} value={estado.code}>
              {estado.label}
            </MenuItem>
          ))}
        </TextField>

        <TextField
          size="small"
          label="Buscar alumno"
          placeholder="Nombre, email o teléfono"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          sx={{ width: 320 }}
          InputProps={{
            endAdornment: search && (
              <InputAdornment position="end">
                <IconButton size="small" onClick={() => setSearch("")}>
                  <CloseIcon fontSize="small" />
                </IconButton>
              </InputAdornment>
            ),
          }}
        />

        <Button
          variant="outlined"
          startIcon={<DownloadIcon />}
          onClick={openExportMenu}
        >
          Exportar
        </Button>

        <Menu
          anchorEl={exportAnchor}
          open={Boolean(exportAnchor)}
          onClose={closeExportMenu}
        >
          <MenuItem onClick={handleExportExcel}>Exportar a Excel</MenuItem>

          <MenuItem onClick={handleExportPdf}>Exportar a PDF</MenuItem>
        </Menu>
      </Box>

      <Paper
        sx={{
          height: 700,
          p: 2,
        }}
      >
        <DataGrid
          rows={rows}
          columns={columns}
          getRowId={(row) => row.id}
          disableRowSelectionOnClick
          pageSizeOptions={[10, 25, 50]}
          initialState={{
            pagination: { paginationModel: { pageSize: 10, page: 0 } },
            sorting: { sortModel: [{ field: "nombre", sort: "asc" }] },
          }}
          onRowClick={(params) => handleOpenDetail(params.row)}
          localeText={{
            noRowsLabel: profesorFiltro
              ? "No hay alumnos asignados al profesor seleccionado"
              : "No hay alumnos disponibles",
          }}
        />
      </Paper>

      <Dialog
        open={open}
        onClose={() => setOpen(false)}
        fullWidth
        maxWidth="md" // 🌟 Cambiado a 'md' para dar suficiente espacio a las dos columnas
      >
        <DialogTitle>
          {editingId ? "Editar Alumno" : "Crear Alumno"}
        </DialogTitle>

        <DialogContent>
          <Box
            sx={{
              display: "grid",
              gridTemplateColumns: { xs: "1fr", sm: "1fr 1fr" }, // 1 columna en móvil, 2 en pantallas 'sm' o superior
              gap: 3, // Espacio entre las dos columnas
              mt: 1,
            }}
          >
            {/* --- COLUMNA IZQUIERDA: FORMULARIO PRINCIPAL --- */}
            <Box sx={{ display: "flex", flexDirection: "column", gap: 1.5 }}>
              <TextField
                margin="none"
                fullWidth
                label="Nombre"
                required
                value={newAlumno.nombre}
                onChange={(e) =>
                  setNewAlumno({
                    ...newAlumno,
                    nombre: e.target.value,
                  })
                }
              />

              <TextField
                margin="none"
                fullWidth
                label="Email"
                required
                value={newAlumno.email}
                onChange={(e) =>
                  setNewAlumno({
                    ...newAlumno,
                    email: e.target.value,
                  })
                }
              />

              <TextField
                margin="none"
                fullWidth
                label="Contraseña"
                required={!editingId}
                type="password"
                helperText={
                  editingId
                    ? "Si la dejas vacía, se mantiene la contraseña actual."
                    : "Mínimo 8 caracteres"
                }
                value={newAlumno.password}
                onChange={(e) =>
                  setNewAlumno({
                    ...newAlumno,
                    password: e.target.value,
                  })
                }
              />

              <TextField
                margin="none"
                fullWidth
                label="Teléfono"
                required
                placeholder="600123123"
                value={newAlumno.telefono}
                onChange={(e) =>
                  setNewAlumno({
                    ...newAlumno,
                    telefono: normalizarTelefono(e.target.value),
                  })
                }
                onBlur={() =>
                  setFieldTouched((prev) => ({
                    ...prev,
                    telefono: true,
                  }))
                }
                error={telefonoIncompleto}
                helperText={
                  telefonoIncompleto
                    ? "Debe tener 9 dígitos numéricos"
                    : "Formato España: 9 dígitos"
                }
                inputProps={{
                  maxLength: 9,
                  inputMode: "numeric",
                  pattern: "[0-9]*",
                }}
              />

              <TextField
                margin="none"
                fullWidth
                label="DNI"
                required
                placeholder="12345678Z"
                value={newAlumno.dni}
                onChange={(e) =>
                  setNewAlumno({
                    ...newAlumno,
                    dni: normalizarDniFormulario(e.target.value),
                  })
                }
                onBlur={() =>
                  setFieldTouched((prev) => ({
                    ...prev,
                    dni: true,
                  }))
                }
                error={dniIncompleto}
                helperText={
                  dniIncompleto
                    ? "DNI incompleto. Introduce 8 números y 1 letra."
                    : undefined // Eliminado el espacio vacío " " para reducir la altura real
                }
                inputProps={{ maxLength: 9 }}
              />

              <TextField
                margin="none"
                fullWidth
                required
                type="text"
                label="Fecha de nacimiento"
                placeholder="dd/mm/aaaa"
                InputLabelProps={{ shrink: true }}
                value={newAlumno.fechaNacimiento}
                onChange={(e) => {
                  const masked = aplicarMascaraFecha(e.target.value);

                  if (!esFechaParcialValida(masked)) {
                    return;
                  }

                  setNewAlumno({
                    ...newAlumno,
                    fechaNacimiento: masked,
                  });
                }}
                onBlur={() =>
                  setFieldTouched((prev) => ({
                    ...prev,
                    fechaNacimiento: true,
                  }))
                }
                error={fechaIncompleta}
                helperText={
                  fechaIncompleta
                    ? "Fecha incompleta o inválida. Usa dd/mm/aaaa."
                    : undefined // Eliminado el espacio vacío " " para reducir la altura real
                }
                inputProps={{ maxLength: 10 }}
              />

              <TextField
                margin="none"
                fullWidth
                required
                select
                label="Licencia Objetivo"
                value={newAlumno.tipoLicencia}
                disabled={Boolean(editingId && puedeAsignarProfesor)}
                onChange={(e) =>
                  setNewAlumno({
                    ...newAlumno,
                    tipoLicencia: e.target.value,
                    promocionId: "",
                  })
                }
                helperText={
                  editingId && puedeAsignarProfesor
                    ? "No editable con matrícula pagada."
                    : ""
                }
              >
                {LICENCIAS_OPCIONES.map((licencia) => (
                  <MenuItem key={licencia.value} value={licencia.value}>
                    {licencia.label}
                  </MenuItem>
                ))}
              </TextField>

              {editingId && (
                <>
                  {!puedeAsignarProfesor && (
                    <Alert severity="info" sx={{ mt: 1 }}>
                      Solo se puede asignar profesor cuando la matrícula del
                      alumno está pagada.
                    </Alert>
                  )}

                  <TextField
                    margin="none"
                    fullWidth
                    select
                    label="Profesor Asignado"
                    value={newAlumno.profesorAsignadoId || ""}
                    disabled={
                      !puedeAsignarProfesor || loadingProfesoresElegibles
                    }
                    onChange={(e) =>
                      setNewAlumno((prev) => ({
                        ...prev,
                        profesorAsignadoId: e.target.value,
                      }))
                    }
                    helperText={
                      !puedeAsignarProfesor
                        ? "Matrícula pendiente de pago"
                        : "Solo se muestran profesores activos con permiso para esta licencia"
                    }
                  >
                    <MenuItem value="">Sin asignar</MenuItem>
                    {profesoresElegibles.map((profesor) => (
                      <MenuItem key={profesor.id} value={profesor.id}>
                        {profesor.usuario?.nombre}
                      </MenuItem>
                    ))}
                  </TextField>
                </>
              )}
            </Box>

            {/* --- COLUMNA DERECHA: SECCIÓN DE PROMOCIONES --- */}
            <Box>
              {!editingId ? (
                <Box sx={{ display: "flex", flexDirection: "column", gap: 2 }}>
                  <Typography
                    variant="subtitle2"
                    color="text.secondary"
                    sx={{ mb: -0.5 }}
                  >
                    Promociones y Descuentos
                  </Typography>

                  <FormControlLabel
                    control={
                      <Checkbox
                        checked={Boolean(newAlumno.esEstudiante)}
                        onChange={(event) =>
                          setNewAlumno((prev) => ({
                            ...prev,
                            esEstudiante: event.target.checked,
                            promocionId: "",
                          }))
                        }
                      />
                    }
                    label="Acredita carnet de estudiante"
                  />

                  <Button
                    variant="outlined"
                    onClick={cargarPromocionesElegibles}
                    disabled={loadingPromociones}
                    fullWidth
                  >
                    {loadingPromociones
                      ? "Comprobando promociones..."
                      : "Comprobar promociones vigentes"}
                  </Button>

                  {promocionesElegibles.length > 0 && (
                    <Box
                      sx={{
                        mt: 1,
                        p: 2,
                        borderRadius: 2,
                        border: "1px solid",
                        borderColor: "divider",
                        display: "grid",
                        gap: 1.5,
                        maxHeight: "300px", // Limita el alto del contenedor para que no estire el modal
                        overflowY: "auto", // Añade scroll interno si hay muchas tarjetas de descuento
                      }}
                    >
                      <Typography variant="caption" fontWeight="bold">
                        Promociones elegibles para este alta
                      </Typography>

                      {promocionesElegibles.map((promocion) => (
                        <Box
                          key={promocion.id}
                          sx={{
                            p: 1,
                            borderRadius: 1,
                            backgroundColor: "background.default",
                            border: "1px solid",
                            borderColor: "action.hover",
                          }}
                        >
                          <Typography variant="body2" fontWeight={700}>
                            {promocion.nombre}
                          </Typography>
                          <Typography
                            variant="caption"
                            color="text.secondary"
                            component="p"
                          >
                            {promocion.descripcion || "Sin descripción"}
                          </Typography>
                          <Typography variant="body2" sx={{ mt: 0.5 }}>
                            Precio promoción: {promocion.precioPromocional} EUR
                          </Typography>
                          <Typography
                            variant="caption"
                            color="text.secondary"
                            component="p"
                          >
                            Reglas:{" "}
                            {promocion.requiereCarnetEstudiante
                              ? "requiere carnet estudiante"
                              : "público general"}
                            {promocion.requiereFidelidad ? " + fidelidad" : ""}
                            {promocion.edadMinima !== null &&
                            promocion.edadMinima !== undefined
                              ? ` + edad mín. ${promocion.edadMinima}`
                              : ""}
                            {promocion.edadMaxima !== null &&
                            promocion.edadMaxima !== undefined
                              ? ` + edad máx. ${promocion.edadMaxima}`
                              : ""}
                          </Typography>
                        </Box>
                      ))}

                      <TextField
                        select
                        fullWidth
                        size="small"
                        label="Promoción a asignar"
                        value={newAlumno.promocionId}
                        onChange={(event) =>
                          setNewAlumno((prev) => ({
                            ...prev,
                            promocionId: event.target.value,
                          }))
                        }
                        helperText={
                          promocionesElegibles.length > 1
                            ? "Obligatorio seleccionar una promoción"
                            : "Si solo hay una promoción aplicable se asignará automáticamente"
                        }
                      >
                        {promocionesElegibles.length > 1 && (
                          <MenuItem value="">Seleccionar promoción...</MenuItem>
                        )}
                        {promocionesElegibles.map((promocion) => (
                          <MenuItem key={promocion.id} value={promocion.id}>
                            {promocion.nombre} - {promocion.precioPromocional}{" "}
                            EUR
                          </MenuItem>
                        ))}
                      </TextField>
                    </Box>
                  )}
                </Box>
              ) : (
                <Box
                  sx={{
                    p: 2,
                    borderRadius: 2,
                    border: "1px solid",
                    borderColor: "divider",
                    backgroundColor: "background.paper",
                  }}
                >
                  <Typography
                    variant="subtitle1"
                    fontWeight="bold"
                    sx={{ mb: 2 }}
                  >
                    Promoción asociada a la matrícula
                  </Typography>

                  {!puedeAsignarProfesor && (
                    <Box sx={{ display: "grid", gap: 1.5, mb: 2 }}>
                      <Alert severity="info">
                        La matrícula está pendiente. Si cambias la licencia,
                        puedes recalcular promociones antes de guardar.
                      </Alert>
                      <Button
                        variant="outlined"
                        onClick={cargarPromocionesElegibles}
                        disabled={loadingPromociones}
                      >
                        {loadingPromociones
                          ? "Comprobando promociones..."
                          : "Recalcular promociones para la licencia"}
                      </Button>

                      {promocionesElegibles.length > 0 ? (
                        <TextField
                          select
                          fullWidth
                          size="small"
                          label="Promoción a aplicar (opcional)"
                          value={newAlumno.promocionId || ""}
                          onChange={(event) =>
                            setNewAlumno((prev) => ({
                              ...prev,
                              promocionId: event.target.value,
                            }))
                          }
                          helperText="Si no eliges ninguna, se guardará la matrícula sin promoción"
                        >
                          <MenuItem value="">Sin promoción</MenuItem>
                          {promocionesElegibles.map((promocion) => (
                            <MenuItem key={promocion.id} value={promocion.id}>
                              {promocion.nombre} - {promocion.precioPromocional}{" "}
                              EUR
                            </MenuItem>
                          ))}
                        </TextField>
                      ) : (
                        <Typography variant="caption" color="text.secondary">
                          No hay promociones elegibles para la licencia
                          seleccionada.
                        </Typography>
                      )}
                    </Box>
                  )}

                  {resumenPromocionOculto ? (
                    <Alert severity="info">
                      La promoción anterior ha sido ocultada temporalmente.
                      Selecciona una nueva promoción (o deja sin promoción) y
                      pulsa Actualizar para guardar los cambios.
                    </Alert>
                  ) : promocionMatricula ? (
                    <>
                      <TextField
                        fullWidth
                        margin="dense"
                        label="Nombre de la promoción"
                        value={promocionMatricula.nombre || ""}
                        InputProps={{
                          readOnly: true,
                        }}
                      />

                      <TextField
                        fullWidth
                        margin="dense"
                        multiline
                        minRows={3}
                        label="Descripción"
                        value={promocionMatricula.descripcion || ""}
                        InputProps={{
                          readOnly: true,
                        }}
                      />

                      <Grid container spacing={2} sx={{ mt: 1 }}>
                        <Grid item xs={12} md={4}>
                          <Box
                            sx={{
                              p: 2,
                              borderRadius: 2,
                              bgcolor: "#f5f5f5",
                              textAlign: "center",
                              border: "1px solid #e0e0e0",
                            }}
                          >
                            <Typography
                              variant="caption"
                              color="text.secondary"
                              display="block"
                            >
                              Precio Base
                            </Typography>

                            <Typography variant="h6" fontWeight="bold">
                              {Number(
                                promocionMatricula.precioOriginal || 0,
                              ).toFixed(2)}{" "}
                              €
                            </Typography>
                          </Box>
                        </Grid>

                        <Grid item xs={12} md={4}>
                          <Box
                            sx={{
                              p: 2,
                              borderRadius: 2,
                              bgcolor: "#e8f5e9",
                              textAlign: "center",
                              border: "1px solid #81c784",
                            }}
                          >
                            <Typography
                              variant="caption"
                              color="text.secondary"
                              display="block"
                            >
                              Precio Final
                            </Typography>

                            <Typography
                              variant="h6"
                              fontWeight="bold"
                              color="success.main"
                            >
                              {Number(
                                promocionMatricula.precioPromocional || 0,
                              ).toFixed(2)}{" "}
                              €
                            </Typography>
                          </Box>
                        </Grid>

                        <Grid item xs={12} md={4}>
                          <Box
                            sx={{
                              p: 2,
                              borderRadius: 2,
                              bgcolor: "#fff8e1",
                              textAlign: "center",
                              border: "1px solid #ffcc80",
                            }}
                          >
                            <Typography
                              variant="caption"
                              color="text.secondary"
                              display="block"
                            >
                              Ahorro
                            </Typography>

                            <Typography
                              variant="h6"
                              fontWeight="bold"
                              color="warning.main"
                            >
                              {(
                                Number(promocionMatricula.precioOriginal || 0) -
                                Number(
                                  promocionMatricula.precioPromocional || 0,
                                )
                              ).toFixed(2)}{" "}
                              €
                            </Typography>
                          </Box>
                        </Grid>
                      </Grid>

                      <Chip
                        color="success"
                        sx={{
                          mt: 2,
                          fontWeight: "bold",
                        }}
                        label={`Descuento aplicado: ${(
                          Number(promocionMatricula.precioOriginal || 0) -
                          Number(promocionMatricula.precioPromocional || 0)
                        ).toFixed(2)} €`}
                      />

                      <Alert severity="success" sx={{ mt: 2 }}>
                        El alumno obtuvo un descuento de{" "}
                        <strong>
                          {(
                            Number(promocionMatricula.precioOriginal || 0) -
                            Number(promocionMatricula.precioPromocional || 0)
                          ).toFixed(2)}{" "}
                          €
                        </strong>{" "}
                        durante el alta de matrícula.
                      </Alert>
                    </>
                  ) : (
                    <Alert severity="info">
                      No existen promociones asignadas en el alta de matrícula
                      del alumno.
                    </Alert>
                  )}
                </Box>
              )}
            </Box>
          </Box>
        </DialogContent>

        <DialogActions>
          <Button
            onClick={() => {
              setOpen(false);
            }}
          >
            Cancelar
          </Button>

          <Button variant="contained" onClick={saveAlumno}>
            {editingId ? "Actualizar" : "Guardar"}
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog
        open={openDetail}
        onClose={() => setOpenDetail(false)}
        fullWidth
        maxWidth="md"
      >
        <DialogTitle>Detalle del Alumno</DialogTitle>

        <DialogContent>
          {loadingDetail ? (
            <Box
              sx={{
                display: "flex",
                justifyContent: "center",
                py: 4,
              }}
            >
              <CircularProgress />
            </Box>
          ) : (
            <Box
              sx={{
                perspective: "1400px",
                mt: 2,
                minHeight: 620,
                overflow: "hidden",
              }}
            >
              <Box
                sx={{
                  position: "relative",
                  minHeight: 620,
                  transition: "transform 700ms ease",
                  transformStyle: "preserve-3d",
                  transform: showExtendedSummary
                    ? "rotateY(180deg)"
                    : "rotateY(0deg)",
                }}
              >
                <Box
                  sx={{
                    position: "absolute",
                    inset: 0,
                    backfaceVisibility: "hidden",
                  }}
                >
                  <Box
                    sx={{
                      display: "grid",
                      gridTemplateColumns: {
                        xs: "1fr",
                        md: "1fr 1fr",
                      },
                      gap: 3,
                    }}
                  >
                    <Box
                      sx={{
                        display: "flex",
                        flexDirection: "column",
                        gap: 2,
                        mt: 1,
                      }}
                    >
                      <TextField
                        label="Nombre"
                        value={selectedAlumno?.usuario?.nombre || ""}
                        InputProps={{ readOnly: true }}
                        sx={readOnlyFieldSx}
                        fullWidth
                      />

                      <TextField
                        label="Email"
                        value={selectedAlumno?.usuario?.email || ""}
                        InputProps={{ readOnly: true }}
                        sx={readOnlyFieldSx}
                        fullWidth
                      />

                      <TextField
                        label="Teléfono"
                        value={selectedAlumno?.usuario?.telefono || ""}
                        InputProps={{ readOnly: true }}
                        sx={readOnlyFieldSx}
                        fullWidth
                      />

                      <TextField
                        label="DNI"
                        value={selectedAlumno?.usuario?.dni || ""}
                        InputProps={{ readOnly: true }}
                        sx={readOnlyFieldSx}
                        fullWidth
                      />

                      <TextField
                        label="Licencia Objetivo"
                        value={selectedAlumno?.tipoLicenciaObjetivo || ""}
                        InputProps={{ readOnly: true }}
                        sx={readOnlyFieldSx}
                        fullWidth
                      />

                      <TextField
                        label="Horas Prácticas"
                        value={
                          selectedAlumno?.horasPracticasCompletadasTexto ||
                          `${Number(selectedAlumno?.horasPracticasCompletadas || 0).toFixed(2)} h`
                        }
                        InputProps={{ readOnly: true }}
                        sx={readOnlyFieldSx}
                        fullWidth
                      />

                      <TextField
                        label="Profesor Asignado"
                        value={
                          selectedAlumno?.profesorAsignado?.usuario?.nombre ||
                          "Sin asignar"
                        }
                        InputProps={{ readOnly: true }}
                        sx={readOnlyFieldSx}
                        fullWidth
                      />

                      <TextField
                        label="Estado"
                        value={selectedAlumno?.activo ? "Activo" : "Inactivo"}
                        InputProps={{ readOnly: true }}
                        sx={readOnlyFieldSx}
                        fullWidth
                      />

                      <Chip
                        label="Resumen Académico y Pagos"
                        sx={{
                          width: "fit-content",
                          backgroundColor: "#fffbeb", // Fondo original
                          borderColor: "#facc15", // Borde original
                          borderStyle: "solid",
                          borderRadius: "15px",
                          borderWidth: "2px",
                          color: "#ca8a04", // Texto original
                          "& .MuiChip-label": {
                            fontWeight: "bold",
                          },
                          // 👇 ESTO ES LO QUE DEBES AÑADIR PARA EL HOVER
                          "&:hover": {
                            backgroundColor: "#fef08a", // Fondo al pasar el ratón (un amarillo un poco más oscuro)
                            borderColor: "#eab308", // Borde al pasar el ratón (opcional)
                            color: "#854d0e", // Texto al pasar el ratón (opcional)
                          },
                        }}
                        clickable
                        onClick={async () => {
                          if (!selectedAlumno?.id) {
                            return;
                          }

                          if (!extendedSummary) {
                            const resumen =
                              await alumnosService.getExtendedSummary(
                                selectedAlumno.id,
                              );
                            setExtendedSummary(resumen);
                          }

                          setShowExtendedSummary(true);
                        }}
                      />
                    </Box>

                    <Box>
                      <Typography
                        variant="subtitle1"
                        fontWeight="bold"
                        sx={{ mb: 2 }}
                      >
                        Promoción asociada a la matrícula
                      </Typography>
                      {promocionMatricula ? (
                        <>
                          <TextField
                            fullWidth
                            margin="dense"
                            label="Nombre de la promoción"
                            value={promocionMatricula.nombre || ""}
                            InputProps={{
                              readOnly: true,
                            }}
                            sx={readOnlyFieldSx}
                          />

                          <TextField
                            fullWidth
                            margin="dense"
                            multiline
                            minRows={3}
                            label="Descripción"
                            value={promocionMatricula.descripcion || ""}
                            InputProps={{
                              readOnly: true,
                            }}
                            sx={readOnlyFieldSx}
                          />

                          <Grid container spacing={2} sx={{ mt: 1 }}>
                            <Grid item xs={12} md={4}>
                              <Box
                                sx={{
                                  p: 2,
                                  borderRadius: 2,
                                  bgcolor: "#f5f5f5",
                                  textAlign: "center",
                                  border: "1px solid #e0e0e0",
                                }}
                              >
                                <Typography
                                  variant="caption"
                                  color="text.secondary"
                                  display="block"
                                >
                                  Precio Base
                                </Typography>

                                <Typography variant="h6" fontWeight="bold">
                                  {Number(
                                    promocionMatricula.precioOriginal || 0,
                                  ).toFixed(2)}{" "}
                                  €
                                </Typography>
                              </Box>
                            </Grid>

                            <Grid item xs={12} md={4}>
                              <Box
                                sx={{
                                  p: 2,
                                  borderRadius: 2,
                                  bgcolor: "#e8f5e9",
                                  textAlign: "center",
                                  border: "1px solid #81c784",
                                }}
                              >
                                <Typography
                                  variant="caption"
                                  color="text.secondary"
                                  display="block"
                                >
                                  Precio Final
                                </Typography>

                                <Typography
                                  variant="h6"
                                  fontWeight="bold"
                                  color="success.main"
                                >
                                  {Number(
                                    promocionMatricula.precioPromocional || 0,
                                  ).toFixed(2)}{" "}
                                  €
                                </Typography>
                              </Box>
                            </Grid>

                            <Grid item xs={12} md={4}>
                              <Box
                                sx={{
                                  p: 2,
                                  borderRadius: 2,
                                  bgcolor: "#fff8e1",
                                  textAlign: "center",
                                  border: "1px solid #ffcc80",
                                }}
                              >
                                <Typography
                                  variant="caption"
                                  color="text.secondary"
                                  display="block"
                                >
                                  Ahorro
                                </Typography>

                                <Typography
                                  variant="h6"
                                  fontWeight="bold"
                                  color="warning.main"
                                >
                                  {(
                                    Number(
                                      promocionMatricula.precioOriginal || 0,
                                    ) -
                                    Number(
                                      promocionMatricula.precioPromocional || 0,
                                    )
                                  ).toFixed(2)}{" "}
                                  €
                                </Typography>
                              </Box>
                            </Grid>
                          </Grid>

                          <Chip
                            color="success"
                            sx={{
                              mt: 2,
                              fontWeight: "bold",
                            }}
                            label={`Descuento aplicado: ${(
                              Number(promocionMatricula.precioOriginal || 0) -
                              Number(promocionMatricula.precioPromocional || 0)
                            ).toFixed(2)} €`}
                          />

                          <Alert severity="success" sx={{ mt: 2 }}>
                            El alumno obtuvo un descuento de{" "}
                            <strong>
                              {(
                                Number(promocionMatricula.precioOriginal || 0) -
                                Number(
                                  promocionMatricula.precioPromocional || 0,
                                )
                              ).toFixed(2)}{" "}
                              €
                            </strong>{" "}
                            durante el alta de matrícula.
                          </Alert>
                        </>
                      ) : (
                        <Alert severity="info">
                          No existen promociones asignadas en el alta de
                          matrícula del alumno.
                        </Alert>
                      )}
                    </Box>
                  </Box>
                </Box>

                <Box
                  sx={{
                    position: "absolute",
                    inset: 0,
                    backfaceVisibility: "hidden",
                    transform: "rotateY(180deg)",
                    borderRadius: 2,
                    p: 2,
                    border: "1px solid",
                    borderColor: "divider",
                    bgcolor: "background.paper",
                    overflowY: "auto",
                  }}
                >
                  <Box
                    sx={{
                      display: "flex",
                      justifyContent: "space-between",
                      alignItems: "center",
                      flexWrap: "wrap",
                      gap: 1,
                      mb: 1.5,
                    }}
                  >
                    <Typography variant="h6" fontWeight={800}>
                      Resumen académico y pagos
                    </Typography>
                    <Chip
                      label="Volver Detalle Alumno"
                      sx={{
                        width: "fit-content",
                        backgroundColor: "#fffbeb", // Fondo original
                        borderColor: "#facc15", // Borde original
                        borderStyle: "solid",
                        borderRadius: "15px",
                        borderWidth: "2px",
                        color: "#ca8a04", // Texto original
                        "& .MuiChip-label": {
                          fontWeight: "bold",
                        },
                        // 👇 ESTO ES LO QUE DEBES AÑADIR PARA EL HOVER
                        "&:hover": {
                          backgroundColor: "#fef08a", // Fondo al pasar el ratón (un amarillo un poco más oscuro)
                          borderColor: "#eab308", // Borde al pasar el ratón (opcional)
                          color: "#854d0e", // Texto al pasar el ratón (opcional)
                        },
                      }}
                      clickable
                      onClick={() => setShowExtendedSummary(false)}
                    />
                  </Box>

                  {extendedSummary ? (
                    <Box sx={{ display: "grid", gap: 2 }}>
                      <Box
                        sx={{
                          display: "flex",
                          flexWrap: "wrap",
                          justifyContent: "space-between",
                          alignItems: "center",
                          gap: 1,
                        }}
                      >
                        <Box
                          sx={{
                            display: "inline-flex",
                            alignItems: "center",
                            gap: 1,
                          }}
                        >
                          <Typography variant="subtitle1" fontWeight={800}>
                            {extendedSummary.nombreCompleto}
                          </Typography>
                          {isLicenseObtainedState(
                            extendedSummary.estadoAcademico,
                          ) && (
                            <Box
                              sx={{
                                display: "inline-flex",
                                alignItems: "center",
                                gap: 0.75,
                                px: 1,
                                py: 0.25,
                                borderRadius: 999,
                                bgcolor: "#fffbeb",
                                border: "1px solid #facc15",
                              }}
                            >
                              <EmojiEventsIcon
                                sx={{ color: "#ca8a04", fontSize: 16 }}
                              />
                              <Typography
                                variant="caption"
                                sx={{ color: "#854d0e", fontWeight: 800 }}
                              >
                                Medalla de oro
                              </Typography>
                              <Box
                                sx={{
                                  width: 20,
                                  height: 20,
                                  borderRadius: "50%",
                                  display: "grid",
                                  placeItems: "center",
                                  color: "#064e3b",
                                  bgcolor: "#d1fae5",
                                  border: "1px solid #34d399",
                                  fontWeight: 900,
                                }}
                              >
                                L
                              </Box>
                            </Box>
                          )}
                        </Box>
                        <ExpedientePhaseChip
                          code={extendedSummary.estadoAcademico?.codigo}
                          label={extendedSummary.estadoAcademico?.label}
                        />
                      </Box>

                      <Box
                        sx={{
                          p: 1.5,
                          borderRadius: 2,
                          bgcolor: "#f8fafc",
                          border: "1px solid #e2e8f0",
                        }}
                      >
                        <Typography
                          variant="subtitle2"
                          fontWeight={700}
                          sx={{ mb: 1 }}
                        >
                          Resumen académico
                        </Typography>

                        <Typography variant="body2">
                          Test de temario realizados:{" "}
                          {extendedSummary.testsTemario?.realizados ?? 0}
                        </Typography>
                        <Typography variant="body2">
                          Test aprobados:{" "}
                          {extendedSummary.testsTemario?.aprobados ?? 0} | Test
                          suspensos:{" "}
                          {extendedSummary.testsTemario?.suspendidos ?? 0} |
                          Porcentaje aprobados:{" "}
                          {extendedSummary.testsTemario?.porcentajeAprobados ??
                            0}
                          %
                        </Typography>

                        <Typography variant="body2" sx={{ mt: 1 }}>
                          Test DGT realizados:{" "}
                          {extendedSummary.testsDgt?.realizados ?? 0}
                        </Typography>
                        <Typography variant="body2">
                          Test DGT aprobados:{" "}
                          {extendedSummary.testsDgt?.aprobados ?? 0} | Test DGT
                          suspensos:{" "}
                          {extendedSummary.testsDgt?.suspendidos ?? 0} |
                          Porcentaje aprobados:{" "}
                          {extendedSummary.testsDgt?.porcentajeAprobados ?? 0}%
                        </Typography>

                        <Typography
                          variant="body2"
                          sx={{ mt: 1, fontWeight: 700 }}
                        >
                          Convocatorias examen teórico
                        </Typography>
                        {(extendedSummary.examenTeoricoHistorial || [])
                          .length ? (
                          (extendedSummary.examenTeoricoHistorial || []).map(
                            (item) => (
                              <Typography
                                variant="body2"
                                key={`teorico-${item.id}`}
                              >
                                {formatDateLabel(item.fecha)} | {item.estado} |
                                Fallos/Aciertos: {item.fallos ?? "-"} /{" "}
                                {item.aciertos ?? "-"}
                              </Typography>
                            ),
                          )
                        ) : (
                          <Typography variant="body2">No presentado</Typography>
                        )}

                        <Typography
                          variant="body2"
                          sx={{ mt: 1, fontWeight: 700 }}
                        >
                          Convocatorias examen práctico: Circulacion
                        </Typography>
                        {(
                          extendedSummary.examenPracticoCirculacionHistorial ||
                          []
                        )?.length ? (
                          (
                            extendedSummary.examenPracticoCirculacionHistorial ||
                            []
                          ).map((item) => (
                            <Typography
                              variant="body2"
                              key={`practico-${item.id}`}
                            >
                              {formatDateLabel(item.fecha)} | {item.estado} |
                              Faltas (L/D/E): {item.leves ?? "-"} /{" "}
                              {item.deficientes ?? "-"} /{" "}
                              {item.eliminatorias ?? "-"}
                            </Typography>
                          ))
                        ) : (
                          <Typography variant="body2">No presentado</Typography>
                        )}

                        {isDualPracticalLicense(
                          extendedSummary?.perfil?.licenciaObjetivo,
                        ) ? (
                          <>
                            <Typography
                              variant="body2"
                              sx={{ mt: 1, fontWeight: 700 }}
                            >
                              Convocatorias examen práctico: Pista (Circuito)
                            </Typography>
                            {(
                              extendedSummary.examenPracticoPistaHistorial || []
                            ).length ? (
                              (
                                extendedSummary.examenPracticoPistaHistorial ||
                                []
                              ).map((item) => (
                                <Typography
                                  variant="body2"
                                  key={`practico-pista-${item.id}`}
                                >
                                  {formatDateLabel(item.fecha)} | {item.estado}{" "}
                                  | Faltas (L/D/E): {item.leves ?? "-"} /{" "}
                                  {item.deficientes ?? "-"} /{" "}
                                  {item.eliminatorias ?? "-"}
                                </Typography>
                              ))
                            ) : (
                              <Typography variant="body2">
                                No presentado
                              </Typography>
                            )}
                          </>
                        ) : null}
                      </Box>

                      <Box
                        sx={{
                          p: 1.5,
                          borderRadius: 2,
                          bgcolor: "#fffaf0",
                          border: "1px solid #fde68a",
                        }}
                      >
                        <Typography
                          variant="subtitle2"
                          fontWeight={700}
                          sx={{ mb: 1 }}
                        >
                          Resumen pagos
                        </Typography>

                        <Typography variant="body2">
                          Matrícula:{" "}
                          {extendedSummary.pagos?.matriculaPagada
                            ? "Pagada"
                            : "No pagada"}
                        </Typography>
                        <Typography variant="body2">
                          Promoción matrícula:{" "}
                          {extendedSummary.pagos?.promocionMatricula?.tiene
                            ? extendedSummary.pagos?.promocionMatricula?.nombre
                            : "Sin promoción"}
                        </Typography>
                        <Typography variant="body2">
                          Psicotécnico:{" "}
                          {extendedSummary.documentacion?.psicotecnicoEntregado
                            ? "Entregado"
                            : "No entregado"}
                        </Typography>
                        <Typography variant="body2">
                          Tasa DGT:{" "}
                          {extendedSummary.pagos?.tasaDgtEstado ===
                          "PENDIENTE_RENOVACION"
                            ? "Pendiente renovación"
                            : extendedSummary.pagos?.tasaDgtPagada
                              ? "Pagada"
                              : "No pagada"}
                        </Typography>
                        <Typography variant="body2">
                          Vidas restantes:{" "}
                          {extendedSummary.vidas?.restantes ?? 0}
                        </Typography>
                        <Typography variant="body2">
                          Pago examen práctico:{" "}
                          {extendedSummary.pagos?.pagoExamenPracticoPagado
                            ? "Pagado"
                            : "No pagado"}
                        </Typography>
                        <Typography variant="body2">
                          Bono clases:{" "}
                          {extendedSummary.bonoClases?.detalle?.nombre ||
                            "No tiene bonos comprados ni asociados"}
                          {extendedSummary.bonoClases?.detalle
                            ? ` | Caducidad: ${formatDateLabel(extendedSummary.bonoClases?.detalle?.fechaCaducidad)}`
                            : ""}
                        </Typography>
                      </Box>
                    </Box>
                  ) : (
                    <Box
                      sx={{
                        display: "flex",
                        justifyContent: "center",
                        alignItems: "center",
                        minHeight: 300,
                      }}
                    >
                      <CircularProgress size={26} />
                    </Box>
                  )}
                </Box>
              </Box>
            </Box>
          )}
        </DialogContent>

        <DialogActions>
          <Button
            variant="contained"
            onClick={() => {
              if (selectedAlumno) {
                setOpenDetail(false);
                handleEdit(selectedAlumno);
              }
            }}
          >
            Editar alumno
          </Button>

          <Button onClick={() => setOpenDetail(false)}>Cerrar</Button>
        </DialogActions>
      </Dialog>

      <Dialog
        open={confirmDialog.open}
        onClose={closeConfirmDialog}
        fullWidth
        maxWidth="xs"
      >
        <DialogTitle>{confirmDialog.title}</DialogTitle>

        <DialogContent>
          <DialogContentText>{confirmDialog.message}</DialogContentText>
        </DialogContent>

        <DialogActions>
          <Button onClick={closeConfirmDialog}>Cancelar</Button>

          <Button
            variant="contained"
            color={confirmDialog.action === "deactivate" ? "error" : "success"}
            onClick={handleConfirmAction}
          >
            Confirmar
          </Button>
        </DialogActions>
      </Dialog>

      <Snackbar
        open={notification.open}
        autoHideDuration={4000}
        onClose={() =>
          setNotification({
            ...notification,
            open: false,
          })
        }
        anchorOrigin={{
          vertical: "top",
          horizontal: "right",
        }}
      >
        <Alert
          severity={notification.severity}
          variant="filled"
          onClose={() =>
            setNotification({
              ...notification,
              open: false,
            })
          }
        >
          {notification.message}
        </Alert>
      </Snackbar>
    </Box>
  );
}

import { useEffect, useMemo, useState } from "react";
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogContentText,
  DialogTitle,
  FormControl,
  Grid,
  IconButton,
  InputLabel,
  MenuItem,
  Select,
  Snackbar,
  TextField,
  Typography,
} from "@mui/material";
import { DataGrid } from "@mui/x-data-grid";
import EditIcon from "@mui/icons-material/Edit";
import DeleteIcon from "@mui/icons-material/Delete";
import AddIcon from "@mui/icons-material/Add";
import ToggleOffIcon from "@mui/icons-material/ToggleOff";
import ToggleOnIcon from "@mui/icons-material/ToggleOn";
import ShoppingCartIcon from "@mui/icons-material/ShoppingCart";
import Tooltip from "@mui/material/Tooltip";
import { jwtDecode } from "jwt-decode";
import { useNavigate } from "react-router-dom";

import { bonosService } from "../../services/bonosService";
import { LicenseChip } from "../../components/common/LicenseChip";

const LICENCIAS = ["B", "A1", "A2", "A", "C", "D", "E"];

const emptyForm = {
  nombre: "",
  descripcion: "",
  licencia: "B",
  clasesIncluidas: 10,
  precio: "",
  validezDias: 90,
  activo: true,
};

function formatPrice(value) {
  return `${Number(value || 0).toFixed(2)} EUR`;
}

function formatDate(value) {
  return value ? new Date(value).toLocaleDateString("es-ES") : "-";
}

const getOwnedBonoStyle = (estado) => {
  if (estado === "AGOTADO") {
    return {
      background: "linear-gradient(145deg, #f3f4f6 0%, #e5e7eb 100%)",
      borderColor: "#d1d5db",
    };
  }

  if (estado === "CADUCADO") {
    return {
      background: "linear-gradient(145deg, #fef2f2 0%, #fee2e2 100%)",
      borderColor: "#fecaca",
    };
  }

  return {
    background: "linear-gradient(145deg, #eff6ff 0%, #dbeafe 100%)",
    borderColor: "#93c5fd",
  };
};

const getOwnedBonoChip = (item) => {
  const compradas = Number(item.clasesCompradas || 0);
  const consumidas = Number(item.clasesConsumidas || 0);
  const disponibles = Math.max(compradas - consumidas, 0);

  if (disponibles <= 0 || item.estado === "AGOTADO") {
    return { label: "GASTADO", color: "default" };
  }

  return { label: "COMPRADO", color: "success" };
};

function StudentBonosView({ rows, loading, onBuy }) {
  if (loading) {
    return <Typography>Cargando bonos...</Typography>;
  }

  if (rows.length === 0) {
    return (
      <Typography color="text.secondary">
        No hay bonos activos disponibles en este momento.
      </Typography>
    );
  }

  return (
    <Grid container spacing={3}>
      {rows.map((row) => (
        <Grid item xs={12} md={6} lg={4} key={row.id}>
          <Card
            sx={{
              height: "100%",
              minHeight: 320,
              borderRadius: 3,
              border: "1px solid rgba(15, 23, 42, 0.14)",
              boxShadow: "0 12px 28px rgba(15, 23, 42, 0.08)",
            }}
          >
            <CardContent
              sx={{
                height: "100%",
                display: "flex",
                flexDirection: "column",
                gap: 2,
              }}
            >
              <Typography
                variant="h4"
                sx={{
                  fontWeight: 900,
                  color: "#0f4c81",
                  lineHeight: 1.1,
                }}
              >
                {row.nombre}
              </Typography>

              <Box
                sx={{
                  display: "flex",
                  justifyContent: "space-between",
                  gap: 2,
                }}
              >
                <Typography sx={{ fontWeight: 700 }}>
                  {row.clasesIncluidas} clases
                </Typography>
                <Typography sx={{ fontWeight: 700 }} color="text.secondary">
                  Validez: {row.validezDias} dias
                </Typography>
              </Box>

              <Typography color="text.secondary" sx={{ flexGrow: 1 }}>
                {row.descripcion || "Bono de clases practicas"}
              </Typography>

              <Box
                sx={{
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "space-between",
                  gap: 2,
                }}
              >
                <Typography variant="h5" sx={{ fontWeight: 900 }}>
                  {formatPrice(row.precio)}
                </Typography>

                <Button
                  variant="contained"
                  size="large"
                  startIcon={<ShoppingCartIcon />}
                  onClick={() => onBuy(row)}
                >
                  Comprar bono
                </Button>
              </Box>
            </CardContent>
          </Card>
        </Grid>
      ))}
    </Grid>
  );
}

export default function Bonos() {
  const navigate = useNavigate();
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(false);
  const [role, setRole] = useState(null);
  const [open, setOpen] = useState(false);
  const [myBonos, setMyBonos] = useState([]);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(emptyForm);
  const [licenciaFiltro, setLicenciaFiltro] = useState("all");
  const [notification, setNotification] = useState({
    open: false,
    message: "",
    severity: "success",
  });
  const [confirmDialog, setConfirmDialog] = useState({
    open: false,
    action: null,
    bonoId: null,
    nombreBono: "",
    title: "",
    message: "",
  });

  useEffect(() => {
    const token = localStorage.getItem("token") || "";

    try {
      const decoded = jwtDecode(token);
      setRole(decoded?.rol ?? "ALUMNO");
    } catch {
      setRole("ALUMNO");
    }
  }, []);

  const loadBonos = async () => {
    if (!role) {
      return;
    }

    try {
      setLoading(true);
      const data =
        role === "ADMIN" || role === "ADMINISTRATIVO"
          ? await bonosService.getAll({
              licencia: licenciaFiltro === "all" ? undefined : licenciaFiltro,
            })
          : await bonosService.getAvailable();
      setRows(data);

      if (role !== "ADMIN" && role !== "ADMINISTRATIVO") {
        const bonosAlumno = await bonosService.getMine();
        setMyBonos(Array.isArray(bonosAlumno) ? bonosAlumno : []);
      }
    } catch (error) {
      console.error(error);
      setNotification({
        open: true,
        message:
          role === "ADMIN" || role === "ADMINISTRATIVO"
            ? "No se pudieron cargar los bonos"
            : "No se pudieron cargar los bonos disponibles",
        severity: "error",
      });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadBonos();
  }, [role, licenciaFiltro]);

  const filteredRows = useMemo(() => rows, [rows]);

  const resetForm = () => {
    setForm(emptyForm);
    setEditingId(null);
  };

  const handleOpenCreate = () => {
    resetForm();
    setOpen(true);
  };

  const handleEdit = (row) => {
    setEditingId(row.id);
    setForm({
      nombre: row.nombre || "",
      descripcion: row.descripcion || "",
      licencia: row.licencia || "B",
      clasesIncluidas: row.clasesIncluidas ?? 10,
      precio: row.precio ?? "",
      validezDias: row.validezDias ?? 90,
      activo: Boolean(row.activo),
    });
    setOpen(true);
  };

  const handleDelete = (row) => {
    setConfirmDialog({
      open: true,
      action: "delete",
      bonoId: row.id,
      nombreBono: row.nombre,
      title: "Confirmar eliminacion",
      message: `Vas a eliminar definitivamente el bono "${row.nombre}" de Autoescuela Eguzkilore. Toda la informacion asociada sera eliminada de forma permanente. Esta accion no podra deshacerse. Deseas continuar?`,
    });
  };

  const handleToggleActivo = (row) => {
    setConfirmDialog({
      open: true,
      action: row.activo ? "deactivate" : "activate",
      bonoId: row.id,
      nombreBono: row.nombre,
      title: row.activo ? "Confirmar desactivacion" : "Confirmar activacion",
      message: row.activo
        ? `Vas a desactivar el bono "${row.nombre}" en Autoescuela Eguzkilore. No podra utilizarse hasta su reactivacion. Deseas continuar?`
        : `Vas a reactivar el bono "${row.nombre}" en Autoescuela Eguzkilore. Volvera a estar disponible de inmediato. Deseas continuar?`,
    });
  };

  const closeConfirmDialog = () => {
    setConfirmDialog({
      open: false,
      action: null,
      bonoId: null,
      nombreBono: "",
      title: "",
      message: "",
    });
  };

  const handleConfirmAction = async () => {
    if (!confirmDialog.bonoId || !confirmDialog.action) {
      closeConfirmDialog();
      return;
    }

    try {
      if (confirmDialog.action === "delete") {
        await bonosService.delete(confirmDialog.bonoId);
      }

      if (confirmDialog.action === "deactivate") {
        await bonosService.deactivate(confirmDialog.bonoId);
      }

      if (confirmDialog.action === "activate") {
        await bonosService.activate(confirmDialog.bonoId);
      }

      await loadBonos();

      setNotification({
        open: true,
        message:
          confirmDialog.action === "delete"
            ? "Bono eliminado correctamente"
            : confirmDialog.action === "deactivate"
              ? "Bono desactivado correctamente"
              : "Bono activado correctamente",
        severity: "success",
      });
    } catch (error) {
      console.error(error);

      setNotification({
        open: true,
        message: error.response?.data?.message || "Error procesando la accion",
        severity: "error",
      });
    } finally {
      closeConfirmDialog();
    }
  };

  const handleSave = async () => {
    try {
      const payload = {
        ...form,
        clasesIncluidas: Number(form.clasesIncluidas),
        precio: Number(form.precio),
        validezDias: Number(form.validezDias),
      };

      if (editingId) {
        await bonosService.update(editingId, payload);
      } else {
        await bonosService.create(payload);
      }

      await loadBonos();
      setOpen(false);
      resetForm();
      setNotification({
        open: true,
        message: editingId
          ? "Bono actualizado correctamente"
          : "Bono creado correctamente",
        severity: "success",
      });
    } catch (error) {
      console.error(error);
      setNotification({
        open: true,
        message: error.response?.data?.message || "Error guardando bono",
        severity: "error",
      });
    }
  };

  const handleBuy = async (row) => {
    try {
      const result = await bonosService.buy(row.id);
      const pagoId = result?.pago?.id;

      if (!pagoId) {
        throw new Error("No se pudo generar el pago pendiente del bono");
      }

      navigate(`/pago-matricula?pagoId=${pagoId}`);
    } catch (error) {
      console.error(error);
      setNotification({
        open: true,
        message:
          error.response?.data?.message ||
          error.message ||
          "No se pudo iniciar la compra del bono",
        severity: "error",
      });
    }
  };

  const columns = [
    { field: "nombre", headerName: "Nombre", flex: 1.1 },
    {
      field: "licencia",
      headerName: "Licencia",
      flex: 0.6,
      renderCell: (params) => <LicenseChip value={params.value} />,
    },
    { field: "clasesIncluidas", headerName: "Clases", flex: 0.6 },
    {
      field: "precio",
      headerName: "Precio",
      flex: 0.7,
      valueFormatter: (value) => formatPrice(value),
    },
    { field: "validezDias", headerName: "Validez (dias)", flex: 0.8 },
    {
      field: "descripcion",
      headerName: "Descripcion",
      flex: 1.4,
      renderCell: (params) => (
        <Box
          sx={{
            display: "flex",
            alignItems: "center",
            height: "100%",
            width: "100%",
          }}
        >
          <Typography variant="body2" noWrap>
            {params.row.descripcion || "Sin descripcion"}
          </Typography>
        </Box>
      ),
    },
    {
      field: "activo",
      headerName: "Estado",
      flex: 0.7,
      renderCell: (params) => (
        <Chip
          size="small"
          label={params.value ? "Activo" : "Inactivo"}
          sx={{
            // Fondo según la opción
            backgroundColor: params.value ? "#e8f5e9" : "#ffebee",

            // Color de la letra según la opción
            color: params.value ? "#2e7d32" : "#c62828",

            // Borde según la opción (grosor, tipo y color)
            border: `1px solid ${params.value ? "#4caf50" : "#ef5350"}`,

            // Opcional: Asegura que si hay iconos o estados hover no rompan tus colores
            "& .MuiChip-label": {
              fontWeight: "medium",
            },
          }}
        />
      ),
    },
    {
      field: "acciones",
      headerName: "Acciones",
      width: 180,
      sortable: false,
      renderCell: (params) => (
        <Box
          sx={{
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            gap: 0.5,
            width: "100%",
          }}
        >
          <Tooltip title="Editar" arrow>
            <IconButton color="primary" onClick={() => handleEdit(params.row)}>
              <EditIcon />
            </IconButton>
          </Tooltip>

          <Tooltip title={params.row.activo ? "Desactivar" : "Activar"} arrow>
            <IconButton
              color={params.row.activo ? "warning" : "success"}
              onClick={() => handleToggleActivo(params.row)}
            >
              {params.row.activo ? <ToggleOffIcon /> : <ToggleOnIcon />}
            </IconButton>
          </Tooltip>

          <Tooltip title="Eliminar" arrow>
            <IconButton color="error" onClick={() => handleDelete(params.row)}>
              <DeleteIcon />
            </IconButton>
          </Tooltip>
        </Box>
      ),
    },
  ];

  if (!role) {
    return <Typography>Cargando bonos...</Typography>;
  }

  return (
    <Box>
      <Box
        sx={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          mb: 2,
        }}
      >
        <Typography variant="h4" fontWeight="bold">
          {role === "ADMIN" || role === "ADMINISTRATIVO"
            ? "Bonos"
            : "Compra de Bonos"}
        </Typography>

        {role === "ADMIN" || role === "ADMINISTRATIVO" ? (
          <Box sx={{ display: "flex", gap: 2, alignItems: "center" }}>
            <FormControl size="small" sx={{ minWidth: 180 }}>
              <InputLabel>Licencia</InputLabel>
              <Select
                label="Licencia"
                value={licenciaFiltro}
                onChange={(event) => setLicenciaFiltro(event.target.value)}
              >
                <MenuItem value="all">Todas</MenuItem>
                {LICENCIAS.map((licencia) => (
                  <MenuItem key={licencia} value={licencia}>
                    {licencia}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>

            <Button
              variant="contained"
              startIcon={<AddIcon />}
              onClick={handleOpenCreate}
            >
              Nuevo bono
            </Button>
          </Box>
        ) : null}
      </Box>

      {role === "ADMIN" || role === "ADMINISTRATIVO" ? (
        <Box sx={{ height: 700 }}>
          <DataGrid
            rows={filteredRows}
            columns={columns}
            getRowId={(row) => row.id}
            disableRowSelectionOnClick
            pageSizeOptions={[10, 25, 50]}
            loading={loading}
            initialState={{
              pagination: { paginationModel: { pageSize: 10, page: 0 } },
              sorting: { sortModel: [{ field: "nombre", sort: "asc" }] },
            }}
          />
        </Box>
      ) : (
        <Box sx={{ display: "grid", gap: 2 }}>
          <StudentBonosView rows={rows} loading={loading} onBuy={handleBuy} />

          {myBonos.length > 0 ? (
            <Box
              sx={{
                p: 2,
                border: "1px solid",
                borderColor: "divider",
                borderRadius: 2,
              }}
            >
              <Typography variant="h6" fontWeight={800} sx={{ mb: 1 }}>
                Bono(s) que ya tienes
              </Typography>
              <Grid container spacing={1.5}>
                {myBonos.map((item) => {
                  const disponibles = Math.max(
                    Number(item.clasesCompradas || 0) -
                      Number(item.clasesConsumidas || 0),
                    0,
                  );
                  const bonoStyle = getOwnedBonoStyle(item.estado);
                  const chip = getOwnedBonoChip(item);

                  return (
                    <Grid item xs={12} md={6} key={`my-bono-${item.id}`}>
                      <Card
                        variant="outlined"
                        sx={{
                          borderRadius: 2,
                          borderColor: bonoStyle.borderColor,
                          background: bonoStyle.background,
                        }}
                      >
                        <CardContent sx={{ display: "grid", gap: 1 }}>
                          <Box
                            sx={{
                              display: "flex",
                              alignItems: "center",
                              justifyContent: "space-between",
                              gap: 1,
                            }}
                          >
                            <Typography fontWeight={800}>
                              {item.nombre || "Bono"}
                            </Typography>
                            <Chip
                              size="small"
                              label={chip.label}
                              color={chip.color}
                            />
                          </Box>

                          <Typography variant="body2" color="text.secondary">
                            {item.descripcion || "Bono de clases practicas"}
                          </Typography>

                          <Typography variant="body2" fontWeight={700}>
                            {item.clasesCompradas} compradas |{" "}
                            {item.clasesConsumidas} consumidas | {disponibles}{" "}
                            disponibles
                          </Typography>

                          <Typography variant="caption" color="text.secondary">
                            Válido hasta: {formatDate(item.fechaValidezHasta)}
                          </Typography>
                        </CardContent>
                      </Card>
                    </Grid>
                  );
                })}
              </Grid>
            </Box>
          ) : null}
        </Box>
      )}

      <Dialog
        open={open}
        onClose={() => setOpen(false)}
        fullWidth
        maxWidth="sm"
      >
        <DialogTitle>{editingId ? "Editar bono" : "Nuevo bono"}</DialogTitle>
        <DialogContent sx={{ pt: 1, display: "grid", gap: 2 }}>
          <TextField
            sx={{ mt: 2 }}
            label="Nombre"
            fullWidth
            value={form.nombre}
            onChange={(event) =>
              setForm((prev) => ({ ...prev, nombre: event.target.value }))
            }
          />
          <TextField
            label="Descripcion"
            fullWidth
            multiline
            minRows={3}
            value={form.descripcion}
            onChange={(event) =>
              setForm((prev) => ({ ...prev, descripcion: event.target.value }))
            }
          />
          <FormControl fullWidth>
            <InputLabel>Licencia</InputLabel>
            <Select
              label="Licencia"
              value={form.licencia}
              onChange={(event) =>
                setForm((prev) => ({ ...prev, licencia: event.target.value }))
              }
            >
              {LICENCIAS.map((licencia) => (
                <MenuItem key={licencia} value={licencia}>
                  {licencia}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
          <TextField
            label="Clases incluidas"
            type="number"
            fullWidth
            value={form.clasesIncluidas}
            onChange={(event) =>
              setForm((prev) => ({
                ...prev,
                clasesIncluidas: event.target.value,
              }))
            }
          />
          <TextField
            label="Precio"
            type="number"
            fullWidth
            value={form.precio}
            onChange={(event) =>
              setForm((prev) => ({ ...prev, precio: event.target.value }))
            }
            inputProps={{ min: 0, step: "0.01" }}
          />
          <TextField
            label="Validez en dias"
            type="number"
            fullWidth
            value={form.validezDias}
            onChange={(event) =>
              setForm((prev) => ({ ...prev, validezDias: event.target.value }))
            }
          />
          <FormControl fullWidth>
            <InputLabel>Estado</InputLabel>
            <Select
              label="Estado"
              value={form.activo ? "true" : "false"}
              onChange={(event) =>
                setForm((prev) => ({
                  ...prev,
                  activo: event.target.value === "true",
                }))
              }
            >
              <MenuItem value="true">Activo</MenuItem>
              <MenuItem value="false">Inactivo</MenuItem>
            </Select>
          </FormControl>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpen(false)}>Cancelar</Button>
          <Button variant="contained" onClick={handleSave}>
            Guardar
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog
        open={confirmDialog.open}
        onClose={closeConfirmDialog}
        fullWidth
        maxWidth="xs"
      >
        <DialogTitle>{confirmDialog.title}</DialogTitle>

        <DialogContent>
          <DialogContentText>{confirmDialog.message}</DialogContentText>
        </DialogContent>

        <DialogActions>
          <Button onClick={closeConfirmDialog}>Cancelar</Button>

          <Button
            variant="contained"
            color={confirmDialog.action === "activate" ? "success" : "error"}
            onClick={handleConfirmAction}
          >
            Confirmar
          </Button>
        </DialogActions>
      </Dialog>

      <Snackbar
        open={notification.open}
        autoHideDuration={3500}
        onClose={() => setNotification((prev) => ({ ...prev, open: false }))}
      >
        <Alert
          severity={notification.severity}
          variant="filled"
          onClose={() => setNotification((prev) => ({ ...prev, open: false }))}
        >
          {notification.message}
        </Alert>
      </Snackbar>
    </Box>
  );
}

