      {!matriculaPendiente && pagoTasaPendiente && (
        <Card
          sx={{
            borderRadius: 2,
            border: "2px solid #2563eb",
            backgroundColor: "#eff6ff",
            borderLeft: "6px solid #2563eb",
            boxShadow: "none",
          }}
        >
          <CardContent>
            {/* Contenedor Flex para alinear el título y el botón en la misma línea */}
