                subtitle={`${clasesConfirmadasProfesor} confirmadas por profesor y ${clasesPendientesConfirmacion} pendientes`}
              />
            </Grid>
          </Grid>
        </Grid>
      </Grid>

      <Grid container spacing={3}>
        <Grid item xs={12} lg={7}>
          <Card
            sx={{
              borderRadius: 2,
              height: "100%",
              display: "flex",
              flexDirection: "column",
              border: "1px solid rgba(148, 163, 184, 0.18)",
              boxShadow: "0 14px 32px rgba(15, 23, 42, 0.04)",
            }}
          >
            <CardContent
              sx={{
                py: 2,
                "&:last-child": { pb: 2 },
                // TRUCO: Buscamos el contenedor del título e icono dentro de SectionTitle
                "& .MuiBox-root": {
                  // O el contenedor principal de tu SectionTitle
                  "& div:first-of-type": {
                    // Selecciona el bloque del icono y texto
                    display: "flex",
                    alignItems: "center",
                    gap: 1,
                  },
                },
              }}
            >
              <SectionTitle
                icon={<SchoolIcon sx={{ color: "#2563eb" }} />}
