                subtitle="Este bloque resume tu progreso en tests, el porcentaje de acierto y la recomendación de revisión."
              />

              <Grid container spacing={1.25}>
                <Grid item xs={12} sm={4}>
                  <Box
                    sx={{
                      p: 1.25,
                      borderRadius: 1,
                      backgroundColor: "#eff6ff",
