                    Índice de preparación teórica
                  </Typography>
                  {teoria.preparadoParaTeorico ? (
                    <Chip label="Preparado" color="success" size="small" />
                  ) : (
                    <Chip
                      label="Necesita repaso"
                      color="warning"
                      size="small"
                    />
                  )}
                </Box>
                <LinearProgress
                  variant="determinate"
                  value={Math.min(teoria.porcentajeAprobado, 100)}
                  sx={{ height: 10, borderRadius: 999 }}
