                    >
                      <Typography variant="body2" color="text.secondary">
                        Total realizados
                      </Typography>
                      <Typography variant="h5" fontWeight={800}>
                        {dgtMetrics.testsTotales}
                      </Typography>
                    </Box>
                  </Grid>
                  <Grid item xs={12} sm={4}>
