                      <Typography variant="body2" color="text.secondary">
                        Aprobados / suspendidos
                      </Typography>
                      <Typography variant="h5" fontWeight={800}>
                        {dgtMetrics.testsAprobados} /{" "}
                        {dgtMetrics.testsSuspendidos}
                      </Typography>
                    </Box>
                  </Grid>
                  <Grid item xs={12} sm={4}>
                    <Box
                      sx={{
                        p: 1.25,
                        borderRadius: 1,
                        backgroundColor: "#f0f9ff",
