                    </Typography>
                    <Typography variant="h5" fontWeight={800}>
                      {practica.clasesCompradas}
                    </Typography>
                  </Box>
                </Grid>
                <Grid item xs={12} sm={3}>
                  <Box
                    sx={{
                      p: 1.5,
                      borderRadius: 1,
                      backgroundColor: "#f8fafc",
                    }}
                  >
                    <Typography variant="body2" color="text.secondary">
                      Pagadas
                    </Typography>
                    <Typography variant="h5" fontWeight={800}>
                      {practica.clasesPagadas}
                    </Typography>
                  </Box>
                </Grid>
                <Grid item xs={12} sm={3}>
                  <Box
                    sx={{
                      p: 1.5,
                      borderRadius: 1,
                      backgroundColor: "#f8fafc",
                    }}
                  >
                    <Typography variant="body2" color="text.secondary">
                      Solicitadas
                    </Typography>
                    <Typography variant="h5" fontWeight={800}>
                      {clasesSolicitadasTotales}
                    </Typography>
                  </Box>
                </Grid>
                <Grid item xs={12} sm={3}>
                  <Box
                    sx={{
                      p: 1.5,
                      borderRadius: 1,
                      backgroundColor: "#f8fafc",
                    }}
                  >
                    <Typography variant="body2" color="text.secondary">
                      Realizadas
                    </Typography>
                    <Typography variant="h5" fontWeight={800}>
                      {practica.clasesRealizadas}
                    </Typography>
                  </Box>
                </Grid>
              </Grid>

              <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
                {clasesConfirmadasProfesor} confirmadas por profesor y{" "}
                {clasesPendientesConfirmacion} pendientes de confirmación.
              </Typography>

              <Divider sx={{ my: 2.5 }} />

              <Box>
                <Typography variant="title" fontWeight={800} sx={{ mb: 1.5 }}>
                  Evolución breve
                </Typography>
                <Grid container spacing={1} alignItems="end">
                  {evolucion.map((periodo) => (
                    <Grid item xs key={periodo.key}>
                      <Box
                        sx={{
                          display: "flex",
                          flexDirection: "column",
                          alignItems: "center",
                          gap: 1,
                        }}
                      >
                        <Box
                          sx={{
                            width: "100%",
                            minHeight: 140,
                            display: "flex",
                            alignItems: "end",
                            justifyContent: "center",
                            gap: 0.5,
                            px: 1,
                          }}
                        >
                          <Box
                            sx={{
                              width: 18,
                              height: `${Math.max((periodo.tests / periodoMaximo) * 120, 8)}px`,
                              borderRadius: 999,
                              backgroundColor: "#2563eb",
                            }}
                            title={`Tests: ${periodo.tests}`}
                          />
                          <Box
                            sx={{
                              width: 18,
                              height: `${Math.max((periodo.clases / periodoMaximo) * 120, 8)}px`,
                              borderRadius: 999,
                              backgroundColor: "#16a34a",
                            }}
                            title={`Clases: ${periodo.clases}`}
                          />
                        </Box>
                        <Typography variant="caption" color="text.secondary">
                          {periodo.label}
                        </Typography>
                      </Box>
                    </Grid>
                  ))}
                </Grid>
              </Box>

              <Divider sx={{ my: 2.5 }} />

              <Box>
                <Typography variant="subtitle1" fontWeight={800} sx={{ mb: 1 }}>
                  Reservas de clases
                </Typography>
                {reservas.length > 0 ? (
                  <List dense disablePadding>
                    {reservas.map((reserva) => (
                      <ListItem
                        key={reserva.id}
                        sx={{
                          px: 0,
                          py: 1,
                          borderBottom: "1px solid #e2e8f0",
                        }}
                        secondaryAction={statusChip(
                          reserva.estado,
                          reserva.estado,
                        )}
                      >
                        <ListItemText
                          primary={`${formatDate(reserva.fecha)} · ${reserva.vehiculo?.matricula ?? "Sin vehículo"}`}
                          secondary={
                            <Stack
                              direction="row"
                              spacing={0.75}
                              alignItems="center"
                              useFlexGap
                              flexWrap="wrap"
                              sx={{ mt: 0.4 }}
                            >
                              <Typography
                                variant="caption"
                                color="text.secondary"
                              >
                                {reserva.profesor?.usuario?.nombre
                                  ? `Profesor: ${reserva.profesor.usuario.nombre}`
                                  : "Profesor no asignado"}
                              </Typography>
                              <LicenseChip
                                value={reserva.vehiculo?.tipoPermiso || "-"}
                              />
                              <PracticalClassTypeChip
                                value={
                                  reserva.tipoClasePractica || "CIRCULACION"
                                }
                              />
                            </Stack>
                          }
                        />
                      </ListItem>
                    ))}
                  </List>
                ) : (
                  <Typography color="text.secondary">
                    No tienes reservas programadas en este momento.
                  </Typography>
                )}
              </Box>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} lg={5}>
          <Stack spacing={3}>
            <Card
              sx={{
                borderRadius: 2,
                height: "100%",
                border: "1px solid rgba(148, 163, 184, 0.18)",
                boxShadow: "0 14px 32px rgba(15, 23, 42, 0.04)",
                width: "900px",
              }}
            >
              <CardContent
                sx={{
                  py: 2,
                  "&:last-child": { pb: 2 },
                  // TRUCO: Buscamos el contenedor del título e icono dentro de SectionTitle
                  "& .MuiBox-root": {
                    // O el contenedor principal de tu SectionTitle
                    "& div:first-of-type": {
                      // Selecciona el bloque del icono y texto
                      display: "flex",
                      alignItems: "center",
                      gap: 1,
                    },
                  },
                }}
              >
                <SectionTitle
                  icon={<WorkspacePremiumIcon sx={{ color: "#d97706" }} />}
                  title="Bonos disponibles"
                  subtitle={`Tienes ${bonos.length} bono(s), ${totalBonoDisponible} clase(s) disponibles y ${totalBonoDisponibleContandoSolicitadas} tras descontar solicitadas.`}
                />

                <Stack spacing={1.25}>
                  {bonos.length > 0 ? (
                    bonos.map((bono) => (
                      <Box
                        key={bono.id}
                        sx={{
                          p: 1.5,
                          borderRadius: 1,
                          border: "1px solid rgba(148, 163, 184, 0.18)",
                          backgroundColor: "#fff",
                          boxShadow: "0 10px 20px rgba(15, 23, 42, 0.02)",
                        }}
                      >
                        <Box
                          display="flex"
                          justifyContent="space-between"
                          gap={1}
                        >
                          <Box>
                            <Typography fontWeight={800}>
                              {bono.nombre}
                            </Typography>
                            <Typography variant="body2" color="text.secondary">
                              {bono.descripcion || "Paquete de clases"}
                            </Typography>
                          </Box>

                          {statusChip(bono.estado, bono.estado)}
                        </Box>

                        <Box sx={{ mt: 1.5 }}>
                          <Typography variant="body2" color="text.secondary">
                            {bono.clasesCompradas} compradas ·{" "}
                            {bono.clasesConsumidas} consumidas ·{" "}
                            {bono.clasesSolicitadas ?? 0} solicitadas ·{" "}
                            {bono.clasesDisponibles} disponibles ·{" "}
                            {bono.clasesDisponiblesContandoSolicitadas ??
                              bono.clasesDisponibles}{" "}
                            disponibles contando solicitadas
                          </Typography>
                          <Typography variant="body2" color="text.secondary">
                            Válido hasta: {formatDate(bono.fechaValidezHasta)}
                          </Typography>
                          <Typography variant="body2" color="text.secondary">
                            {bono.aplicable
                              ? "Puedes aplicarlo ahora"
                              : "No aplicable en este momento"}
                          </Typography>
                        </Box>
                      </Box>
                    ))
                  ) : (
                    <Typography color="text.secondary">
                      Todavía no tienes bonos comprados.
                    </Typography>
                  )}
                </Stack>
              </CardContent>
            </Card>

            <Card
              sx={{
                borderRadius: 2,
                width: "900px",
                border: "1px solid rgba(148, 163, 184, 0.18)",
                boxShadow: "0 14px 32px rgba(15, 23, 42, 0.04)",
              }}
            >
              <CardContent
                sx={{
                  py: 2,
                  "&:last-child": { pb: 2 },
                  // TRUCO: Buscamos el contenedor del título e icono dentro de SectionTitle
                  "& .MuiBox-root": {
                    // O el contenedor principal de tu SectionTitle
                    "& div:first-of-type": {
                      // Selecciona el bloque del icono y texto
                      display: "flex",
                      alignItems: "center",
                      gap: 1,
                    },
                  },
                }}
              >
                <SectionTitle
                  icon={<EventNoteIcon sx={{ color: "#7c3aed" }} />}
                  title="Solicitudes de examen"
                  subtitle="Estado de tus solicitudes para examen teórico y práctico."
                />

                <Grid container spacing={2}>
                  <Grid item xs={12} md={6}>
                    <Box
                      sx={{
                        p: 1.75,
                        borderRadius: 1,
                        border: "1px solid rgba(148, 163, 184, 0.18)",
                        backgroundColor: "#fff",
                        width: "850px",
                      }}
                    >
                      <Typography
                        variant="subtitle1"
                        fontWeight={800}
                        sx={{ mb: 2 }}
                      >
                        Examen teórico
                      </Typography>

                      {examenes.teoricos.length > 0 ? (
                        <Stack spacing={2} sx={{ width: "100%" }}>
                          {examenes.teoricos.map((examen, index) => (
                            <Box
                              key={examen.id}
                              onClick={() => handleOpenExamModal(examen)}
                              sx={{
                                cursor: "pointer",
                                borderRadius: 2,
                                p: 1.5,
                                width: "100%",
                                boxSizing: "border-box",
                                transition: "background-color 0.2s ease",
                                "&:hover": {
                                  backgroundColor: "#f8fafc",
                                },
                              }}
                            >
                              {/* Fila Principal: Fecha Programada, Estado y Botón de Acción */}
                              <Stack
                                direction="row"
                                spacing={2}
                                alignItems="center"
                                justifyContent="space-between"
                                sx={{ width: "100%", mb: 1 }}
                              >
                                {/* Contenedor Izquierdo: Fechas de Programación y Solicitud */}
                                <Stack spacing={0.5}>
                                  <Typography
                                    variant="body1"
                                    fontWeight={700}
                                    noWrap
                                  >
                                    Fecha del Examen:{" "}
                                    {formatDate(examen.fechaProgramada)}
                                  </Typography>
                                  <Typography
                                    variant="body2"
                                    color="text.secondary"
                                    noWrap
                                  ></Typography>
                                </Stack>

                                {/* Contenedor Derecho: Estado y Botón Detalle */}
                                <Stack
                                  direction="row"
                                  spacing={1.5}
                                  alignItems="center"
                                  sx={{ flexShrink: 0 }}
                                >
                                  {statusChip(examen.estado, examen.estado)}

                                  <Typography
                                    variant="caption"
                                    sx={{
                                      display: "inline-block",
                                      backgroundColor: "#fffbeb",
                                      borderColor: "#facc15",
                                      borderRadius: "15px",
                                      borderWidth: "1px",
                                      borderStyle: "solid",
                                      px: 1.5,
                                      py: 0.5,
                                      fontWeight: 500,
                                      color: "#b45309",
                                    }}
                                  >
                                    Pulsa para ver detalle de examen
                                  </Typography>
                                </Stack>
                              </Stack>

                              {/* Sección Opcional de Observaciones 
                              {examen.observaciones ? (
                                <Typography
                                  variant="body2"
                                  color="text.secondary"
                                  sx={{ mt: 1, px: 0.5 }}
                                >
                                  {examen.observaciones}
                                </Typography>
                              ) : null}*/}

                              {/* Separador entre elementos (evita duplicar al final de la lista) */}
                              {index < examenes.teoricos.length - 1 && (
                                <Divider sx={{ mt: 2 }} />
                              )}
                            </Box>
                          ))}
                        </Stack>
                      ) : (
                        <Typography color="text.secondary">
                          Todavía no has solicitado examen teórico.
                        </Typography>
                      )}
                    </Box>
                  </Grid>

                  <Grid item xs={12} md={6}>
                    <Box
                      sx={{
                        p: 2,
                        borderRadius: 2,
                        border: "1px solid rgba(148, 163, 184, 0.18)",
                        backgroundColor: "#fff",
                        height: "100%", // Asegura que ambos contenedores midan lo mismo de alto
                        width: "850px",
                      }}
                    >
                      <Typography
                        variant="subtitle1"
                        fontWeight={800}
                        sx={{ mb: 2 }}
                      >
                        Examen práctico
                      </Typography>

                      {examenes.practicos.length > 0 ? (
                        <Stack spacing={2} sx={{ width: "100%" }}>
                          {examenes.practicos.map((examen) => (
                            <Box
                              key={examen.id}
                              onClick={() => handleOpenExamModal(examen)}
                              sx={{
                                cursor: "pointer",
                                borderRadius: 1,
                                p: 1.5,
                                width: "100%",
                                boxSizing: "border-box",
                                transition: "background-color 0.2s ease",
                                "&:hover": {
                                  backgroundColor: "#f8fafc",
                                },
                              }}
                            >
                              {/* Contenedor principal alineado horizontalmente */}
                              <Stack
                                direction="row"
                                spacing={2}
                                alignItems="center"
                                justifyContent="space-between"
                                sx={{ width: "100%", mb: 1 }}
                              >
                                {/* Bloque Izquierdo: Fechas apiladas verticalmente */}
                                <Stack spacing={0.5}>
                                  <Typography fontWeight={700} variant="body1">
                                    Fecha del Examen:{" "}
                                    {formatDate(examen.fechaProgramada)}
                                  </Typography>
                                  <Typography
                                    variant="body2"
                                    color="text.secondary"
                                  >
                                    Subtipo:{" "}
                                    {getPracticalExamTypeLabel({
                                      license: practicalLicense,
                                      phase: examen?.fasePractica,
                                    })}
                                  </Typography>

                                  {/* ─── COMENTADO DESDE AQUÍ ───
                                      {examen.observaciones ? (
                                      <Typography
                                        variant="body2"
                                        color="text.secondary"
                                      >
                                        {examen.observaciones}
                                      </Typography>
                                    ) : null}
                                    ─── HASTA AQUÍ ─── */}
                                </Stack>

                                {/* Bloque Derecho: Chip de estado y Botón de detalles */}
                                <Stack
                                  direction="row"
                                  spacing={1.5}
                                  alignItems="center"
                                >
                                  {statusChip(examen.estado, examen.estado)}
                                  <Typography
                                    variant="caption"
                                    sx={{
                                      display: "inline-block",
                                      backgroundColor: "#fffbeb",
                                      borderColor: "#facc15",
                                      borderRadius: "15px",
                                      borderWidth: "1px",
                                      borderStyle: "solid",
                                      px: 1.5,
                                      py: 0.5,
                                      fontWeight: 500,
                                      color: "#b45309",
                                      whiteSpace: "nowrap", // Evita que el texto del botón se rompa en dos líneas
                                    }}
                                  >
                                    Pulsa para ver detalle de faltas
                                  </Typography>
                                </Stack>
                              </Stack>

                              <Divider sx={{ mt: 2 }} />
                            </Box>
                          ))}
                        </Stack>
                      ) : (
                        <Typography color="text.secondary">
                          Todavía no has solicitado examen práctico.
                        </Typography>
                      )}
                    </Box>
                  </Grid>
                </Grid>
                {/*
                <Box
                  sx={{
                    mt: 2.5,
                    p: 1.75,
                    borderRadius: 2.5,
                    backgroundColor: "#f8fafc",
                  }}
                >
                  <Typography
                    variant="subtitle1"
                    fontWeight={800}
                    sx={{ mb: 0.5 }}
                  >
                    Estado general
                  </Typography>
                  <Typography color="text.secondary">
                    {resumen.preparadoParaTeorico
                      ? "Según tu progreso actual, ya estás preparado para el examen teórico."
                      : "Aún no estás listo para examinarte del teórico; revisa los temarios recomendados y mejora el porcentaje de acierto."}
                  </Typography>
                </Box>
                */}
                <Dialog
                  open={openExamModal}
                  onClose={handleCloseExamModal}
                  fullWidth
                  maxWidth="sm"
                >
                  <DialogTitle
                    sx={{
                      display: "flex",
                      justifyContent: "space-between",
                      alignItems: "center", // Keeps them perfectly aligned vertically
                      width: "100%",
                    }}
                  >
                    <span>Detalle de evaluación</span>
                    <Chip
                      label={selectedExam?.estado || "-"}
                      variant="outlined"
                      sx={{
                        borderRadius: "15px",
                        borderWidth: "1px",
                        "& .MuiChip-label": {
                          fontWeight: "bold",
                        },
                        // Modifica el FONDO según el estado
                        backgroundColor:
                          {
                            SOLICITADO: "#e0f2fe",
                            APTO: "#ecfdf5",
                            NO_APTO: "#fef2f2",
                            PENDIENTE: "#fffbeb",
                            CANCELADO: "#eae9e9",
                          }[selectedExam?.estado] || "#f3f4f6", // Color por defecto si no coincide

                        // Modifica el BORDE según el estado
                        borderColor:
                          {
                            SOLICITADO: "#0284c7",
                            APTO: "#34d399",
                            NO_APTO: "#f87171",
                            PENDIENTE: "#facc15",
                            CANCELADO: "#000000",
                          }[selectedExam?.estado] || "#d1d5db", // Color por defecto si no coincide

                        // Modifica la LETRA según el estado
                        color:
                          {
                            SOLICITADO: "#0369a1",
                            APTO: "#065f46",
                            NO_APTO: "#991b1b",
                            PENDIENTE: "#854d0e",
                            CANCELADO: "#000000",
                          }[selectedExam?.estado] || "#374151", // Color por defecto si no coincide
                      }}
                    />
                  </DialogTitle>

                  <DialogContent sx={{ display: "grid", gap: 1, pt: 1 }}>
                    <Typography>
                      <strong>Tipo:</strong> {selectedExam?.tipo || "-"}
                    </Typography>
                    {selectedExam?.tipo === "PRACTICO" ? (
                      <Typography>
                        <strong>Subtipo:</strong>{" "}
                        {getPracticalExamTypeLabel({
                          license: practicalLicense,
                          phase: selectedExam?.fasePractica,
                        })}
                      </Typography>
                    ) : null}
                    <Typography>
                      <strong>Fecha:</strong>{" "}
                      {formatDate(selectedExam?.fechaProgramada)}
                    </Typography>

                    {selectedExam?.tipo === "PRACTICO" ? (
                      <>
                        <Typography>
                          <strong>Motivo no apto:</strong>{" "}
                          {selectedExam?.motivoNoApto || "-"}
                        </Typography>

                        <Divider sx={{ my: 0.5 }} />

                        <Typography>
                          <strong>Faltas leves:</strong>{" "}
                          {selectedExam?.faltasLeves ?? 0}
                        </Typography>
                        {(selectedExam?.faltasLevesDetalle || []).length > 0 ? (
                          <List dense disablePadding>
                            {selectedExam.faltasLevesDetalle.map(
                              (falta, index) => (
                                <ListItem
                                  key={`leve-${index}`}
                                  sx={{ px: 0, py: 0.25 }}
                                >
                                  <ListItemText
                                    primaryTypographyProps={{
                                      variant: "body2",
                                    }}
                                    primary={`- ${falta}`}
                                  />
                                </ListItem>
                              ),
                            )}
                          </List>
                        ) : (
                          <Typography variant="body2" color="text.secondary">
                            Sin faltas leves registradas.
                          </Typography>
                        )}

                        <Typography>
                          <strong>Faltas deficientes:</strong>{" "}
                          {selectedExam?.faltasDeficientes ?? 0}
                        </Typography>
                        {(selectedExam?.faltasDeficientesDetalle || []).length >
                        0 ? (
                          <List dense disablePadding>
                            {selectedExam.faltasDeficientesDetalle.map(
                              (falta, index) => (
                                <ListItem
                                  key={`def-${index}`}
                                  sx={{ px: 0, py: 0.25 }}
                                >
                                  <ListItemText
                                    primaryTypographyProps={{
                                      variant: "body2",
                                    }}
                                    primary={`- ${falta}`}
                                  />
                                </ListItem>
                              ),
                            )}
                          </List>
                        ) : (
                          <Typography variant="body2" color="text.secondary">
                            Sin faltas deficientes registradas.
                          </Typography>
                        )}

                        <Typography>
                          <strong>Faltas eliminatorias:</strong>{" "}
                          {selectedExam?.faltasEliminatorias ?? 0}
                        </Typography>
                        {(selectedExam?.faltasEliminatoriasDetalle || [])
                          .length > 0 ? (
                          <List dense disablePadding>
                            {selectedExam.faltasEliminatoriasDetalle.map(
                              (falta, index) => (
                                <ListItem
                                  key={`eli-${index}`}
                                  sx={{ px: 0, py: 0.25 }}
                                >
                                  <ListItemText
                                    primaryTypographyProps={{
                                      variant: "body2",
                                    }}
                                    primary={`- ${falta}`}
                                  />
                                </ListItem>
                              ),
                            )}
                          </List>
                        ) : (
                          <Typography variant="body2" color="text.secondary">
                            Sin faltas eliminatorias registradas.
                          </Typography>
                        )}
                      </>
                    ) : (
                      <>
                        <Typography>
                          <strong>Errores:</strong>{" "}
                          {selectedExam?.erroresExamen ?? "-"}
                        </Typography>
                        <Typography>
                          <strong>Aciertos:</strong>{" "}
                          {selectedExam?.aciertosExamen ?? "-"}
                        </Typography>
                      </>
                    )}
                  </DialogContent>
                  <DialogActions>
                    <Button onClick={handleCloseExamModal}>Cerrar</Button>
                  </DialogActions>
                </Dialog>
              </CardContent>
            </Card>
          </Stack>
        </Grid>
      </Grid>
    </Box>
  );
}

import { useEffect, useMemo, useState } from "react";
import {
  Alert,
  Box,
  Button,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  IconButton,
  InputLabel,
  MenuItem,
  Select,
  Snackbar,
  Stack,
  TextField,
  Typography,
} from "@mui/material";
import { DataGrid } from "@mui/x-data-grid";
import AddIcon from "@mui/icons-material/Add";
import DeleteIcon from "@mui/icons-material/Delete";
import EditIcon from "@mui/icons-material/Edit";
import UploadFileIcon from "@mui/icons-material/UploadFile";
import VisibilityIcon from "@mui/icons-material/Visibility";
import { documentosAlumnoService } from "../../services/documentosAlumnoService";
import Tooltip from "@mui/material/Tooltip"; // Asegúrate de importar el componente

const TIPOS_DOCUMENTO = [
  "DNI",
  "CERTIFICADO_PSICOTECNICO",
  "FOTOGRAFIA",
  "PERMISO_RESIDENCIA",
  "JUSTIFICANTE",
  "OTRO",
];

const ESTADOS = {
  PENDIENTE_VALIDACION: "Pendiente de validar",
  VALIDADO: "Validado",
  RECHAZADO: "Rechazado",
};

const formatDate = (value) => {
  if (!value) return "-";
  return new Date(value).toLocaleDateString("es-ES");
};

const buildFileUrl = (ruta) => {
  if (!ruta) return "";
  return ruta.startsWith("http") ? ruta : `${window.location.origin}${ruta}`;
};

const isImageFile = (mimeType = "") => mimeType.startsWith("image/");

export default function DocumentosAlumno() {
  const [rows, setRows] = useState([]);
  const [open, setOpen] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [tipo, setTipo] = useState("DNI");
  const [observaciones, setObservaciones] = useState("");
  const [files, setFiles] = useState([]);
  const [notification, setNotification] = useState({
    open: false,
    message: "",
    severity: "success",
  });

  const loadDocuments = async () => {
    try {
      const data = await documentosAlumnoService.getMine();
      setRows(data);
    } catch (error) {
      console.error(error);
      setNotification({
        open: true,
        message: "No se pudieron cargar tus documentos",
        severity: "error",
      });
    }
  };

  useEffect(() => {
    loadDocuments();
  }, []);

  const resetForm = () => {
    setTipo("DNI");
    setObservaciones("");
    setFiles([]);
    setEditingId(null);
  };

  const handleCreateOpen = () => {
    resetForm();
    setOpen(true);
  };

  const handleEditRow = (row) => {
    if (row.estado !== "PENDIENTE_VALIDACION") {
      setNotification({
        open: true,
        message: "Este documento ya está validado y no puede modificarse.",
        severity: "warning",
      });
      return;
    }

    setEditingId(row.id);
    setTipo(row.tipo);
    setObservaciones(row.observaciones || "");
    setFiles([]);
    setOpen(true);
  };

  const handleClose = () => {
    setOpen(false);
    resetForm();
  };

  const submitDocument = async () => {
    try {
      const formData = new FormData();
      formData.append("tipo", tipo);
      if (observaciones) {
        formData.append("observaciones", observaciones);
      }

      files.forEach((file) => {
        formData.append("archivos", file);
      });

      if (editingId) {
        await documentosAlumnoService.update(editingId, formData);
      } else {
        await documentosAlumnoService.create(formData);
      }

      setNotification({
        open: true,
        message: editingId
          ? "Documento actualizado correctamente"
          : "Documento registrado correctamente",
        severity: "success",
      });
      handleClose();
      loadDocuments();
    } catch (error) {
      setNotification({
        open: true,
        message:
          error.response?.data?.message || "No se pudo guardar el documento",
        severity: "error",
      });
    }
  };

  const handleDelete = async (row) => {
    if (row.estado !== "PENDIENTE_VALIDACION") {
      setNotification({
        open: true,
        message: "Solo se pueden eliminar documentos pendientes de validación.",
        severity: "warning",
      });
      return;
    }

    try {
      await documentosAlumnoService.remove(row.id);
      setNotification({
        open: true,
        message: "Documento eliminado correctamente",
        severity: "success",
      });
      loadDocuments();
    } catch (error) {
      setNotification({
        open: true,
        message:
          error.response?.data?.message || "No se pudo eliminar el documento",
        severity: "error",
      });
    }
  };

  const removeSelectedFile = (index) => {
    setFiles((prev) => prev.filter((_, i) => i !== index));
  };

  const columns = useMemo(
    () => [
      { field: "tipo", headerName: "Tipo", flex: 1.4 },
      {
        field: "estado",
        headerName: "Estado",
        flex: 1.2,
        renderCell: (params) => (
          <Chip
            label={ESTADOS[params.value] || params.value}
            color={
              params.value === "VALIDADO"
                ? "success"
                : params.value === "RECHAZADO"
                  ? "error"
                  : "warning"
            }
            size="small"
          />
        ),
      },

      {
        field: "createdAt",
        headerName: "Fecha alta",
        flex: 1,
        valueGetter: (_, row) => formatDate(row.createdAt),
      },
      {
        field: "acciones",
        headerName: "Acciones",
        sortable: false,
        filterable: false,
        disableColumnMenu: true,
        flex: 1.2,
        renderCell: (params) => (
          <Stack direction="row" spacing={1}>
            {(params.row.archivos || []).length > 0 && (
              <Tooltip title="Ver archivo" arrow>
                <span>
                  <IconButton
                    color="primary"
                    size="small"
                    aria-label="Ver archivo"
                    onClick={() =>
                      window.open(
                        buildFileUrl(params.row.archivos[0]?.ruta),
                        "_blank",
                      )
                    }
                  >
                    <VisibilityIcon />
                  </IconButton>
                </span>
              </Tooltip>
            )}
            <Tooltip title="Editar documento" arrow>
              <span>
                <IconButton
                  color="primary"
                  size="small"
                  aria-label="Editar documento"
                  disabled={params.row.estado !== "PENDIENTE_VALIDACION"}
                  onClick={() => handleEditRow(params.row)}
                >
                  <EditIcon />
                </IconButton>
              </span>
            </Tooltip>
            <Tooltip title="Eliminar documento" arrow>
              <span>
                <IconButton
                  color="error"
                  size="small"
                  aria-label="Eliminar documento"
                  disabled={params.row.estado !== "PENDIENTE_VALIDACION"}
                  onClick={() => handleDelete(params.row)}
                >
                  <DeleteIcon />
                </IconButton>
              </span>
            </Tooltip>
          </Stack>
        ),
      },
    ],
    [rows],
  );

  return (
    <Box>
      <Box
        sx={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          mb: 2,
        }}
      >
        <Box>
          <Typography variant="h4">Mis documentos</Typography>
          <Typography variant="body2" color="text.secondary">
            Gestiona tus documentos oficiales con estado de validación.
          </Typography>
        </Box>
        <Button
          variant="contained"
          startIcon={<AddIcon />}
          onClick={handleCreateOpen}
        >
          Nuevo documento
        </Button>
      </Box>

      {rows.length === 0 ? (
        <Alert severity="info">Todavía no has subido ningún documento.</Alert>
      ) : (
        <Box sx={{ height: 700 }}>
          <DataGrid
            rows={rows}
            columns={columns}
            getRowId={(row) => row.id}
            disableRowSelectionOnClick
            pageSizeOptions={[10, 25, 50]}
            initialState={{
              pagination: { paginationModel: { pageSize: 10, page: 0 } },
              sorting: { sortModel: [{ field: "tipo", sort: "asc" }] },
            }}
          />
        </Box>
      )}

      <Dialog open={open} onClose={handleClose} maxWidth="sm" fullWidth>
        <DialogTitle>
          {editingId ? "Editar documento" : "Nuevo documento"}
        </DialogTitle>
        <DialogContent
          sx={{ display: "flex", flexDirection: "column", gap: 2, pt: 2 }}
        >
          <FormControl fullWidth sx={{ mt: 2 }}>
            <InputLabel id="tipo-documento-label">Tipo de documento</InputLabel>
            <Select
              labelId="tipo-documento-label"
              value={tipo}
              label="Tipo de documento"
              onChange={(event) => setTipo(event.target.value)}
            >
              {TIPOS_DOCUMENTO.map((item) => (
                <MenuItem key={item} value={item}>
                  {item}
                </MenuItem>
              ))}
            </Select>
          </FormControl>

          <TextField
            label="Observaciones"
            multiline
            minRows={3}
            value={observaciones}
            onChange={(event) => setObservaciones(event.target.value)}
          />

          <Alert severity="info" sx={{ mb: 0 }}>
            Formatos aceptados: PDF, JPG, PNG, WEBP.
          </Alert>

          <Button
            component="label"
            variant="outlined"
            startIcon={<UploadFileIcon />}
          >
            Adjuntar archivos
            <input
              hidden
              type="file"
              multiple
              accept=".pdf,image/png,image/jpeg,image/webp"
              onChange={(event) =>
                setFiles(Array.from(event.target.files || []))
              }
            />
          </Button>

          {files.length > 0 && (
            <Stack spacing={1}>
              {files.map((file, index) => (
                <Box
                  key={`${file.name}-${index}`}
                  sx={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "space-between",
                    gap: 1,
                    border: "1px solid #e2e8f0",
                    borderRadius: 1,
                    px: 1,
                    py: 0.5,
                  }}
                >
                  <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                    {isImageFile(file.type) ? (
                      <img
                        src={URL.createObjectURL(file)}
                        alt={file.name}
                        style={{
                          width: 28,
                          height: 28,
                          objectFit: "cover",
                          borderRadius: 6,
                        }}
                      />
                    ) : (
                      <Box
                        sx={{
                          width: 28,
                          height: 28,
                          borderRadius: 6,
                          backgroundColor: "#e2e8f0",
                          display: "grid",
                          placeItems: "center",
                          fontSize: 10,
                          fontWeight: 700,
                          color: "#334155",
                        }}
                      >
                        {file.name.split(".").pop()?.toUpperCase() || "FILE"}
                      </Box>
                    )}
                    <Typography variant="body2" noWrap sx={{ maxWidth: 260 }}>
                      {file.name}
                    </Typography>
                  </Box>
                  <Button
                    size="small"
                    color="error"
                    variant="text"
                    onClick={() => removeSelectedFile(index)}
                  >
                    Quitar
                  </Button>
                </Box>
              ))}
            </Stack>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={handleClose}>Cancelar</Button>
          <Button
            variant="contained"
            onClick={submitDocument}
            disabled={!files.length && !editingId}
          >
            {editingId ? "Guardar cambios" : "Crear documento"}
          </Button>
        </DialogActions>
      </Dialog>

      <Snackbar
        open={notification.open}
        autoHideDuration={3500}
        onClose={() => setNotification((prev) => ({ ...prev, open: false }))}
      >
        <Alert
          severity={notification.severity}
          variant="filled"
          onClose={() => setNotification((prev) => ({ ...prev, open: false }))}
        >
          {notification.message}
        </Alert>
      </Snackbar>
    </Box>
  );
}

import { useEffect, useMemo, useState } from "react";
import {
  Alert,
  Box,
  Chip,
  IconButton,
  FormControl,
  InputLabel,
  MenuItem,
  Select,
  TextField,
  Snackbar,
  Stack,
  Link,
  Typography,
} from "@mui/material";
import { DataGrid } from "@mui/x-data-grid";
import CheckCircleIcon from "@mui/icons-material/CheckCircle";
import CancelIcon from "@mui/icons-material/Cancel";
import { documentosAlumnoService } from "../../services/documentosAlumnoService";
import Tooltip from "@mui/material/Tooltip"; // Asegúrate de importar el componente

const ESTADOS = {
  TODOS: "Todos",
  PENDIENTE_VALIDACION: "Pendiente de validar",
  VALIDADO: "Validado",
  RECHAZADO: "Rechazado",
};

const TIPOS_DOCUMENTO = [
  "TODOS",
  "DNI",
  "CERTIFICADO_PSICOTECNICO",
  "FOTOGRAFIA",
  "PERMISO_RESIDENCIA",
  "JUSTIFICANTE",
  "OTRO",
];

const buildFileUrl = (ruta) => {
  if (!ruta) return "";
  return ruta.startsWith("http") ? ruta : `${window.location.origin}${ruta}`;
};

export default function DocumentosAlumnoAdmin() {
  const [rows, setRows] = useState([]);
  const [searchAlumno, setSearchAlumno] = useState("");
  const [tipoFiltro, setTipoFiltro] = useState("TODOS");
  const [estadoFiltro, setEstadoFiltro] = useState("TODOS");
  const [notification, setNotification] = useState({
    open: false,
    message: "",
    severity: "success",
  });

  const loadDocuments = async (
    search = searchAlumno,
    tipo = tipoFiltro,
    estado = estadoFiltro,
  ) => {
    try {
      const data = await documentosAlumnoService.getAllAdmin({
        search,
        tipo,
        estado,
      });
      setRows(data);
    } catch (error) {
      console.error(error);
      setNotification({
        open: true,
        message: "No se pudieron cargar los documentos",
        severity: "error",
      });
    }
  };

  useEffect(() => {
    loadDocuments();
  }, [searchAlumno, tipoFiltro, estadoFiltro]);

  const handleValidate = async (id) => {
    try {
      await documentosAlumnoService.validate(id, "VALIDADO");
      setNotification({
        open: true,
        message: "Documento validado correctamente",
        severity: "success",
      });
      await loadDocuments(searchAlumno, tipoFiltro, estadoFiltro);
    } catch (error) {
      setNotification({
        open: true,
        message:
          error.response?.data?.message || "No se pudo validar el documento",
        severity: "error",
      });
    }
  };

  const handleReject = async (id) => {
    try {
      await documentosAlumnoService.validate(id, "RECHAZADO");
      setNotification({
        open: true,
        message: "Documento rechazado correctamente",
        severity: "warning",
      });
      await loadDocuments(searchAlumno, tipoFiltro, estadoFiltro);
    } catch (error) {
      setNotification({
        open: true,
        message:
          error.response?.data?.message || "No se pudo rechazar el documento",
        severity: "error",
      });
    }
  };

  const columns = useMemo(
    () => [
      {
        field: "alumno",
        headerName: "Alumno",
        flex: 1.5,
        valueGetter: (_, row) => row.alumno?.usuario?.nombre || "-",
      },
      { field: "tipo", headerName: "Tipo", flex: 1.1 },
      {
        field: "estado",
        headerName: "Estado",
        flex: 1,
        renderCell: (params) => (
          <Chip
            label={ESTADOS[params.value] || params.value}
            size="small"
            sx={{
              fontWeight: "bold", // Estilo común opcional

              // Aplicación dinámica de estilos según el valor
              ...(params.value === "VALIDADO" && {
                backgroundColor: "#e8f5e9", // Verde claro
                color: "#2e7d32", // Verde oscuro
                border: "1px solid #2e7d32", // Borde verde
              }),

              ...(params.value === "RECHAZADO" && {
                backgroundColor: "#ffebee", // Rojo claro
                color: "#c62828", // Rojo oscuro
                border: "1px solid #c62828", // Borde rojo
              }),

              // Estado por defecto (Warning / Pendiente)
              ...(params.value !== "VALIDADO" &&
                params.value !== "RECHAZADO" && {
                  backgroundColor: "#fff3e0", // Naranja/Amarillo claro
                  color: "#ef6c00", // Naranja oscuro
                  border: "1px solid #ef6c00", // Borde naranja
                }),
            }}
          />
        ),
      },
      {
        field: "observaciones",
        headerName: "Observaciones",
        flex: 1.2,
        valueGetter: (_, row) => row.observaciones || "-",
      },
      {
        field: "archivos",
        headerName: "Archivos",
        flex: 1.4,
        renderCell: (params) => (
          <Stack direction="row" spacing={0.75} flexWrap="wrap" useFlexGap>
            {(params.row.archivos || []).map((archivo) => (
              <Link
                key={archivo.id}
                component="button"
                variant="body2"
                color="#C00000" /* Color del texto */
                underline="none" /* Cambia a "hover" si  quieres que se subraye al pasar el ratón */
                onClick={() =>
                  window.open(buildFileUrl(archivo.ruta), "_blank")
                }
                sx={{
                  mt: 2,
                  textAlign: "left",
                }} /* Evita problemas de alineación si el texto es largo */
              >
                {archivo.nombreOriginal}
              </Link>
            ))}
          </Stack>
        ),
      },
      {
        field: "createdAt",
        headerName: "Fecha alta",
        flex: 0.9,
        valueGetter: (_, row) =>
          new Date(row.createdAt).toLocaleDateString("es-ES"),
      },
      {
        field: "acciones",
        headerName: "Acciones",
        sortable: false,
        filterable: false,
        disableColumnMenu: true,
        flex: 1.2,
        renderCell: (params) => (
          <Stack direction="row" spacing={1}>
            <Tooltip title="Validar documento" arrow>
              <span>
                <IconButton
                  color="success"
                  size="small"
                  aria-label="Validar documento"
                  disabled={params.row.estado === "VALIDADO"}
                  onClick={() => handleValidate(params.row.id)}
                >
                  <CheckCircleIcon />
                </IconButton>
              </span>
            </Tooltip>
            <Tooltip title="Rechazar documento" arrow>
              <span>
                <IconButton
                  color="error"
                  size="small"
                  aria-label="Rechazar documento"
                  disabled={params.row.estado === "RECHAZADO"}
                  onClick={() => handleReject(params.row.id)}
                >
                  <CancelIcon />
                </IconButton>
              </span>
            </Tooltip>
          </Stack>
        ),
      },
    ],
    [],
  );

  return (
    <Box>
      <Typography variant="h4">Documentos de alumnos</Typography>
      <Typography color="text.secondary" sx={{ mb: 2 }}>
        Almacena y verifica los expedientes, certificados médicos, psicotécnicos
        y documentación oficial de cada estudiante.
      </Typography>

      <Stack
        direction={{ xs: "column", md: "row" }}
        spacing={1.5}
        sx={{ mb: 2 }}
      >
        <TextField
          size="small"
          label="Buscar alumno"
          placeholder="Nombre, DNI o email"
          value={searchAlumno}
          onChange={(event) => setSearchAlumno(event.target.value)}
          sx={{ minWidth: 280 }}
        />

        <FormControl size="small" sx={{ minWidth: 220 }}>
          <InputLabel>Tipo</InputLabel>
          <Select
            label="Tipo"
            value={tipoFiltro}
            onChange={(event) => setTipoFiltro(event.target.value)}
          >
            {TIPOS_DOCUMENTO.map((tipo) => (
              <MenuItem key={tipo} value={tipo}>
                {tipo}
              </MenuItem>
            ))}
          </Select>
        </FormControl>

        <FormControl size="small" sx={{ minWidth: 220 }}>
          <InputLabel>Estado</InputLabel>
          <Select
            label="Estado"
            value={estadoFiltro}
            onChange={(event) => setEstadoFiltro(event.target.value)}
          >
            {Object.keys(ESTADOS).map((estado) => (
              <MenuItem key={estado} value={estado}>
                {ESTADOS[estado]}
              </MenuItem>
            ))}
          </Select>
        </FormControl>
      </Stack>

      {rows.length === 0 ? (
        <Alert severity="info">No hay documentos pendientes de validar.</Alert>
      ) : (
        <Box sx={{ height: 700 }}>
          <DataGrid
            rows={rows}
            columns={columns}
            getRowId={(row) => row.id}
            disableRowSelectionOnClick
            pageSizeOptions={[10, 25, 50]}
            initialState={{
              pagination: { paginationModel: { pageSize: 10, page: 0 } },
              sorting: { sortModel: [{ field: "alumno", sort: "asc" }] },
            }}
          />
        </Box>
      )}

      <Snackbar
        open={notification.open}
        autoHideDuration={3500}
        onClose={() => setNotification((prev) => ({ ...prev, open: false }))}
        anchorOrigin={{ vertical: "top", horizontal: "right" }}
      >
        <Alert
          severity={notification.severity}
          variant="filled"
          onClose={() => setNotification((prev) => ({ ...prev, open: false }))}
        >
          {notification.message}
        </Alert>
      </Snackbar>
    </Box>
  );
}

import { useEffect, useMemo, useState } from "react";
import {
  Alert,
  Box,
  Button,
  Chip,
  Divider,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Paper,
  Snackbar,
  Stack,
  Typography,
} from "@mui/material";
import { DataGrid } from "@mui/x-data-grid";
import CheckCircleIcon from "@mui/icons-material/CheckCircle";
import DirectionsCarIcon from "@mui/icons-material/DirectionsCar";
import LocalOfferIcon from "@mui/icons-material/LocalOffer";
import { solicitudesExamenService } from "../../services/solicitudesExamenService";
import Tooltip from "@mui/material/Tooltip"; // Asegúrate de importar el componente

const WEEK_DAYS = ["L", "M", "X", "J", "V", "S", "D"];

const pad2 = (value) => String(value).padStart(2, "0");

const toLocalDateKey = (date) =>
  `${date.getFullYear()}-${pad2(date.getMonth() + 1)}-${pad2(date.getDate())}`;

const extractDateKey = (value) => {
  if (!value) return "";

  if (typeof value === "string") {
    const [datePart] = value.split("T");
    if (/^\d{4}-\d{2}-\d{2}$/.test(datePart)) {
      return datePart;
    }
  }

  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "";
  return toLocalDateKey(date);
};

const getDateKey = (value) => {
  return extractDateKey(value);
};

const formatDate = (value) => {
  const dateKey = extractDateKey(value);
  if (!dateKey) return "-";

  const [year, month, day] = dateKey.split("-");
  return `${day}/${month}/${year}`;
};

const canCancelTheoreticalRequest = (row) => {
  const estado = String(row?.estado || "").toUpperCase();
  if (!["SOLICITADO", "PROGRAMADO", "PENDIENTE"].includes(estado)) {
    return false;
  }

  const fecha = new Date(row?.fechaProgramada || 0);
  if (Number.isNaN(fecha.getTime())) {
    return false;
  }

  const horasRestantes = (fecha.getTime() - Date.now()) / (1000 * 60 * 60);

  return horasRestantes > 24;
};

const buildMonthGrid = (viewDate) => {
  const year = viewDate.getFullYear();
  const month = viewDate.getMonth();
  const firstDay = new Date(year, month, 1);
  const daysInMonth = new Date(year, month + 1, 0).getDate();

  const startOffset = (firstDay.getDay() + 6) % 7;
  const cells = [];

  for (let i = 0; i < startOffset; i += 1) {
    cells.push(null);
  }

  for (let day = 1; day <= daysInMonth; day += 1) {
    cells.push(new Date(year, month, day));
  }

  while (cells.length % 7 !== 0) {
    cells.push(null);
  }

  return cells;
};

export default function ExamenTeoricoAlumno() {
  const [eligibility, setEligibility] = useState(null);
  const [calendarDates, setCalendarDates] = useState([]);
  const [myRequests, setMyRequests] = useState([]);
  const [hasObtainedLicense, setHasObtainedLicense] = useState(false);
  const [viewDate, setViewDate] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState(null);
  const [loading, setLoading] = useState(false);
  const [selectedExam, setSelectedExam] = useState(null);
  const [openExamModal, setOpenExamModal] = useState(false);
  const [notification, setNotification] = useState({
    open: false,
    message: "",
    severity: "success",
  });

  const loadData = async () => {
    setLoading(true);
    try {
      const [eligibilityData, calendarData, mineData] = await Promise.all([
        solicitudesExamenService.getTheoreticalEligibility(),
        solicitudesExamenService.getTheoreticalCalendar(),
        solicitudesExamenService.getMine(),
      ]);

      setEligibility(eligibilityData);
      setCalendarDates(calendarData.fechas || []);
      const normalizedMineData = mineData || [];

      setMyRequests(
        normalizedMineData.filter((item) => item.tipo === "TEORICO"),
      );
      setHasObtainedLicense(
        normalizedMineData.some(
          (item) =>
            String(item?.tipo || "").toUpperCase() === "PRACTICO" &&
            String(item?.estado || "").toUpperCase() === "APTO",
        ),
      );
    } catch (error) {
      setNotification({
        open: true,
        message:
          error.response?.data?.message ||
          "No se pudo cargar la convocatoria teórica",
        severity: "error",
      });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  const availableDateSet = useMemo(() => {
    const set = new Set();
    calendarDates.forEach((item) => {
      set.add(getDateKey(item.fecha));
    });
    return set;
  }, [calendarDates]);

  const monthGrid = useMemo(() => buildMonthGrid(viewDate), [viewDate]);

  const canRequest = Boolean(eligibility?.canRequest);
  const hasApprovedTheory = useMemo(
    () => myRequests.some((item) => item.estado === "APTO"),
    [myRequests],
  );
  const shouldShowRequirements =
    Boolean(eligibility) && !hasApprovedTheory && !hasObtainedLicense;

  const columns = [
    {
      field: "fechaProgramada",
      headerName: "Fecha examen",
      flex: 1,
      valueGetter: (_, row) => formatDate(row.fechaProgramada),
    },
    {
      field: "estado",
      headerName: "Estado",
      flex: 1,
      renderCell: (params) => {
        const color =
          params.value === "APTO"
            ? "success"
            : ["NO_APTO", "NO_PRESENTADO", "CANCELADO"].includes(params.value)
              ? "error"
              : "warning";
        return <Chip size="small" label={params.value} color={color} />;
      },
    },
    {
      field: "erroresExamen",
      headerName: "Errores",
      width: 120,
      valueGetter: (_, row) =>
        row.erroresExamen === null || row.erroresExamen === undefined
          ? "-"
          : row.erroresExamen,
    },
    {
      field: "fechaSolicitud",
      headerName: "Solicitado",
      flex: 1,
      valueGetter: (_, row) => formatDate(row.fechaSolicitud),
    },
  ];

  const handleRequest = async () => {
    if (!selectedDate) {
      setNotification({
        open: true,
        message: "Selecciona una fecha del calendario DGT",
        severity: "warning",
      });
      return;
    }

    try {
      await solicitudesExamenService.requestTheoreticalExam({
        fechaProgramada: selectedDate,
      });

      setNotification({
        open: true,
        message: "Convocatoria solicitada correctamente",
        severity: "success",
      });
      setSelectedDate(null);
      await loadData();
    } catch (error) {
      setNotification({
        open: true,
        message:
          error.response?.data?.message ||
          "No se pudo registrar la solicitud de examen teórico",
        severity: "error",
      });
    }
  };

  const handleOpenExamModal = (row) => {
    setSelectedExam(row);
    setOpenExamModal(true);
  };

  const handleCloseExamModal = () => {
    setOpenExamModal(false);
    setSelectedExam(null);
  };

  const handleCancelRequest = async () => {
    if (!selectedExam?.id) {
      return;
    }

    try {
      await solicitudesExamenService.cancelTheoreticalRequest(selectedExam.id);

      setNotification({
        open: true,
        message: "Solicitud teórica cancelada correctamente",
        severity: "success",
      });

      handleCloseExamModal();
      await loadData();
    } catch (error) {
      setNotification({
        open: true,
        message:
          error.response?.data?.message ||
          "No se pudo cancelar la convocatoria teórica",
        severity: "error",
      });
    }
  };

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" sx={{ fontWeight: 700, mb: 1 }}>
        Convocatoria examen teórico
      </Typography>
      <Typography variant="body1" color="text.secondary" sx={{ mb: 3 }}>
        Revisa requisitos, elige una fecha oficial de la DGT y solicita tu
        convocatoria.
      </Typography>

      {shouldShowRequirements && (
        <Paper sx={{ p: 2.5, mb: 3, border: "1px solid #e2e8f0" }}>
          <Typography variant="h6" sx={{ mb: 1.5 }}>
            Estado de requisitos
          </Typography>
          <Stack
            direction="row"
            spacing={1}
            useFlexGap
            flexWrap="wrap"
            sx={{ mb: 1.5 }}
          >
            <Chip
              label={
                eligibility.checks?.matriculaPagada
                  ? "Matrícula pagada"
                  : "Matrícula pendiente"
              }
              color={
                eligibility.checks?.matriculaPagada ? "success" : "warning"
              }
            />
            <Chip
              label={
                eligibility.checks?.psicotecnicoValidado
                  ? "Psicotécnico validado"
                  : "Psicotécnico pendiente"
              }
              color={
                eligibility.checks?.psicotecnicoValidado ? "success" : "warning"
              }
            />
            <Chip
              label={
                eligibility.checks?.tasaPagada
                  ? "Tasa DGT pagada"
                  : "Tasa DGT pendiente"
              }
              color={eligibility.checks?.tasaPagada ? "success" : "warning"}
            />
            <Chip
              label={`Vidas restantes: ${eligibility.tasa?.convocatoriasDisponibles ?? 0}`}
              color={
                eligibility.checks?.convocatoriasDisponibles
                  ? "success"
                  : "warning"
              }
            />
          </Stack>

          {!canRequest &&
            (eligibility.bloqueos || []).map((bloqueo) => (
              <Alert key={bloqueo} severity="warning" sx={{ mb: 1 }}>
                {bloqueo}
              </Alert>
            ))}

          {canRequest && (
            <Alert severity="success">
              Cumples todos los requisitos para solicitar convocatoria teórica.
            </Alert>
          )}
        </Paper>
      )}

      {hasApprovedTheory ? (
        <Paper
          sx={{
            p: 2.5,
            mb: 3,
            border: "1px solid #bbf7d0",
            backgroundColor: "#f0fdf4",
          }}
        >
          <Stack
            direction="row"
            spacing={1.5}
            alignItems="center"
            sx={{ mb: 1 }}
          >
            <CheckCircleIcon color="success" />
            <Typography variant="h6" sx={{ fontWeight: 700, color: "#166534" }}>
              Enhorabuena, ya has aprobado el teórico
            </Typography>
          </Stack>

          <Typography variant="body1" sx={{ mb: 2 }}>
            Ya no necesitas solicitar nuevas convocatorias teóricas. Ahora
            puedes empezar con tu preparación práctica.
          </Typography>

          <Stack spacing={1.2}>
            <Alert
              icon={<DirectionsCarIcon fontSize="inherit" />}
              severity="info"
              variant="outlined"
            >
              Ya puedes comenzar a solicitar y organizar tus clases prácticas
              con tu profesor.
            </Alert>
            <Alert
              icon={<LocalOfferIcon fontSize="inherit" />}
              severity="info"
              variant="outlined"
            >
              Consulta los bonos de prácticas disponibles: suelen ofrecer un
              mejor precio por clase al comprarlos en pack.
            </Alert>
            <Alert severity="success" variant="outlined">
              Recomendación: habla con secretaría para planificar un itinerario
              de clases y elegir el bono más conveniente según tu
              disponibilidad.
            </Alert>
          </Stack>
        </Paper>
      ) : (
        <Paper sx={{ p: 2.5, mb: 3, border: "1px solid #e2e8f0" }}>
          <Stack
            direction={{ xs: "column", sm: "row" }}
            justifyContent="space-between"
            alignItems={{ xs: "flex-start", sm: "center" }}
            spacing={1}
            sx={{ mb: 2 }}
          >
            <Typography variant="h6">
              Calendario de convocatorias DGT
            </Typography>
            <Stack direction="row" spacing={1}>
              <Button
                size="small"
                variant="outlined"
                onClick={() => {
                  const prev = new Date(viewDate);
                  prev.setMonth(prev.getMonth() - 1);
                  setViewDate(prev);
                }}
              >
                Mes anterior
              </Button>
              <Button
                size="small"
                variant="outlined"
                onClick={() => {
                  const next = new Date(viewDate);
                  next.setMonth(next.getMonth() + 1);
                  setViewDate(next);
                }}
              >
                Mes siguiente
              </Button>
            </Stack>
          </Stack>

          <Typography variant="subtitle1" sx={{ mb: 1.5, fontWeight: 600 }}>
            {viewDate.toLocaleDateString("es-ES", {
              month: "long",
              year: "numeric",
            })}
          </Typography>

          <Box
            sx={{
              display: "grid",
              gridTemplateColumns: "repeat(7, minmax(0, 1fr))",
              gap: 1,
            }}
          >
            {WEEK_DAYS.map((label) => (
              <Box
                key={label}
                sx={{
                  textAlign: "center",
                  fontWeight: 700,
                  color: "text.secondary",
                }}
              >
                {label}
              </Box>
            ))}

            {monthGrid.map((cell, index) => {
              if (!cell) {
                return <Box key={`empty-${index}`} sx={{ height: 44 }} />;
              }

              const key = toLocalDateKey(cell);
              const isAvailable = availableDateSet.has(key);
              const isSelected = selectedDate === key;

              return (
                <Button
                  key={key}
                  variant={isSelected ? "contained" : "outlined"}
                  color={isAvailable ? "primary" : "inherit"}
                  disabled={!isAvailable || !canRequest || loading}
                  onClick={() => setSelectedDate(key)}
                  sx={{ minWidth: 0, height: 44 }}
                >
                  {cell.getDate()}
                </Button>
              );
            })}
          </Box>

          <Divider sx={{ my: 2 }} />

          <Stack
            direction={{ xs: "column", sm: "row" }}
            spacing={1}
            alignItems={{ xs: "stretch", sm: "center" }}
          >
            <Typography variant="body2" color="text.secondary" sx={{ flex: 1 }}>
              Fecha seleccionada:{" "}
              {selectedDate ? formatDate(selectedDate) : "ninguna"}
            </Typography>
            <Button
              variant="contained"
              onClick={handleRequest}
              disabled={!canRequest || loading}
            >
              Solicitar convocatoria
            </Button>
          </Stack>
        </Paper>
      )}

      <Paper sx={{ p: 2.5, border: "1px solid #e2e8f0" }}>
        <Typography variant="h6" sx={{ mb: 1.5 }}>
          Mis solicitudes teóricas
        </Typography>
        <DataGrid
          autoHeight
          rows={myRequests}
          columns={columns}
          getRowId={(row) => row.id}
          disableRowSelectionOnClick
          onRowClick={(params) => handleOpenExamModal(params.row)}
          pageSizeOptions={[10, 25, 50]}
          initialState={{
            pagination: { paginationModel: { pageSize: 10, page: 0 } },
            sorting: {
              sortModel: [{ field: "fechaProgramada", sort: "asc" }],
            },
          }}
        />
      </Paper>

      <Dialog
        open={openExamModal}
        onClose={handleCloseExamModal}
        fullWidth
        maxWidth="sm"
      >
        <DialogTitle>Detalle de examen teórico</DialogTitle>
        <DialogContent sx={{ display: "grid", gap: 1, pt: 1 }}>
          <Typography>
            <strong>Fecha programada:</strong>{" "}
            {formatDate(selectedExam?.fechaProgramada)}
          </Typography>
          <Typography>
            <strong>Estado:</strong> {selectedExam?.estado || "-"}
          </Typography>
          <Typography>
            <strong>Errores:</strong> {selectedExam?.erroresExamen ?? "-"}
          </Typography>
          <Typography>
            <strong>Aciertos:</strong> {selectedExam?.aciertosExamen ?? "-"}
          </Typography>
          <Typography>
            <strong>Fecha solicitud:</strong>{" "}
            {formatDate(selectedExam?.fechaSolicitud)}
          </Typography>
          <Typography>
            <strong>Observaciones:</strong> {selectedExam?.observaciones || "-"}
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button
            color="warning"
            onClick={handleCancelRequest}
            disabled={!canCancelTheoreticalRequest(selectedExam)}
          >
            Cancelar convocatoria
          </Button>
          <Button onClick={handleCloseExamModal}>Cerrar</Button>
        </DialogActions>
      </Dialog>

      <Snackbar
        open={notification.open}
        autoHideDuration={4500}
        onClose={() => setNotification((prev) => ({ ...prev, open: false }))}
        anchorOrigin={{ vertical: "bottom", horizontal: "center" }}
      >
        <Alert
          severity={notification.severity}
          onClose={() => setNotification((prev) => ({ ...prev, open: false }))}
          variant="filled"
        >
          {notification.message}
        </Alert>
      </Snackbar>
    </Box>
  );
}

import { useEffect, useMemo, useState } from "react";
import {
  Alert,
  Box,
  Button,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  InputLabel,
  Menu,
  MenuItem,
  Paper,
  Select,
  Snackbar,
  Stack,
  TextField,
  Typography,
} from "@mui/material";
import VisibilityIcon from "@mui/icons-material/Visibility";
import IconButton from "@mui/material/IconButton";
import Tooltip from "@mui/material/Tooltip";
import { DataGrid } from "@mui/x-data-grid";

import DownloadIcon from "@mui/icons-material/Download";
import { evaluacionExamenesService } from "../../services/evaluacionExamenesService";
import { LicenseChip } from "../../components/common/LicenseChip";
import { ExamTypeChip } from "../../components/common/ExamTypeChip";
import { exportExamenesExcel } from "../../utils/exportExamenesExcel";
import { exportExamenesPdf } from "../../utils/exportExamenesPdf";

const formatDate = (value) => {
  if (!value) return "-";

  return new Intl.DateTimeFormat("es-ES", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
  }).format(new Date(value));
};

const stateToColor = (estado) => {
  if (estado === "APTO" || estado === "APROBADO") return "success";
  if (estado === "NO_APTO" || estado === "SUSPENSO") return "error";
  if (estado === "CANCELADO") return "secondary";
  return "warning";
};

export default function Examenes() {
  const [rows, setRows] = useState([]);
  const [selectedRow, setSelectedRow] = useState(null);
  const [openDetail, setOpenDetail] = useState(false);
  const [notification, setNotification] = useState({
    open: false,
    message: "",
    severity: "success",
  });

  const [fechaDesde, setFechaDesde] = useState("");
  const [fechaHasta, setFechaHasta] = useState("");
  const [licenciaFiltro, setLicenciaFiltro] = useState("TODAS");
  const [exportAnchorEl, setExportAnchorEl] = useState(null);
  const [estadoFiltro, setEstadoFiltro] = useState("TODOS");
  const [tipoFiltro, setTipoFiltro] = useState("TODOS");

  const loadData = async () => {
    try {
      const [teorico, practico] = await Promise.all([
        evaluacionExamenesService.getTeorico(),
        evaluacionExamenesService.getPractico(),
      ]);

      setRows([...(teorico || []), ...(practico || [])]);
    } catch (error) {
      setNotification({
        open: true,
        message:
          error.response?.data?.message ||
          "No se pudo cargar la información de exámenes",
        severity: "error",
      });
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  const licencias = useMemo(() => {
    const values = new Set();

    rows.forEach((row) => {
      if (row.permisoLicencia) {
        values.add(row.permisoLicencia);
      }
    });

    return Array.from(values).sort();
  }, [rows]);

  const estados = useMemo(() => {
    const values = new Set();

    rows.forEach((row) => {
      if (row.estado) {
        values.add(row.estado);
      }
    });

    return Array.from(values).sort();
  }, [rows]);

  const estadoOptions = useMemo(() => {
    const values = new Set(["CANCELADO", ...estados]);
    return Array.from(values).sort();
  }, [estados]);

  const tipos = useMemo(() => {
    const values = new Set();

    rows.forEach((row) => {
      if (row.tipo) {
        values.add(row.tipo);
      }
    });

    return Array.from(values).sort();
  }, [rows]);

  const filteredRows = useMemo(() => {
    return rows.filter((row) => {
      const convocatoria = row.fechaConvocatoria
        ? new Date(row.fechaConvocatoria)
        : null;

      if (fechaDesde && convocatoria && convocatoria < new Date(fechaDesde)) {
        return false;
      }

      if (fechaHasta && convocatoria) {
        const end = new Date(fechaHasta);
        end.setHours(23, 59, 59, 999);

        if (convocatoria > end) {
          return false;
        }
      }

      if (
        licenciaFiltro !== "TODAS" &&
        row.permisoLicencia !== licenciaFiltro
      ) {
        return false;
      }

      if (estadoFiltro !== "TODOS" && row.estado !== estadoFiltro) {
        return false;
      }

      if (tipoFiltro !== "TODOS" && row.tipo !== tipoFiltro) {
        return false;
      }

      return true;
    });
  }, [rows, fechaDesde, fechaHasta, licenciaFiltro, estadoFiltro, tipoFiltro]);

  const columns = useMemo(
    () => [
      {
        field: "alumnoNombre",
        headerName: "Alumno",
        flex: 1.2,
      },
      {
        field: "fechaSolicitud",
        headerName: "Fecha solicitud",
        flex: 0.95,
        valueGetter: (_, row) => formatDate(row.fechaSolicitud),
      },
      {
        field: "fechaConvocatoria",
        headerName: "Fecha convocatoria",
        flex: 1,
        valueGetter: (_, row) => formatDate(row.fechaConvocatoria),
      },
      {
        field: "permisoLicencia",
        headerName: "Permiso/Licencia",
        flex: 0.95,
        renderCell: (params) => <LicenseChip value={params.value} />,
      },
      {
        field: "tipo",
        headerName: "Tipo",
        flex: 0.75,
        renderCell: (params) => <ExamTypeChip value={params.value} />,
      },
      {
        field: "estado",
        headerName: "Estado/Resultado",
        flex: 1,
        renderCell: (params) => (
          <Chip
            size="small"
            label={params.value}
            sx={{
              backgroundColor: (theme) => {
                if (params.value === "APTO" || params.value === "APROBADO")
                  return "#e8f5e9";
                if (params.value === "NO_APTO" || params.value === "SUSPENSO")
                  return "#ffebee";
                if (params.value === "CANCELADO") return "#f3e5f5";
                return "#fff8e1"; // default
              },
              color: (theme) => {
                if (params.value === "APTO" || params.value === "APROBADO")
                  return "#2e7d32";
                if (params.value === "NO_APTO" || params.value === "SUSPENSO")
                  return "#c62828";
                if (params.value === "CANCELADO") return "#6a1b9a";
                return "#b78103"; // default
              },
              border: (theme) => {
                if (params.value === "APTO" || params.value === "APROBADO")
                  return "1px solid #4caf50";
                if (params.value === "NO_APTO" || params.value === "SUSPENSO")
                  return "1px solid #ef5350";
                if (params.value === "CANCELADO") return "1px solid #ab47bc";
                return "1px solid #ffb74d"; // default
              },
            }}
          />
        ),
      },
      {
        field: "acciones",
        headerName: "Acciones",
        width: 120,
        sortable: false,
        renderCell: (params) => (
          <Box
            sx={{ width: "100%", display: "flex", justifyContent: "center" }}
          >
            <Tooltip title="Ver detalle" arrow>
              <IconButton
                color="primary"
                onClick={(event) => {
                  event.stopPropagation();
                  setSelectedRow(params.row);
                  setOpenDetail(true);
                }}
              >
                <VisibilityIcon />
              </IconButton>
            </Tooltip>
          </Box>
        ),
      },
    ],
    [],
  );

  const exportMenuOpen = Boolean(exportAnchorEl);

  const handleExportExcel = () => {
    exportExamenesExcel(filteredRows);
    setExportAnchorEl(null);
  };

  const handleExportPdf = () => {
    exportExamenesPdf(filteredRows);
    setExportAnchorEl(null);
  };

  return (
    <Box>
      <Box
        sx={{
          mb: 2,
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          gap: 2,
          flexWrap: "wrap",
        }}
      >
        <Box>
          <Typography variant="h4" fontWeight="bold">
            Exámenes
          </Typography>
          <Typography color="text.secondary">
            Vista unificada de exámenes teóricos y prácticos.
          </Typography>
        </Box>

        <Box>
          <Button
            variant="contained"
            startIcon={<DownloadIcon />}
            onClick={(event) => setExportAnchorEl(event.currentTarget)}
          >
            Exportar
          </Button>
          <Menu
            anchorEl={exportAnchorEl}
            open={exportMenuOpen}
            onClose={() => setExportAnchorEl(null)}
          >
            <MenuItem onClick={handleExportExcel}>Exportar a Excel</MenuItem>
            <MenuItem onClick={handleExportPdf}>Exportar a PDF</MenuItem>
          </Menu>
        </Box>
      </Box>

      <Stack
        direction={{ xs: "column", md: "row" }}
        spacing={1.5}
        sx={{ mb: 2 }}
      >
        <TextField
          size="small"
          label="Convocatoria desde"
          type="date"
          InputLabelProps={{ shrink: true }}
          value={fechaDesde}
          onChange={(event) => setFechaDesde(event.target.value)}
          sx={{
            minWidth: 210,
            // 1. Fuerza a la etiqueta a estar SIEMPRE en color azul
            "& .MuiInputLabel-root": {
              color: "rgb(0, 0, 0) !important",
            },
            // 2. Fuerza al borde/muesca exterior a estar SIEMPRE en color azul
            "& .MuiOutlinedInput-notchedOutline": {
              borderColor: "#1976d2 !important",
              borderWidth: "1px",
            },
            // 3. Mantiene el color azul si pasas el ratón por encima (Hover)
            "& :hover .MuiOutlinedInput-notchedOutline": {
              borderColor: "#1976d2 !important",
            },
            // 4. CONTROL DINÁMICO DEL FORMATO dd/mm/aaaa:
            // Oculto por defecto si no hay fecha informada
            "& input::-webkit-datetime-edit": {
              color: fechaDesde ? "inherit" : "transparent",
            },
            // Se muestra en color gris cuando el campo recibe el foco (haces clic dentro)
            "& .MuiInputBase-root.Mui-focused input::-webkit-datetime-edit": {
              color: fechaDesde ? "inherit" : "rgba(0, 0, 0, 0.42)",
            },
            // 5. Ajuste de espaciado interno
            "& .MuiInputBase-input": {
              pt: 1.5,
            },
          }}
        />

        <TextField
          size="small"
          label="Convocatoria hasta"
          type="date"
          InputLabelProps={{ shrink: true }}
          value={fechaHasta}
          onChange={(event) => setFechaHasta(event.target.value)}
          sx={{
            minWidth: 210,
            // 1. Fuerza a la etiqueta a estar SIEMPRE en color azul
            "& .MuiInputLabel-root": {
              color: "rgb(0, 0, 0) !important",
            },
            // 2. Fuerza al borde/muesca exterior a estar SIEMPRE en color azul
            "& .MuiOutlinedInput-notchedOutline": {
              borderColor: "#1976d2 !important",
              borderWidth: "1px",
            },
            // 3. Mantiene el color azul si pasas el ratón por encima (Hover)
            "& :hover .MuiOutlinedInput-notchedOutline": {
              borderColor: "#1976d2 !important",
            },
            // 4. CONTROL DINÁMICO DEL FORMATO dd/mm/aaaa:
            // Oculto por defecto si no hay fecha informada
            "& input::-webkit-datetime-edit": {
              color: fechaHasta ? "inherit" : "transparent",
            },
            // Se muestra en color gris cuando el campo recibe el foco (haces clic dentro)
            "& .MuiInputBase-root.Mui-focused input::-webkit-datetime-edit": {
              color: fechaHasta ? "inherit" : "rgba(0, 0, 0, 0.42)",
            },
            // 5. Ajuste de espaciado interno
            "& .MuiInputBase-input": {
              pt: 1.5,
            },
          }}
        />

        <FormControl size="small" sx={{ minWidth: 220 }}>
          <InputLabel>Licencia</InputLabel>
          <Select
            label="Licencia"
            value={licenciaFiltro}
            onChange={(event) => setLicenciaFiltro(event.target.value)}
          >
            <MenuItem value="TODAS">Todas</MenuItem>
            {licencias.map((licencia) => (
              <MenuItem key={licencia} value={licencia}>
                {licencia}
              </MenuItem>
            ))}
          </Select>
        </FormControl>

        <FormControl size="small" sx={{ minWidth: 220 }}>
          <InputLabel>Estado/Resultado</InputLabel>
          <Select
            label="Estado/Resultado"
            value={estadoFiltro}
            onChange={(event) => setEstadoFiltro(event.target.value)}
          >
            <MenuItem value="TODOS">Todos</MenuItem>
            {estadoOptions.map((estado) => (
              <MenuItem key={estado} value={estado}>
                {estado}
              </MenuItem>
            ))}
          </Select>
        </FormControl>

        <FormControl size="small" sx={{ minWidth: 220 }}>
          <InputLabel>Tipo</InputLabel>
          <Select
            label="Tipo"
            value={tipoFiltro}
            onChange={(event) => setTipoFiltro(event.target.value)}
          >
            <MenuItem value="TODOS">Todos</MenuItem>
            {tipos.map((tipo) => (
              <MenuItem key={tipo} value={tipo}>
                {tipo}
              </MenuItem>
            ))}
          </Select>
        </FormControl>
      </Stack>

      <Box sx={{ height: 700 }}>
        <DataGrid
          rows={filteredRows}
          columns={columns}
          getRowId={(row) => row.id}
          disableRowSelectionOnClick
          onRowClick={(params) => {
            setSelectedRow(params.row);
            setOpenDetail(true);
          }}
          pageSizeOptions={[10, 25, 50]}
          initialState={{
            pagination: { paginationModel: { pageSize: 10, page: 0 } },
            sorting: {
              sortModel: [{ field: "fechaConvocatoria", sort: "desc" }],
            },
          }}
        />
      </Box>

      <Dialog
        open={openDetail}
        onClose={() => setOpenDetail(false)}
        fullWidth
        maxWidth="md"
      >
        <DialogTitle>Detalle de examen</DialogTitle>
        <DialogContent>
          {!selectedRow ? null : (
            <Stack spacing={2} sx={{ pt: 1 }}>
              <Paper variant="outlined" sx={{ p: 2 }}>
                <Typography variant="subtitle2" color="text.secondary">
                  Información general
                </Typography>
                <Stack
                  direction={{ xs: "column", md: "row" }}
                  spacing={2}
                  sx={{ mt: 1 }}
                >
                  <Box sx={{ flex: 1 }}>
                    <Typography variant="body2" color="text.secondary">
                      Alumno
                    </Typography>
                    <Typography fontWeight={700}>
                      {selectedRow.alumnoNombre || "-"}
                    </Typography>
                  </Box>
                  <Box sx={{ flex: 1 }}>
                    <Typography variant="body2" color="text.secondary">
                      Permiso/Licencia
                    </Typography>
                    <LicenseChip value={selectedRow.permisoLicencia} />
                  </Box>
                  <Box sx={{ flex: 1 }}>
                    <Typography variant="body2" color="text.secondary">
                      Tipo
                    </Typography>
                    <Chip
                      size="small"
                      label={selectedRow.tipo || "-"}
                      sx={{
                        fontWeight: 700,
                        backgroundColor:
                          selectedRow.tipo === "PRACTICO"
                            ? "#ffedd5"
                            : "#dbeafe",
                        color:
                          selectedRow.tipo === "PRACTICO"
                            ? "#c2410c"
                            : "#1e40af",
                        border:
                          selectedRow.tipo === "PRACTICO"
                            ? "1px solid #fed7aa"
                            : "1px solid #93c5fd",
                      }}
                    />
                  </Box>
                </Stack>
              </Paper>

              <Paper variant="outlined" sx={{ p: 2 }}>
                <Typography variant="subtitle2" color="text.secondary">
                  Convocatoria y resultado
                </Typography>
                <Stack
                  direction={{ xs: "column", md: "row" }}
                  spacing={2}
                  sx={{ mt: 1 }}
                >
                  <Box sx={{ flex: 1 }}>
                    <Typography variant="body2" color="text.secondary">
                      Fecha solicitud
                    </Typography>
                    <Typography>
                      {formatDate(selectedRow.fechaSolicitud)}
                    </Typography>
                  </Box>
                  <Box sx={{ flex: 1 }}>
                    <Typography variant="body2" color="text.secondary">
                      Fecha convocatoria
                    </Typography>
                    <Typography>
                      {formatDate(selectedRow.fechaConvocatoria)}
                    </Typography>
                  </Box>
                  <Box sx={{ flex: 1 }}>
                    <Typography variant="body2" color="text.secondary">
                      Estado/Resultado
                    </Typography>
                    {(() => {
                      const estado = selectedRow.estado;
                      let bgColor, borderColor, textColor;

                      switch (estado) {
                        case "APTO":
                        case "APROBADO":
                          bgColor = "#e8f5e9";
                          borderColor = "#4caf50";
                          textColor = "#2e7d32";
                          break;
                        case "NO_APTO":
                        case "SUSPENSO":
                          bgColor = "#ffebee";
                          borderColor = "#ef5350";
                          textColor = "#c62828";
                          break;
                        case "CANCELADO":
                          bgColor = "#f3e5f5";
                          borderColor = "#ab47bc";
                          textColor = "#6a1b9a";
                          break;
                        default:
                          // Estado por defecto (warning / pendiente) o si viene vacío/null
                          bgColor = "#fff8e1";
                          borderColor = "#ffb74d";
                          textColor = "#b78103";
                      }

                      return (
                        <Chip
                          size="small"
                          label={estado || "-"}
                          sx={{
                            backgroundColor: bgColor,
                            color: textColor,
                            border: `1px solid ${borderColor}`,
                            fontWeight: 500,
                          }}
                        />
                      );
                    })()}
                  </Box>
                </Stack>
              </Paper>

              <Paper variant="outlined" sx={{ p: 2 }}>
                <Typography variant="subtitle2" color="text.secondary">
                  Datos del examen
                </Typography>
                <Stack
                  direction={{ xs: "column", md: "row" }}
                  spacing={2}
                  sx={{ mt: 1 }}
                >
                  <Typography variant="body2">
                    <strong>Número de convocatoria:</strong>{" "}
                    {selectedRow.numeroIntento ?? "-"}
                  </Typography>
                  <Typography variant="body2">
                    <strong>Convocatorias restantes:</strong>{" "}
                    {selectedRow.convocatoriasRestantes ?? "-"}
                  </Typography>
                  <Typography variant="body2">
                    <strong>Profesor:</strong>{" "}
                    {selectedRow.profesorAsignado || "Sin asignar"}
                  </Typography>
                </Stack>

                {selectedRow.tipo === "PRACTICO" ? (
                  <Stack
                    direction={{ xs: "column", md: "row" }}
                    spacing={2}
                    sx={{ mt: 1 }}
                  >
                    <Chip
                      size="small"
                      label={`Leves: ${selectedRow.faltasLeves ?? "-"}`}
                      sx={{
                        fontWeight: 700,
                        backgroundColor: "#dcfce7", // Verde claro
                        color: "#15803d", // Verde oscuro
                        border: "1px solid #86efac", // Borde verde
                      }}
                    />
                    <Chip
                      size="small"
                      label={`Deficientes: ${selectedRow.faltasDeficientes ?? "-"}`}
                      sx={{
                        fontWeight: 700,
                        backgroundColor: "#ffedd5", // Naranja claro
                        color: "#c2410c", // Naranja oscuro
                        border: "1px solid #fed7aa", // Borde naranja
                      }}
                    />
                    <Chip
                      size="small"
                      label={`Eliminatorias: ${selectedRow.faltasEliminatorias ?? "-"}`}
                      sx={{
                        fontWeight: 700,
                        backgroundColor: "#fee2e2", // Rojo claro
                        color: "#b91c1c", // Rojo oscuro
                        border: "1px solid #fca5a5", // Borde rojo
                      }}
                    />
                  </Stack>
                ) : (
                  <Stack
                    direction={{ xs: "column", md: "row" }}
                    spacing={2}
                    sx={{ mt: 1 }}
                  >
                    <Chip
                      size="small"
                      label={`Aciertos: ${selectedRow.aciertosExamen ?? "-"}`}
                      sx={{
                        fontWeight: 700,
                        backgroundColor: "#dcfce7", // Verde claro
                        color: "#15803d", // Verde oscuro
                        border: "1px solid #86efac", // Borde verde
                      }}
                    />
                    <Chip
                      size="small"
                      label={`Fallos: ${selectedRow.erroresExamen ?? "-"}`}
                      sx={{
                        fontWeight: 700,
                        backgroundColor: "#fee2e2", // Rojo claro
                        color: "#b91c1c", // Rojo oscuro
                        border: "1px solid #fca5a5", // Borde rojo
                      }}
                    />
                  </Stack>
                )}
              </Paper>

              <Paper variant="outlined" sx={{ p: 2 }}>
                {/*<Typography variant="subtitle2" color="text.secondary">
                  Observaciones
                </Typography>
                <Typography sx={{ mt: 1 }}>
                  {selectedRow.observaciones || "Sin observaciones"}
                </Typography>*/}
                {selectedRow.motivoNoApto ? (
                  <Typography sx={{ mt: 1 }}>
                    <strong>Motivo no apto:</strong> {selectedRow.motivoNoApto}
                  </Typography>
                ) : null}
              </Paper>
            </Stack>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenDetail(false)}>Cerrar</Button>
        </DialogActions>
      </Dialog>

      <Snackbar
        open={notification.open}
        autoHideDuration={4000}
        onClose={() => setNotification((prev) => ({ ...prev, open: false }))}
      >
        <Alert
          severity={notification.severity}
          onClose={() => setNotification((prev) => ({ ...prev, open: false }))}
          sx={{ width: "100%" }}
        >
          {notification.message}
        </Alert>
      </Snackbar>
    </Box>
  );
}

import { useEffect, useMemo, useState } from "react";
import {
  Alert,
  Box,
  Button,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  IconButton,
  Menu,
  MenuItem,
  Paper,
  Snackbar,
  Stack,
  TextField,
  Tooltip,
  Typography,
} from "@mui/material";
import { DataGrid } from "@mui/x-data-grid";
import VisibilityIcon from "@mui/icons-material/Visibility";
import SendIcon from "@mui/icons-material/Send";
import DownloadIcon from "@mui/icons-material/Download";
import CheckCircleIcon from "@mui/icons-material/CheckCircle";
import CancelIcon from "@mui/icons-material/Cancel";
import { useLocation, useNavigate } from "react-router-dom";
import { jwtDecode } from "jwt-decode";

import { facturasService } from "../../services/facturasService";
import { matriculasService } from "../../services/matriculasService";
import { LicenseChip } from "../../components/common/LicenseChip";
import { PracticalClassTypeChip } from "../../components/common/PracticalClassTypeChip";
import { exportIngresosExcel } from "../../utils/exportIngresosExcel";
import { exportIngresosPdf } from "../../utils/exportIngresosPdf";

const CONCEPTO_OPTIONS = [
  { value: "MATRICULA", label: "Matrícula" },
  { value: "TASA_DGT", label: "Tasa DGT" },
  { value: "EXAMEN_PRACTICO", label: "Examen práctico" },
  { value: "BONO", label: "Bono" },
  { value: "CLASE_PRACTICA", label: "Clase práctica" },
  { value: "OTROS", label: "Otros" },
];

const LICENSE_OPTIONS = ["A1", "A2", "A", "B", "C", "D", "E"];

const TASA_DGT_FIJA = 94.05;

const formatDate = (value) =>
  value ? new Date(value).toLocaleDateString("es-ES") : "-";

const formatCurrency = (value) => `${Number(value || 0).toFixed(2)} EUR`;

const normalizeEstado = (estado) => {
  if (estado === "EMITIDA") {
    return "PENDIENTE";
  }

  return estado;
};

const classifyConcepto = (concepto) => {
  const text = String(concepto || "").toLowerCase();

  if (text.includes("matricul")) {
    return "MATRICULA";
  }

  if (text.includes("tasa") || text.includes("dgt")) {
    return "TASA_DGT";
  }

  if (text.includes("bono")) {
    return "BONO";
  }

  if (text.includes("clase")) {
    return "CLASE_PRACTICA";
  }

  if (
    text.includes("práctic") ||
    text.includes("practic") ||
    text.includes("examen")
  ) {
    return "EXAMEN_PRACTICO";
  }

  return "OTROS";
};

const getRowOrigen = (row) => {
  const category = classifyConcepto(row?.concepto);

  if (category === "TASA_DGT") {
    return "DGT";
  }

  if (category === "EXAMEN_PRACTICO") {
    return "EXAMEN PRÁCTICO";
  }

  if (row?.compraBonoId || row?.clasePracticaId) {
    return "PAGO";
  }

  if (row?.matriculaId) {
    return "MATRÍCULA";
  }

  return "FACTURA";
};

const getRowLicencia = (row) =>
  row?.licenciaInferida ||
  row?.compraBono?.bono?.licencia ||
  row?.clasePractica?.vehiculo?.tipoPermiso ||
  row?.matricula?.licencia ||
  "-";

const getRowPracticalClassType = (row) =>
  row?.clasePractica?.tipoClasePractica || null;

const getBaseAmount = (row) => {
  const category = classifyConcepto(row?.concepto);

  if (category === "TASA_DGT") {
    return TASA_DGT_FIJA;
  }

  if (
    category === "MATRICULA" &&
    row.matricula?.promocion?.precioOriginal !== undefined &&
    row.matricula?.promocion?.precioOriginal !== null
  ) {
    return Number(row.matricula.promocion.precioOriginal);
  }

  return Number(row.baseImponible || 0);
};

const getDiscountAmount = (row) => {
  const category = classifyConcepto(row?.concepto);

  if (category === "TASA_DGT") {
    return 0;
  }

  if (category === "MATRICULA" && row.matricula) {
    const base = getBaseAmount(row);
    const final = Number(row.total || 0);
    const discount = base - final;

    return discount > 0 ? Number(discount.toFixed(2)) : 0;
  }

  return Number(row.descuento || 0);
};

const getFinalAmount = (row) => {
  if (classifyConcepto(row?.concepto) === "TASA_DGT") {
    return TASA_DGT_FIJA;
  }

  return Number(row.total || 0);
};

const matchesValue = (left, right) =>
  String(left || "").trim() !== "" &&
  String(right || "").trim() !== "" &&
  String(left).trim() === String(right).trim();

const resolveFacturaFromSearch = (rows, search) => {
  const params = new URLSearchParams(search);

  if (params.get("openFactura") !== "1") {
    return null;
  }

  const facturaId = params.get("facturaId");
  const numeroFactura = params.get("numeroFactura");
  const matriculaId = params.get("matriculaId");
  const compraBonoId = params.get("compraBonoId");
  const clasePracticaId = params.get("clasePracticaId");

  return (
    rows.find((row) => matchesValue(row.id, facturaId)) ||
    rows.find((row) => matchesValue(row.numero, numeroFactura)) ||
    rows.find((row) => matchesValue(row.compraBonoId, compraBonoId)) ||
    rows.find((row) => matchesValue(row.matriculaId, matriculaId)) ||
    rows.find((row) => matchesValue(row.clasePracticaId, clasePracticaId)) ||
    null
  );
};

const normalizeRole = (role) => {
  if (role === "GESTOR") {
    return "SOPORTE";
  }

  return role;
};

export default function IngresosFacturas() {
  const token = localStorage.getItem("token") || "";
  const location = useLocation();
  const navigate = useNavigate();
  const [currentRole, setCurrentRole] = useState("ADMIN");
  const [rows, setRows] = useState([]);
  const [searchAlumno, setSearchAlumno] = useState("");
  const [conceptoFiltro, setConceptoFiltro] = useState("");
  const [licenciaFiltro, setLicenciaFiltro] = useState("");
  const [fechaDesde, setFechaDesde] = useState("");
  const [fechaHasta, setFechaHasta] = useState("");
  const [focusFechaDesde, setFocusFechaDesde] = useState(false);
  const [focusFechaHasta, setFocusFechaHasta] = useState(false);
  const [tipoFechaDesde, setTipoFechaDesde] = useState("text");
  const [tipoFechaHasta, setTipoFechaHasta] = useState("text");
  const [activeStates, setActiveStates] = useState([]);

  const [previewOpen, setPreviewOpen] = useState(false);
  const [sendOpen, setSendOpen] = useState(false);
  const [loadingPreview, setLoadingPreview] = useState(false);
  const [selectedFactura, setSelectedFactura] = useState(null);
  const [sendFacturaId, setSendFacturaId] = useState(null);
  const [sendEmail, setSendEmail] = useState("");
  const [sending, setSending] = useState(false);
  const [exportAnchor, setExportAnchor] = useState(null);

  const [notification, setNotification] = useState({
    open: false,
    message: "",
    severity: "success",
  });

  useEffect(() => {
    try {
      const decoded = jwtDecode(token);
      setCurrentRole(normalizeRole(decoded?.rol || "ADMIN"));
    } catch {
      setCurrentRole("ADMIN");
    }
  }, [token]);

  const canMutateMatricula = currentRole !== "ADMINISTRATIVO";

  const loadRows = async () => {
    try {
      const data = await facturasService.getAll();
      setRows(data);
    } catch (error) {
      console.error(error);
      setNotification({
        open: true,
        message: "No se pudieron cargar los ingresos",
        severity: "error",
      });
    }
  };

  useEffect(() => {
    loadRows();
  }, []);

  const toggleStateChip = (state) => {
    setActiveStates((prev) =>
      prev.includes(state)
        ? prev.filter((item) => item !== state)
        : [...prev, state],
    );
  };

  const filteredRows = useMemo(() => {
    return rows.filter((row) => {
      const normalizedEstado = normalizeEstado(row.estado);

      if (activeStates.length > 0 && !activeStates.includes(normalizedEstado)) {
        return false;
      }

      const alumnoNombre = String(
        row.alumno?.usuario?.nombre || "",
      ).toLowerCase();
      if (
        searchAlumno.trim() &&
        !alumnoNombre.includes(searchAlumno.trim().toLowerCase())
      ) {
        return false;
      }

      if (conceptoFiltro) {
        const category = classifyConcepto(row.concepto);
        if (category !== conceptoFiltro) {
          return false;
        }
      }

      if (licenciaFiltro) {
        const licenciaRow = String(getRowLicencia(row) || "").toUpperCase();
        if (licenciaRow !== licenciaFiltro) {
          return false;
        }
      }

      const emision = row.fechaEmision ? new Date(row.fechaEmision) : null;
      if (fechaDesde && emision && emision < new Date(fechaDesde)) {
        return false;
      }

      if (fechaHasta && emision) {
        const endDate = new Date(fechaHasta);
        endDate.setHours(23, 59, 59, 999);

        if (emision > endDate) {
          return false;
        }
      }

      return true;
    });
  }, [
    rows,
    activeStates,
    searchAlumno,
    conceptoFiltro,
    licenciaFiltro,
    fechaDesde,
    fechaHasta,
  ]);

  const handleOpenPreview = async (row) => {
    setLoadingPreview(true);
    setPreviewOpen(true);

    try {
      const preview = await facturasService.getPreview(row.id);
      setSelectedFactura(preview);
    } catch (error) {
      console.error(error);
      setSelectedFactura(null);
      setPreviewOpen(false);
      setNotification({
        open: true,
        message:
          error.response?.data?.message || "No se pudo cargar la factura",
        severity: "error",
      });
    } finally {
      setLoadingPreview(false);
    }
  };

  useEffect(() => {
    if (!rows.length) {
      return;
    }

    const params = new URLSearchParams(location.search);

    if (params.get("openFactura") !== "1") {
      return;
    }

    const targetRow = resolveFacturaFromSearch(rows, location.search);

    if (!targetRow) {
      setNotification({
        open: true,
        message: "No se encontró la factura asociada a la notificación",
        severity: "warning",
      });
      navigate("/facturas", { replace: true });
      return;
    }

    handleOpenPreview(targetRow);
    navigate("/facturas", { replace: true });
  }, [rows, location.search]);

  const handleDownloadPdf = async (facturaId) => {
    try {
      const { blob, fileName } = await facturasService.downloadPdf(facturaId);
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement("a");

      link.href = url;
      link.download = fileName;
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);
    } catch (error) {
      console.error(error);
      setNotification({
        open: true,
        message: error.response?.data?.message || "No se pudo descargar el PDF",
        severity: "error",
      });
    }
  };

  const handleOpenSend = (row) => {
    setSendFacturaId(row.id);
    setSendEmail(row.alumno?.usuario?.email || "");
    setSendOpen(true);
  };

  const handleSendDuplicate = async () => {
    setSending(true);

    try {
      await facturasService.sendDuplicate(sendFacturaId, sendEmail);
      setSendOpen(false);
      setNotification({
        open: true,
        message: "Duplicado enviado correctamente",
        severity: "success",
      });
    } catch (error) {
      console.error(error);
      setNotification({
        open: true,
        message:
          error.response?.data?.message ||
          "No se pudo enviar el duplicado de factura",
        severity: "error",
      });
    } finally {
      setSending(false);
    }
  };

  const handlePagarMatricula = async (row) => {
    if (!row.matriculaId) {
      return;
    }

    try {
      await matriculasService.pagar(row.matriculaId);
      await loadRows();
      setNotification({
        open: true,
        message: "Matrícula marcada como pagada",
        severity: "success",
      });
    } catch (error) {
      console.error(error);
      setNotification({
        open: true,
        message:
          error.response?.data?.message || "No se pudo pagar la matrícula",
        severity: "error",
      });
    }
  };

  const handleAnularMatricula = async (row) => {
    if (!row.matriculaId) {
      return;
    }

    try {
      await matriculasService.anular(row.matriculaId);
      await loadRows();
      setNotification({
        open: true,
        message: "Matrícula anulada correctamente",
        severity: "success",
      });
    } catch (error) {
      console.error(error);
      setNotification({
        open: true,
        message:
          error.response?.data?.message || "No se pudo anular la matrícula",
        severity: "error",
      });
    }
  };

  const openExportMenu = (event) => {
    setExportAnchor(event.currentTarget);
  };

  const closeExportMenu = () => {
    setExportAnchor(null);
  };

  const getExportRows = () =>
    filteredRows.map((row) => ({
      "Nº Factura": row.numero || "-",
      Alumno: row.alumno?.usuario?.nombre || "-",
      Licencia: getRowLicencia(row),
      "Tipo clase práctica": getRowPracticalClassType(row) || "-",
      Origen: getRowOrigen(row),
      Concepto: row.concepto || "-",
      "Precio Base": Number(getBaseAmount(row) || 0).toFixed(2),
      Descuento: Number(getDiscountAmount(row) || 0).toFixed(2),
      "Precio Final": Number(getFinalAmount(row) || 0).toFixed(2),
      Estado: normalizeEstado(row.estado),
      "Fecha Emisión": formatDate(row.fechaEmision),
      "Fecha Pago": formatDate(row.fechaPago),
    }));

  const handleExportExcel = () => {
    exportIngresosExcel(getExportRows());
    closeExportMenu();
  };

  const handleExportPdf = () => {
    exportIngresosPdf(getExportRows());
    closeExportMenu();
  };

  const columns = [
    {
      field: "numero",
      headerName: "Nº Factura",
      width: 200, // 💡 Configurable: Cambia este número por los píxeles que necesites
      minWidth: 120, // Opcional: Asegura un ancho mínimo para que el Chip no se corte
    },
    {
      field: "alumno",
      headerName: "Alumno",
      flex: 1.5,
      valueGetter: (_, row) => row.alumno?.usuario?.nombre || "-",
    },
    {
      field: "licencia",
      headerName: "Licencia",
      flex: 0.8,
      sortable: false,
      renderCell: (params) => (
        <LicenseChip value={getRowLicencia(params.row)} />
      ),
    },
    {
      field: "tipoClasePractica",
      headerName: "Tipo clase",
      width: 160,
      sortable: false,
      valueGetter: (_, row) => getRowPracticalClassType(row),
      renderCell: (params) => {
        if (!params.value) {
          return "-";
        }

        return <PracticalClassTypeChip value={params.value} />;
      },
    },
    {
      field: "origen",
      headerName: "Origen",
      width: 180, // 💡 Configurable: Cambia este número por los píxeles que necesites
      minWidth: 120, // Opcional: Asegura un ancho mínimo para que el Chip no se corte
      valueGetter: (_, row) => getRowOrigen(row),
      renderCell: (params) => {
        const origen = params.value;

        // Configuración de colores personalizados para cada origen
        const configEstilos = {
          MATRÍCULA: {
            bg: "#fff3e0", // Naranja pastel muy suave
            border: "#ff9800", // Naranja vibrante
            text: "#e65100", // Naranja oscuro / Óxido
          },
          PAGO: {
            bg: "#fce4ec", // Rosa/Fucsia pastel muy suave (Fondo)
            border: "#f06292", // Rosa medio (Borde)
            text: "#880e4f", // Vino/Fucsia profundo (Texto para máxima legibilidad)
          },
          DGT: {
            bg: "#e1f5fe", // Azul cielo muy claro
            border: "#0288d1", // Azul océano medio
            text: "#01579b", // Azul marino profundo
          },
          "EXAMEN PRÁCTICO": {
            bg: "#f1f8e9", // Verde lima / Manzana muy suave
            border: "#8bc34a", // Verde hoja medio
            text: "#33691e", // Verde bosque profundo
          },
        };

        // Estilos por defecto en caso de que aparezca un origen no mapeado
        const estilos = configEstilos[origen] || {
          bg: "#f5f5f5",
          border: "#9e9e9e",
          text: "#616161",
        };

        return (
          <Chip
            size="small"
            label={origen}
            align="center" // 🎯 Centra el Chip horizontalmente dentro de la celda
            headerAlign="center" // 🎯 Centra también el texto del encabezado "Origen"
            variant="outlined"
            sx={{
              backgroundColor: estilos.bg,
              borderColor: estilos.border,
              color: estilos.text,
              fontWeight: "medium", // Hace que el texto sea un poco más legible
            }}
          />
        );
      },
    },
    {
      field: "concepto",
      headerName: "Concepto",
      flex: 1.9,
    },
    /*
      field: "baseImponible",
      headerName: "Precio Base",
      flex: 0.8,
      valueGetter: (_, row) => getBaseAmount(row),
      valueFormatter: (value) => formatCurrency(value),
    
    
      field: "descuento",
      headerName: "Descuento",
      flex: 0.8,
      valueGetter: (_, row) => getDiscountAmount(row),
      valueFormatter: (value) => formatCurrency(value),
    */
    {
      field: "total",
      headerName: "Precio Final",
      flex: 0.85,
      valueGetter: (_, row) => getFinalAmount(row),
      valueFormatter: (value) => formatCurrency(value),
    },
    {
      field: "estado",
      headerName: "Estado",
      flex: 0.85,
      renderCell: (params) => {
        const estado = normalizeEstado(params.row.estado);

        // 1. Definimos los estilos personalizados para cada estado
        const estilosPorEstado = {
          PAGADA: {
            backgroundColor: "#e8f5e9", // Fondo verde claro
            color: "#2e7d32", // Letra verde oscura
            borderColor: "#2e7d32", // Borde verde
          },
          DEVUELTA: {
            backgroundColor: "#ffebee", // Fondo rojo claro
            color: "#c62828", // Letra roja oscura
            borderColor: "#c62828", // Borde rojo
          },
          PENDIENTE: {
            // O el nombre por defecto que use tu backend/normalizador
            backgroundColor: "#fff3e0", // Fondo naranja claro
            color: "#ef6c00", // Letra naranja oscura
            borderColor: "#ef6c00", // Borde naranja
          },
        };

        // 2. Obtenemos el estilo actual o aplicamos el de por defecto (PENDIENTE)
        const estiloActual =
          estilosPorEstado[estado] || estilosPorEstado.PENDIENTE;

        return (
          <Chip
            size="small"
            label={estado}
            variant="outlined" // Agregamos 'outlined' para que el borde sea visible de forma nativa
            sx={{
              backgroundColor: estiloActual.backgroundColor,
              color: estiloActual.color,
              borderColor: estiloActual.borderColor,
              fontWeight: "bold", // Opcional: hace la letra más legible
            }}
          />
        );
      },
    },

    /*
      field: "fechaEmision",
      headerName: "Fecha Emisión",
      flex: 1,
      valueGetter: (_, row) => formatDate(row.fechaEmision),
    */
    {
      field: "fechaPago",
      headerName: "Fecha Pago",
      flex: 1,
      valueGetter: (_, row) => formatDate(row.fechaPago),
    },
    {
      field: "acciones",
      headerName: "Acciones",
      width: 220,
      sortable: false,
      renderCell: (params) => {
        const estado = normalizeEstado(params.row.estado);
        const isMatricula = Boolean(params.row.matriculaId);
        const disableMatriculaActions =
          !isMatricula || estado === "PAGADA" || estado === "ANULADA";

        return (
          <Stack direction="row" spacing={0.25}>
            <Tooltip title="Ver factura" arrow>
              <IconButton
                color="primary"
                size="small"
                onClick={() => handleOpenPreview(params.row)}
              >
                <VisibilityIcon fontSize="small" />
              </IconButton>
            </Tooltip>

            <Tooltip title="Descargar PDF" arrow>
              <IconButton
                color="info"
                size="small"
                onClick={() => handleDownloadPdf(params.row.id)}
              >
                <DownloadIcon fontSize="small" />
              </IconButton>
            </Tooltip>

            <Tooltip title="Enviar duplicado" arrow>
              <IconButton
                color="secondary"
                size="small"
                onClick={() => handleOpenSend(params.row)}
              >
                <SendIcon fontSize="small" />
              </IconButton>
            </Tooltip>

            {canMutateMatricula ? (
              <Tooltip title="Pagar Factura" arrow>
                <span>
                  <IconButton
                    color="success"
                    size="small"
                    disabled={disableMatriculaActions}
                    onClick={() => handlePagarMatricula(params.row)}
                  >
                    <CheckCircleIcon fontSize="small" />
                  </IconButton>
                </span>
              </Tooltip>
            ) : null}

            {canMutateMatricula ? (
              <Tooltip title="Anular Factura" arrow>
                <span>
                  <IconButton
                    color="error"
                    size="small"
                    disabled={disableMatriculaActions}
                    onClick={() => handleAnularMatricula(params.row)}
                  >
                    <CancelIcon fontSize="small" />
                  </IconButton>
                </span>
              </Tooltip>
            ) : null}
          </Stack>
        );
      },
    },
  ];

  return (
    <Box>
      <Typography variant="h4" mb={1} fontWeight="bold">
        Ingresos y Facturas
      </Typography>

      <Typography color="text.secondary" sx={{ mb: 2 }}>
