        </Stack>
      </CardContent>
    </Card>
  );
}

export default function Informes() {
  const now = new Date();
  const [period, setPeriod] = useState("MONTH");
  const [year, setYear] = useState(String(now.getFullYear()));
  const [month, setMonth] = useState(String(now.getMonth() + 1));
  const [quarter, setQuarter] = useState("1");
  const [dateFrom, setDateFrom] = useState("");
  const [dateTo, setDateTo] = useState("");
  const [focusDateFrom, setFocusDateFrom] = useState(false);
  const [focusDateTo, setFocusDateTo] = useState(false);
  const [dateFromInputType, setDateFromInputType] = useState("text");
  const [dateToInputType, setDateToInputType] = useState("text");

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [report, setReport] = useState(null);
  const [exportAnchor, setExportAnchor] = useState(null);
  const [conceptoFiltro, setConceptoFiltro] = useState("TODOS");
  const [searchConcepto, setSearchConcepto] = useState("");
  const [previewOpen, setPreviewOpen] = useState(false);
  const [previewLoading, setPreviewLoading] = useState(false);
  const [selectedFactura, setSelectedFactura] = useState(null);
  const [nominaPreviewOpen, setNominaPreviewOpen] = useState(false);
  const [nominaPreviewLoading, setNominaPreviewLoading] = useState(false);
  const [selectedNomina, setSelectedNomina] = useState(null);

  const loadReport = async () => {
    setLoading(true);
    setError("");

    try {
      const params = {
        period,
        year,
      };

      if (period === "MONTH") {
        params.month = month;
      }

      if (period === "QUARTER") {
        params.quarter = quarter;
      }

      if (period === "CUSTOM") {
        params.dateFrom = dateFrom;
        params.dateTo = dateTo;
      }

      const response = await informesService.getAccountingReport(params);
      setReport(response);
    } catch (loadError) {
      setError(
        loadError.response?.data?.message ||
          "No se pudieron cargar los datos del informe",
      );
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadReport();
  }, []);

  const movementRows = report?.movimientos || [];

  const conceptoOptions = useMemo(() => {
    const values = new Set();

    movementRows.forEach((row) => {
      if (row?.concepto) {
        values.add(row.concepto);
      }
    });

    return Array.from(values).sort((a, b) => a.localeCompare(b));
  }, [movementRows]);

  const filteredMovementRows = useMemo(() => {
    const text = searchConcepto.trim().toLowerCase();

    return movementRows.filter((row) => {
      if (conceptoFiltro !== "TODOS" && row.concepto !== conceptoFiltro) {
        return false;
      }

      if (!text) {
        return true;
      }

      return String(row.concepto || "")
        .toLowerCase()
        .includes(text);
    });
  }, [movementRows, conceptoFiltro, searchConcepto]);

  const handleOpenFacturaModal = async (movement) => {
    const movementId = String(movement?.id || "");

    if (!movementId.startsWith("factura-")) {
      return;
    }

    const facturaId = movementId.replace("factura-", "");

    try {
      setPreviewOpen(true);
      setPreviewLoading(true);
      const preview = await facturasService.getPreview(facturaId);
      setSelectedFactura(preview);
    } catch (error) {
      setPreviewOpen(false);
      setSelectedFactura(null);
      setError(
        error.response?.data?.message ||
          "No se pudo cargar el detalle de la factura",
      );
    } finally {
      setPreviewLoading(false);
    }
  };

  const handleDownloadFacturaModalPdf = async () => {
    if (!selectedFactura?.id) {
      return;
    }

    try {
      const { blob, fileName } = await facturasService.downloadPdf(
        selectedFactura.id,
      );
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement("a");

      link.href = url;
      link.download = fileName;
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);
    } catch (error) {
      setError(error.response?.data?.message || "No se pudo descargar el PDF");
    }
  };

  const handleOpenNominaModal = async (movement) => {
    const movementId = String(movement?.id || "");

    if (!movementId.startsWith("nomina-")) {
      return;
    }

    const nominaId = movementId.replace("nomina-", "");

    try {
      setNominaPreviewOpen(true);
      setNominaPreviewLoading(true);
      const preview = await nominasService.getPreview(nominaId);
      setSelectedNomina(preview);
    } catch (error) {
      setNominaPreviewOpen(false);
      setSelectedNomina(null);
      setError(
        error.response?.data?.message ||
          "No se pudo cargar el detalle de la nómina",
      );
    } finally {
      setNominaPreviewLoading(false);
    }
  };

  const handleDownloadNominaModalPdf = async () => {
    if (!selectedNomina?.id) {
      return;
    }

    try {
      const { blob, fileName } = await nominasService.downloadPdf(
        selectedNomina.id,
      );
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement("a");

      link.href = url;
      link.download = fileName;
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);
    } catch (error) {
      setError(error.response?.data?.message || "No se pudo descargar el PDF");
    }
  };

  const movementColumns = useMemo(
    () => [
      { field: "tipo", headerName: "Tipo", width: 110 },
      { field: "concepto", headerName: "Concepto", flex: 1.2, minWidth: 180 },
      { field: "categoria", headerName: "Categoria", flex: 1, minWidth: 160 },
      {
        field: "fecha",
        headerName: "Fecha",
        minWidth: 170,
        valueGetter: (_, row) => formatDateTime(row.fecha),
      },
      { field: "estado", headerName: "Estado", minWidth: 130 },
      {
        field: "importe",
        headerName: "Importe",
        minWidth: 140,
        valueGetter: (_, row) => formatCurrency(row.importe),
      },
      {
        field: "acciones",
        headerName: "Acciones",
        width: 120,
        sortable: false,
        filterable: false,
        disableColumnMenu: true,
        renderCell: (params) => {
          if (!["FACTURA", "NOMINA"].includes(params.row.tipo)) {
            return <Typography variant="caption">-</Typography>;
          }

          if (params.row.tipo === "NOMINA") {
            return (
              <Stack direction="row" spacing={0.25}>
                <Tooltip title="Ver nómina" arrow>
                  <IconButton
                    color="primary"
                    size="small"
                    onClick={() => handleOpenNominaModal(params.row)}
                  >
                    <VisibilityIcon fontSize="small" />
                  </IconButton>
                </Tooltip>
              </Stack>
            );
          }

          return (
            <Stack direction="row" spacing={0.25}>
              <Tooltip title="Ver factura" arrow>
                <IconButton
                  color="primary"
                  size="small"
                  onClick={() => handleOpenFacturaModal(params.row)}
                >
                  <VisibilityIcon fontSize="small" />
                </IconButton>
              </Tooltip>
            </Stack>
          );
        },
      },
    ],
    [],
  );

  const pendingRatio = useMemo(() => {
    const totalIngresos = Number(report?.kpis?.ingresosTotales || 0);
    const pending = Number(report?.kpis?.cobrosPendientesMatricula || 0);

    if (totalIngresos <= 0) {
      return 0;
    }

    return Math.min(100, Math.round((pending / totalIngresos) * 100));
  }, [report?.kpis?.cobrosPendientesMatricula, report?.kpis?.ingresosTotales]);

  const cashFlowRows = report?.flujoCaja || [];
  const distributionRows = report?.distribucionIngresos || [];

  return (
    <Box sx={{ display: "grid", gap: 2 }}>
      <Stack spacing={0.6}>
        <Typography variant="h4" fontWeight={900}>
          Informes de contabilidad
        </Typography>
        <Typography color="text.secondary">
          Controla ingresos, gastos, beneficio neto y cobros pendientes en una
          vista unificada.
        </Typography>
      </Stack>

      <Card
        sx={{
          borderRadius: 3,
          border: "1px solid #e2e8f0",
          background:
            "linear-gradient(90deg, rgba(255,247,237,0.95) 0%, rgba(239,246,255,0.9) 48%, rgba(240,253,250,0.95) 100%)",
        }}
      >
        <CardContent>
          <Stack
            direction={{ xs: "column", xl: "row" }}
            spacing={1}
            justifyContent="space-between"
            alignItems={{ xs: "stretch", xl: "center" }}
          >
            <Stack direction="row" spacing={1} useFlexGap flexWrap="wrap">
              <TextField
                select
                label="Periodo"
                size="small"
                value={period}
                onChange={(event) => setPeriod(event.target.value)}
                sx={{ minWidth: 140 }}
              >
                {PERIOD_OPTIONS.map((option) => (
                  <MenuItem key={option.value} value={option.value}>
                    {option.label}
                  </MenuItem>
                ))}
              </TextField>

              {period !== "CUSTOM" ? (
                <TextField
                  size="small"
                  label="Año"
                  value={year}
                  onChange={(event) => setYear(event.target.value)}
                  sx={{ width: 120 }}
                />
              ) : null}

              {period === "MONTH" ? (
                <TextField
                  select
                  size="small"
                  label="Mes"
                  value={month}
                  onChange={(event) => setMonth(event.target.value)}
                  sx={{ minWidth: 150 }}
                >
                  {MONTHS.map((option) => (
                    <MenuItem key={option.value} value={option.value}>
                      {option.label}
                    </MenuItem>
                  ))}
                </TextField>
              ) : null}

              {period === "QUARTER" ? (
                <TextField
                  select
                  size="small"
                  label="Trimestre"
                  value={quarter}
                  onChange={(event) => setQuarter(event.target.value)}
                  sx={{ minWidth: 140 }}
                >
                  {QUARTERS.map((option) => (
                    <MenuItem key={option.value} value={option.value}>
                      {option.label}
                    </MenuItem>
                  ))}
                </TextField>
              ) : null}

              {period === "CUSTOM" ? (
                <>
                  <TextField
                    size="small"
                    type={dateFromInputType}
                    label="Desde"
                    value={dateFrom}
                    onChange={(event) => setDateFrom(event.target.value)}
                    placeholder={focusDateFrom ? "dd/mm/aaaa" : ""}
                    InputLabelProps={{
                      shrink: focusDateFrom || Boolean(dateFrom),
                    }}
                    onFocus={() => {
                      setFocusDateFrom(true);
                      setDateFromInputType("date");
                    }}
                    onBlur={() => {
                      setFocusDateFrom(false);
                      if (!dateFrom) {
                        setDateFromInputType("text");
                      }
                    }}
                    sx={{ minWidth: 170 }}
                  />
                  <TextField
                    size="small"
                    type={dateToInputType}
                    label="Hasta"
                    value={dateTo}
                    onChange={(event) => setDateTo(event.target.value)}
                    placeholder={focusDateTo ? "dd/mm/aaaa" : ""}
                    InputLabelProps={{ shrink: focusDateTo || Boolean(dateTo) }}
                    onFocus={() => {
                      setFocusDateTo(true);
                      setDateToInputType("date");
                    }}
                    onBlur={() => {
                      setFocusDateTo(false);
                      if (!dateTo) {
                        setDateToInputType("text");
                      }
                    }}
                    sx={{ minWidth: 170 }}
                  />
                </>
              ) : null}
            </Stack>

            <Stack direction="row" spacing={1}>
              <Button
                variant="outlined"
                startIcon={<RefreshIcon />}
                onClick={loadReport}
                disabled={loading}
              >
                Actualizar
              </Button>

              <Button
                variant="contained"
                startIcon={<DownloadIcon />}
                onClick={(event) => setExportAnchor(event.currentTarget)}
                disabled={!report}
              >
                Exportar
              </Button>

              <Menu
                anchorEl={exportAnchor}
                open={Boolean(exportAnchor)}
                onClose={() => setExportAnchor(null)}
              >
                <MenuItem
                  onClick={() => {
                    exportInformesExcel({
                      rows: movementRows,
                      kpis: report?.kpis,
                    });
                    setExportAnchor(null);
                  }}
                >
                  Exportar a Excel
                </MenuItem>
                <MenuItem
                  onClick={() => {
                    exportInformesPdf({
                      rows: movementRows,
                      kpis: report?.kpis,
                    });
                    setExportAnchor(null);
                  }}
                >
                  Exportar a PDF
                </MenuItem>
              </Menu>
            </Stack>
          </Stack>
        </CardContent>
      </Card>

      {error ? <Alert severity="error">{error}</Alert> : null}

      <Box
        sx={{
          display: "grid",
          gap: 1.2,
          gridTemplateColumns: {
            xs: "1fr",
            md: "repeat(2, minmax(0, 1fr))",
            xl: "repeat(4, minmax(0, 1fr))",
          },
        }}
      >
        <KpiCard
          title="Ingresos totales"
          value={formatCurrency(report?.kpis?.ingresosTotales)}
          subtitle="Matrículas, bonos, clases y otros conceptos"
          icon={<PaymentsIcon fontSize="small" />}
          color="#16a34a"
        />

        <KpiCard
          title="Gastos"
          value={formatCurrency(report?.kpis?.gastosTotales)}
          subtitle="Combustible y gastos operativos registrados"
          icon={<ReceiptLongIcon fontSize="small" />}
          color="#dc2626"
        />

        <KpiCard
          title="Beneficio neto"
          value={formatCurrency(report?.kpis?.beneficioNeto)}
          subtitle="Diferencia entre ingresos y gastos"
          icon={<SavingsIcon fontSize="small" />}
          color="#0f172a"
        />

        <KpiCard
          title="Cobros pendientes matrícula"
          value={formatCurrency(report?.kpis?.cobrosPendientesMatricula)}
          subtitle="Facturas de matrícula pendientes de pago"
          icon={<WarningAmberIcon fontSize="small" />}
          color="#f59e0b"
        />
      </Box>

      <Box
        sx={{
          display: "grid",
          gap: 1.2,
          gridTemplateColumns: {
            xs: "1fr",
            xl: "2fr 1.2fr 1fr",
          },
        }}
      >
        <Card sx={{ borderRadius: 3, border: "1px solid #e2e8f0" }}>
          <CardContent>
            <Typography variant="subtitle1" fontWeight={800}>
              Flujo de caja
            </Typography>
            <Typography variant="caption" color="text.secondary">
              Ingresos y gastos diarios en el periodo seleccionado.
            </Typography>
            <Box sx={{ mt: 1.2, width: "100%", height: 270 }}>
              <ResponsiveContainer>
                <LineChart data={cashFlowRows}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis
                    dataKey="fecha"
                    tick={{ fontSize: 10 }}
                    tickMargin={6}
                  />
                  <YAxis tick={{ fontSize: 10 }} width={58} />
                  <RechartsTooltip />
                  <Legend />
                  <Line
                    type="monotone"
                    dataKey="ingresos"
                    stroke="#16a34a"
                    strokeWidth={2.5}
                    name="Ingresos"
                    dot={false}
                  />
                  <Line
                    type="monotone"
                    dataKey="gastos"
                    stroke="#dc2626"
                    strokeWidth={2.5}
                    name="Gastos"
                    dot={false}
                  />
                  <Line
                    type="monotone"
                    dataKey="saldoAcumulado"
                    stroke="#1d4ed8"
                    strokeWidth={2.5}
                    name="Saldo acumulado"
                    dot={false}
                  />
                </LineChart>
              </ResponsiveContainer>
            </Box>
          </CardContent>
        </Card>

        <Card sx={{ borderRadius: 3, border: "1px solid #e2e8f0" }}>
          <CardContent>
            <Typography variant="subtitle1" fontWeight={800}>
              Ingresos por actividad
            </Typography>
            <Typography variant="caption" color="text.secondary">
              Distribución de facturación pagada por categoría.
            </Typography>
            <Box sx={{ mt: 1.2, width: "100%", height: 270 }}>
              <ResponsiveContainer>
                <PieChart>
                  <Pie
                    data={distributionRows}
                    dataKey="total"
                    nameKey="categoria"
                    outerRadius={86}
                    label
                  >
                    {distributionRows.map((entry, index) => (
                      <Cell
                        key={entry.categoria}
                        fill={PIE_COLORS[index % PIE_COLORS.length]}
                      />
                    ))}
                  </Pie>
                  <RechartsTooltip />
                  <Legend />
                </PieChart>
              </ResponsiveContainer>
            </Box>
          </CardContent>
        </Card>

        <Card sx={{ borderRadius: 3, border: "1px solid #e2e8f0" }}>
          <CardContent>
            <Typography variant="subtitle1" fontWeight={800}>
              Cobros pendientes
            </Typography>
            <Typography variant="caption" color="text.secondary">
              Prioridad de cobro sobre matrículas sin liquidar.
            </Typography>

            <Typography variant="h4" fontWeight={900} sx={{ mt: 1.2 }}>
              {formatCurrency(report?.cobrosPendientes?.total)}
            </Typography>

            <Typography variant="body2" color="text.secondary" sx={{ mt: 0.4 }}>
              Facturas pendientes:{" "}
              {report?.cobrosPendientes?.totalFacturas || 0}
            </Typography>

            <Divider sx={{ my: 1.3 }} />

            <Chip
              icon={<AssessmentIcon fontSize="small" />}
              label={`Peso sobre ingresos: ${pendingRatio}%`}
              color="warning"
            />
          </CardContent>
        </Card>
      </Box>

      <Card sx={{ borderRadius: 3, border: "1px solid #e2e8f0" }}>
        <CardContent>
          <Stack
            direction={{ xs: "column", md: "row" }}
            justifyContent="space-between"
            alignItems={{ xs: "stretch", md: "center" }}
            spacing={1}
            sx={{ mb: 1 }}
          >
            <Typography variant="subtitle1" fontWeight={800}>
              Últimos movimientos
            </Typography>
            <Typography variant="caption" color="text.secondary">
              Fuente combinada: facturas, pagos y gastos de combustible.
            </Typography>
          </Stack>

          <Stack
            direction={{ xs: "column", md: "row" }}
            spacing={1}
            sx={{ mb: 1.5 }}
          >
            <TextField
              select
              size="small"
              label="Concepto"
              value={conceptoFiltro}
              onChange={(event) => setConceptoFiltro(event.target.value)}
              sx={{ minWidth: 240 }}
            >
              <MenuItem value="TODOS">Todos</MenuItem>
              {conceptoOptions.map((concepto) => (
                <MenuItem key={concepto} value={concepto}>
                  {concepto}
                </MenuItem>
              ))}
            </TextField>

            <TextField
              size="small"
              label="Buscar por concepto"
              value={searchConcepto}
              onChange={(event) => setSearchConcepto(event.target.value)}
              sx={{ minWidth: 260 }}
            />
          </Stack>

          <Box sx={{ height: 420 }}>
            <DataGrid
              rows={filteredMovementRows}
              columns={movementColumns}
              getRowId={(row) => row.id}
              disableRowSelectionOnClick
              pageSizeOptions={[10, 25, 50]}
              loading={loading}
              initialState={{
                pagination: {
                  paginationModel: {
                    pageSize: 10,
                    page: 0,
                  },
                },
              }}
            />
          </Box>
        </CardContent>
      </Card>

      <Dialog
        open={previewOpen}
        onClose={() => {
          setPreviewOpen(false);
          setSelectedFactura(null);
        }}
        fullWidth
        maxWidth="md"
      >
        <DialogTitle>Factura</DialogTitle>
        <DialogContent>
          {previewLoading ? (
            <Typography>Cargando factura...</Typography>
          ) : selectedFactura ? (
            <Stack spacing={1} sx={{ pt: 0.5 }}>
              <Typography fontWeight={700}>
                Nº {selectedFactura.numero || "-"}
              </Typography>
              <Typography variant="body2">
                Alumno: {selectedFactura.alumno?.nombre || "-"}
              </Typography>
              <Typography variant="body2">
                Concepto: {selectedFactura.concepto || "-"}
              </Typography>
              <Typography variant="body2">
                Estado: {selectedFactura.estado || "-"}
              </Typography>
              <Typography variant="body2" fontWeight={700}>
                Total: {formatCurrency(selectedFactura.total || 0)}
              </Typography>
            </Stack>
          ) : (
            <Alert severity="warning">No hay factura para mostrar</Alert>
          )}
        </DialogContent>
        <DialogActions>
          <Button
            onClick={() => {
              setPreviewOpen(false);
              setSelectedFactura(null);
            }}
          >
            Cerrar
          </Button>
          <Button
            variant="contained"
            startIcon={<DownloadIcon />}
            onClick={handleDownloadFacturaModalPdf}
            disabled={!selectedFactura?.id}
          >
            Descargar PDF
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog
        open={nominaPreviewOpen}
        onClose={() => {
          setNominaPreviewOpen(false);
          setSelectedNomina(null);
        }}
        fullWidth
        maxWidth="md"
      >
        <DialogTitle>Nómina</DialogTitle>
        <DialogContent>
          {nominaPreviewLoading ? (
            <Typography>Cargando nómina...</Typography>
          ) : selectedNomina ? (
            <Stack spacing={1} sx={{ pt: 0.5 }}>
              <Typography fontWeight={700}>
                Nº {selectedNomina.numero || "-"}
              </Typography>
              <Typography variant="body2">
                Profesor: {selectedNomina.profesor?.usuario?.nombre || "-"}
              </Typography>
              <Typography variant="body2">
                Periodo: {String(selectedNomina.mes).padStart(2, "0")}/
                {selectedNomina.anio}
              </Typography>
              <Typography variant="body2" fontWeight={700}>
                Neto: {formatCurrency(selectedNomina.liquidoPercibir || 0)}
              </Typography>
            </Stack>
          ) : (
            <Alert severity="warning">No hay nómina para mostrar</Alert>
          )}
        </DialogContent>
        <DialogActions>
          <Button
            onClick={() => {
              setNominaPreviewOpen(false);
              setSelectedNomina(null);
            }}
          >
            Cerrar
          </Button>
          <Button
            variant="contained"
            startIcon={<DownloadIcon />}
            onClick={handleDownloadNominaModalPdf}
            disabled={!selectedNomina?.id}
          >
            Descargar PDF
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
}

import {
  Box,
  Button,
  Card,
  CardContent,
  TextField,
  Typography,
  Divider,
  Snackbar,
  Alert,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
} from "@mui/material";

import { useEffect, useState } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import { jwtDecode } from "jwt-decode";

import { matriculasService } from "../../services/matriculasService";
import { pagosService } from "../../services/pagosService";

export default function PagoMatricula() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const pagoId = searchParams.get("pagoId");

  const [matricula, setMatricula] = useState(null);
  const [pagoPendiente, setPagoPendiente] = useState(null);

  const [loading, setLoading] = useState(true);

  const descuento = matricula
    ? Math.round(
        ((Number(matricula.precioBase) - Number(matricula.precioFinal)) /
          Number(matricula.precioBase)) *
          100,
      )
    : 0;

  const [notification, setNotification] = useState({
    open: false,
    message: "",
    severity: "success",
  });

  const [titular, setTitular] = useState("");

  const [numeroTarjeta, setNumeroTarjeta] = useState("");

  const [caducidad, setCaducidad] = useState("");

  const [cvv, setCvv] = useState("");

  const [errores, setErrores] = useState({});

  const [openConfirmarPago, setOpenConfirmarPago] = useState(false);

  const esPagoPendiente = Boolean(pagoId);

  const esCaducidadValida = (value) => {
    if (!/^\d{2}\/\d{2}$/.test(value)) {
      return false;
    }

    const [mesRaw, yearRaw] = value.split("/");
    const mes = Number(mesRaw);
    const year = Number(yearRaw);
    const yearActual2Digitos = new Date().getFullYear() % 100;

    if (!Number.isInteger(mes) || mes < 1 || mes > 12) {
      return false;
    }

    if (!Number.isInteger(year) || year < yearActual2Digitos) {
      return false;
    }

    return true;
  };

  const validarFormulario = () => {
    const nuevosErrores = {};

    if (!titular.trim()) {
      nuevosErrores.titular = "El titular es obligatorio";
    }

    if (!/^\d{16}$/.test(numeroTarjeta)) {
      nuevosErrores.numeroTarjeta = "La tarjeta debe tener 16 dígitos";
    }

    if (!/^\d{2}\/\d{2}$/.test(caducidad)) {
      nuevosErrores.caducidad = "Formato MM/AA";
    } else if (!esCaducidadValida(caducidad)) {
      const yearActual2Digitos = String(
        new Date().getFullYear() % 100,
      ).padStart(2, "0");
      nuevosErrores.caducidad = `Fecha de Caducidad inválida`;
    }

    if (!/^\d{3}$/.test(cvv)) {
      nuevosErrores.cvv = "El CVV debe tener 3 dígitos";
    }

    setErrores(nuevosErrores);

    return Object.keys(nuevosErrores).length === 0;
  };

  useEffect(() => {
    const loadData = async () => {
      try {
        if (esPagoPendiente) {
          const pago = await pagosService.getMineById(pagoId);
          setPagoPendiente(pago);
        } else {
          const data = await matriculasService.getMine();
          setMatricula(data);
        }
      } catch (error) {
        console.error(error);
        setNotification({
          open: true,
          message:
            error.response?.data?.message ||
            "No se pudieron cargar los datos de pago",
          severity: "error",
        });
      } finally {
        setLoading(false);
      }
    };

    loadData();
  }, [esPagoPendiente, pagoId]);

  useEffect(() => {
    if (titular.trim()) {
      return;
    }

    const nombreDesdePago = pagoPendiente?.alumno?.usuario?.nombre;
    const nombreDesdeMatricula = matricula?.alumno?.usuario?.nombre;

    let nombreDesdeToken = "";
    const token = localStorage.getItem("token");

    if (token) {
      try {
        const decoded = jwtDecode(token);
        nombreDesdeToken = decoded?.nombre || "";
      } catch {
        nombreDesdeToken = "";
      }
    }

    const nombreSugerido =
      nombreDesdePago || nombreDesdeMatricula || nombreDesdeToken;

    if (nombreSugerido) {
      setTitular(nombreSugerido);
    }
  }, [matricula, pagoPendiente, titular]);

  const formatNumeroTarjeta = (value) =>
    value
      .replace(/\D/g, "")
      .slice(0, 16)
      .replace(/(.{4})/g, "$1 ")
      .trim();

  const formatCaducidad = (value) => {
    const numeric = value.replace(/\D/g, "").slice(0, 4);

    if (numeric.length <= 2) {
      return numeric;
    }

    return `${numeric.slice(0, 2)}/${numeric.slice(2)}`;
  };

  const handlePagar = async () => {
    if (!validarFormulario()) {
      return;
    }

    try {
      if (esPagoPendiente) {
        await pagosService.payMine(pagoPendiente.id);
      } else {
        await matriculasService.pagar(matricula.id);
      }

      setNotification({
        open: true,
        message: "Factura generada",
        severity: "success",
      });

      navigate(esPagoPendiente ? "/mis-pagos" : "/dashboard", {
        replace: true,
      });

      if (!esPagoPendiente) {
        window.location.reload();
      }
    } catch (error) {
      console.error(error);
      setNotification({
        open: true,
        message:
          error.response?.data?.message || "No se pudo completar el pago",
        severity: "error",
      });
    }
  };

  const importePagoPendiente = Number(pagoPendiente?.importe || 0);

  if (loading) {
    return (
      <Box
        sx={{
          display: "flex",
          justifyContent: "center",
          mt: 10,
        }}
      >
        Cargando matrícula...
      </Box>
    );
  }
  return (
    <Box
      sx={{
        display: "flex",
        justifyContent: "center",
        py: 5,
      }}
    >
      <Card
        sx={{
          width: 700,
          maxWidth: "100%",
          borderRadius: 4,
        }}
      >
        <CardContent>
          <Typography variant="h4" fontWeight={800} gutterBottom>
            {esPagoPendiente ? "Pago pendiente" : "Pago de Matrícula"}
          </Typography>

          <Typography color="text.secondary" sx={{ mb: 3 }}>
            {esPagoPendiente
              ? "Completa el pago pendiente para continuar con tu proceso formativo."
              : "Completa el pago de tu matrícula para acceder a todos los contenidos de la plataforma."}
          </Typography>

          <Divider sx={{ mb: 3 }} />

          <Box
            sx={{
              mb: 3,
              p: 2,
              borderRadius: 2,
              backgroundColor: "#f8fafc",
            }}
          >
            {esPagoPendiente ? (
              <>
                <Typography fontWeight={700}>
                  Concepto: {pagoPendiente?.concepto}
                </Typography>

                <Typography>
                  Permiso: {pagoPendiente?.permiso || "-"}
                </Typography>

                <Typography
                  sx={{
                    mt: 1,
                    fontWeight: 700,
                    fontSize: "1.1rem",
                  }}
                >
                  Importe: {importePagoPendiente.toFixed(2)} €
                </Typography>

                <Typography
                  color={
                    pagoPendiente?.estado === "PAGADO"
                      ? "success.main"
                      : "warning.main"
                  }
                >
                  Estado: {pagoPendiente?.estado}
                </Typography>

                {typeof pagoPendiente?.convocatoriasIncluidas === "number" && (
                  <Typography>
                    Convocatorias: {pagoPendiente?.convocatoriasConsumidas || 0}
                    /{pagoPendiente?.convocatoriasIncluidas}
                  </Typography>
                )}
              </>
            ) : (
              <>
                <Typography fontWeight={700}>
                  Permiso: {matricula?.licencia}
                </Typography>

                <Typography>
                  Precio original: {matricula?.precioBase} €
                </Typography>

                {matricula?.promocion && (
                  <Typography color="success.main">
                    Promoción aplicada: {matricula.promocion.nombre}
                  </Typography>
                )}

                {matricula?.promocion && (
                  <Typography color="success.main">
                    Descuento: {descuento} %
                  </Typography>
                )}

                <Typography
                  sx={{
                    mt: 1,
                    fontWeight: 700,
                    fontSize: "1.1rem",
                  }}
                >
                  Importe final: {matricula?.precioFinal} €
                </Typography>

                <Typography color="warning.main">
                  Estado: {matricula?.estado}
                </Typography>
              </>
            )}
          </Box>

          <TextField
            fullWidth
            label="Titular de la tarjeta"
            value={titular}
            onChange={(e) => setTitular(e.target.value)}
            error={Boolean(errores.titular)}
            helperText={errores.titular}
            sx={{ mb: 2 }}
          />

          <TextField
            fullWidth
            label="Número de tarjeta"
            value={formatNumeroTarjeta(numeroTarjeta)}
            inputProps={{
              maxLength: 19,
            }}
            onChange={(e) =>
              setNumeroTarjeta(e.target.value.replace(/\D/g, "").slice(0, 16))
            }
            error={Boolean(errores.numeroTarjeta)}
            helperText={errores.numeroTarjeta}
            sx={{ mb: 2 }}
          />

          <Box
            sx={{
              display: "grid",
              gridTemplateColumns: "1fr 1fr",
              gap: 2,
              mb: 3,
            }}
          >
            <TextField
              label="Caducidad"
              value={caducidad}
              onChange={(e) => setCaducidad(formatCaducidad(e.target.value))}
              inputProps={{
                maxLength: 5,
              }}
              placeholder="MM/AA"
              error={Boolean(errores.caducidad)}
              helperText={errores.caducidad}
            />

            <TextField
              label="CVV"
              value={cvv}
              inputProps={{
                maxLength: 3,
              }}
              onChange={(e) =>
                setCvv(e.target.value.replace(/\D/g, "").slice(0, 3))
              }
              error={Boolean(errores.cvv)}
              helperText={errores.cvv}
            />
          </Box>

          <Button
            variant="contained"
            fullWidth
            size="large"
            color="success"
            disabled={esPagoPendiente && pagoPendiente?.estado !== "PENDIENTE"}
            onClick={() => {
              if (validarFormulario()) {
                setOpenConfirmarPago(true);
              }
            }}
          >
            {esPagoPendiente ? "Pagar ahora" : "Pagar Matrícula"}
          </Button>

          <Dialog
            open={openConfirmarPago}
            onClose={() => setOpenConfirmarPago(false)}
            maxWidth="sm"
            fullWidth
          >
            <DialogTitle>Confirmar pago</DialogTitle>

            <DialogContent>
              {esPagoPendiente ? (
                <>
                  <Typography>
                    Vas a realizar el pago de este concepto.
                  </Typography>

                  <Typography sx={{ mt: 2 }} fontWeight={700}>
                    Concepto: {pagoPendiente?.concepto}
                  </Typography>

                  <Typography>
                    Permiso: {pagoPendiente?.permiso || "-"}
                  </Typography>

                  <Typography fontWeight={700} sx={{ mt: 1 }}>
                    Total a pagar: {importePagoPendiente.toFixed(2)} €
                  </Typography>
                </>
              ) : (
                <>
                  <Typography>
                    Vas a realizar el pago de tu matrícula.
                  </Typography>

                  <Typography sx={{ mt: 2 }} fontWeight={700}>
                    Permiso: {matricula?.licencia}
                  </Typography>

                  <Typography>
                    Precio original: {matricula?.precioBase} €
                  </Typography>

                  {matricula?.promocion && (
                    <Typography color="success.main">
                      Promoción: {matricula.promocion.nombre}
                    </Typography>
                  )}

                  <Typography fontWeight={700} sx={{ mt: 1 }}>
                    Total a pagar: {matricula?.precioFinal} €
                  </Typography>
                </>
              )}
            </DialogContent>

            <DialogActions>
              <Button onClick={() => setOpenConfirmarPago(false)}>
                Cancelar
              </Button>

              <Button variant="contained" color="success" onClick={handlePagar}>
                Confirmar pago
              </Button>
            </DialogActions>
          </Dialog>
        </CardContent>
      </Card>

      <Snackbar
        open={notification.open}
        autoHideDuration={3000}
        onClose={() =>
          setNotification((prev) => ({
            ...prev,
            open: false,
          }))
        }
      >
        <Alert severity={notification.severity} variant="filled">
          {notification.message}
        </Alert>
      </Snackbar>
    </Box>
  );
}

import { useEffect, useMemo, useState } from "react";
import {
  Alert,
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  InputLabel,
  Menu,
  MenuItem,
  Select,
  Snackbar,
  Stack,
  TextField,
  Tooltip,
  Typography,
  IconButton,
} from "@mui/material";
import { DataGrid } from "@mui/x-data-grid";
import VisibilityIcon from "@mui/icons-material/Visibility";
import DownloadIcon from "@mui/icons-material/Download";
import BoltIcon from "@mui/icons-material/Bolt";
import { jwtDecode } from "jwt-decode";

import { nominasService } from "../../services/nominasService";
import { exportNominasExcel } from "../../utils/exportNominasExcel";
import { exportNominasPdf } from "../../utils/exportNominasPdf";

const MONTHS = [
  { value: 1, label: "Enero" },
  { value: 2, label: "Febrero" },
  { value: 3, label: "Marzo" },
  { value: 4, label: "Abril" },
  { value: 5, label: "Mayo" },
  { value: 6, label: "Junio" },
  { value: 7, label: "Julio" },
  { value: 8, label: "Agosto" },
  { value: 9, label: "Septiembre" },
  { value: 10, label: "Octubre" },
  { value: 11, label: "Noviembre" },
  { value: 12, label: "Diciembre" },
];

const formatCurrency = (value) => `${Number(value || 0).toFixed(2)} EUR`;

const normalizeRole = (role) => {
  if (role === "GESTOR") {
    return "ADMINISTRATIVO";
  }

  return role;
};

const resolveRoleFromToken = (token) => {
  try {
    const decoded = jwtDecode(token || "");
    return normalizeRole(decoded?.rol || "");
  } catch {
    return "";
  }
};

export default function Nominas() {
  const now = new Date();
  const token = localStorage.getItem("token") || "";
  const [role] = useState(() => resolveRoleFromToken(token));
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(false);
  const [searchProfesor, setSearchProfesor] = useState("");
  const [mesFiltro, setMesFiltro] = useState("");
  const [anioFiltro, setAnioFiltro] = useState("");
  const [exportAnchor, setExportAnchor] = useState(null);
  const [previewOpen, setPreviewOpen] = useState(false);
  const [previewLoading, setPreviewLoading] = useState(false);
  const [selectedNomina, setSelectedNomina] = useState(null);
  const [notification, setNotification] = useState({
    open: false,
    message: "",
    severity: "success",
  });

  const isProfessor = role === "PROFESOR";
  const canGenerate = role === "ADMIN" || role === "ADMINISTRATIVO";
  const canListNominas = canGenerate || isProfessor;

  const yearOptions = useMemo(() => {
    const years = [];
    for (let year = 2026; year <= now.getFullYear() + 2; year += 1) {
      years.push(year);
    }
    return years;
  }, []);

  const loadRows = async () => {
    if (!canListNominas) {
      setRows([]);
      setLoading(false);
      return;
    }

    setLoading(true);

    try {
      const params = {
        ...(mesFiltro ? { mes: Number(mesFiltro) } : {}),
        ...(anioFiltro ? { anio: Number(anioFiltro) } : {}),
        ...(!isProfessor && searchProfesor.trim()
          ? { profesorNombre: searchProfesor.trim() }
          : {}),
      };

      const data = isProfessor
        ? await nominasService.getMine(params)
        : await nominasService.getAll(params);

      setRows(Array.isArray(data) ? data : []);
    } catch (error) {
      setNotification({
        open: true,
        message:
          error.response?.data?.message || "No se pudieron cargar las nóminas",
        severity: "error",
      });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadRows();
  }, [canListNominas, role, mesFiltro, anioFiltro]);

  const filteredRows = useMemo(() => {
    if (isProfessor) {
      return rows;
    }

    const text = searchProfesor.trim().toLowerCase();
    if (!text) {
      return rows;
    }

    return rows.filter((row) =>
      String(row.profesor?.usuario?.nombre || "")
        .toLowerCase()
        .includes(text),
    );
  }, [rows, isProfessor, searchProfesor]);

  const handleOpenPreview = async (row) => {
    setPreviewOpen(true);
    setPreviewLoading(true);

    try {
      const data = await nominasService.getPreview(row.id);
      setSelectedNomina(data);
    } catch (error) {
      setPreviewOpen(false);
      setNotification({
        open: true,
        message: error.response?.data?.message || "No se pudo cargar la nómina",
        severity: "error",
      });
    } finally {
      setPreviewLoading(false);
    }
  };

  const handleDownloadPdf = async (id) => {
    try {
      const { blob, fileName } = await nominasService.downloadPdf(id);
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement("a");

      link.href = url;
      link.download = fileName;
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);
    } catch (error) {
      setNotification({
        open: true,
        message:
          error.response?.data?.message ||
          "No se pudo descargar el PDF de nómina",
        severity: "error",
      });
    }
  };

  const handleGenerateMonth = async () => {
    try {
      const payload = {
        year: anioFiltro ? Number(anioFiltro) : now.getFullYear(),
        month: mesFiltro ? Number(mesFiltro) : now.getMonth() + 1,
      };

      const result = await nominasService.generateMonth(payload);

      setNotification({
        open: true,
        message: `Generación completada: ${result.generated} nóminas nuevas, ${result.skipped} omitidas`,
        severity: "success",
      });

      await loadRows();
    } catch (error) {
      setNotification({
        open: true,
        message:
          error.response?.data?.message || "No se pudieron generar las nóminas",
        severity: "error",
      });
    }
  };

  const columns = [
    {
      field: "numero",
      headerName: "Nº Nómina",
      flex: 1,
    },
    {
      field: "profesor",
      headerName: "Profesor",
      flex: 1.4,
      valueGetter: (_, row) => row.profesor?.usuario?.nombre || "-",
    },
    {
      field: "periodo",
      headerName: "Periodo de liquidación",
      flex: 1,
      valueGetter: (_, row) =>
        `${String(row.mes).padStart(2, "0")}/${row.anio}`,
    },
    {
      field: "importe",
      headerName: "Importe nómina",
      flex: 0.9,
      valueGetter: (_, row) => formatCurrency(row.liquidoPercibir),
    },
    {
      field: "acciones",
      headerName: "Acciones",
      width: 150,
      sortable: false,
      filterable: false,
      disableColumnMenu: true,
      renderCell: (params) => (
        <Stack direction="row" spacing={0.25}>
          <Tooltip title="Ver nómina" arrow>
            <IconButton
              color="primary"
              size="small"
              onClick={() => handleOpenPreview(params.row)}
            >
              <VisibilityIcon fontSize="small" />
            </IconButton>
          </Tooltip>

          <Tooltip title="Descargar nómina" arrow>
            <IconButton
              color="primary"
              size="small"
              onClick={() => handleDownloadPdf(params.row.id)}
            >
              <DownloadIcon fontSize="small" />
            </IconButton>
          </Tooltip>
        </Stack>
      ),
    },
  ];

  const exportRows = filteredRows.map((row) => ({
    numero: row.numero,
    profesor: row.profesor,
    mes: row.mes,
    anio: row.anio,
    liquidoPercibir: row.liquidoPercibir,
  }));

  return (
    <Box>
      <Box
        sx={{
          display: "flex",
          alignItems: "flex-start",
          justifyContent: "space-between",
          gap: 2,
          mb: 2,
          flexWrap: "wrap",
        }}
      >
        <Box>
          <Typography variant="h4" fontWeight={700} mb={2}>
            Nóminas
          </Typography>

          <Typography color="text.secondary">
            Gestión mensual de nóminas de profesorado.
          </Typography>
        </Box>

        <Stack
          direction={{ xs: "column", md: "row" }}
          spacing={1.25}
          alignItems={{ xs: "stretch", md: "center" }}
        >
          {!isProfessor ? (
            <TextField
              size="small"
              label="Buscar profesor"
              value={searchProfesor}
              onChange={(event) => setSearchProfesor(event.target.value)}
              sx={{ width: { xs: "100%", md: 240 } }}
            />
          ) : null}

          <FormControl size="small" sx={{ minWidth: 170 }}>
            <InputLabel>Mes</InputLabel>
            <Select
              label="Mes"
              value={mesFiltro}
              onChange={(event) => setMesFiltro(event.target.value)}
            >
              <MenuItem value="">Todos</MenuItem>
              {MONTHS.map((item) => (
                <MenuItem key={item.value} value={String(item.value)}>
                  {item.label}
                </MenuItem>
              ))}
            </Select>
          </FormControl>

          <FormControl size="small" sx={{ minWidth: 130 }}>
            <InputLabel>Año</InputLabel>
            <Select
              label="Año"
              value={anioFiltro}
              onChange={(event) => setAnioFiltro(event.target.value)}
            >
              <MenuItem value="">Todos</MenuItem>
              {yearOptions.map((year) => (
                <MenuItem key={year} value={String(year)}>
                  {year}
                </MenuItem>
              ))}
            </Select>
          </FormControl>

          <Button variant="outlined" onClick={loadRows}>
            Recargar
          </Button>

          {canGenerate ? (
            <Button
              variant="contained"
              startIcon={<BoltIcon />}
              onClick={handleGenerateMonth}
            >
              Generar nóminas del mes
            </Button>
          ) : null}

          <Button
            variant="contained"
            startIcon={<DownloadIcon />}
            onClick={(event) => setExportAnchor(event.currentTarget)}
          >
            Exportar
          </Button>

          <Menu
            anchorEl={exportAnchor}
            open={Boolean(exportAnchor)}
            onClose={() => setExportAnchor(null)}
          >
            <MenuItem
              onClick={() => {
                exportNominasExcel(exportRows);
                setExportAnchor(null);
              }}
            >
              Exportar a Excel
            </MenuItem>
            <MenuItem
              onClick={() => {
                exportNominasPdf(exportRows);
                setExportAnchor(null);
              }}
            >
              Exportar a PDF
            </MenuItem>
          </Menu>
        </Stack>
      </Box>

      <Box sx={{ height: 700 }}>
        <DataGrid
          rows={filteredRows}
          columns={columns}
          loading={loading}
          getRowId={(row) => row.id}
          disableRowSelectionOnClick
          pageSizeOptions={[10, 25, 50]}
          initialState={{
            pagination: { paginationModel: { pageSize: 10, page: 0 } },
            sorting: { sortModel: [{ field: "anio", sort: "desc" }] },
          }}
        />
      </Box>

      <Dialog
        open={previewOpen}
        onClose={() => setPreviewOpen(false)}
        fullWidth
        maxWidth="md"
      >
        <DialogTitle>Detalle de nómina</DialogTitle>
        <DialogContent>
          {previewLoading ? (
            <Typography>Cargando...</Typography>
          ) : selectedNomina ? (
            <Stack spacing={1.2} sx={{ mt: 1 }}>
              <Typography>
                <strong>Nº Nómina:</strong> {selectedNomina.numero}
              </Typography>
              <Typography>
                <strong>Profesor:</strong>{" "}
                {selectedNomina.profesor?.usuario?.nombre || "-"}
              </Typography>
              <Typography>
                <strong>Periodo:</strong>{" "}
                {String(selectedNomina.mes).padStart(2, "0")}/
                {selectedNomina.anio}
              </Typography>
              <Typography>
                <strong>Días trabajados:</strong>{" "}
                {selectedNomina.diasTrabajados}/{selectedNomina.diasMes}
              </Typography>
              <Typography>
                <strong>Convocatorias APTO/NO_APTO:</strong>{" "}
                {selectedNomina.presentadosApto}/
                {selectedNomina.presentadosNoApto}
              </Typography>
              <Typography>
                <strong>Total convocatorias:</strong>{" "}
                {selectedNomina.totalPresentados}
              </Typography>
              <Typography>
                <strong>Total devengos:</strong>{" "}
                {formatCurrency(selectedNomina.totalDevengos)}
              </Typography>
              <Typography>
                <strong>Total deducciones:</strong>{" "}
                {formatCurrency(selectedNomina.totalDeducciones)}
              </Typography>
              <Typography>
                <strong>Líquido a percibir:</strong>{" "}
                {formatCurrency(selectedNomina.liquidoPercibir)}
              </Typography>
            </Stack>
          ) : (
            <Typography>No hay información para mostrar.</Typography>
          )}
        </DialogContent>
        <DialogActions>
          {selectedNomina?.id ? (
            <Button onClick={() => handleDownloadPdf(selectedNomina.id)}>
              Descargar PDF
            </Button>
          ) : null}
          <Button onClick={() => setPreviewOpen(false)}>Cerrar</Button>
        </DialogActions>
      </Dialog>

      <Snackbar
        open={notification.open}
        autoHideDuration={3500}
        onClose={() => setNotification((prev) => ({ ...prev, open: false }))}
      >
        <Alert
          severity={notification.severity}
          variant="filled"
          onClose={() => setNotification((prev) => ({ ...prev, open: false }))}
        >
          {notification.message}
        </Alert>
      </Snackbar>
    </Box>
  );
}

import { useEffect, useState } from "react";
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  Stack,
  Typography,
} from "@mui/material";
import { useNavigate } from "react-router-dom";
import { jwtDecode } from "jwt-decode";

import { notificacionesService } from "../../services/notificacionesService";

const notifyUnreadChanged = () => {
  window.dispatchEvent(new CustomEvent("notificaciones:updated"));
};

const colorByType = (type) => {
  if (type?.includes("CANCELADA")) return "error";
  if (type?.includes("CONFIRMADA")) return "success";
  if (type?.includes("PAGO")) return "warning";
  return "info";
};

const formatDate = (value) =>
  new Date(value).toLocaleString("es-ES", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });

const normalizeNotificationRoute = (route) => {
  const normalizedRoute = String(route || "")
    .trim()
    .toLowerCase();

  if (normalizedRoute === "/matricula" || normalizedRoute === "/matriculas") {
    return "/facturas";
  }

  return route;
};

const upper = (value) =>
  String(value || "")
    .trim()
    .toUpperCase();

const shouldOpenInFacturas = (item) => {
  const route = normalizeNotificationRoute(item?.metadata?.route || "");
  const tipo = upper(item?.tipo);

  if (route === "/facturas") {
    return true;
  }

  return ["BONO_COMPRADO", "MATRICULA_PAGADA"].includes(tipo);
};

const buildFacturasRoute = (item, role) => {
  const params = new URLSearchParams();
  const metadata = item?.metadata || {};
  const normalizedRole = String(role || "")
    .trim()
    .toUpperCase();
  const isAlumno = normalizedRole === "ALUMNO";

  params.set("openFactura", "1");

  [
    "facturaId",
    "numeroFactura",
    "numeroFacturaPago",
    "matriculaId",
    "compraBonoId",
    "pagoId",
    "clasePracticaId",
  ].forEach((key) => {
    const value = metadata?.[key];
    if (value !== undefined && value !== null && String(value).trim() !== "") {
      params.set(key, String(value));
    }
  });

  params.set("notificationType", upper(item?.tipo));

  return `${isAlumno ? "/mis-facturas" : "/facturas"}?${params.toString()}`;
};

export default function Notificaciones() {
  const navigate = useNavigate();
  const [role, setRole] = useState("");
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(true);
  const [onlyUnread, setOnlyUnread] = useState(true);
  const [includeArchived, setIncludeArchived] = useState(false);
  const [error, setError] = useState("");

  const loadData = async (unread = onlyUnread, archived = includeArchived) => {
    setLoading(true);
    setError("");

    try {
      const data = await notificacionesService.getMine(unread, archived);
      setRows(data || []);
    } catch (loadError) {
      setError(
        loadError.response?.data?.message ||
          "No se pudieron cargar las notificaciones",
      );
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    try {
      const token = localStorage.getItem("token") || "";
      const decoded = jwtDecode(token);
      setRole(String(decoded?.rol || "").toUpperCase());
    } catch {
      setRole("");
    }
  }, []);

  useEffect(() => {
    loadData(onlyUnread, includeArchived);
  }, [onlyUnread, includeArchived]);

  useEffect(() => {
    const stream = notificacionesService.createStream();

    if (!stream) {
      return undefined;
    }

    const onRealtime = () => {
      loadData(onlyUnread, includeArchived);
      notifyUnreadChanged();
    };

    stream.addEventListener("notification:created", onRealtime);
    stream.addEventListener("notification:updated", onRealtime);
    stream.addEventListener("notification:bulk-updated", onRealtime);

    return () => {
      stream.close();
    };
  }, [onlyUnread, includeArchived]);

  const markOneAsRead = async (id) => {
    try {
      await notificacionesService.markAsRead(id);
      await loadData(onlyUnread);
      notifyUnreadChanged();
    } catch (markError) {
      setError(
        markError.response?.data?.message || "No se pudo marcar como leída",
      );
    }
  };

  const markAll = async () => {
    try {
      await notificacionesService.markAllAsRead();
      await loadData(onlyUnread);
      notifyUnreadChanged();
    } catch (markError) {
      setError(
        markError.response?.data?.message || "No se pudieron marcar todas",
      );
    }
  };

  const archiveToggle = async (item) => {
    try {
      if (item.archivada) {
        await notificacionesService.unarchive(item.id);
      } else {
        await notificacionesService.archive(item.id);
      }
      await loadData(onlyUnread, includeArchived);
      notifyUnreadChanged();
    } catch (archiveError) {
      setError(
        archiveError.response?.data?.message ||
          "No se pudo actualizar el archivado",
      );
    }
  };

  const goToSource = (item) => {
    const route = item?.metadata?.route;
    const normalizedRoute = normalizeNotificationRoute(route);

    if (!route || typeof route !== "string") {
      return;
    }

    if (shouldOpenInFacturas(item)) {
      navigate(buildFacturasRoute(item, role));
      return;
    }

    navigate(normalizedRoute);
  };

  if (loading) {
    return <Typography>Cargando notificaciones...</Typography>;
  }

  return (
    <Box sx={{ display: "flex", flexDirection: "column", gap: 2 }}>
      <Box
        sx={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          gap: 1,
        }}
      >
        <Box>
          <Typography variant="h4" fontWeight={800}>
            Notificaciones
          </Typography>
          <Typography color="text.secondary">
            Centro de avisos de tu actividad en la plataforma.
          </Typography>
        </Box>

        <Stack direction="row" spacing={1}>
          <Button
            variant={onlyUnread ? "contained" : "outlined"}
            onClick={() => setOnlyUnread((prev) => !prev)}
          >
            {onlyUnread ? "Mostrando no leídas" : "Filtrar no leídas"}
          </Button>
          <Button
            variant={includeArchived ? "contained" : "outlined"}
            onClick={() => setIncludeArchived((prev) => !prev)}
          >
            {includeArchived ? "Incluye archivadas" : "Sin archivadas"}
          </Button>
          <Button variant="contained" onClick={markAll}>
            Marcar todo leído
          </Button>
        </Stack>
      </Box>

      {error ? <Alert severity="error">{error}</Alert> : null}

      <Stack spacing={1.2}>
        {rows.length === 0 ? (
          <Card>
            <CardContent>
              <Typography color="text.secondary">
                No tienes notificaciones por ahora.
              </Typography>
            </CardContent>
          </Card>
        ) : (
          rows.map((item) => (
            <Card
              key={item.id}
              sx={{
                border: item.archivada
                  ? "1px dashed #cbd5e1"
                  : item.leida
                    ? "1px solid #e2e8f0"
                    : "2px solid #2563eb",
              }}
            >
              <CardContent>
                <Stack
                  direction="row"
                  alignItems="center"
                  spacing={2} // Un pequeño espacio de seguridad entre el texto y los chips
                  sx={{ mb: 0.7, width: "100%" }}
                >
                  {/* El flexGrow: 1 hace que este contenedor ocupe todo el espacio libre restante, empujando los chips a la derecha */}
                  <Box sx={{ flexGrow: 1 }}>
                    <Typography fontWeight={800}>{item.titulo}</Typography>
                  </Box>

                  <Stack direction="row" spacing={1} alignItems="center">
                    <Chip
                      label={item.leida ? "Leída" : "Nueva"}
                      variant="outlined" // Permite visualizar el borde personalizado
                      size="small"
                      sx={{
                        ...(item.leida
                          ? {
                              backgroundColor: "#fff3e0", // Fondo naranja muy claro
                              color: "#e65100", // Letra naranja oscuro (alta legibilidad)
                              borderColor: "#f57c00", // Borde naranja medio
                            }
                          : {
                              backgroundColor: "#e3f2fd", // Fondo azul claro
                              color: "#0d47a1", // Letra azul oscuro
                              borderColor: "#1976d2", // Borde azul
                            }),
                        fontWeight: "500", // Opcional: mejora la legibilidad
                      }}
                    />
                    <Chip
                      label={item.archivada ? "Archivada" : "Activa"}
                      variant="outlined"
                      size="small"
                      sx={{
                        ...(item.archivada
                          ? {
                              backgroundColor: "#eceff1", // Fondo gris azulado
                              color: "#455a64", // Letra gris oscuro
                              borderColor: "#b0bec5", // Borde
                            }
                          : {
                              backgroundColor: "#e8f5e9", // Fondo verde claro
                              color: "#1b5e20", // Letra verde oscuro
                              borderColor: "#2e7d32", // Borde verde
                            }),
                        fontWeight: "500",
                      }}
                    />
                  </Stack>
                </Stack>

                <Typography variant="body2" sx={{ mb: 1, mt: 3 }}>
                  {item.mensaje}
                </Typography>

                <Stack
                  direction="row"
                  alignItems="center"
                  spacing={2}
                  sx={{ width: "100%", mt: 2 }} // Forzamos el ancho completo del contenedor
                >
                  {/* El flexGrow: 1 en este Box expande el espacio y empuja todo lo que esté después hacia la derecha */}
                  <Box sx={{ flexGrow: 1 }}>
                    <Typography color="text.secondary">
                      {formatDate(item.createdAt)}
                    </Typography>
                  </Box>

                  {/* Contenedor de botones alineados perfectamente a la derecha */}
                  <Stack direction="row" spacing={1} alignItems="center">
                    {!item.leida ? (
                      <Button
                        size="small"
                        onClick={() => markOneAsRead(item.id)}
                      >
                        Marcar como leída
                      </Button>
                    ) : null}

                    {item?.metadata?.route ? (
                      <Button size="small" onClick={() => goToSource(item)}>
                        Ir al origen
                      </Button>
                    ) : null}

                    <Button size="small" onClick={() => archiveToggle(item)}>
                      {item.archivada ? "Desarchivar" : "Archivar"}
                    </Button>
                  </Stack>
                </Stack>
              </CardContent>
            </Card>
          ))
        )}
      </Stack>
    </Box>
  );
}

import { useEffect, useMemo, useState } from "react";

import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  FormControl,
  Grid,
  InputLabel,
  MenuItem,
  Select,
  Snackbar,
  Stack,
  Typography,
} from "@mui/material";

import LocalOfferIcon from "@mui/icons-material/LocalOffer";

import { promocionesService } from "../../services/promocionesService";
import { LicenseChip } from "../../components/common/LicenseChip";

const LICENCIAS = ["B", "A1", "A2", "A", "C", "D", "E"];

const isPromotionCurrent = (promo, now = new Date()) => {
  const start = promo?.fechaInicio ? new Date(promo.fechaInicio) : null;
  const end = promo?.fechaFin ? new Date(promo.fechaFin) : null;

  const startOk = !start || start <= now;
  const endOk = !end || end >= now;

  return startOk && endOk;
};

const formatDate = (value) => {
  if (!value) {
    return "Sin fecha límite";
  }

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return "Sin fecha límite";
  }

  return new Intl.DateTimeFormat("es-ES", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
  }).format(date);
};

export default function NuevaLicencia() {
  const [licencia, setLicencia] = useState("B");
  const [promociones, setPromociones] = useState([]);
  const [loading, setLoading] = useState(true);
  const [snackbar, setSnackbar] = useState({
    open: false,
    message: "",
    severity: "info",
  });

  useEffect(() => {
    const loadPromociones = async () => {
      setLoading(true);

      try {
        const allPromos = await promocionesService.getPublic();
        setPromociones(Array.isArray(allPromos) ? allPromos : []);
      } catch (error) {
        setPromociones([]);
        setSnackbar({
          open: true,
          message: "No se pudieron cargar las promociones",
          severity: "error",
        });
      } finally {
        setLoading(false);
      }
    };

    loadPromociones();
  }, []);

  const promocionesFiltradas = useMemo(() => {
    const now = new Date();

    return promociones.filter((promo) => {
      if (!Array.isArray(promo?.licenciasAplicables)) {
        return false;
      }

      return (
        promo.licenciasAplicables.includes(licencia) &&
        promo.activa === true &&
        isPromotionCurrent(promo, now)
      );
    });
  }, [promociones, licencia]);

  return (
    <Box sx={{ display: "flex", flexDirection: "column", gap: 3 }}>
      <Box>
        <Typography variant="h4" fontWeight={800}>
          Nueva licencia
        </Typography>
        <Typography color="text.secondary" sx={{ mt: 1 }}>
          Selecciona la licencia que quieres obtener y revisa las promociones
          vigentes disponibles.
        </Typography>
      </Box>

      <Card sx={{ borderRadius: 2 }}>
        <CardContent>
          <Stack direction={{ xs: "column", sm: "row" }} spacing={2}>
            <FormControl size="small" sx={{ minWidth: 220 }}>
              <InputLabel id="nueva-licencia-select-label">
                Licencia objetivo
              </InputLabel>
              <Select
                labelId="nueva-licencia-select-label"
                value={licencia}
                label="Licencia objetivo"
                onChange={(event) => setLicencia(event.target.value)}
              >
                {LICENCIAS.map((option) => (
                  <MenuItem key={option} value={option}>
                    {option}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>

            <Button variant="contained" disabled>
              Confirmar nueva licencia (Próximamente)
            </Button>
          </Stack>
        </CardContent>
      </Card>

      <Card sx={{ borderRadius: 2 }}>
        <CardContent>
          <Typography variant="h6" fontWeight={800} sx={{ mb: 2 }}>
            Promociones vigentes para licencia {licencia}
          </Typography>

          {loading ? (
            <Typography color="text.secondary">
              Cargando promociones...
            </Typography>
          ) : promocionesFiltradas.length === 0 ? (
            <Alert severity="info">
              No hay promociones disponibles para la licencia seleccionada
            </Alert>
          ) : (
            <Grid container spacing={2}>
              {promocionesFiltradas.map((promo) => (
                <Grid item xs={12} md={6} lg={4} key={promo.id}>
                  <Card variant="outlined" sx={{ height: "100%" }}>
                    <CardContent>
                      <Stack
                        direction="row"
                        justifyContent="space-between"
                        alignItems="flex-start"
                        spacing={1}
                      >
                        <Box>
                          <Typography variant="h6" fontWeight={700}>
                            {promo.nombre}
                          </Typography>
                          <Typography variant="body2" color="text.secondary">
                            {promo.descripcion || "Promoción activa"}
                          </Typography>
                        </Box>
                        <Chip
                          icon={<LocalOfferIcon />}
                          label="Vigente"
                          color="success"
                          size="small"
                        />
                      </Stack>

                      <Stack
                        direction="row"
                        spacing={1}
                        sx={{ mt: 1.5, mb: 1 }}
                      >
                        {(promo.licenciasAplicables || []).map((item) => (
                          <LicenseChip
                            key={`${promo.id}-${item}`}
                            value={item}
                          />
                        ))}
                      </Stack>

                      <Typography variant="body2" color="text.secondary">
                        Precio original:{" "}
                        {Number(promo.precioOriginal || 0).toFixed(2)} EUR
                      </Typography>
                      <Typography variant="body1" fontWeight={800}>
                        Precio oferta:{" "}
                        {Number(promo.precioPromocional || 0).toFixed(2)} EUR
                      </Typography>
                      <Typography
                        variant="body2"
                        color="text.secondary"
                        sx={{ mt: 0.5 }}
                      >
                        Vigencia: {formatDate(promo.fechaInicio)} -{" "}
                        {formatDate(promo.fechaFin)}
                      </Typography>

                      <Button
                        variant="outlined"
                        fullWidth
                        sx={{ mt: 2 }}
                        disabled
                      >
                        Comprar promoción (Próximamente)
                      </Button>
                    </CardContent>
                  </Card>
                </Grid>
              ))}
            </Grid>
          )}
        </CardContent>
      </Card>

      <Snackbar
        open={snackbar.open}
        autoHideDuration={3000}
        onClose={() => setSnackbar((prev) => ({ ...prev, open: false }))}
      >
        <Alert
          severity={snackbar.severity}
          onClose={() => setSnackbar((prev) => ({ ...prev, open: false }))}
        >
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  );
}

import { useEffect, useMemo, useState } from "react";
import {
  Alert,
  Box,
  Button,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogContentText,
  DialogTitle,
  FormControl,
  IconButton,
  InputLabel,
  Menu,
  MenuItem,
  Paper,
  Select,
  Snackbar,
  Stack,
  TextField,
  Tooltip,
  Typography,
} from "@mui/material";
import { DataGrid } from "@mui/x-data-grid";
import AddIcon from "@mui/icons-material/Add";
import EditIcon from "@mui/icons-material/Edit";
import ToggleOnIcon from "@mui/icons-material/ToggleOn";
import ToggleOffIcon from "@mui/icons-material/ToggleOff";
import DownloadIcon from "@mui/icons-material/Download";
import LockResetIcon from "@mui/icons-material/LockReset";
import DeleteForeverIcon from "@mui/icons-material/DeleteForever";
import { jwtDecode } from "jwt-decode";

import { otrosUsuariosService } from "../../services/otrosUsuariosService";
import { exportOtrosUsuariosExcel } from "../../utils/exportOtrosUsuariosExcel";
import { exportOtrosUsuariosPdf } from "../../utils/exportOtrosUsuariosPdf";

const emptyForm = {
  nombre: "",
  email: "",
  password: "",
  dni: "",
  telefono: "",
  rol: "ADMINISTRATIVO",
};

const normalizarTelefono = (valor) =>
  String(valor || "")
    .replace(/\D/g, "")
    .slice(0, 9);

const limpiarDni = (valor) =>
  String(valor || "")
    .toUpperCase()
    .replace(/[^0-9A-Z]/g, "");

const esDniCompleto = (valor) => /^\d{8}[A-Z]$/.test(limpiarDni(valor));

const esTelefonoValido = (valor) => /^\d{9}$/.test(String(valor || ""));

const normalizeRole = (role) => {
  if (role === "GESTOR") {
    return "SOPORTE";
  }

  return role;
};

export default function OtrosUsuarios() {
  const token = localStorage.getItem("token") || "";
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(false);
  const [currentRole, setCurrentRole] = useState("ADMIN");
  const [search, setSearch] = useState("");
  const [estadoFiltro, setEstadoFiltro] = useState("todos");
  const [rolFiltro, setRolFiltro] = useState("todos");
  const [openDialog, setOpenDialog] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(emptyForm);
  const [exportAnchorEl, setExportAnchorEl] = useState(null);
  const [resetDialog, setResetDialog] = useState({
    open: false,
    usuarioId: null,
    nombre: "",
    motivo: "",
    newPassword: "",
  });

  const [confirmDialog, setConfirmDialog] = useState({
    open: false,
    action: null,
    usuarioId: null,
    nombre: "",
    title: "",
    message: "",
  });

  const [notification, setNotification] = useState({
    open: false,
    message: "",
    severity: "success",
  });

  useEffect(() => {
    try {
      const decoded = jwtDecode(token);
      setCurrentRole(normalizeRole(decoded?.rol || "ADMIN"));
    } catch {
      setCurrentRole("ADMIN");
    }
  }, [token]);

  const isAdmin = currentRole === "ADMIN";
  const isSupport = currentRole === "SOPORTE";

  const loadData = async () => {
    setLoading(true);

    try {
      const params = {
        search: search.trim() || undefined,
        rol: rolFiltro !== "todos" ? rolFiltro : undefined,
        activo:
          estadoFiltro === "todos"
            ? undefined
            : estadoFiltro === "activos"
              ? true
              : false,
      };

      const data = await otrosUsuariosService.getAll(params);
      setRows(Array.isArray(data) ? data : []);
    } catch (error) {
      setNotification({
        open: true,
        message:
          error.response?.data?.message || "No se pudieron cargar los usuarios",
        severity: "error",
      });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, [search, rolFiltro, estadoFiltro]);

  const resetForm = () => {
    setForm(emptyForm);
    setEditingId(null);
  };

  const handleOpenCreate = () => {
    resetForm();
    setOpenDialog(true);
  };

  const handleOpenEdit = (row) => {
    setEditingId(row.id);
    setForm({
      nombre: row.nombre || "",
      email: row.email || "",
      password: "",
      dni: row.dni || "",
      telefono: row.telefono || "",
      rol: row.rol || "ADMINISTRATIVO",
    });
    setOpenDialog(true);
  };

  const handleCloseDialog = () => {
    setOpenDialog(false);
    resetForm();
  };

  const saveUsuario = async () => {
    try {
      if (!form.nombre.trim()) {
        throw new Error("El nombre es obligatorio");
      }

      if (!form.email.trim()) {
        throw new Error("El email es obligatorio");
      }

      if (!esDniCompleto(form.dni)) {
        throw new Error("El DNI debe tener formato 12345678Z");
      }

      const telefono = normalizarTelefono(form.telefono);

      if (!esTelefonoValido(telefono)) {
        throw new Error("El teléfono debe tener 9 dígitos");
      }

      if (!editingId && String(form.password || "").length < 8) {
        throw new Error("La contraseña debe tener al menos 8 caracteres");
      }

      const payload = {
        nombre: form.nombre.trim(),
        email: form.email.trim(),
        dni: limpiarDni(form.dni),
        telefono,
        rol: form.rol,
      };

      if (form.password.trim()) {
        payload.password = form.password.trim();
      }

      if (editingId) {
        await otrosUsuariosService.update(editingId, payload);
      } else {
        await otrosUsuariosService.create({
          ...payload,
          password: form.password,
        });
      }

      setNotification({
        open: true,
        message: editingId
          ? "Usuario actualizado correctamente"
          : "Usuario creado correctamente",
        severity: "success",
      });

      handleCloseDialog();
      await loadData();
    } catch (error) {
      setNotification({
        open: true,
        message:
          error.response?.data?.message ||
          error.message ||
          "Error guardando usuario",
        severity: "error",
      });
    }
  };

  const askDeactivate = (row) => {
    setConfirmDialog({
      open: true,
      action: "deactivate",
      usuarioId: row.id,
      nombre: row.nombre,
      title: "Confirmar desactivación",
      message: `Vas a desactivar a ${row.nombre}. ¿Deseas continuar?`,
    });
  };

  const askActivate = (row) => {
    setConfirmDialog({
      open: true,
      action: "activate",
      usuarioId: row.id,
      nombre: row.nombre,
      title: "Confirmar activación",
      message: `Vas a activar a ${row.nombre}. ¿Deseas continuar?`,
    });
  };

  const askHardDelete = (row) => {
    setConfirmDialog({
      open: true,
      action: "hard-delete",
      usuarioId: row.id,
      nombre: row.nombre,
      title: "Confirmar borrado definitivo",
      message: `Vas a eliminar definitivamente a ${row.nombre}. Esta acción no se puede deshacer. ¿Deseas continuar?`,
    });
  };

  const closeConfirm = () => {
    setConfirmDialog({
      open: false,
      action: null,
      usuarioId: null,
      nombre: "",
      title: "",
      message: "",
    });
  };

  const handleConfirmAction = async () => {
    try {
      if (!confirmDialog.usuarioId) {
        return;
      }

      if (confirmDialog.action === "deactivate") {
        await otrosUsuariosService.deactivate(confirmDialog.usuarioId);
      }

      if (confirmDialog.action === "activate") {
        await otrosUsuariosService.activate(confirmDialog.usuarioId);
      }

      if (confirmDialog.action === "hard-delete") {
        await otrosUsuariosService.hardDelete(confirmDialog.usuarioId);
      }

      setNotification({
        open: true,
        message:
          confirmDialog.action === "activate"
            ? "Usuario activado correctamente"
            : confirmDialog.action === "hard-delete"
              ? "Usuario eliminado definitivamente"
              : "Usuario desactivado correctamente",
        severity: "success",
      });

      closeConfirm();
      await loadData();
    } catch (error) {
      setNotification({
        open: true,
        message:
          error.response?.data?.message || "No se pudo procesar la acción",
        severity: "error",
      });
    }
  };

  const openResetDialog = (row) => {
    setResetDialog({
      open: true,
      usuarioId: row.id,
      nombre: row.nombre,
      motivo: "",
      newPassword: "",
    });
  };

  const closeResetDialog = () => {
    setResetDialog({
      open: false,
      usuarioId: null,
      nombre: "",
      motivo: "",
      newPassword: "",
    });
  };

  const submitResetPassword = async () => {
    try {
      const response = await otrosUsuariosService.resetPassword(
        resetDialog.usuarioId,
        {
          motivo: resetDialog.motivo || undefined,
          newPassword: resetDialog.newPassword || undefined,
        },
      );

      setNotification({
        open: true,
        message: `Password reseteada. Temporal: ${response.passwordTemporal}`,
        severity: "success",
      });

      closeResetDialog();
      await loadData();
    } catch (error) {
      setNotification({
        open: true,
        message:
          error.response?.data?.message || "No se pudo resetear la contraseña",
        severity: "error",
      });
    }
  };

  const filteredRows = useMemo(() => rows, [rows]);

  const columns = [
    {
      field: "nombre",
      headerName: "Nombre",
      flex: 1.2,
    },
    {
      field: "email",
      headerName: "Email",
      flex: 1.4,
    },
    {
      field: "rol",
      headerName: "Perfil",
      flex: 0.9,
      renderCell: (params) => {
        // 1. Definimos los colores personalizados para cada rol
        const coloresPorRol = {
          SOPORTE: { fondo: "#e3f2fd", texto: "#0d47a1" }, // Azul claro y oscuro
          ADMINISTRATIVO: { fondo: "#fff3e0", texto: "#e65100" }, // Naranja claro y oscuro
        };

        // 2. Obtenemos los colores correspondientes o asignamos unos por defecto
        const estiloActual = coloresPorRol[params.value] || {
          fondo: "#f5f5f5",
          texto: "#333333",
        };

        return (
          <Chip
            label={params.value}
            size="small"
            sx={{
              backgroundColor: estiloActual.fondo,
              color: estiloActual.texto,
              fontWeight: "bold", // Opcional: para que resalte más el texto
            }}
          />
        );
      },
    },
    {
      field: "dni",
      headerName: "DNI",
      flex: 0.8,
      valueGetter: (_, row) => row.dni || "-",
    },
    {
      field: "telefono",
      headerName: "Teléfono",
      flex: 0.9,
      valueGetter: (_, row) => row.telefono || "-",
    },
    {
      field: "activo",
      headerName: "Estado",
      flex: 0.8,
      renderCell: (params) => (
        <Chip
          label={(params.row.activo ?? true) ? "Activo" : "Inactivo"}
          size="small"
          sx={{
            // 1. Estilos si está Activo
            ...((params.row.activo ?? true) && {
              backgroundColor: "#e8f5e9", // Fondo verde claro
              color: "#2e7d32", // Texto verde oscuro
              border: "1px solid #2e7d32", // Borde verde
            }),
            // 2. Estilos si está Inactivo
            ...(!(params.row.activo ?? true) && {
              backgroundColor: "#ffebee", // Fondo rojo claro
              color: "#c62828", // Texto rojo oscuro
              border: "1px solid #c62828", // Borde rojo
            }),
            fontWeight: "bold", // Estilo común para ambos estados (opcional)
          }}
        />
      ),
    },
    {
      field: "acciones",
      headerName: "Acciones",
      sortable: false,
      filterable: false,
      disableColumnMenu: true,
      width: 260,
      renderCell: (params) => (
        <Stack direction="row" spacing={0.5}>
          <Tooltip title="Editar" arrow>
            <IconButton
              color="primary"
              size="small"
              onClick={() => handleOpenEdit(params.row)}
            >
              <EditIcon fontSize="small" />
            </IconButton>
          </Tooltip>

          {isSupport ? (
            <Tooltip title="Reset password" arrow>
              <IconButton
                color="warning"
                size="small"
                onClick={() => openResetDialog(params.row)}
              >
                <LockResetIcon fontSize="small" />
              </IconButton>
            </Tooltip>
          ) : null}

          {params.row.activo ? (
            <Tooltip title="Desactivar" arrow>
              <IconButton
                color="warning"
                size="small"
                onClick={() => askDeactivate(params.row)}
              >
                <ToggleOffIcon fontSize="small" />
              </IconButton>
            </Tooltip>
          ) : (
            <Tooltip title="Activar" arrow>
              <IconButton
                color="success"
                size="small"
                onClick={() => askActivate(params.row)}
              >
                <ToggleOnIcon fontSize="small" />
              </IconButton>
            </Tooltip>
          )}

          {isAdmin ? (
            <Tooltip title="Borrar definitivo" arrow>
              <IconButton
                color="error"
                size="small"
                onClick={() => askHardDelete(params.row)}
              >
                <DeleteForeverIcon fontSize="small" />
              </IconButton>
            </Tooltip>
          ) : null}
        </Stack>
      ),
    },
  ];

  return (
    <Box>
      <Box
        sx={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          gap: 2,
          mb: 2,
          flexWrap: "wrap",
        }}
      >
        <Box>
          <Typography variant="h4" fontWeight={700}>
            Otros Usuarios
          </Typography>
          <Typography color="text.secondary">
            {isSupport
              ? "Gestión de usuarios (ADMIN, PROFESOR, ALUMNO y ADMINISTRATIVO)."
