        <DialogTitle>
          {editingId ? "Editar usuario" : "Nuevo usuario"}
        </DialogTitle>
        <DialogContent>
          <Stack spacing={2} sx={{ mt: 0.5 }}>
            <TextField
              label="Nombre"
              value={form.nombre}
              onChange={(event) =>
