              fullWidth
            />
            <TextField
              label={editingId ? "Nueva contraseña (opcional)" : "Contraseña"}
              type="password"
              value={form.password}
              onChange={(event) =>
                setForm((prev) => ({ ...prev, password: event.target.value }))
              }
              fullWidth
            />
            <TextField
              label="DNI"
              value={form.dni}
              onChange={(event) =>
                setForm((prev) => ({
                  ...prev,
                  dni: limpiarDni(event.target.value),
                }))
              }
              fullWidth
            />
            <TextField
              label="Teléfono"
              value={form.telefono}
              onChange={(event) =>
                setForm((prev) => ({
                  ...prev,
                  telefono: normalizarTelefono(event.target.value),
                }))
              }
              fullWidth
            />
            <FormControl fullWidth>
              <InputLabel id="rol-label">Perfil</InputLabel>
              <Select
                labelId="rol-label"
                label="Perfil"
                value={form.rol}
                onChange={(event) =>
                  setForm((prev) => ({ ...prev, rol: event.target.value }))
                }
              >
                {isSupport ? <MenuItem value="ADMIN">ADMIN</MenuItem> : null}
                {isSupport ? (
                  <MenuItem value="PROFESOR">PROFESOR</MenuItem>
                ) : null}
                {isSupport ? <MenuItem value="ALUMNO">ALUMNO</MenuItem> : null}
                <MenuItem value="ADMINISTRATIVO">ADMINISTRATIVO</MenuItem>
                {!isSupport ? (
                  <MenuItem value="SOPORTE">SOPORTE</MenuItem>
                ) : null}
              </Select>
            </FormControl>
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseDialog}>Cancelar</Button>
          <Button variant="contained" onClick={saveUsuario}>
            Guardar
