        </DialogContent>
        <DialogActions>
          <Button onClick={closeConfirm}>Cancelar</Button>
          <Button
            variant="contained"
            color={confirmDialog.action === "activate" ? "success" : "error"}
            onClick={handleConfirmAction}
          >
            Confirmar
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog
        open={resetDialog.open}
        onClose={closeResetDialog}
        fullWidth
        maxWidth="sm"
      >
        <DialogTitle>Reset de contraseña</DialogTitle>
        <DialogContent>
          <DialogContentText sx={{ mb: 2 }}>
            Se forzará cambio de contraseña en el próximo acceso para{" "}
            {resetDialog.nombre}.
          </DialogContentText>
          <Stack spacing={2}>
            <TextField
              label="Nueva contraseña temporal (opcional)"
              type="password"
              value={resetDialog.newPassword}
              onChange={(event) =>
                setResetDialog((prev) => ({
                  ...prev,
                  newPassword: event.target.value,
                }))
              }
              fullWidth
            />
            <TextField
              label="Motivo de reset (opcional)"
              value={resetDialog.motivo}
              onChange={(event) =>
                setResetDialog((prev) => ({
                  ...prev,
                  motivo: event.target.value,
                }))
              }
              fullWidth
              multiline
              minRows={2}
            />
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button onClick={closeResetDialog}>Cancelar</Button>
          <Button
            variant="contained"
            color="warning"
            onClick={submitResetPassword}
          >
            Resetear
          </Button>
        </DialogActions>
      </Dialog>

      <Snackbar
        open={notification.open}
        autoHideDuration={4500}
        onClose={() => setNotification((prev) => ({ ...prev, open: false }))}
      >
        <Alert
          onClose={() => setNotification((prev) => ({ ...prev, open: false }))}
          severity={notification.severity}
          variant="filled"
          sx={{ width: "100%" }}
        >
          {notification.message}
        </Alert>
      </Snackbar>
    </Box>
  );
}

import { useEffect, useMemo, useState } from "react";
import {
  Alert,
  Box,
  Button,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  IconButton,
  InputLabel,
  Menu,
  MenuItem,
  Paper,
  Select,
  Stack,
  TextField,
  Typography,
} from "@mui/material";
import NavigateBeforeIcon from "@mui/icons-material/NavigateBefore";
import NavigateNextIcon from "@mui/icons-material/NavigateNext";
import CheckCircleIcon from "@mui/icons-material/CheckCircle";
import CancelIcon from "@mui/icons-material/Cancel";
import SaveIcon from "@mui/icons-material/Save";
import AddIcon from "@mui/icons-material/Add";
import DeleteIcon from "@mui/icons-material/Delete";
import CalendarMonthIcon from "@mui/icons-material/CalendarMonth";
import AccessTimeIcon from "@mui/icons-material/AccessTime";
import DirectionsCarIcon from "@mui/icons-material/DirectionsCar";
import PersonIcon from "@mui/icons-material/Person";
import { profesorPortalService } from "../../services/profesorPortalService";
import { clasesPracticasPortalService } from "../../services/clasesPracticasPortalService";
import {
  addDaysToDateKey,
  dateFromKeyAtNoon,
  extractDateKey,
  formatDateValue,
  getWeekDayIdFromValue,
  toDateKeyFromDate,
} from "../../utils/calendarDate";
import { LicenseChip } from "../../components/common/LicenseChip";

const DAYS = [
  { id: 1, short: "Lun", label: "Lunes" },
  { id: 2, short: "Mar", label: "Martes" },
  { id: 3, short: "Mie", label: "Miercoles" },
  { id: 4, short: "Jue", label: "Jueves" },
  { id: 5, short: "Vie", label: "Viernes" },
  { id: 6, short: "Sab", label: "Sabado" },
  { id: 7, short: "Dom", label: "Domingo" },
];

const DAY_NAME_BY_ID = DAYS.reduce((acc, day) => {
  acc[day.id] = day.label;
  return acc;
}, {});

const DEFAULT_START_MINUTES = 8 * 60;
const DEFAULT_END_MINUTES = 16 * 60;
const HOUR_HEIGHT = 230;
const EVENT_CARD_BOTTOM_BUFFER = 150;
const TIME_GUTTER_WIDTH = 98;
const TIME_GUTTER_HEIGHT = 98;
const DAY_COLUMN_MIN_WIDTH = 210;

const STUDENT_PALETTE = [
  {
    bg: "#e9f2ff",
    border: "#9cc6ff",
    title: "#1e3a8a",
  },
  {
    bg: "#fff3e6",
    border: "#ffd39f",
    title: "#92400e",
  },
  {
    bg: "#e8f9f1",
    border: "#98e4be",
    title: "#166534",
  },
  {
    bg: "#f1ecff",
    border: "#c5b2ff",
    title: "#5b21b6",
  },
  {
    bg: "#e8f7fb",
    border: "#93dff0",
    title: "#0f4f66",
  },
];

const formatDate = (value) => {
  return (
    formatDateValue(value, {
      day: "numeric",
      month: "numeric",
      year: "numeric",
    }) || ""
  );
};

const formatDayMonth = (value) => {
  return (
    formatDateValue(value, {
      day: "numeric",
      month: "short",
    }) || ""
  );
};

const formatHour = (value) => {
  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return "--:--";
  }

  return date.toLocaleTimeString("es-ES", {
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  });
};

const formatWeekLabel = (week) => {
  if (!week?.inicio || !week?.fin) {
    return "Semana";
  }

  return `${formatDate(week.inicio)} - ${formatDate(week.fin)}`;
};

const dateToDayId = (value) => {
  return getWeekDayIdFromValue(value);
};

const timeToMinutes = (time) => {
  if (typeof time !== "string") {
    return Number.NaN;
  }

  const match = time.match(/^([01]\d|2[0-3]):([0-5]\d)$/);

  if (!match) {
    return Number.NaN;
  }

  return Number(match[1]) * 60 + Number(match[2]);
};

const minutesToTime = (minutes) => {
  const hh = String(Math.floor(minutes / 60)).padStart(2, "0");
  const mm = String(minutes % 60).padStart(2, "0");
  return `${hh}:${mm}`;
};

const getColorByStudent = (studentId, studentName) => {
  const seed = String(studentId || studentName || "SIN_ALUMNO");
  let hash = 0;

  for (let i = 0; i < seed.length; i += 1) {
    hash = (hash << 5) - hash + seed.charCodeAt(i);
    hash |= 0;
  }

  const index = Math.abs(hash) % STUDENT_PALETTE.length;
  return STUDENT_PALETTE[index];
};

const formatHoursSummary = (minutes) => {
  const safeMinutes = Number.isFinite(minutes) ? Math.max(minutes, 0) : 0;
  const hours = Math.floor(safeMinutes / 60);
  const remainder = safeMinutes % 60;
  return `${hours}h ${String(remainder).padStart(2, "0")}min`;
};

const getAgendaStatusChipConfig = (status) => {
  const normalized = String(status || "").toUpperCase();

  if (normalized === "REGISTRADA") {
    return { label: "REGISTRADA", color: "success" };
  }

  if (normalized === "PENDIENTE_REGISTRO") {
    return { label: "PENDIENTE REGISTRO", color: "warning" };
  }

  if (normalized === "EN_CURSO") {
    return { label: "EN CURSO", color: "info" };
  }

  if (normalized === "CONFIRMADA") {
    return { label: "CONFIRMADA", color: "primary" };
  }

  if (normalized === "PROGRAMADA") {
    return { label: "PROGRAMADA", color: "default" };
  }

  return { label: normalized || "SIN ESTADO", color: "default" };
};

const COMPLETED_STATUSES = [
  "REALIZADA",
  "COMPLETADA",
  "FINALIZADA",
  "REGISTRADA",
];

const PROGRAMMED_STATUSES = ["PROGRAMADA", "CONFIRMADA"];

const buildImageSrc = (ruta) => {
  if (!ruta) {
    return "";
  }

  if (ruta.startsWith("http://") || ruta.startsWith("https://")) {
    return ruta;
  }

  if (ruta.startsWith("/api/")) {
    return ruta;
  }

  if (ruta.startsWith("api/")) {
    return `/${ruta}`;
  }

  if (ruta.startsWith("/uploads/")) {
    return `/api${ruta}`;
  }

  if (ruta.startsWith("uploads/")) {
    return `/api/${ruta}`;
  }

  return ruta;
};

const isDateInRange = (value, from, to) => {
  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return false;
  }

  return date >= from && date <= to;
};

const summarizeClassesByPeriod = (rows, from, to) => {
  return (rows || []).reduce(
    (acc, row) => {
      if (!isDateInRange(row?.fecha, from, to)) {
        return acc;
      }

      const estado = String(row?.estado || "").toUpperCase();

      if (PROGRAMMED_STATUSES.includes(estado)) {
        acc.programadasConfirmadas += 1;
      }

      if (estado === "PROGRAMADA") {
        acc.pendientesConfirmar += 1;
      }

      if (COMPLETED_STATUSES.includes(estado)) {
        acc.completadasRegistradas += 1;
      }

      return acc;
    },
    {
      programadasConfirmadas: 0,
      pendientesConfirmar: 0,
      completadasRegistradas: 0,
    },
  );
};

export default function ProfesorAgenda() {
  const [weekOffset, setWeekOffset] = useState(0);
  const [agenda, setAgenda] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [saving, setSaving] = useState(false);
  const [savingClassId, setSavingClassId] = useState("");
  const [openScheduleModal, setOpenScheduleModal] = useState(false);
  const [viewMenuAnchor, setViewMenuAnchor] = useState(null);
  const [showOnlyToday, setShowOnlyToday] = useState(false);
  const [classRows, setClassRows] = useState([]);

  const [scheduleBlocks, setScheduleBlocks] = useState([]);
  const [newBlock, setNewBlock] = useState({
    diaSemana: 1,
    horaInicio: "08:00",
    horaFin: "08:45",
  });

  const loadAgenda = async (offset = weekOffset) => {
    setLoading(true);
    setError("");

    try {
      const [data, professorClasses] = await Promise.all([
        profesorPortalService.getAgenda(offset),
        clasesPracticasPortalService.getProfessorRequests(),
      ]);
      setAgenda(data);
      setClassRows(Array.isArray(professorClasses) ? professorClasses : []);

      const flattened = (data?.horario || []).flatMap((day) =>
        (day?.bloques || []).map((block) => ({
          diaSemana: day.diaSemana,
          horaInicio: block.horaInicio,
          horaFin: block.horaFin,
        })),
      );

      setScheduleBlocks(flattened);
    } catch (loadError) {
      setError(
        loadError.response?.data?.message ||
          "No se pudo cargar la agenda del profesor",
      );
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadAgenda(weekOffset);
  }, [weekOffset]);

  const weekDays = useMemo(() => {
    const weekStartKey = extractDateKey(agenda?.semana?.inicio);

    if (!weekStartKey) {
      return DAYS.map((day) => ({
        ...day,
        date: null,
      }));
    }

    return DAYS.map((day, index) => {
      const dayKey = addDaysToDateKey(weekStartKey, index);
      const date = dateFromKeyAtNoon(dayKey);

      return {
        ...day,
        date,
      };
    });
  }, [agenda?.semana?.inicio]);

  const classesByDay = useMemo(() => {
    const map = new Map();
    weekDays.forEach((day) => map.set(day.id, []));

    (agenda?.clases || []).forEach((clase) => {
      const dayId = dateToDayId(clase.fecha);
      const list = map.get(dayId) || [];
      list.push(clase);
      map.set(dayId, list);
    });

    for (const day of weekDays) {
      const sorted = (map.get(day.id) || []).sort(
        (a, b) => new Date(a.fecha).getTime() - new Date(b.fecha).getTime(),
      );
      map.set(day.id, sorted);
    }

    return map;
  }, [agenda, weekDays]);

  const minuteRange = useMemo(() => {
    const allMinutes = [];

    for (const block of scheduleBlocks) {
      const start = timeToMinutes(block.horaInicio);
      const end = timeToMinutes(block.horaFin);

      if (!Number.isNaN(start)) {
        allMinutes.push(start);
      }

      if (!Number.isNaN(end)) {
        allMinutes.push(end);
      }
    }

    for (const clase of agenda?.clases || []) {
      const date = new Date(clase.fecha);

      if (Number.isNaN(date.getTime())) {
        continue;
      }

      const start = date.getHours() * 60 + date.getMinutes();
      const duration = Number(clase.duracion) || 45;
      allMinutes.push(start, start + duration);
    }

    if (allMinutes.length === 0) {
      return {
        startMinutes: DEFAULT_START_MINUTES,
        endMinutes: DEFAULT_END_MINUTES,
      };
    }

    const minValue = Math.max(0, Math.min(...allMinutes));
    const maxValue = Math.min(24 * 60, Math.max(...allMinutes));
    const startMinutes = Math.floor(minValue / 60) * 60;
    const endRounded = Math.ceil(maxValue / 60) * 60;
    const endMinutes = Math.max(endRounded, startMinutes + 60);

    return {
      startMinutes,
      endMinutes,
    };
  }, [agenda?.clases, scheduleBlocks]);

  const hourMarks = useMemo(() => {
    const marks = [];

    for (
      let minutes = minuteRange.startMinutes;
      minutes <= minuteRange.endMinutes;
      minutes += 60
    ) {
      marks.push(minutes);
    }

    return marks;
  }, [minuteRange]);

  const timelineHeight =
    ((minuteRange.endMinutes - minuteRange.startMinutes) / 60) * HOUR_HEIGHT;
  const dayColumnHeight = timelineHeight + EVENT_CARD_BOTTOM_BUFFER;

  const footerSummary = useMemo(() => {
    const clases = agenda?.clases || [];
    const totalReservas = clases.length;

    const totalMinutes = clases.reduce(
      (acc, clase) => acc + (Number(clase.duracion) || 45),
      0,
    );

    const vehiculosUnicos = new Set(
      clases
        .map((clase) => clase.vehiculo?.matricula)
        .filter((matricula) => Boolean(matricula)),
    );

    return {
      totalReservas,
      totalMinutes,
      vehiculosUtilizados: vehiculosUnicos.size,
    };
  }, [agenda?.clases]);

  const periodSummary = useMemo(() => {
    const now = new Date();

    const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
    const endOfMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0);
    endOfMonth.setHours(23, 59, 59, 999);

    const weekStart = new Date(now);
    weekStart.setHours(0, 0, 0, 0);
    const dayIndex = weekStart.getDay();
    const distanceFromMonday = (dayIndex + 6) % 7;
    weekStart.setDate(weekStart.getDate() - distanceFromMonday);

    const weekEnd = new Date(weekStart);
    weekEnd.setDate(weekEnd.getDate() + 6);
    weekEnd.setHours(23, 59, 59, 999);

    return {
      mes: summarizeClassesByPeriod(classRows, startOfMonth, endOfMonth),
      semana: summarizeClassesByPeriod(classRows, weekStart, weekEnd),
    };
  }, [classRows]);

  const addBlock = () => {
    const startMinutes = timeToMinutes(newBlock.horaInicio);
    const endMinutes = timeToMinutes(newBlock.horaFin);

    if (Number.isNaN(startMinutes) || Number.isNaN(endMinutes)) {
      setError("Las horas del bloque deben tener formato HH:mm");
      return;
    }

    if (endMinutes <= startMinutes) {
      setError("La hora de fin del bloque debe ser posterior a la de inicio");
      return;
    }

    setError("");

    setScheduleBlocks((prev) => [
      ...prev,
      {
        diaSemana: Number(newBlock.diaSemana),
        horaInicio: newBlock.horaInicio,
        horaFin: newBlock.horaFin,
      },
    ]);
  };

  const removeBlock = (index) => {
    setScheduleBlocks((prev) => prev.filter((_, i) => i !== index));
  };

  const removeLastInsertedBlock = () => {
    setScheduleBlocks((prev) => prev.slice(0, -1));
  };

  const saveSchedule = async () => {
    setSaving(true);
    setError("");

    try {
      const response =
        await profesorPortalService.updateWorkSchedule(scheduleBlocks);

      const flattened = (response?.horario || []).flatMap((day) =>
        (day?.bloques || []).map((block) => ({
          diaSemana: day.diaSemana,
          horaInicio: block.horaInicio,
          horaFin: block.horaFin,
        })),
      );

      setScheduleBlocks(flattened);
      await loadAgenda(weekOffset);
    } catch (saveError) {
      setError(
        saveError.response?.data?.message || "No se pudo guardar el horario",
      );
    } finally {
      setSaving(false);
    }
  };

  const handleClassStatus = async (classId, estado) => {
    setSavingClassId(classId);
    setError("");

    try {
      await profesorPortalService.updateClassStatus(classId, estado);
      await loadAgenda(weekOffset);
    } catch (statusError) {
      setError(
        statusError.response?.data?.message ||
          "No se pudo actualizar el estado de la clase",
      );
    } finally {
      setSavingClassId("");
    }
  };

  return (
    <Box>
      <Stack
        direction={{ xs: "column", md: "row" }}
        spacing={1.25}
        justifyContent="space-between"
        alignItems={{ xs: "stretch", md: "flex-start" }}
        sx={{ mb: 2 }}
      >
        <Stack spacing={1} sx={{ width: "100%" }}>
          <Stack
            direction={{ xs: "column", sm: "row" }}
            spacing={1}
            alignItems={{ xs: "flex-start", sm: "center" }}
          >
            <Typography variant="h4" fontWeight={800}>
              Mi agenda
            </Typography>

            <Button
              variant="outlined"
              onClick={() => setOpenScheduleModal(true)}
            >
              Configurar horario
            </Button>
          </Stack>

          <Stack
            direction={{ xs: "column", lg: "row" }}
            spacing={1}
            sx={{ width: "100%" }}
          >
            <Paper
              variant="outlined"
              sx={{
                p: 1,
                borderRadius: 2,
                flex: 1,
                minWidth: 300,
                backgroundColor: "#f8fbff",
              }}
            >
              <Typography variant="caption" color="text.secondary">
                Clases del mes actual
              </Typography>
              <Stack direction="row" spacing={0.75} sx={{ mt: 0.7 }} useFlexGap>
                <Chip
                  size="small"
                  color="primary"
                  label={`Prog./Conf.: ${periodSummary.mes.programadasConfirmadas}`}
                />
                <Chip
                  size="small"
                  color="warning"
                  label={`Pend. confirmar: ${periodSummary.mes.pendientesConfirmar}`}
                />
                <Chip
                  size="small"
                  color="success"
                  label={`Complet./Reg.: ${periodSummary.mes.completadasRegistradas}`}
                />
              </Stack>
            </Paper>

            <Paper
              variant="outlined"
              sx={{
                p: 1,
                borderRadius: 2,
                flex: 1,
                minWidth: 300,
                backgroundColor: "#f7fcf9",
              }}
            >
              <Typography variant="caption" color="text.secondary">
                Clases de esta semana
              </Typography>
              <Stack direction="row" spacing={0.75} sx={{ mt: 0.7 }} useFlexGap>
                <Chip
                  size="small"
                  color="primary"
                  label={`Prog./Conf.: ${periodSummary.semana.programadasConfirmadas}`}
                />
                <Chip
                  size="small"
                  color="warning"
                  label={`Pend. confirmar: ${periodSummary.semana.pendientesConfirmar}`}
                />
                <Chip
                  size="small"
                  color="success"
                  label={`Complet./Reg.: ${periodSummary.semana.completadasRegistradas}`}
                />
              </Stack>
            </Paper>
          </Stack>
        </Stack>
      </Stack>

      {error && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {error}
        </Alert>
      )}

      <Paper sx={{ p: 2, borderRadius: 3 }}>
        <Stack
          direction={{ xs: "column", md: "row" }}
          justifyContent="space-between"
          alignItems={{ xs: "stretch", md: "center" }}
          spacing={1.5}
          sx={{ mb: 2 }}
        >
          <Box
            sx={{
              display: "grid",
              gridTemplateColumns: "auto minmax(230px, 1fr) auto",
              alignItems: "center",
              gap: 1,
              width: { xs: "100%", md: 320 },
            }}
          >
            <IconButton
              sx={{ border: "1px solid #dbe5f2", borderRadius: 2 }}
              onClick={() => {
                setWeekOffset((prev) => prev - 1);
                setShowOnlyToday(false);
              }}
            >
              <NavigateBeforeIcon />
            </IconButton>

            <Typography
              fontWeight={700}
              sx={{ textAlign: "center", whiteSpace: "nowrap" }}
            >
              {formatWeekLabel(agenda?.semana)}
            </Typography>

            <IconButton
              sx={{ border: "1px solid #dbe5f2", borderRadius: 2 }}
              onClick={() => {
                setWeekOffset((prev) => prev + 1);
                setShowOnlyToday(false);
              }}
            >
              <NavigateNextIcon />
            </IconButton>
          </Box>

          <Stack direction="row" spacing={1}>
            <Button
              variant={showOnlyToday ? "contained" : "outlined"}
              onClick={() => {
                setWeekOffset(0);
                setShowOnlyToday(true);
              }}
            >
              Hoy
            </Button>

            <Button
              variant={showOnlyToday ? "outlined" : "contained"}
              onClick={() => setShowOnlyToday(false)}
              sx={{
                backgroundColor: showOnlyToday ? "transparent" : "#2f80ed",
                textTransform: "none",
                boxShadow: "none",
                "&:hover": {
                  backgroundColor: showOnlyToday ? "transparent" : "#1d6fe0",
                  boxShadow: "none",
                },
              }}
            >
              Semana
            </Button>

            <Button
              variant="outlined"
              onClick={(event) => setViewMenuAnchor(event.currentTarget)}
            >
              Mas vistas
            </Button>

            <Menu
              anchorEl={viewMenuAnchor}
              open={Boolean(viewMenuAnchor)}
              onClose={() => setViewMenuAnchor(null)}
            >
              <MenuItem disabled>2 semanas (proximamente)</MenuItem>
              <MenuItem disabled>4 semanas (proximamente)</MenuItem>
            </Menu>

            <Button variant="outlined" onClick={() => loadAgenda(weekOffset)}>
              Recargar
            </Button>
          </Stack>
        </Stack>

        {loading ? (
          <Typography color="text.secondary">Cargando agenda...</Typography>
        ) : (
          <Box sx={{ overflowX: "auto" }}>
            <Box sx={{ minWidth: 1600 }}>
              <Box
                sx={{
                  display: "grid",
                  gridTemplateColumns: `${TIME_GUTTER_WIDTH}px repeat(7, minmax(${DAY_COLUMN_MIN_WIDTH}px, 1fr))`,
                  borderTop: "1px solid #e3ebf6",
                  borderLeft: "1px solid #e3ebf6",
                  borderRight: "1px solid #e3ebf6",
                  borderTopLeftRadius: 12,
                  borderTopRightRadius: 12,
                  overflow: "hidden",
                }}
              >
                <Box
                  sx={{ borderBottom: "1px solid #e3ebf6", bgcolor: "#f9fbff" }}
                />

                {weekDays.map((day) => (
                  <Box
                    key={day.id}
                    sx={{
                      py: 1,
                      px: 1.25,
                      borderLeft: "1px solid #e3ebf6",
                      borderBottom: "1px solid #e3ebf6",
                      bgcolor: "#f9fbff",
                    }}
                  >
                    <Typography variant="body2" fontWeight={600}>
                      {day.label}
                    </Typography>
                    <Typography variant="caption" color="text.secondary">
                      {formatDayMonth(day.date)}
                    </Typography>
                  </Box>
                ))}
              </Box>

              <Box
                sx={{
                  display: "grid",
                  gridTemplateColumns: `${TIME_GUTTER_WIDTH}px repeat(7, minmax(${DAY_COLUMN_MIN_WIDTH}px, 1fr))`,
                  borderLeft: "1px solid #e3ebf6",
                  borderRight: "1px solid #e3ebf6",
                  borderBottom: "1px solid #e3ebf6",
                  borderBottomLeftRadius: 12,
                  borderBottomRightRadius: 12,
                  overflow: "hidden",
                }}
              >
                <Box
                  sx={{
                    position: "relative",
                    height: dayColumnHeight,
                    bgcolor: "#fbfdff",
                  }}
                >
                  {hourMarks.map((minutes) => {
                    const top =
                      ((minutes - minuteRange.startMinutes) / 60) * HOUR_HEIGHT;

                    return (
                      <Box
                        key={minutes}
                        sx={{
                          position: "absolute",
                          top,
                          marginTop: 4,
                          left: 10,
                          right: 8,
                          borderTop: "0px solid #edf2fa",
                          pr: 1.25,
                        }}
                      >
                        <Typography
                          variant="caption"
                          color="text.secondary"
                          sx={{
                            position: "absolute",
                            top: -7,
                            left: 6,
                            fontWeight: 600,
                          }}
                        >
                          {minutesToTime(minutes)}
                        </Typography>
                      </Box>
                    );
                  })}
                </Box>

                {weekDays.map((day) => {
                  const dayClasses = classesByDay.get(day.id) || [];
                  const now = new Date();
                  const todayDayId = now.getDay() === 0 ? 7 : now.getDay();

                  const visibleDayClasses = showOnlyToday
                    ? day.id === todayDayId
                      ? dayClasses.filter((clase) => {
                          const classDateKey = extractDateKey(clase.fecha);
                          const todayDateKey = toDateKeyFromDate(now);

                          if (!classDateKey) {
                            return false;
                          }

                          return classDateKey === todayDateKey;
                        })
                      : []
                    : dayClasses;

                  const isSundayWithoutClasses =
                    day.id === 7 && visibleDayClasses.length === 0;

                  return (
                    <Box
                      key={day.id}
                      sx={{
                        position: "relative",
                        height: dayColumnHeight,
                        borderLeft: "1px solid #e3ebf6",
                        bgcolor: "#fff",
                      }}
                    >
                      {hourMarks.map((minutes) => {
                        const top =
                          ((minutes - minuteRange.startMinutes) / 60) *
                          HOUR_HEIGHT;

                        return (
                          <Box
                            key={`${day.id}-${minutes}`}
                            sx={{
                              position: "absolute",
                              top,
                              left: 0,
                              right: 0,
                              borderTop: "1px solid #edf2fa",
                            }}
                          />
                        );
                      })}

                      {isSundayWithoutClasses && (
                        <Stack
                          direction="row" // 💡 Cambia a horizontal
                          spacing={1} // Espacio entre el icono y el texto
                          alignItems="center"
                          justifyContent="center"
                          sx={{
                            mt: 4,
                            ml: 3,
                            position: "absolute",
                            inset: 0,
                            color: "#8ea0b8",
                          }}
                        >
                          <CalendarMonthIcon />
                          <Typography
                            variant="body2"
                            sx={{
                              whiteSpace: "nowrap", // 💡 Fuerza a que no se rompa la línea jamás
                            }}
                          >
                            Sin clases programadas
                          </Typography>
                        </Stack>
                      )}

                      {visibleDayClasses.map((clase) => {
                        const date = new Date(clase.fecha);
                        const startMinute =
                          date.getHours() * 60 + date.getMinutes();
                        const duration = Number(clase.duracion) || 45;
                        const endMinute = startMinute + duration;
                        const offset = startMinute - minuteRange.startMinutes;

                        if (endMinute <= minuteRange.startMinutes) {
                          return null;
                        }

                        if (startMinute >= minuteRange.endMinutes) {
                          return null;
                        }

                        const top = (offset / 60) * HOUR_HEIGHT;
                        const isProgramada = clase.estado === "PROGRAMADA";
                        const height = Math.max(
                          (duration / 60) * HOUR_HEIGHT,
                          isProgramada ? 176 : 154,
                        );
                        const color = getColorByStudent(
                          clase.alumno?.id,
                          clase.alumno?.nombre,
                        );

                        return (
                          <Box
                            key={clase.id}
                            sx={{
                              position: "absolute",
                              top,
                              left: 7,
                              right: 7,
                              minHeight: 154,
                              height: 154,
                              p: 1,
                              borderRadius: 1,
                              border: `1px solid ${color.border}`,
                              backgroundColor: color.bg,
                              overflow: "visible",
                              zIndex: 2,
                              boxShadow: "0 4px 10px rgba(15,23,42,0.06)",
                            }}
                          >
                            {/* Fecha y Hora de la clase */}
                            <Typography
                              variant="caption"
                              sx={{
                                fontWeight: 700,
                                color: color.title,
                                display: "block",
                                pr: 4,
                              }} // Añadimos padding derecho para que el texto largo no choque con el chip
                            >
                              {`${formatHour(clase.fecha)} - ${minutesToTime(startMinute + duration)}`}
                            </Typography>

                            {/* CHIP DE LICENCIA: Posicionado de forma absoluta arriba a la derecha */}
                            <Box
                              sx={{ position: "absolute", top: 7, right: 12 }}
                            >
                              <LicenseChip
                                value={clase.vehiculo?.tipoPermiso || "-"}
                                size="small"
                                sx={{
                                  width: 22, // Tamaño pequeño y discreto
                                  height: 22, // Mismo ancho y alto para círculo perfecto
                                  borderRadius: "50%", // Lo convierte en un círculo
                                  display: "inline-flex",
                                  alignItems: "center",
                                  justifyContent: "center",
                                  p: 0,
                                  fontSize: 10, // Letra compacta para que quepa en el círculo pequeño
                                  fontWeight: 700,
                                  "& .MuiChip-label": {
                                    p: 0, // Quita márgenes internos del texto para centrarlo
                                  },
                                }}
                              />
                            </Box>

                            <Stack
                              direction="row"
                              spacing={0.5}
                              alignItems="center"
                              sx={{ mt: 0.4 }}
                            >
                              <PersonIcon
                                sx={{ fontSize: 14, color: color.title }}
                              />
                              <Typography
                                variant="body2"
                                sx={{
                                  lineHeight: 1.15,
                                  fontWeight: 700,
                                  color: color.title,
                                  whiteSpace: "normal",
                                  wordBreak: "break-word",
                                }}
                              >
                                {clase.alumno?.nombre || "Alumno"}
                              </Typography>
                            </Stack>

                            <Typography
                              variant="caption"
                              display="block"
                              color="text.secondary"
                              sx={{ mt: 0.25 }}
                            >
                              {clase.vehiculo?.marca || "Vehiculo"}{" "}
                              {clase.vehiculo?.modelo || ""}
                            </Typography>

                            <Chip
                              size="small"
                              label={
                                clase.vehiculo?.matricula || "Sin matricula"
                              }
                              sx={{
                                mt: 0.55,
                                ml: 1,
                                maxWidth: "100%",
                                fontSize: 10,
                                height: 20,
                                bgcolor: "#fff",
                                border: "1px solid #dbe5f2",
                              }}
                            />

                            {/* Eliminamos el Stack antiguo del LicenseChip que rompía la línea */}

                            <Stack
                              direction="row"
                              spacing={0.6}
                              sx={{ mt: 0.55, flexWrap: "wrap", pr: 5 }}
                              useFlexGap
                            >
                              {(() => {
                                const statusConfig = getAgendaStatusChipConfig(
                                  clase.estadoAgenda || clase.estado,
                                );

                                return (
                                  <Chip
                                    size="small"
                                    label={statusConfig.label}
                                    color={statusConfig.color}
                                    sx={{ height: 20, fontSize: 10 }}
                                  />
                                );
                              })()}
                            </Stack>

                            {isProgramada && (
                              <Stack
                                direction="row"
                                spacing={0.6}
                                sx={{ mt: 0.45, pr: 5 }}
                              >
                                <Chip
                                  size="small"
                                  color="success"
                                  label="Confirmar"
                                  icon={<CheckCircleIcon />}
                                  onClick={() =>
                                    handleClassStatus(clase.id, "CONFIRMADA")
                                  }
                                  disabled={savingClassId === clase.id}
                                  sx={{ height: 20, fontSize: 10 }}
                                />
                                <Chip
                                  size="small"
                                  color="error"
                                  label="Cancelar"
                                  icon={<CancelIcon />}
                                  onClick={() =>
                                    handleClassStatus(clase.id, "CANCELADA")
                                  }
                                  disabled={savingClassId === clase.id}
                                  sx={{ height: 20, fontSize: 10 }}
                                />
                              </Stack>
                            )}

                            <Box
                              sx={{
                                position: "absolute",
                                right: 8,
                                bottom: 8,
                                width: 80,
                                height: 70,
                                borderRadius: 1,
                                overflow: "hidden",
                                border: "1px solid #cbd5e1",
                                backgroundColor: "#fff",
                                display: "grid",
                                placeItems: "center",
                              }}
                            >
                              {buildImageSrc(clase.vehiculo?.imagenRuta) ? (
                                <Box
                                  component="img"
                                  src={buildImageSrc(
                                    clase.vehiculo?.imagenRuta,
                                  )}
                                  alt={clase.vehiculo?.matricula || "Vehiculo"}
                                  sx={{
                                    width: "100%",
                                    height: "100%",
                                    objectFit: "cover",
                                  }}
                                />
                              ) : (
                                <DirectionsCarIcon
                                  sx={{ fontSize: 100, color: "#64748b" }}
                                />
                              )}
                            </Box>
                          </Box>
                        );
                      })}
                    </Box>
                  );
                })}
              </Box>
            </Box>

            <Paper
              variant="outlined"
              sx={{
                mt: 2,
                p: 0,
                borderColor: "#dbe5f2",
                borderRadius: 2,
                overflow: "hidden",
              }}
            >
              <Box
                sx={{
                  display: "grid",
                  gridTemplateColumns: {
                    xs: "1fr",
                    md: "1fr 1fr 1fr",
                  },
                  bgcolor: "#fff",
                }}
              >
                <Stack
                  direction="row"
                  spacing={1}
                  alignItems="center"
                  sx={{ p: 1.6, borderRight: { md: "1px solid #edf2fa" } }}
                >
                  <CalendarMonthIcon sx={{ color: "#1d4ed8" }} />
                  <Box>
                    <Typography variant="caption" color="text.secondary">
                      Total de clases esta semana
                    </Typography>
                    <Typography variant="h6" fontWeight={800}>
                      {footerSummary.totalReservas}
                    </Typography>
                  </Box>
                </Stack>

                <Stack
                  direction="row"
                  spacing={1}
                  alignItems="center"
                  sx={{ p: 1.6, borderRight: { md: "1px solid #edf2fa" } }}
                >
                  <AccessTimeIcon sx={{ color: "#0f172a" }} />
                  <Box>
                    <Typography variant="caption" color="text.secondary">
                      Horas de clase
                    </Typography>
                    <Typography variant="h6" fontWeight={800}>
                      {formatHoursSummary(footerSummary.totalMinutes)}
                    </Typography>
                  </Box>
                </Stack>

                <Stack
                  direction="row"
                  spacing={1}
                  alignItems="center"
                  sx={{ p: 1.6 }}
                >
                  <DirectionsCarIcon sx={{ color: "#1e3a8a" }} />
                  <Box>
                    <Typography variant="caption" color="text.secondary">
                      Vehiculos utilizados
                    </Typography>
                    <Typography variant="h6" fontWeight={800}>
                      {footerSummary.vehiculosUtilizados}
                    </Typography>
                  </Box>
                </Stack>
              </Box>
            </Paper>
          </Box>
        )}
      </Paper>

      <Dialog
        open={openScheduleModal}
        onClose={() => setOpenScheduleModal(false)}
        fullWidth
        maxWidth={false} // 💡 Desactiva los tamaños preestablecidos de MUI (sm, md, lg, etc.)
        sx={{
          "& .MuiDialog-paper": {
            width: "auto", // El ancho inicial se adapta al tamaño de los datos
            maxWidth: "90%", // 💡 Límite porcentual máximo para que no toque los bordes de la pantalla
            minWidth: "320px", // Evita que se vea demasiado estrecho si hay pocos datos
            transition: "max-width 0.3s ease-in-out", // Opcional: suaviza el cambio si los datos se cargan dinámicamente
          },
        }}
      >
        <DialogTitle>Configurar horario de trabajo</DialogTitle>
        <DialogContent>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            Define bloques por dia. Puedes crear una jornada continua o partida.
            Maximo 8 horas por dia.
          </Typography>

          <Stack
            direction={{ xs: "column", md: "row" }}
            spacing={1.5}
            sx={{ alignItems: { md: "center" } }}
          >
            <FormControl size="small" sx={{ minWidth: 170 }}>
              <InputLabel>Dia</InputLabel>
              <Select
                value={newBlock.diaSemana}
                label="Dia"
                onChange={(event) =>
                  setNewBlock((prev) => ({
                    ...prev,
                    diaSemana: event.target.value,
                  }))
                }
              >
                {DAYS.map((day) => (
                  <MenuItem key={day.id} value={day.id}>
                    {day.label}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>

            <TextField
              size="small"
              type="time"
              label="Inicio"
              value={newBlock.horaInicio}
              onChange={(event) =>
                setNewBlock((prev) => ({
                  ...prev,
                  horaInicio: event.target.value,
                }))
              }
              InputLabelProps={{ shrink: true }}
              sx={{ width: 140 }}
            />

            <TextField
              size="small"
              type="time"
              label="Fin"
              value={newBlock.horaFin}
              onChange={(event) =>
                setNewBlock((prev) => ({
                  ...prev,
                  horaFin: event.target.value,
                }))
              }
              InputLabelProps={{ shrink: true }}
              sx={{ width: 140 }}
            />

            <Button
              variant="outlined"
              startIcon={<AddIcon />}
              onClick={addBlock}
            >
              Anadir bloque
            </Button>
          </Stack>

          <Stack
            direction="row"
            spacing={1}
            useFlexGap
            flexWrap="wrap"
            sx={{ mt: 2 }}
          >
            {scheduleBlocks.length === 0 && (
              <Typography variant="body2" color="text.secondary">
                No hay bloques definidos.
              </Typography>
            )}

            {scheduleBlocks.map((block, index) => (
              <Chip
                key={`${block.diaSemana}-${block.horaInicio}-${block.horaFin}-${index}`}
                label={`${DAY_NAME_BY_ID[block.diaSemana]} ${block.horaInicio}-${block.horaFin}`}
                onDelete={() => removeBlock(index)}
                deleteIcon={<DeleteIcon />}
                color="primary"
                variant="outlined"
              />
            ))}
          </Stack>
        </DialogContent>

        <DialogActions>
          <Button
            variant="outlined"
            color="inherit"
            onClick={() => {
              removeLastInsertedBlock();
            }}
            disabled={scheduleBlocks.length === 0}
          >
            Deshacer ultimo
          </Button>

          <Button onClick={() => setOpenScheduleModal(false)} color="inherit">
            Cerrar
          </Button>

          <Button
            variant="contained"
            startIcon={<SaveIcon />}
            disabled={saving}
            onClick={async () => {
              await saveSchedule();
              setOpenScheduleModal(false);
            }}
          >
            Guardar horario
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
}

import { useEffect, useMemo, useState } from "react";

import {
  Box,
  Button,
  Paper,
  Typography,
  Chip,
  CircularProgress,
  Stack,
} from "@mui/material";

import { DataGrid } from "@mui/x-data-grid";

import { profesoresService } from "../../services/profesoresService";

import EditIcon from "@mui/icons-material/Edit";
import DeleteIcon from "@mui/icons-material/Delete";

import ToggleOffIcon from "@mui/icons-material/ToggleOff";
import ToggleOnIcon from "@mui/icons-material/ToggleOn";
import { LicenseChipList } from "../../components/common/LicenseChip";
import CalendarMonthIcon from "@mui/icons-material/CalendarMonth";
import NavigateBeforeIcon from "@mui/icons-material/NavigateBefore";
import NavigateNextIcon from "@mui/icons-material/NavigateNext";
import PersonIcon from "@mui/icons-material/Person";

import Tooltip from "@mui/material/Tooltip"; // Asegúrate de importar el componente

import { IconButton } from "@mui/material";

import Snackbar from "@mui/material/Snackbar";
import Alert from "@mui/material/Alert";

import Radio from "@mui/material/Radio";
import RadioGroup from "@mui/material/RadioGroup";
import FormControl from "@mui/material/FormControl";
import FormControlLabel from "@mui/material/FormControlLabel";

import MenuItem from "@mui/material/MenuItem";
import Select from "@mui/material/Select";

import InputAdornment from "@mui/material/InputAdornment";
import CloseIcon from "@mui/icons-material/Close";

import DownloadIcon from "@mui/icons-material/Download";
import Menu from "@mui/material/Menu";

import { exportProfesoresExcel } from "../../utils/exportProfesoresExcel";

import { exportProfesoresPdf } from "../../utils/exportProfesoresPdf";

import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  DialogContentText,
  TextField,
} from "@mui/material";
import {
  addDaysToDateKey,
  dateFromKeyAtNoon,
  extractDateKey,
  formatDateValue,
  getWeekDayIdFromValue,
} from "../../utils/calendarDate";

const normalizarDni = (valor) =>
  valor
    ?.toString()
    .toUpperCase()
    .replace(/[^0-9A-Z]/g, "") || "";

const normalizarTelefono = (valor) =>
  String(valor || "")
    .replace(/\D/g, "")
    .slice(0, 9);

const esTelefonoValido = (valor) => /^\d{9}$/.test(String(valor || ""));

const WEEK_DAYS = [
  { id: 1, label: "Lunes" },
  { id: 2, label: "Martes" },
  { id: 3, label: "Miercoles" },
  { id: 4, label: "Jueves" },
  { id: 5, label: "Viernes" },
  { id: 6, label: "Sabado" },
  { id: 7, label: "Domingo" },
];

const STUDENT_PALETTE = [
  {
    bg: "#e9f2ff",
    border: "#9cc6ff",
    title: "#1e3a8a",
  },
  {
    bg: "#fff3e6",
    border: "#ffd39f",
    title: "#92400e",
  },
  {
    bg: "#e8f9f1",
    border: "#98e4be",
    title: "#166534",
  },
  {
    bg: "#f1ecff",
    border: "#c5b2ff",
    title: "#5b21b6",
  },
  {
    bg: "#e8f7fb",
    border: "#93dff0",
    title: "#0f4f66",
  },
];

const formatAgendaDate = (value) => {
  const formatted = formatDateValue(value, {
    day: "numeric",
    month: "numeric",
    year: "numeric",
  });

  return formatted || "-";
};

const formatAgendaDay = (value) => {
  const formatted = formatDateValue(value, {
    day: "numeric",
    month: "short",
  });

  return formatted || "-";
};

const formatHour = (value) => {
  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return "--:--";
  }

  return date.toLocaleTimeString("es-ES", {
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  });
};

const formatHourRange = (value, duracion = 45) => {
  const startDate = new Date(value);

  if (Number.isNaN(startDate.getTime())) {
    return "--:-- - --:--";
  }

  const endDate = new Date(startDate);
  endDate.setMinutes(endDate.getMinutes() + (Number(duracion) || 45));

  return `${formatHour(startDate)} - ${formatHour(endDate)}`;
};

const getColorByStudent = (studentId, studentName) => {
  const seed = String(studentId || studentName || "SIN_ALUMNO");
  let hash = 0;

  for (let i = 0; i < seed.length; i += 1) {
    hash = (hash << 5) - hash + seed.charCodeAt(i);
    hash |= 0;
  }

  const index = Math.abs(hash) % STUDENT_PALETTE.length;
  return STUDENT_PALETTE[index];
};

const getAgendaStatusChipConfig = (status) => {
  const normalized = String(status || "").toUpperCase();

  if (normalized === "REGISTRADA") {
    return { label: "REGISTRADA", color: "success" };
  }

  if (normalized === "PENDIENTE_REGISTRO") {
    return { label: "PENDIENTE REGISTRO", color: "warning" };
  }

  if (normalized === "EN_CURSO") {
    return { label: "EN CURSO", color: "info" };
  }

  if (normalized === "CONFIRMADA") {
    return { label: "CONFIRMADA", color: "primary" };
  }

  if (normalized === "PROGRAMADA") {
    return { label: "PROGRAMADA", color: "default" };
  }

  return { label: normalized || "SIN ESTADO", color: "default" };
};

export default function Profesores() {
  const [rows, setRows] = useState([]);

  const [estadoFiltro, setEstadoFiltro] = useState("activos");

  const [search, setSearch] = useState("");

  const licencias = ["B", "A1", "A2", "A", "C", "D", "E"];

  const [exportAnchor, setExportAnchor] = useState(null);

  const openExportMenu = (event) => {
    setExportAnchor(event.currentTarget);
  };

  const closeExportMenu = () => {
    setExportAnchor(null);
  };

  const handleExportExcel = () => {
    exportProfesoresExcel(rows);
    closeExportMenu();
  };

  const handleExportPdf = () => {
    exportProfesoresPdf(rows);
    closeExportMenu();
  };

  useEffect(() => {
    loadProfesores();
  }, [estadoFiltro, search]);

  const loadProfesores = async () => {
    try {
      const data = await profesoresService.getAll();

      console.log("TOTAL ProfesorS:", data.length);

      console.log(
        "TODOS LOS ProfesorS:",
        data.map((a) => ({
          nombre: a.usuario?.nombre,
          activo: a.activo,
        })),
      );

      let filteredData = data;

      if (estadoFiltro === "activos") {
        filteredData = data.filter((Profesor) => Profesor.activo === true);
      }

      if (estadoFiltro === "inactivos") {
        filteredData = data.filter((Profesor) => Profesor.activo === false);
      }

      if (estadoFiltro === "todos") {
        filteredData = data;
      }

      if (search.trim() !== "") {
        const texto = search.toLowerCase();

        filteredData = filteredData.filter(
          (Profesor) =>
            Profesor.usuario?.nombre?.toLowerCase().includes(texto) ||
            Profesor.usuario?.email?.toLowerCase().includes(texto) ||
            Profesor.usuario?.telefono?.toLowerCase().includes(texto),
        );
      }

      console.log(
        "FILTRADOS:",
        filteredData.map((a) => ({
          nombre: a.usuario?.nombre,
          activo: a.activo,
        })),
      );

      setRows(filteredData);
    } catch (error) {
      console.error(error);
    }
  };

  const saveProfesor = async () => {
    try {
      const telefonoNormalizado = normalizarTelefono(nuevoProfesor.telefono);

      if (!esTelefonoValido(telefonoNormalizado)) {
        setNotification({
          open: true,
          message: "El teléfono debe tener exactamente 9 dígitos numéricos",
          severity: "error",
        });
        return;
      }

      const payloadBase = {
        nombre: nuevoProfesor.nombre?.trim() || "",
        email: nuevoProfesor.email?.trim() || "",
        telefono: telefonoNormalizado,
        permisosLicencias: nuevoProfesor.permisosLicencias,
        licenciaConducir: nuevoProfesor.permisosLicencias[0] || "",
        dni: normalizarDni(nuevoProfesor.dni),
      };

      if (editingId) {
        const payload = {
          nombre: payloadBase.nombre,
          email: payloadBase.email,
          dni: payloadBase.dni,
          telefono: payloadBase.telefono,
          licenciaConducir: payloadBase.licenciaConducir,
          permisosLicencias: payloadBase.permisosLicencias,
        };

        if (nuevoProfesor.password?.trim()) {
          payload.password = nuevoProfesor.password.trim();
        }

        await profesoresService.update(editingId, payload);
      } else {
        await profesoresService.create({
          ...payloadBase,
          password: nuevoProfesor.password || "",
        });
      }

      setOpen(false);

      setEditingId(null);

      setNuevoProfesor({
        nombre: "",
        email: "",
        password: "",
        dni: "",
        telefono: "",
        permisosLicencias: ["B"],
      });

      loadProfesores();

      setNotification({
        open: true,
        message: editingId
          ? "Profesor actualizado correctamente"
          : "Profesor creado correctamente",
        severity: "success",
      });
    } catch (error) {
      console.error(error);

      setNotification({
        open: true,
        message:
          error.response?.data?.message ||
          (editingId ? "Error modificando Profesor" : "Error creando Profesor"),
        severity: "error",
      });
    }
  };

  const handleDeactivate = async (row) => {
    const nombreProfesor = row?.usuario?.nombre || "este profesor";

    try {
      const impacto = await profesoresService.getDeactivationImpact(row.id);

      if (!impacto?.alumnos?.length) {
        setConfirmDialog({
          open: true,
          action: "deactivate",
          profesorId: row.id,
          profesorNombre: nombreProfesor,
          title: "Confirmar desactivación",
          message: `Vas a desactivar a ${nombreProfesor} en la plataforma Autoescuela Eguzkilore. No podrá operar hasta su reactivación. ¿Deseas continuar?`,
        });
        return;
      }

      const reasignacionesIniciales = {};
      impacto.alumnos.forEach((item) => {
        reasignacionesIniciales[item.alumnoId] = "";
      });

      setReasignacionesProfesor(reasignacionesIniciales);
      setDeactivationModal({
        open: true,
        loading: false,
        profesor: impacto.profesor,
        alumnos: impacto.alumnos,
      });
    } catch (error) {
      setNotification({
        open: true,
        message:
          error.response?.data?.message ||
          "No se pudo cargar el impacto de desactivación del profesor",
        severity: "error",
      });
    }
  };

  const closeDeactivationModal = () => {
    setDeactivationModal({
      open: false,
      loading: false,
      profesor: null,
      alumnos: [],
    });
    setReasignacionesProfesor({});
  };

  const handleConfirmDeactivateWithReassignment = async () => {
    if (!deactivationModal.profesor?.id) {
      return;
    }

    const reasignaciones = [];

    for (const alumno of deactivationModal.alumnos) {
      const nuevoProfesorId = reasignacionesProfesor[alumno.alumnoId];

      if (!nuevoProfesorId) {
        setNotification({
          open: true,
          message:
            "Debes seleccionar un nuevo profesor para todos los alumnos asignados",
          severity: "error",
        });
        return;
      }

      reasignaciones.push({
        alumnoId: alumno.alumnoId,
        nuevoProfesorId,
      });
    }

    try {
      setDeactivationModal((prev) => ({ ...prev, loading: true }));
      await profesoresService.deactivateWithReassignment(
        deactivationModal.profesor.id,
        reasignaciones,
      );
      await loadProfesores();
      closeDeactivationModal();
      setNotification({
        open: true,
        message:
          "Profesor desactivado correctamente con reasignación obligatoria de alumnos y clases futuras",
        severity: "success",
      });
    } catch (error) {
      setNotification({
        open: true,
        message:
          error.response?.data?.message ||
          "No se pudo completar la desactivación con reasignación",
        severity: "error",
      });
    } finally {
      setDeactivationModal((prev) => ({ ...prev, loading: false }));
    }
  };

  const handleActivate = async (row) => {
    const nombreProfesor = row?.usuario?.nombre || "este profesor";

    setConfirmDialog({
      open: true,
      action: "activate",
      profesorId: row.id,
      profesorNombre: nombreProfesor,
      title: "Confirmar activación",
      message: `Vas a reactivar a ${nombreProfesor} en la plataforma Autoescuela Eguzkilore. Recuperará acceso operativo de inmediato. ¿Deseas continuar?`,
    });
  };

  const handleDelete = async (row) => {
    const nombreProfesor = row?.usuario?.nombre || "este profesor";

    setConfirmDialog({
      open: true,
      action: "delete",
      profesorId: row.id,
      profesorNombre: nombreProfesor,
      title: "Confirmar eliminación",
      message: `Vas a eliminar definitivamente a ${nombreProfesor} de Autoescuela Eguzkilore. Toda la información asociada será eliminada de forma permanente. Esta acción no podrá deshacerse. ¿Deseas continuar?`,
    });
  };

  const closeConfirmDialog = () => {
    setConfirmDialog({
      open: false,
      action: null,
      profesorId: null,
      profesorNombre: "",
      title: "",
      message: "",
    });
  };

  const handleConfirmAction = async () => {
    if (!confirmDialog.profesorId || !confirmDialog.action) {
      closeConfirmDialog();
      return;
    }

    try {
      if (confirmDialog.action === "deactivate") {
        await profesoresService.deactivate(confirmDialog.profesorId);
      }

      if (confirmDialog.action === "activate") {
        await profesoresService.activate(confirmDialog.profesorId);
      }

      if (confirmDialog.action === "delete") {
        await profesoresService.delete(confirmDialog.profesorId);
      }

      loadProfesores();

      setNotification({
        open: true,
        message:
          confirmDialog.action === "deactivate"
            ? "Profesor desactivado correctamente"
            : confirmDialog.action === "activate"
              ? "Profesor activado correctamente"
              : "Profesor eliminado correctamente",
        severity: "success",
      });
    } catch (error) {
      console.error(error);

      setNotification({
        open: true,
        message:
          confirmDialog.action === "deactivate"
            ? "Error desactivando profesor"
            : confirmDialog.action === "activate"
              ? "Error activando profesor"
              : "Error eliminando profesor",
        severity: "error",
      });
    } finally {
      closeConfirmDialog();
    }
  };

  const columns = [
    {
      field: "nombre",
      headerName: "Nombre",
      flex: 1,

      valueGetter: (_, row) => row.usuario?.nombre || "",
    },

    {
      field: "email",
      headerName: "Email",
      flex: 1.5,

      valueGetter: (_, row) => row.usuario?.email || "",
    },

    {
      field: "permisosLicencias",
      headerName: "Permisos",
      flex: 1.2,
      renderCell: (params) => (
        <Box
          sx={{
            display: "flex",
            flexDirection: "column",
            justifyContent: "flex-end", // Empuja los chips al fondo de la celda
            height: "100%", // Usa todo el alto disponible de la fila
            pb: 1.5, // Padding bottom opcional (8px) para separar del borde
          }}
        >
          <LicenseChipList
            values={
              Array.isArray(params.row.permisosLicencias) &&
              params.row.permisosLicencias.length > 0
                ? params.row.permisosLicencias
                : [params.row.licenciaConducir]
            }
          />
        </Box>
      ),
    },

    {
      field: "telefono",
      headerName: "Teléfono",
      flex: 1,
    },

    {
      field: "activo",
      headerName: "Estado",
      width: 130,
      renderCell: (params) => (
        <Chip
          label={(params.row.activo ?? true) ? "Activo" : "Inactivo"}
          color={(params.row.activo ?? true) ? "success" : "error"}
          size="small"
        />
      ),
    },

    {
      field: "acciones",
      headerName: "Acciones",
      width: 160,

      renderCell: (params) => (
        <>
          <Tooltip title="Editar" arrow>
            <IconButton
              color="primary"
              onClick={(event) => {
                event.stopPropagation();
                handleEdit(params.row);
              }}
            >
              <EditIcon />
            </IconButton>
          </Tooltip>

          <Tooltip title={params.row.activo ? "Desactivar" : "Activar"} arrow>
            {params.row.activo ? (
              <IconButton
                color="warning"
                onClick={(event) => {
                  event.stopPropagation();
                  handleDeactivate(params.row);
                }}
              >
                <ToggleOffIcon />
              </IconButton>
            ) : (
              <IconButton
                color="success"
                onClick={(event) => {
                  event.stopPropagation();
                  handleActivate(params.row);
                }}
              >
                <ToggleOnIcon />
              </IconButton>
            )}
          </Tooltip>

          <Tooltip title="Eliminar" arrow>
            <IconButton
              color="error"
              onClick={(event) => {
                event.stopPropagation();
                handleDelete(params.row);
              }}
            >
              <DeleteIcon />
            </IconButton>
          </Tooltip>
        </>
      ),
    },
  ];

  const [open, setOpen] = useState(false);
  const [editingId, setEditingId] = useState(null);

  const [openDetail, setOpenDetail] = useState(false);
  const [loadingDetail, setLoadingDetail] = useState(false);
  const [selectedProfesor, setSelectedProfesor] = useState(null);
  const [detailView, setDetailView] = useState("PERFIL");
  const [overviewLoading, setOverviewLoading] = useState(false);
  const [overviewData, setOverviewData] = useState(null);
  const [overviewWeekOffset, setOverviewWeekOffset] = useState(0);
  const [selectedAlumnoAgendaId, setSelectedAlumnoAgendaId] = useState("");

  const [nuevoProfesor, setNuevoProfesor] = useState({
    nombre: "",
    email: "",
    password: "",
    dni: "",
    permisosLicencias: ["B"],
    telefono: "",
    activo: true,
  });

  const [confirmDialog, setConfirmDialog] = useState({
    open: false,
    action: null,
    profesorId: null,
    profesorNombre: "",
    title: "",
    message: "",
  });

  const [notification, setNotification] = useState({
    open: false,
    message: "",
    severity: "success",
  });

  const [deactivationModal, setDeactivationModal] = useState({
    open: false,
    loading: false,
    profesor: null,
    alumnos: [],
  });
  const [reasignacionesProfesor, setReasignacionesProfesor] = useState({});

  const handleEdit = (row) => {
    setEditingId(row.id);

    setNuevoProfesor({
      nombre: row.usuario?.nombre || "",
      email: row.usuario?.email || "",
      password: "",
      dni: row.usuario?.dni || "",
      telefono: row.usuario?.telefono || "",
      permisosLicencias:
        Array.isArray(row.permisosLicencias) && row.permisosLicencias.length > 0
          ? row.permisosLicencias
          : [row.licenciaConducir || "B"],
    });

    setOpen(true);
  };

  const handleOpenDetail = async (row) => {
    setOpenDetail(true);
    setLoadingDetail(true);
    setDetailView("PERFIL");
    setOverviewData(null);
    setOverviewWeekOffset(0);
    setSelectedAlumnoAgendaId("");

    try {
      const detalle = await profesoresService.getById(row.id);

      setSelectedProfesor(detalle);
    } catch (error) {
      console.error(error);

      setNotification({
        open: true,
        message: "No se pudo cargar el detalle del profesor",
        severity: "error",
      });
    } finally {
      setLoadingDetail(false);
    }
  };

  const loadOverview = async (profesorId, options = {}) => {
    if (!profesorId) {
      return;
    }

    const nextWeekOffset =
      options.weekOffset !== undefined
        ? options.weekOffset
        : overviewWeekOffset;
    const alumnoId = options.alumnoId || selectedAlumnoAgendaId || undefined;

    setOverviewLoading(true);

    try {
      const response = await profesoresService.getOverview(profesorId, {
        weekOffset: nextWeekOffset,
        alumnoId,
      });

      setOverviewData(response);
      setOverviewWeekOffset(nextWeekOffset);
      setSelectedAlumnoAgendaId(
        response?.agendaAlumno?.alumnoSeleccionadoId || "",
      );
    } catch (error) {
      setNotification({
        open: true,
        message:
          error.response?.data?.message ||
          "No se pudo cargar el bloque de alumnos y agenda",
        severity: "error",
      });
    } finally {
      setOverviewLoading(false);
    }
  };

  const openStudentsAndAgendaView = async () => {
    setDetailView("ALUMNOS_AGENDA");

    if (!selectedProfesor?.id) {
      return;
    }

    await loadOverview(selectedProfesor.id, {
      weekOffset: overviewWeekOffset,
      alumnoId: selectedAlumnoAgendaId || undefined,
    });
  };

  const agendaWeekDays = useMemo(() => {
    const weekStartKey = extractDateKey(
      overviewData?.agendaAlumno?.semana?.inicio,
    );

    if (!weekStartKey) {
      return WEEK_DAYS.map((day) => ({
        ...day,
        date: null,
      }));
    }

    return WEEK_DAYS.map((day, index) => {
      const dateKey = addDaysToDateKey(weekStartKey, index);
      return {
        ...day,
        date: dateFromKeyAtNoon(dateKey),
      };
    });
  }, [overviewData?.agendaAlumno?.semana?.inicio]);

  const agendaClassesByDay = useMemo(() => {
    const map = new Map();

    WEEK_DAYS.forEach((day) => {
      map.set(day.id, []);
    });

    const classes = overviewData?.agendaAlumno?.clases || [];

    classes.forEach((clase) => {
      const dayId = getWeekDayIdFromValue(clase.fecha);
      const list = map.get(dayId) || [];
      list.push(clase);
      map.set(dayId, list);
    });

    WEEK_DAYS.forEach((day) => {
      const sorted = (map.get(day.id) || []).sort(
        (a, b) => new Date(a.fecha).getTime() - new Date(b.fecha).getTime(),
      );
      map.set(day.id, sorted);
    });

    return map;
  }, [overviewData?.agendaAlumno?.clases]);

  const readOnlyFieldSx = {
    "& .MuiInputBase-input": {
      cursor: "default",
      caretColor: "transparent",
      userSelect: "none",
    },
    "& .MuiOutlinedInput-root": {
      backgroundColor: "action.hover",
    },
  };

  return (
    <Box>
      <Typography variant="h4" fontWeight="bold" mb={4}>
        Gestión de Profesores
      </Typography>
      <Typography color="text.secondary" sx={{ mb: 2 }}>
        Organiza los datos del personal docente, sus horarios de disponibilidad
        y las clases asignadas.
      </Typography>
      <Box
        sx={{
          display: "flex",
          alignItems: "center",
          gap: 4,
          mb: 3,
          flexWrap: "wrap",
        }}
      >
        <Button
          variant="contained"
          onClick={() => {
            setEditingId(null);

            setNuevoProfesor({
              nombre: "",
              email: "",
              password: "",
              dni: "",
              telefono: "",
              permisosLicencias: ["B"],
            });

            setOpen(true);
          }}
        >
          Nuevo Profesor
        </Button>

        <RadioGroup
          row
          value={estadoFiltro}
          onChange={(e) => setEstadoFiltro(e.target.value)}
        >
          <FormControlLabel
            value="activos"
            control={<Radio />}
            label="Activos"
          />

          <FormControlLabel
            value="inactivos"
            control={<Radio />}
            label="Inactivos"
          />

          <FormControlLabel value="todos" control={<Radio />} label="Todos" />
        </RadioGroup>

        <TextField
          size="small"
          label="Buscar profesor"
          placeholder="Nombre, email o teléfono"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          sx={{ width: 320 }}
          InputProps={{
            endAdornment: search && (
              <InputAdornment position="end">
                <IconButton size="small" onClick={() => setSearch("")}>
                  <CloseIcon fontSize="small" />
                </IconButton>
              </InputAdornment>
            ),
          }}
        />

        <Button
          variant="outlined"
          startIcon={<DownloadIcon />}
          onClick={openExportMenu}
        >
          Exportar
        </Button>

        <Menu
          anchorEl={exportAnchor}
          open={Boolean(exportAnchor)}
          onClose={closeExportMenu}
        >
          <MenuItem onClick={handleExportExcel}>Exportar a Excel</MenuItem>

          <MenuItem onClick={handleExportPdf}>Exportar a PDF</MenuItem>
        </Menu>
      </Box>

      <Paper
        sx={{
          height: 700,
          p: 2,
        }}
      >
        <DataGrid
          rows={rows}
          columns={columns}
          getRowId={(row) => row.id}
          disableRowSelectionOnClick
          pageSizeOptions={[10, 25, 50]}
          initialState={{
            pagination: { paginationModel: { pageSize: 10, page: 0 } },
            sorting: { sortModel: [{ field: "nombre", sort: "asc" }] },
          }}
          onRowClick={(params) => handleOpenDetail(params.row)}
        />
      </Paper>

      <Dialog
        open={open}
        onClose={() => setOpen(false)}
        fullWidth
        maxWidth="sm"
      >
        <DialogTitle>
          {editingId ? "Editar Profesor" : "Crear Profesor"}
        </DialogTitle>

        <DialogContent>
          <TextField
            margin="normal"
            fullWidth
            label="Nombre"
            value={nuevoProfesor.nombre}
            onChange={(e) =>
              setNuevoProfesor({
                ...nuevoProfesor,
                nombre: e.target.value,
              })
            }
          />

          <TextField
            margin="normal"
            fullWidth
            label="Email"
            value={nuevoProfesor.email}
            onChange={(e) =>
              setNuevoProfesor({
                ...nuevoProfesor,
                email: e.target.value,
              })
            }
          />

          <TextField
            margin="normal"
            fullWidth
            label="Contraseña"
            type="password"
            helperText={
              editingId
                ? "Si la dejas vacía, se mantiene la contraseña actual."
                : "Mínimo 8 caracteres"
            }
            value={nuevoProfesor.password}
            onChange={(e) =>
              setNuevoProfesor({
                ...nuevoProfesor,
                password: e.target.value,
              })
            }
          />

          <TextField
            margin="normal"
            fullWidth
            required
            label="DNI"
            placeholder="12345678Z"
            value={nuevoProfesor.dni}
            onChange={(e) =>
              setNuevoProfesor({
                ...nuevoProfesor,
                dni: normalizarDni(e.target.value),
              })
            }
          />

          <TextField
            margin="normal"
            fullWidth
            label="Teléfono"
            value={nuevoProfesor.telefono}
            onChange={(e) =>
              setNuevoProfesor({
                ...nuevoProfesor,
                telefono: normalizarTelefono(e.target.value),
              })
            }
            helperText="Formato España: 9 dígitos"
            inputProps={{
              maxLength: 9,
              inputMode: "numeric",
              pattern: "[0-9]*",
            }}
          />

          <Select
            fullWidth
            multiple
            value={nuevoProfesor.permisosLicencias}
            renderValue={(selected) => selected.join(", ")}
            onChange={(e) =>
              setNuevoProfesor({
                ...nuevoProfesor,
                permisosLicencias:
                  typeof e.target.value === "string"
                    ? e.target.value.split(",")
                    : e.target.value,
              })
            }
          >
            {licencias.map((e) => (
              <MenuItem key={e} value={e}>
                {e}
              </MenuItem>
            ))}
          </Select>
        </DialogContent>

        <DialogActions>
          <Button
            onClick={() => {
              setOpen(false);
            }}
          >
            Cancelar
          </Button>

          <Button variant="contained" onClick={saveProfesor}>
            {editingId ? "Actualizar" : "Guardar"}
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog
        open={openDetail}
        onClose={() => setOpenDetail(false)}
        fullWidth
        maxWidth="lg"
      >
        <DialogTitle>
          <Box
            sx={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              gap: 1,
              flexWrap: "wrap",
            }}
          >
            <Typography variant="h6" fontWeight={700}>
              Detalle del Profesor
            </Typography>

            <Button
              variant="outlined"
              size="small"
              startIcon={<CalendarMonthIcon />}
              onClick={
                detailView === "ALUMNOS_AGENDA"
                  ? () => setDetailView("PERFIL")
                  : openStudentsAndAgendaView
              }
              disabled={loadingDetail}
            >
              {detailView === "ALUMNOS_AGENDA"
                ? "Volver al detalle"
                : "Ver alumnos y agenda"}
            </Button>
          </Box>
        </DialogTitle>

        <DialogContent>
          {loadingDetail ? (
            <Box
              sx={{
                display: "flex",
                justifyContent: "center",
                py: 4,
              }}
            >
              <CircularProgress />
            </Box>
          ) : (
            <Box sx={{ perspective: "1400px", mt: 1, minHeight: 620 }}>
              <Box
                sx={{
                  transition: "transform 700ms ease",
                  transformStyle: "preserve-3d",
                  transform:
                    detailView === "ALUMNOS_AGENDA"
                      ? "rotateY(180deg)"
                      : "rotateY(0deg)",
                }}
              >
                <Box
                  sx={{
                    transform:
                      detailView === "ALUMNOS_AGENDA"
                        ? "rotateY(180deg)"
                        : "rotateY(0deg)",
                  }}
                >
                  {detailView === "ALUMNOS_AGENDA" ? (
                    <Box sx={{ display: "grid", gap: 2 }}>
                      {overviewLoading ? (
                        <Box
                          sx={{
                            display: "flex",
                            justifyContent: "center",
                            py: 4,
                          }}
                        >
                          <CircularProgress />
                        </Box>
                      ) : (
                        <>
                          <Paper variant="outlined" sx={{ p: 2 }}>
                            <Typography
                              variant="subtitle1"
                              fontWeight={700}
                              sx={{ mb: 1 }}
                            >
                              Alumnos asignados
                            </Typography>

                            {overviewData?.alumnos?.length ? (
                              <Box
                                sx={{
                                  display: "grid",
                                  gridTemplateColumns: {
                                    xs: "1fr",
                                    md: "1fr 1fr",
                                  },
                                  gap: 1,
                                }}
                              >
                                {(overviewData?.alumnos || []).map((alumno) => {
                                  const isSelected =
                                    alumno.id ===
                                    overviewData?.agendaAlumno
                                      ?.alumnoSeleccionadoId;

                                  return (
                                    <Button
                                      key={alumno.id}
                                      variant={
                                        isSelected ? "contained" : "outlined"
                                      }
                                      onClick={() =>
                                        loadOverview(selectedProfesor?.id, {
                                          weekOffset: overviewWeekOffset,
                                          alumnoId: alumno.id,
                                        })
                                      }
                                      sx={{
                                        justifyContent: "space-between",
                                        textTransform: "none",
                                        py: 1,
                                        px: 1.5,
                                      }}
                                    >
                                      <Box sx={{ textAlign: "left" }}>
                                        <Typography fontWeight={700}>
                                          {alumno.nombre}
                                        </Typography>
                                      </Box>
                                      <Chip
                                        size="small"
                                        label={`Licencia ${alumno.licencia || "-"}`}
                                        color={isSelected ? "warning" : "info"}
                                      />
                                    </Button>
                                  );
                                })}
                              </Box>
                            ) : (
                              <Alert severity="info">
                                Este profesor no tiene alumnos asignados.
                              </Alert>
                            )}
                          </Paper>

                          <Paper variant="outlined" sx={{ p: 2 }}>
                            <Typography
                              variant="subtitle1"
                              fontWeight={700}
                              sx={{ mb: 1 }}
                            >
                              Clases del mes actual
                            </Typography>
                            <Box
                              sx={{ display: "flex", gap: 1, flexWrap: "wrap" }}
                            >
                              <Chip
                                color="warning"
                                label={`Programadas: ${overviewData?.resumenMes?.programadas ?? 0}`}
                              />
                              <Chip
                                color="success"
                                label={`Realizadas: ${overviewData?.resumenMes?.realizadas ?? 0}`}
                              />
                            </Box>
                          </Paper>

                          <Paper variant="outlined" sx={{ p: 2 }}>
                            <Box
                              sx={{
                                display: "flex",
                                alignItems: "center",
                                justifyContent: "space-between",
                                gap: 1,
                                mb: 1.5,
                                flexWrap: "wrap",
                              }}
                            >
                              <Typography variant="subtitle1" fontWeight={700}>
                                Agenda semanal del alumno
                              </Typography>

                              <Box
                                sx={{
                                  display: "flex",
                                  alignItems: "center",
                                  gap: 1,
                                }}
                              >
                                <IconButton
                                  size="small"
                                  onClick={() =>
                                    loadOverview(selectedProfesor?.id, {
                                      weekOffset: overviewWeekOffset - 1,
                                      alumnoId:
                                        overviewData?.agendaAlumno
                                          ?.alumnoSeleccionadoId,
                                    })
                                  }
                                >
                                  <NavigateBeforeIcon fontSize="small" />
                                </IconButton>

                                <Typography variant="body2" fontWeight={700}>
                                  {formatAgendaDate(
                                    overviewData?.agendaAlumno?.semana?.inicio,
                                  )}{" "}
                                  -{" "}
                                  {formatAgendaDate(
                                    overviewData?.agendaAlumno?.semana?.fin,
                                  )}
                                </Typography>

                                <IconButton
                                  size="small"
                                  onClick={() =>
                                    loadOverview(selectedProfesor?.id, {
                                      weekOffset: overviewWeekOffset + 1,
                                      alumnoId:
                                        overviewData?.agendaAlumno
                                          ?.alumnoSeleccionadoId,
                                    })
                                  }
                                >
                                  <NavigateNextIcon fontSize="small" />
                                </IconButton>
                              </Box>
                            </Box>

                            {!overviewData?.agendaAlumno
                              ?.alumnoSeleccionadoId ? (
                              <Alert severity="info">
                                Selecciona un alumno para consultar su agenda
                                semanal.
                              </Alert>
                            ) : (
                              <Box
                                sx={{
                                  display: "grid",
                                  gridTemplateColumns: {
                                    xs: "1fr",
                                    md: "repeat(7, minmax(0, 1fr))",
                                  },
                                  gap: 1,
                                }}
                              >
                                {agendaWeekDays.map((day) => {
                                  const dayClasses =
                                    agendaClassesByDay.get(day.id) || [];

                                  return (
                                    <Box
                                      key={day.id}
                                      sx={{
                                        border: "1px solid #e2e8f0",
                                        borderRadius: 1,
                                        p: 1,
                                        minHeight: 180,
                                        backgroundColor: "#f8fafc",
                                      }}
                                    >
                                      <Typography
                                        fontWeight={700}
                                        variant="body2"
                                      >
                                        {day.label}
                                      </Typography>
                                      <Typography
                                        variant="caption"
                                        color="text.secondary"
                                        sx={{ display: "block", mb: 1 }}
                                      >
                                        {formatAgendaDay(day.date)}
                                      </Typography>

                                      <Stack spacing={0.8}>
                                        {dayClasses.length ? (
                                          dayClasses.map((clase) => (
                                            <Box
                                              key={clase.id}
                                              sx={{
                                                border: "1px solid",
                                                borderColor: getColorByStudent(
                                                  clase.alumno?.id,
                                                  clase.alumno?.nombre,
                                                ).border,
                                                borderRadius: 1.5,
                                                p: 0.9,
                                                bgcolor: getColorByStudent(
                                                  clase.alumno?.id,
                                                  clase.alumno?.nombre,
                                                ).bg,
                                              }}
                                            >
                                              <Typography
                                                variant="caption"
                                                fontWeight={700}
                                                sx={{
                                                  color: getColorByStudent(
                                                    clase.alumno?.id,
                                                    clase.alumno?.nombre,
                                                  ).title,
                                                }}
                                              >
                                                {formatHourRange(
                                                  clase.fecha,
                                                  clase.duracion,
                                                )}
                                              </Typography>

                                              <Stack
                                                direction="row"
                                                spacing={0.5}
                                                alignItems="center"
                                                sx={{ mt: 0.3 }}
                                              >
                                                <PersonIcon
                                                  sx={{
                                                    fontSize: 14,
                                                    color: getColorByStudent(
                                                      clase.alumno?.id,
                                                      clase.alumno?.nombre,
                                                    ).title,
                                                  }}
                                                />
                                                <Typography
                                                  variant="caption"
                                                  fontWeight={700}
                                                  sx={{
                                                    color: getColorByStudent(
                                                      clase.alumno?.id,
                                                      clase.alumno?.nombre,
                                                    ).title,
                                                  }}
                                                >
                                                  {clase.alumno?.nombre ||
                                                    "Alumno"}
                                                </Typography>
                                              </Stack>

                                              <Typography
                                                variant="caption"
                                                color="text.secondary"
                                                sx={{
                                                  display: "block",
                                                  mt: 0.15,
                                                }}
                                              >
                                                {clase.vehiculo?.marca ||
                                                  "Vehículo"}{" "}
                                                {clase.vehiculo?.modelo || ""}
                                              </Typography>

                                              <Chip
                                                size="small"
                                                label={
                                                  clase.vehiculo?.matricula ||
                                                  "Sin matrícula"
                                                }
                                                sx={{
                                                  mt: 0.45,
                                                  height: 20,
                                                  fontSize: 10,
                                                  bgcolor: "#fff",
                                                  border: "1px solid #dbe5f2",
                                                }}
                                              />

                                              <Chip
                                                size="small"
                                                color={
                                                  getAgendaStatusChipConfig(
                                                    clase.estadoAgenda ||
                                                      clase.estado,
                                                  ).color
                                                }
                                                label={
                                                  getAgendaStatusChipConfig(
                                                    clase.estadoAgenda ||
                                                      clase.estado,
                                                  ).label
                                                }
                                                sx={{
                                                  mt: 0.45,
                                                  height: 20,
                                                  fontSize: 10,
                                                }}
                                              />
                                            </Box>
                                          ))
                                        ) : (
                                          <Typography
                                            variant="caption"
                                            color="text.secondary"
                                          >
                                            Sin clases
                                          </Typography>
                                        )}
                                      </Stack>
                                    </Box>
                                  );
                                })}
                              </Box>
                            )}
                          </Paper>
                        </>
                      )}
                    </Box>
                  ) : (
                    <Box
                      sx={{
                        display: "grid",
                        gap: 2,
                        mt: 2,
                      }}
                    >
                      <TextField
                        label="Nombre"
                        value={selectedProfesor?.usuario?.nombre || ""}
                        InputProps={{
                          readOnly: true,
                          tabIndex: -1,
                        }}
                        sx={readOnlyFieldSx}
                        fullWidth
                      />

                      <TextField
                        label="Email"
                        value={selectedProfesor?.usuario?.email || ""}
                        InputProps={{
                          readOnly: true,
                          tabIndex: -1,
                        }}
                        sx={readOnlyFieldSx}
                        fullWidth
                      />

                      <TextField
                        label="Teléfono"
                        value={selectedProfesor?.usuario?.telefono || ""}
                        InputProps={{
                          readOnly: true,
                          tabIndex: -1,
                        }}
                        sx={readOnlyFieldSx}
                        fullWidth
                      />

                      <TextField
                        label="DNI"
                        value={selectedProfesor?.usuario?.dni || ""}
                        InputProps={{
                          readOnly: true,
                          tabIndex: -1,
                        }}
                        sx={readOnlyFieldSx}
                        fullWidth
                      />

                      <TextField
                        label="Permisos"
                        value={
                          selectedProfesor?.permisosLicencias?.join(", ") || ""
                        }
                        InputProps={{
                          readOnly: true,
                          tabIndex: -1,
                        }}
                        sx={readOnlyFieldSx}
                        fullWidth
                      />

                      <TextField
                        label="Estado"
                        value={selectedProfesor?.activo ? "Activo" : "Inactivo"}
                        InputProps={{
                          readOnly: true,
                          tabIndex: -1,
                        }}
                        sx={readOnlyFieldSx}
                        fullWidth
                      />
                    </Box>
                  )}
                </Box>
              </Box>
            </Box>
          )}
        </DialogContent>

        <DialogActions>
          <Button
            variant="contained"
            onClick={() => {
              if (selectedProfesor) {
                setOpenDetail(false);
                handleEdit(selectedProfesor);
              }
            }}
            disabled={detailView === "ALUMNOS_AGENDA"}
          >
            Editar profesor
          </Button>

          <Button onClick={() => setOpenDetail(false)}>Cerrar</Button>
        </DialogActions>
      </Dialog>

      <Dialog
        open={confirmDialog.open}
        onClose={closeConfirmDialog}
        fullWidth
        maxWidth="xs"
      >
        <DialogTitle>{confirmDialog.title}</DialogTitle>

        <DialogContent>
          <DialogContentText>{confirmDialog.message}</DialogContentText>
        </DialogContent>

        <DialogActions>
          <Button onClick={closeConfirmDialog}>Cancelar</Button>

          <Button
            variant="contained"
            color={confirmDialog.action === "activate" ? "success" : "error"}
            onClick={handleConfirmAction}
          >
            Confirmar
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog
        open={deactivationModal.open}
        onClose={deactivationModal.loading ? () => {} : closeDeactivationModal}
        fullWidth
        maxWidth="md"
      >
        <DialogTitle>
          Reasignación obligatoria para desactivar profesor
        </DialogTitle>
        <DialogContent sx={{ display: "grid", gap: 2, pt: 1 }}>
          <DialogContentText>
            Debes reasignar todos los alumnos asignados antes de desactivar al
            profesor {deactivationModal.profesor?.nombre || ""}. Al guardar, la
            reasignación también se aplicará a sus clases prácticas futuras.
          </DialogContentText>

          {deactivationModal.alumnos.map((alumno) => (
            <Box
              key={alumno.alumnoId}
              sx={{
                border: "1px solid",
                borderColor: "divider",
                borderRadius: 1,
                p: 2,
                display: "grid",
                gap: 1,
              }}
            >
              <Typography variant="body2" fontWeight={700}>
                {alumno.alumnoNombre} | Licencia {alumno.licencia}
              </Typography>

              <FormControl fullWidth size="small">
                <Select
                  value={reasignacionesProfesor[alumno.alumnoId] || ""}
                  displayEmpty
                  onChange={(event) =>
                    setReasignacionesProfesor((prev) => ({
                      ...prev,
                      [alumno.alumnoId]: event.target.value,
                    }))
                  }
                >
                  <MenuItem value="">
                    <em>Seleccionar profesor compatible</em>
                  </MenuItem>
                  {alumno.opciones.map((opcion) => (
                    <MenuItem key={opcion.id} value={opcion.id}>
                      {opcion.nombre} (
                      {(opcion.permisosLicencias || []).join(", ")})
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Box>
          ))}
        </DialogContent>
        <DialogActions>
          <Button
            onClick={closeDeactivationModal}
            disabled={deactivationModal.loading}
          >
            Cancelar
          </Button>
          <Button
            variant="contained"
            color="error"
            onClick={handleConfirmDeactivateWithReassignment}
            disabled={deactivationModal.loading}
          >
            {deactivationModal.loading
              ? "Guardando..."
              : "Guardar y desactivar"}
          </Button>
        </DialogActions>
      </Dialog>
      <Snackbar
        open={notification.open}
        autoHideDuration={4000}
        onClose={() =>
          setNotification({
            ...notification,
            open: false,
          })
        }
        anchorOrigin={{
          vertical: "top",
          horizontal: "right",
        }}
      >
        <Alert
          severity={notification.severity}
          variant="filled"
          onClose={() =>
            setNotification({
              ...notification,
              open: false,
            })
          }
        >
          {notification.message}
        </Alert>
      </Snackbar>
    </Box>
  );
}

import { useEffect, useMemo, useState } from "react";

import {
  Box,
  Button,
  Paper,
  Typography,
  Chip,
  CircularProgress,
  Stack,
} from "@mui/material";

import { DataGrid } from "@mui/x-data-grid";

import { profesoresService } from "../../services/profesoresService";

import EditIcon from "@mui/icons-material/Edit";
import DeleteIcon from "@mui/icons-material/Delete";

import ToggleOffIcon from "@mui/icons-material/ToggleOff";
import ToggleOnIcon from "@mui/icons-material/ToggleOn";
import { LicenseChipList } from "../../components/common/LicenseChip";
import CalendarMonthIcon from "@mui/icons-material/CalendarMonth";

import Tooltip from "@mui/material/Tooltip"; // Asegúrate de importar el componente

import { IconButton } from "@mui/material";

import Snackbar from "@mui/material/Snackbar";
import Alert from "@mui/material/Alert";

import Radio from "@mui/material/Radio";
import RadioGroup from "@mui/material/RadioGroup";
import FormControl from "@mui/material/FormControl";
import FormControlLabel from "@mui/material/FormControlLabel";

import MenuItem from "@mui/material/MenuItem";
import Select from "@mui/material/Select";

import InputAdornment from "@mui/material/InputAdornment";
import CloseIcon from "@mui/icons-material/Close";

import DownloadIcon from "@mui/icons-material/Download";
import Menu from "@mui/material/Menu";

import { exportProfesoresExcel } from "../../utils/exportProfesoresExcel";

import { exportProfesoresPdf } from "../../utils/exportProfesoresPdf";

import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  DialogContentText,
  TextField,
} from "@mui/material";
import ReadOnlyWeeklyAgendaBoard from "../../components/agenda/ReadOnlyWeeklyAgendaBoard";

const limpiarDni = (valor) =>
  String(valor || "")
    .toUpperCase()
    .replace(/[^0-9A-Z]/g, "");

const normalizarDniFormulario = (valor) => {
  const limpio = limpiarDni(valor);
  const numeros = limpio.replace(/[^0-9]/g, "").slice(0, 8);
  const letra = limpio.replace(/[0-9]/g, "").slice(0, 1);

  return `${numeros}${letra}`;
};

const esDniCompleto = (valor) => /^\d{8}[A-Z]$/.test(limpiarDni(valor));

const normalizarTelefono = (valor) =>
  String(valor || "")
    .replace(/\D/g, "")
    .slice(0, 9);

const esTelefonoValido = (valor) => /^\d{9}$/.test(String(valor || ""));

export default function Profesores() {
  const [rows, setRows] = useState([]);

  const [estadoFiltro, setEstadoFiltro] = useState("activos");

  const [search, setSearch] = useState("");

  const licencias = ["B", "A1", "A2", "A", "C", "D", "E"];

  const [exportAnchor, setExportAnchor] = useState(null);

  const openExportMenu = (event) => {
    setExportAnchor(event.currentTarget);
  };

  const closeExportMenu = () => {
    setExportAnchor(null);
  };

  const handleExportExcel = () => {
    exportProfesoresExcel(rows);
    closeExportMenu();
  };

  const handleExportPdf = () => {
    exportProfesoresPdf(rows);
    closeExportMenu();
  };

  useEffect(() => {
    loadProfesores();
  }, [estadoFiltro, search]);

  const loadProfesores = async () => {
    try {
      const data = await profesoresService.getAll();

      console.log("TOTAL ProfesorS:", data.length);

      console.log(
        "TODOS LOS ProfesorS:",
        data.map((a) => ({
          nombre: a.usuario?.nombre,
          activo: a.activo,
        })),
      );

      let filteredData = data;

      if (estadoFiltro === "activos") {
        filteredData = data.filter((Profesor) => Profesor.activo === true);
      }

      if (estadoFiltro === "inactivos") {
        filteredData = data.filter((Profesor) => Profesor.activo === false);
      }

      if (estadoFiltro === "todos") {
        filteredData = data;
      }

      if (search.trim() !== "") {
        const texto = search.toLowerCase();

        filteredData = filteredData.filter(
          (Profesor) =>
            Profesor.usuario?.nombre?.toLowerCase().includes(texto) ||
            Profesor.usuario?.email?.toLowerCase().includes(texto) ||
            Profesor.usuario?.telefono?.toLowerCase().includes(texto),
        );
      }

      console.log(
        "FILTRADOS:",
        filteredData.map((a) => ({
          nombre: a.usuario?.nombre,
          activo: a.activo,
        })),
      );

      setRows(filteredData);
    } catch (error) {
      console.error(error);
    }
  };

  const saveProfesor = async () => {
    try {
      const dniNormalizado = limpiarDni(nuevoProfesor.dni);

      if (!esDniCompleto(dniNormalizado)) {
        setNotification({
          open: true,
          message: "El DNI está incompleto. Formato esperado: 12345678Z",
          severity: "error",
        });
        setFieldTouched((prev) => ({ ...prev, dni: true }));
        return;
      }

      const telefonoNormalizado = normalizarTelefono(nuevoProfesor.telefono);

      if (!esTelefonoValido(telefonoNormalizado)) {
        setNotification({
          open: true,
          message: "El teléfono debe tener exactamente 9 dígitos numéricos",
          severity: "error",
        });
        return;
      }

      const payloadBase = {
        nombre: nuevoProfesor.nombre?.trim() || "",
        email: nuevoProfesor.email?.trim() || "",
        telefono: telefonoNormalizado,
        permisosLicencias: nuevoProfesor.permisosLicencias,
        licenciaConducir: nuevoProfesor.permisosLicencias[0] || "",
        dni: dniNormalizado,
      };

      if (editingId) {
        const payload = {
          nombre: payloadBase.nombre,
          email: payloadBase.email,
          dni: payloadBase.dni,
          telefono: payloadBase.telefono,
          licenciaConducir: payloadBase.licenciaConducir,
          permisosLicencias: payloadBase.permisosLicencias,
        };

        if (nuevoProfesor.password?.trim()) {
          payload.password = nuevoProfesor.password.trim();
        }

        await profesoresService.update(editingId, payload);
      } else {
        await profesoresService.create({
          ...payloadBase,
          password: nuevoProfesor.password || "",
        });
      }

      setOpen(false);

      setEditingId(null);

      setNuevoProfesor({
        nombre: "",
        email: "",
        password: "",
        dni: "",
        telefono: "",
        permisosLicencias: ["B"],
      });

      setFieldTouched({
        dni: false,
      });

      loadProfesores();

      setNotification({
        open: true,
        message: editingId
          ? "Profesor actualizado correctamente"
          : "Profesor creado correctamente",
        severity: "success",
      });
    } catch (error) {
      console.error(error);

      setNotification({
        open: true,
        message:
          error.response?.data?.message ||
          (editingId ? "Error modificando Profesor" : "Error creando Profesor"),
        severity: "error",
      });
    }
  };

  const handleDeactivate = async (row) => {
    const nombreProfesor = row?.usuario?.nombre || "este profesor";

    try {
      const impacto = await profesoresService.getDeactivationImpact(row.id);

      if (!impacto?.alumnos?.length) {
        setConfirmDialog({
          open: true,
          action: "deactivate",
          profesorId: row.id,
          profesorNombre: nombreProfesor,
          title: "Confirmar desactivación",
          message: `Vas a desactivar a ${nombreProfesor} en la plataforma Autoescuela Eguzkilore. No podrá operar hasta su reactivación. ¿Deseas continuar?`,
        });
        return;
      }

      const reasignacionesIniciales = {};
      impacto.alumnos.forEach((item) => {
        reasignacionesIniciales[item.alumnoId] = "";
      });

      setReasignacionesProfesor(reasignacionesIniciales);
      setDeactivationModal({
        open: true,
        loading: false,
        profesor: impacto.profesor,
        alumnos: impacto.alumnos,
      });
    } catch (error) {
      setNotification({
        open: true,
        message:
          error.response?.data?.message ||
          "No se pudo cargar el impacto de desactivación del profesor",
        severity: "error",
      });
    }
  };

  const closeDeactivationModal = () => {
    setDeactivationModal({
      open: false,
      loading: false,
      profesor: null,
      alumnos: [],
    });
    setReasignacionesProfesor({});
  };

  const handleConfirmDeactivateWithReassignment = async () => {
    if (!deactivationModal.profesor?.id) {
      return;
    }

    const reasignaciones = [];

    for (const alumno of deactivationModal.alumnos) {
      const nuevoProfesorId = reasignacionesProfesor[alumno.alumnoId];

      if (!nuevoProfesorId) {
        setNotification({
          open: true,
          message:
            "Debes seleccionar un nuevo profesor para todos los alumnos asignados",
          severity: "error",
        });
        return;
      }

      reasignaciones.push({
        alumnoId: alumno.alumnoId,
        nuevoProfesorId,
      });
    }

    try {
      setDeactivationModal((prev) => ({ ...prev, loading: true }));
      await profesoresService.deactivateWithReassignment(
        deactivationModal.profesor.id,
        reasignaciones,
      );
      await loadProfesores();
      closeDeactivationModal();
      setNotification({
        open: true,
        message:
          "Profesor desactivado correctamente con reasignación obligatoria de alumnos y clases futuras",
        severity: "success",
      });
    } catch (error) {
      setNotification({
        open: true,
        message:
          error.response?.data?.message ||
          "No se pudo completar la desactivación con reasignación",
        severity: "error",
      });
    } finally {
      setDeactivationModal((prev) => ({ ...prev, loading: false }));
    }
  };

  const handleActivate = async (row) => {
    const nombreProfesor = row?.usuario?.nombre || "este profesor";

    setConfirmDialog({
      open: true,
      action: "activate",
      profesorId: row.id,
      profesorNombre: nombreProfesor,
      title: "Confirmar activación",
      message: `Vas a reactivar a ${nombreProfesor} en la plataforma Autoescuela Eguzkilore. Recuperará acceso operativo de inmediato. ¿Deseas continuar?`,
    });
  };

  const handleDelete = async (row) => {
    const nombreProfesor = row?.usuario?.nombre || "este profesor";

    setConfirmDialog({
      open: true,
      action: "delete",
      profesorId: row.id,
      profesorNombre: nombreProfesor,
      title: "Confirmar eliminación",
      message: `Vas a eliminar definitivamente a ${nombreProfesor} de Autoescuela Eguzkilore. Toda la información asociada será eliminada de forma permanente. Esta acción no podrá deshacerse. ¿Deseas continuar?`,
    });
  };

  const closeConfirmDialog = () => {
    setConfirmDialog({
      open: false,
      action: null,
      profesorId: null,
      profesorNombre: "",
      title: "",
      message: "",
    });
  };

  const handleConfirmAction = async () => {
    if (!confirmDialog.profesorId || !confirmDialog.action) {
      closeConfirmDialog();
      return;
    }

    try {
      if (confirmDialog.action === "deactivate") {
        await profesoresService.deactivate(confirmDialog.profesorId);
      }

      if (confirmDialog.action === "activate") {
        await profesoresService.activate(confirmDialog.profesorId);
      }

      if (confirmDialog.action === "delete") {
        await profesoresService.delete(confirmDialog.profesorId);
      }

      loadProfesores();

      setNotification({
        open: true,
        message:
          confirmDialog.action === "deactivate"
            ? "Profesor desactivado correctamente"
            : confirmDialog.action === "activate"
              ? "Profesor activado correctamente"
              : "Profesor eliminado correctamente",
        severity: "success",
      });
    } catch (error) {
      console.error(error);

      setNotification({
        open: true,
        message:
          confirmDialog.action === "deactivate"
            ? "Error desactivando profesor"
            : confirmDialog.action === "activate"
              ? "Error activando profesor"
              : "Error eliminando profesor",
        severity: "error",
      });
    } finally {
      closeConfirmDialog();
    }
  };

  const columns = [
    {
      field: "nombre",
      headerName: "Nombre",
      flex: 1,

      valueGetter: (_, row) => row.usuario?.nombre || "",
    },

    {
      field: "email",
      headerName: "Email",
      flex: 1.5,

      valueGetter: (_, row) => row.usuario?.email || "",
    },

    {
      field: "permisosLicencias",
      headerName: "Permisos",
      flex: 1.2,
      renderCell: (params) => (
        <Box
          sx={{
            display: "flex",
            flexDirection: "column",
            justifyContent: "flex-end", // Empuja los chips al fondo de la celda
            height: "100%", // Usa todo el alto disponible de la fila
            pb: 1.5, // Padding bottom opcional (8px) para separar del borde
          }}
        >
          <LicenseChipList
            values={
              Array.isArray(params.row.permisosLicencias) &&
              params.row.permisosLicencias.length > 0
                ? params.row.permisosLicencias
                : [params.row.licenciaConducir]
            }
          />
        </Box>
      ),
    },

    {
      field: "telefono",
      headerName: "Teléfono",
      flex: 1,
    },

    {
      field: "activo",
      headerName: "Estado",
      width: 130,
      renderCell: (params) => (
        <Chip
          label={(params.row.activo ?? true) ? "Activo" : "Inactivo"}
          size="small"
          sx={{
            // 1. Estilos si está Activo
            ...((params.row.activo ?? true) && {
              backgroundColor: "#e8f5e9", // Fondo verde claro
              color: "#2e7d32", // Texto verde oscuro
              border: "1px solid #2e7d32", // Borde verde
            }),
            // 2. Estilos si está Inactivo
            ...(!(params.row.activo ?? true) && {
              backgroundColor: "#ffebee", // Fondo rojo claro
              color: "#c62828", // Texto rojo oscuro
              border: "1px solid #c62828", // Borde rojo
            }),
            fontWeight: "bold", // Estilo común para ambos estados (opcional)
          }}
        />
      ),
    },

    {
      field: "acciones",
      headerName: "Acciones",
      width: 160,

      renderCell: (params) => (
        <>
          <Tooltip title="Editar" arrow>
            <IconButton
              color="primary"
              onClick={(event) => {
                event.stopPropagation();
                handleEdit(params.row);
              }}
            >
              <EditIcon />
            </IconButton>
          </Tooltip>

          <Tooltip title={params.row.activo ? "Desactivar" : "Activar"} arrow>
            {params.row.activo ? (
              <IconButton
                color="warning"
                onClick={(event) => {
                  event.stopPropagation();
                  handleDeactivate(params.row);
                }}
              >
                <ToggleOffIcon />
              </IconButton>
            ) : (
              <IconButton
                color="success"
                onClick={(event) => {
                  event.stopPropagation();
                  handleActivate(params.row);
                }}
              >
                <ToggleOnIcon />
              </IconButton>
            )}
          </Tooltip>

          <Tooltip title="Eliminar" arrow>
            <IconButton
              color="error"
              onClick={(event) => {
                event.stopPropagation();
                handleDelete(params.row);
              }}
            >
              <DeleteIcon />
            </IconButton>
          </Tooltip>
        </>
      ),
    },
  ];

  const [open, setOpen] = useState(false);
  const [editingId, setEditingId] = useState(null);

  const [openDetail, setOpenDetail] = useState(false);
  const [loadingDetail, setLoadingDetail] = useState(false);
  const [selectedProfesor, setSelectedProfesor] = useState(null);
  const [detailView, setDetailView] = useState("PERFIL");
  const [overviewLoading, setOverviewLoading] = useState(false);
  const [overviewData, setOverviewData] = useState(null);
  const [overviewWeekOffset, setOverviewWeekOffset] = useState(0);
  const [selectedAlumnoAgendaId, setSelectedAlumnoAgendaId] = useState("");

  const [nuevoProfesor, setNuevoProfesor] = useState({
    nombre: "",
    email: "",
    password: "",
    dni: "",
    permisosLicencias: ["B"],
    telefono: "",
    activo: true,
  });

  const [fieldTouched, setFieldTouched] = useState({
    dni: false,
  });

  const dniIncompleto = fieldTouched.dni && !esDniCompleto(nuevoProfesor.dni);

  const [confirmDialog, setConfirmDialog] = useState({
    open: false,
    action: null,
    profesorId: null,
    profesorNombre: "",
    title: "",
    message: "",
  });

  const [notification, setNotification] = useState({
    open: false,
    message: "",
    severity: "success",
  });

  const [deactivationModal, setDeactivationModal] = useState({
    open: false,
    loading: false,
    profesor: null,
    alumnos: [],
  });
  const [reasignacionesProfesor, setReasignacionesProfesor] = useState({});

  const handleEdit = (row) => {
    setEditingId(row.id);

    setNuevoProfesor({
      nombre: row.usuario?.nombre || "",
      email: row.usuario?.email || "",
      password: "",
      dni: normalizarDniFormulario(row.usuario?.dni || ""),
      telefono: row.usuario?.telefono || "",
      permisosLicencias:
        Array.isArray(row.permisosLicencias) && row.permisosLicencias.length > 0
          ? row.permisosLicencias
          : [row.licenciaConducir || "B"],
    });

    setFieldTouched({
      dni: false,
    });

    setOpen(true);
  };

  const handleOpenDetail = async (row) => {
    setOpenDetail(true);
    setLoadingDetail(true);
    setDetailView("PERFIL");
    setOverviewData(null);
    setOverviewWeekOffset(0);
    setSelectedAlumnoAgendaId("");

    try {
      const detalle = await profesoresService.getById(row.id);

      setSelectedProfesor(detalle);
      await loadOverview(detalle.id, {
        weekOffset: 0,
        alumnoId: "",
      });
    } catch (error) {
      console.error(error);

      setNotification({
        open: true,
        message: "No se pudo cargar el detalle del profesor",
        severity: "error",
      });
    } finally {
      setLoadingDetail(false);
    }
  };

  const loadOverview = async (profesorId, options = {}) => {
    if (!profesorId) {
      return;
    }

    const nextWeekOffset =
      options.weekOffset !== undefined
        ? options.weekOffset
        : overviewWeekOffset;
    const hasAlumnoOption = Object.prototype.hasOwnProperty.call(
      options,
      "alumnoId",
    );
    const alumnoId = hasAlumnoOption
      ? options.alumnoId || undefined
      : selectedAlumnoAgendaId || undefined;

    setOverviewLoading(true);

    try {
      const response = await profesoresService.getOverview(profesorId, {
        weekOffset: nextWeekOffset,
        alumnoId,
      });

      setOverviewData(response);
      setOverviewWeekOffset(nextWeekOffset);
      setSelectedAlumnoAgendaId(
        response?.agendaAlumno?.alumnoSeleccionadoId || "",
      );
    } catch (error) {
      setNotification({
        open: true,
        message:
          error.response?.data?.message ||
          "No se pudo cargar el bloque de alumnos y agenda",
        severity: "error",
      });
    } finally {
      setOverviewLoading(false);
    }
  };

  const openStudentsAndAgendaView = async () => {
    setDetailView("ALUMNOS_AGENDA");

    if (!selectedProfesor?.id) {
      return;
    }

    await loadOverview(selectedProfesor.id, {
      weekOffset: overviewWeekOffset,
      alumnoId: selectedAlumnoAgendaId || undefined,
    });
  };

  const readOnlyFieldSx = {
    "& .MuiInputBase-input": {
      cursor: "default",
      caretColor: "transparent",
      userSelect: "none",
    },
    "& .MuiOutlinedInput-root": {
      backgroundColor: "action.hover",
    },
  };

  const overviewAgendaData = useMemo(() => {
    if (!overviewData?.agendaAlumno) {
      return null;
    }

    return {
      semana: overviewData.agendaAlumno.semana,
      horario: overviewData.agendaAlumno.horario || [],
      clasesSemana: overviewData.agendaAlumno.clases || [],
      resumenSemanaPorEstado:
        overviewData.agendaAlumno.resumenSemanaPorEstado || {},
      resumenMesPorEstado: overviewData.agendaAlumno.resumenMesPorEstado || {},
      mesVisible: overviewData.agendaAlumno.mesVisible || null,
    };
  }, [overviewData]);

  const alumnosResumenColumns = useMemo(
    () => [
      {
        field: "nombre",
        headerName: "Alumno",
        flex: 1.2,
      },
      {
        field: "licencia",
        headerName: "Licencia",
        width: 120,
      },
      {
        field: "estadoExpedienteLabel",
        headerName: "Estado expediente",
        flex: 1.6,
      },
    ],
    [],
  );

  return (
    <Box>
      <Typography variant="h4" fontWeight="bold" mb={4}>
        Gestión de Profesores
      </Typography>
      <Typography color="text.secondary" sx={{ mb: 2 }}>
        Administra los profesores registrados en la Autoescuela Eguskilore.
      </Typography>
      <Box
        sx={{
          display: "flex",
          alignItems: "center",
          gap: 4,
          mb: 3,
          flexWrap: "wrap",
        }}
      >
        <Button
          variant="contained"
          onClick={() => {
            setEditingId(null);

            setNuevoProfesor({
              nombre: "",
              email: "",
              password: "",
              dni: "",
              telefono: "",
              permisosLicencias: ["B"],
            });

            setFieldTouched({
              dni: false,
            });

            setOpen(true);
          }}
        >
          Nuevo Profesor
        </Button>

        <RadioGroup
          row
          value={estadoFiltro}
          onChange={(e) => setEstadoFiltro(e.target.value)}
        >
          <FormControlLabel
            value="activos"
            control={<Radio />}
            label="Activos"
          />

          <FormControlLabel
            value="inactivos"
            control={<Radio />}
            label="Inactivos"
          />

          <FormControlLabel value="todos" control={<Radio />} label="Todos" />
        </RadioGroup>

        <TextField
          size="small"
          label="Buscar profesor"
          placeholder="Nombre, email o teléfono"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          sx={{ width: 320 }}
          InputProps={{
            endAdornment: search && (
              <InputAdornment position="end">
                <IconButton size="small" onClick={() => setSearch("")}>
                  <CloseIcon fontSize="small" />
                </IconButton>
              </InputAdornment>
            ),
          }}
        />

        <Button
          variant="outlined"
          startIcon={<DownloadIcon />}
          onClick={openExportMenu}
        >
          Exportar
        </Button>

        <Menu
          anchorEl={exportAnchor}
          open={Boolean(exportAnchor)}
          onClose={closeExportMenu}
        >
          <MenuItem onClick={handleExportExcel}>Exportar a Excel</MenuItem>

          <MenuItem onClick={handleExportPdf}>Exportar a PDF</MenuItem>
        </Menu>
      </Box>

      <Paper
        sx={{
          height: 700,
          p: 2,
        }}
      >
        <DataGrid
          rows={rows}
          columns={columns}
          getRowId={(row) => row.id}
          disableRowSelectionOnClick
          pageSizeOptions={[10, 25, 50]}
          initialState={{
            pagination: { paginationModel: { pageSize: 10, page: 0 } },
            sorting: { sortModel: [{ field: "nombre", sort: "asc" }] },
          }}
          onRowClick={(params) => handleOpenDetail(params.row)}
        />
      </Paper>

      <Dialog
        open={open}
        onClose={() => setOpen(false)}
        fullWidth
        maxWidth="sm"
      >
        <DialogTitle>
          {editingId ? "Editar Profesor" : "Crear Profesor"}
        </DialogTitle>

        <DialogContent>
          <TextField
            margin="normal"
            fullWidth
            label="Nombre"
            value={nuevoProfesor.nombre}
            onChange={(e) =>
              setNuevoProfesor({
                ...nuevoProfesor,
                nombre: e.target.value,
              })
            }
          />

          <TextField
            margin="normal"
            fullWidth
            label="Email"
            value={nuevoProfesor.email}
            onChange={(e) =>
              setNuevoProfesor({
                ...nuevoProfesor,
                email: e.target.value,
              })
            }
          />

          <TextField
            margin="normal"
            fullWidth
            label="Contraseña"
            type="password"
            helperText={
              editingId
                ? "Si la dejas vacía, se mantiene la contraseña actual."
                : "Mínimo 8 caracteres"
            }
            value={nuevoProfesor.password}
            onChange={(e) =>
              setNuevoProfesor({
                ...nuevoProfesor,
                password: e.target.value,
              })
            }
          />

          <TextField
            margin="normal"
            fullWidth
            required
            label="DNI"
            placeholder="12345678Z"
            value={nuevoProfesor.dni}
            onChange={(e) =>
              setNuevoProfesor({
                ...nuevoProfesor,
                dni: normalizarDniFormulario(e.target.value),
              })
            }
            onBlur={() =>
              setFieldTouched((prev) => ({
                ...prev,
                dni: true,
              }))
            }
            error={dniIncompleto}
            helperText={
              dniIncompleto
                ? "DNI incompleto. Introduce 8 números y 1 letra."
                : undefined
            }
            inputProps={{ maxLength: 9 }}
          />

          <TextField
            margin="normal"
            fullWidth
            label="Teléfono"
            value={nuevoProfesor.telefono}
            onChange={(e) =>
              setNuevoProfesor({
                ...nuevoProfesor,
                telefono: normalizarTelefono(e.target.value),
              })
            }
            helperText="Formato España: 9 dígitos"
            inputProps={{
              maxLength: 9,
              inputMode: "numeric",
              pattern: "[0-9]*",
            }}
          />

          <Select
            fullWidth
            multiple
            value={nuevoProfesor.permisosLicencias}
            renderValue={(selected) => selected.join(", ")}
            onChange={(e) =>
              setNuevoProfesor({
                ...nuevoProfesor,
                permisosLicencias:
                  typeof e.target.value === "string"
                    ? e.target.value.split(",")
                    : e.target.value,
              })
            }
          >
            {licencias.map((e) => (
              <MenuItem key={e} value={e}>
                {e}
              </MenuItem>
            ))}
          </Select>
        </DialogContent>

        <DialogActions>
          <Button
            onClick={() => {
              setOpen(false);
            }}
          >
            Cancelar
          </Button>

          <Button variant="contained" onClick={saveProfesor}>
            {editingId ? "Actualizar" : "Guardar"}
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog
        open={openDetail}
        onClose={() => setOpenDetail(false)}
        fullWidth
        maxWidth="lg" // Mantenemos el breakpoint como base
        sx={{
          "& .MuiDialog-paper": {
            maxWidth: "1400px", // <--- Cambia este valor al ancho en píxeles que desees (ej: 1400px, 1600px)
            width: "100%", // Fuerza a que use el máximo disponible si la pantalla lo permite
            overflowX: "hidden", // <--- Oculta el scroll horizontal de raíz
          },
        }}
      >
        <DialogTitle>
          <Box
            sx={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              gap: 1,
              flexWrap: "wrap",
            }}
          >
            <Typography variant="h6" fontWeight={700}>
              Detalle del Profesor
            </Typography>

            <Button
              size="small"
              onClick={
                detailView === "ALUMNOS_AGENDA"
                  ? () => setDetailView("PERFIL")
                  : openStudentsAndAgendaView
              }
              disabled={loadingDetail}
              sx={{
                width: "fit-content",
                backgroundColor: "#fffbeb",
                borderColor: "#facc15",
                borderStyle: "solid",
                borderRadius: "15px",
                borderWidth: "2px",
                color: "#ca8a04",
                fontWeight: "bold", // Aplicado directamente al texto del botón
                "&:hover": {
                  backgroundColor: "#fef08a",
                  borderColor: "#eab308",
                  color: "#854d0e",
                },
              }}
            >
              {detailView === "ALUMNOS_AGENDA"
                ? "Volver al detalle"
                : "Ver alumnos y agenda"}
            </Button>
          </Box>
        </DialogTitle>

        <DialogContent>
          {loadingDetail ? (
            <Box
              sx={{
                display: "flex",
                justifyContent: "center",
                py: 4,
              }}
            >
              <CircularProgress />
            </Box>
          ) : (
            <Box
              sx={{
                perspective: "1400px",
                mt: 1,
                minHeight: 620,
                overflow: "hidden",
              }}
            >
              {" "}
              {/* <--- Añade overflow: "hidden" aquí */}
              <Box
                sx={{
                  transition: "transform 700ms ease",
                  transformStyle: "preserve-3d",
                  transform:
                    detailView === "ALUMNOS_AGENDA"
                      ? "rotateY(180deg)"
                      : "rotateY(0deg)",
                }}
              >
                <Box
                  sx={{
                    transform:
                      detailView === "ALUMNOS_AGENDA"
                        ? "rotateY(180deg)"
                        : "rotateY(0deg)",
                  }}
                >
                  {detailView === "ALUMNOS_AGENDA" ? (
                    <Box sx={{ display: "grid", gap: 2 }}>
                      {overviewLoading ? (
                        <Box
                          sx={{
                            display: "flex",
                            justifyContent: "center",
                            py: 4,
                          }}
                        >
                          <CircularProgress />
                        </Box>
                      ) : (
                        <>
                          <Paper variant="outlined" sx={{ p: 2 }}>
                            <Typography
                              variant="subtitle1"
                              fontWeight={700}
                              sx={{ mb: 1 }}
                            >
                              Alumnos asignados
                            </Typography>

                            {overviewData?.alumnos?.length ? (
                              <TextField
                                select
                                fullWidth
                                size="small"
                                label="Seleccionar alumno"
                                value={
                                  overviewData?.agendaAlumno
                                    ?.alumnoSeleccionadoId || ""
                                }
                                onChange={(event) =>
                                  loadOverview(selectedProfesor?.id, {
                                    weekOffset: overviewWeekOffset,
                                    alumnoId: event.target.value,
                                  })
                                }
                              >
                                {(overviewData?.alumnos || []).map((alumno) => (
                                  <MenuItem key={alumno.id} value={alumno.id}>
                                    {alumno.nombre} | Licencia{" "}
                                    {alumno.licencia || "-"}
                                  </MenuItem>
                                ))}
                              </TextField>
                            ) : (
                              <Alert severity="info">
                                Este profesor no tiene alumnos asignados.
                              </Alert>
                            )}
                          </Paper>

                          {!overviewData?.agendaAlumno?.alumnoSeleccionadoId ? (
                            <Alert severity="info">
                              Selecciona un alumno para consultar su agenda
                              semanal.
                            </Alert>
                          ) : (
                            <ReadOnlyWeeklyAgendaBoard
                              title="Agenda semanal del alumno"
                              data={overviewAgendaData}
                              loading={overviewLoading}
                              error={""}
                              onPrevWeek={() =>
                                loadOverview(selectedProfesor?.id, {
                                  weekOffset: overviewWeekOffset - 1,
                                  alumnoId:
                                    overviewData?.agendaAlumno
                                      ?.alumnoSeleccionadoId,
                                })
                              }
                              onNextWeek={() =>
                                loadOverview(selectedProfesor?.id, {
                                  weekOffset: overviewWeekOffset + 1,
                                  alumnoId:
                                    overviewData?.agendaAlumno
                                      ?.alumnoSeleccionadoId,
                                })
                              }
                              showStudentName={false}
                              emptyMessage="No hay clases del alumno en la semana seleccionada."
                            />
                          )}
                        </>
                      )}
                    </Box>
                  ) : (
                    <Box
                      sx={{
                        display: "grid",
                        gridTemplateColumns: {
                          xs: "1fr",
                          md: "1fr 1fr",
                        },
                        gap: 3,
                        mt: 2,
                      }}
                    >
                      <Paper variant="outlined" sx={{ p: 2 }}>
                        <Typography
                          variant="subtitle1"
                          fontWeight={700}
                          sx={{ mb: 1.5 }}
                        >
                          Datos personales
                        </Typography>

                        <Box sx={{ display: "grid", gap: 1.5 }}>
                          <TextField
                            label="Nombre"
                            value={selectedProfesor?.usuario?.nombre || ""}
                            InputProps={{
                              readOnly: true,
                              tabIndex: -1,
                            }}
                            sx={readOnlyFieldSx}
                            fullWidth
                          />

                          <TextField
                            label="Email"
                            value={selectedProfesor?.usuario?.email || ""}
                            InputProps={{
                              readOnly: true,
                              tabIndex: -1,
                            }}
                            sx={readOnlyFieldSx}
                            fullWidth
                          />

                          <TextField
                            label="Teléfono"
                            value={selectedProfesor?.usuario?.telefono || ""}
                            InputProps={{
                              readOnly: true,
                              tabIndex: -1,
                            }}
                            sx={readOnlyFieldSx}
                            fullWidth
                          />

                          <TextField
                            label="DNI"
                            value={selectedProfesor?.usuario?.dni || ""}
                            InputProps={{
                              readOnly: true,
                              tabIndex: -1,
                            }}
                            sx={readOnlyFieldSx}
                            fullWidth
                          />

                          <TextField
                            label="Permisos"
                            value={
                              selectedProfesor?.permisosLicencias?.join(", ") ||
                              ""
                            }
                            InputProps={{
                              readOnly: true,
                              tabIndex: -1,
                            }}
                            sx={readOnlyFieldSx}
                            fullWidth
                          />

                          <TextField
                            label="Estado"
                            value={
                              selectedProfesor?.activo ? "Activo" : "Inactivo"
                            }
                            InputProps={{
                              readOnly: true,
                              tabIndex: -1,
                            }}
                            sx={readOnlyFieldSx}
                            fullWidth
                          />
                        </Box>
                      </Paper>

                      <Paper
                        variant="outlined"
                        sx={{ p: 2, display: "grid", gap: 2 }}
                      >
                        <Typography variant="subtitle1" fontWeight={700}>
                          Resumen operativo
                        </Typography>

                        {overviewLoading ? (
                          <Box
                            sx={{
                              display: "flex",
                              justifyContent: "center",
                              py: 4,
                            }}
                          >
                            <CircularProgress size={28} />
                          </Box>
                        ) : (
                          <>
                            <Stack
                              direction="row"
                              flexWrap="wrap"
                              useFlexGap
                              gap={1.5} // Aumentado para dar más separación horizontal y vertical entre los chips
                              sx={{ mr: 1 }} // Margen inferior extra si es necesario para separarlo del contenido de abajo
                            >
                              <Chip
                                variant="outlined"
                                label={`Clases realizadas este mes: ${overviewData?.resumenProfesor?.clasesRealizadasMes || 0}`}
                                sx={{
                                  backgroundColor: "#e8f5e9", // Verde claro
                                  color: "#2e7d32",
                                  borderColor: "#c8e6c9",
                                  mr: 0.5,
                                }}
                              />
                              <Chip
                                variant="outlined"
                                label={`Clases realizadas total: ${overviewData?.resumenProfesor?.clasesRealizadasTotal || 0}`}
                                sx={{
                                  backgroundColor: "#e3f2fd", // Azul claro
                                  color: "#1565c0",
                                  borderColor: "#bbdefb",
                                  mr: 0.5,
                                }}
                              />
                              <Chip
                                variant="outlined"
                                label={`Pendientes mes: ${overviewData?.resumenProfesor?.clasesPendientesMes || 0}`}
                                sx={{
                                  backgroundColor: "#fff3e0", // Naranja claro
                                  color: "#e65100",
                                  borderColor: "#ffe0b2",
                                  mr: 0.5,
                                }}
                              />
                              <Chip
                                variant="outlined"
                                label={`Licencia obtenida: ${overviewData?.resumenProfesor?.alumnosLicenciaObtenida || 0}`}
                                sx={{
                                  backgroundColor: "#e8f5e9", // Verde claro
                                  color: "#2e7d32",
                                  borderColor: "#c8e6c9",
                                  mr: 0.5,
                                }}
                              />
                              <Chip
                                variant="outlined"
                                label={`Alumnos en progreso: ${overviewData?.resumenProfesor?.alumnosEnProgreso || 0}`}
                                sx={{
                                  backgroundColor: "#f3e5f5", // Morado claro
                                  color: "#6a1b9a",
                                  borderColor: "#e1bee7",
                                  mr: 0.5,
                                }}
                              />
                            </Stack>

                            <Typography variant="subtitle2" fontWeight={700}>
                              Alumnos y estado de expediente
                            </Typography>

                            <Box sx={{ height: 260 }}>
                              <DataGrid
                                rows={overviewData?.alumnosDetalle || []}
                                columns={alumnosResumenColumns}
                                getRowId={(row) => row.id}
                                disableRowSelectionOnClick
                                pageSizeOptions={[5, 10, 20]}
                                initialState={{
                                  pagination: {
                                    paginationModel: {
                                      pageSize: 5,
                                      page: 0,
                                    },
                                  },
                                }}
                                localeText={{
                                  noRowsLabel: "No hay alumnos asignados",
                                }}
                              />
                            </Box>

                            <Typography variant="subtitle2" fontWeight={700}>
                              Clases efectuadas por vehículo (este mes)
                            </Typography>

                            {(overviewData?.resumenProfesor?.vehiculosMes || [])
                              .length ? (
                              <Box sx={{ display: "grid", gap: 1 }}>
                                {(
                                  overviewData?.resumenProfesor?.vehiculosMes ||
                                  []
                                ).map((item) => (
                                  <Chip
                                    key={`mes-${item.vehiculoId || item.matricula}`}
                                    variant="outlined"
                                    label={`${item.matricula} | ${item.marca} ${item.modelo} | ${item.clasesEfectuadas} clases`}
                                  />
                                ))}
                              </Box>
                            ) : (
                              <Alert severity="info">
                                No hay clases efectuadas este mes.
                              </Alert>
                            )}

                            <Typography variant="subtitle2" fontWeight={700}>
                              Clases efectuadas por vehículo (total)
                            </Typography>

                            {(
                              overviewData?.resumenProfesor?.vehiculosTotal ||
                              []
                            ).length ? (
                              <Box sx={{ display: "grid", gap: 1 }}>
                                {(
                                  overviewData?.resumenProfesor
                                    ?.vehiculosTotal || []
                                ).map((item) => (
                                  <Chip
                                    key={`total-${item.vehiculoId || item.matricula}`}
                                    variant="outlined"
                                    label={`${item.matricula} | ${item.marca} ${item.modelo} | ${item.clasesEfectuadas} clases`}
                                  />
                                ))}
                              </Box>
                            ) : (
                              <Alert severity="info">
                                No hay clases efectuadas en el histórico.
                              </Alert>
                            )}
                          </>
                        )}
                      </Paper>
                    </Box>
                  )}
                </Box>
              </Box>
            </Box>
          )}
        </DialogContent>

        <DialogActions>
          <Button
            variant="contained"
            onClick={() => {
              if (selectedProfesor) {
                setOpenDetail(false);
                handleEdit(selectedProfesor);
              }
            }}
            disabled={detailView === "ALUMNOS_AGENDA"}
          >
            Editar profesor
          </Button>

          <Button onClick={() => setOpenDetail(false)}>Cerrar</Button>
        </DialogActions>
      </Dialog>

      <Dialog
        open={confirmDialog.open}
        onClose={closeConfirmDialog}
        fullWidth
        maxWidth="xs"
      >
        <DialogTitle>{confirmDialog.title}</DialogTitle>

        <DialogContent>
          <DialogContentText>{confirmDialog.message}</DialogContentText>
        </DialogContent>

        <DialogActions>
          <Button onClick={closeConfirmDialog}>Cancelar</Button>

          <Button
            variant="contained"
            color={confirmDialog.action === "activate" ? "success" : "error"}
            onClick={handleConfirmAction}
          >
            Confirmar
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog
        open={deactivationModal.open}
        onClose={deactivationModal.loading ? () => {} : closeDeactivationModal}
        fullWidth
        maxWidth="md"
      >
        <DialogTitle>
          Reasignación obligatoria para desactivar profesor
        </DialogTitle>
        <DialogContent sx={{ display: "grid", gap: 2, pt: 1 }}>
          <DialogContentText>
            Debes reasignar todos los alumnos asignados antes de desactivar al
            profesor {deactivationModal.profesor?.nombre || ""}. Al guardar, la
            reasignación también se aplicará a sus clases prácticas futuras.
          </DialogContentText>

          {deactivationModal.alumnos.map((alumno) => (
            <Box
              key={alumno.alumnoId}
              sx={{
                border: "1px solid",
                borderColor: "divider",
                borderRadius: 1,
                p: 2,
                display: "grid",
                gap: 1,
              }}
            >
              <Typography variant="body2" fontWeight={700}>
                {alumno.alumnoNombre} | Licencia {alumno.licencia}
              </Typography>

              <FormControl fullWidth size="small">
                <Select
                  value={reasignacionesProfesor[alumno.alumnoId] || ""}
                  displayEmpty
                  onChange={(event) =>
                    setReasignacionesProfesor((prev) => ({
                      ...prev,
                      [alumno.alumnoId]: event.target.value,
                    }))
                  }
                >
                  <MenuItem value="">
                    <em>Seleccionar profesor compatible</em>
                  </MenuItem>
                  {alumno.opciones.map((opcion) => (
                    <MenuItem key={opcion.id} value={opcion.id}>
                      {opcion.nombre} (
                      {(opcion.permisosLicencias || []).join(", ")})
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Box>
          ))}
        </DialogContent>
        <DialogActions>
          <Button
            onClick={closeDeactivationModal}
            disabled={deactivationModal.loading}
          >
            Cancelar
          </Button>
          <Button
            variant="contained"
            color="error"
            onClick={handleConfirmDeactivateWithReassignment}
            disabled={deactivationModal.loading}
          >
            {deactivationModal.loading
              ? "Guardando..."
              : "Guardar y desactivar"}
          </Button>
        </DialogActions>
      </Dialog>
      <Snackbar
        open={notification.open}
        autoHideDuration={4000}
        onClose={() =>
          setNotification({
            ...notification,
            open: false,
          })
        }
        anchorOrigin={{
          vertical: "top",
          horizontal: "right",
        }}
      >
        <Alert
          severity={notification.severity}
          variant="filled"
          onClose={() =>
            setNotification({
              ...notification,
              open: false,
            })
          }
        >
          {notification.message}
        </Alert>
      </Snackbar>
    </Box>
  );
}

import { useEffect, useMemo, useState } from "react";

import {
  Alert,
  Box,
  Button,
  Checkbox,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogContentText,
  IconButton,
  DialogTitle,
  FormControl,
  FormControlLabel,
  InputLabel,
  MenuItem,
  Select,
  Snackbar,
  TextField,
  Typography,
} from "@mui/material";
import { DataGrid } from "@mui/x-data-grid";
import EditIcon from "@mui/icons-material/Edit";
import DeleteIcon from "@mui/icons-material/Delete";
import AddIcon from "@mui/icons-material/Add";
import ToggleOffIcon from "@mui/icons-material/ToggleOff";
import ToggleOnIcon from "@mui/icons-material/ToggleOn";
import Tooltip from "@mui/material/Tooltip"; // Asegúrate de importar el componente

import { promocionesService } from "../../services/promocionesService";
import { LicenseChipList } from "../../components/common/LicenseChip";
import { tarifasMatriculaService } from "../../services/tarifasMatriculaService";

const LICENCIAS = ["B", "A1", "A2", "A", "C", "D", "E"];

const TAMANO_MAXIMO_IMAGEN = 5 * 1024 * 1024;

const TIPOS_IMAGEN_PERMITIDOS = ["image/png", "image/jpeg", "image/webp"];

const emptyForm = {
  nombre: "",
  descripcion: "",
  precioOriginal: "",
  precioPromocional: "",
  licenciasAplicables: ["B"],
  fechaInicio: "",
  fechaFin: "",
  activa: true,
  requiereCarnetEstudiante: false,
  requiereFidelidad: false,
  edadMinima: "",
  edadMaxima: "",
  incluyePagoExamenGratis: false,
  incluirClasesGratis: false,
  clasesGratisIncluidas: "",
  licenciaClasesGratis: "B",
};

export default function Promociones() {
  const [rows, setRows] = useState([]);
  const [tarifasMatricula, setTarifasMatricula] = useState([]);
  const [licenciaFiltro, setLicenciaFiltro] = useState("all");
  const [open, setOpen] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(emptyForm);

  const [imagenFile, setImagenFile] = useState(null);

  const [previewImage, setPreviewImage] = useState("");

  const [eliminarImagenActual, setEliminarImagenActual] = useState(false);
  const [notification, setNotification] = useState({
    open: false,
    message: "",
    severity: "success",
  });

  const [confirmDialog, setConfirmDialog] = useState({
    open: false,
    action: null,
    promocionId: null,
    nombrePromocion: "",
    title: "",
    message: "",
  });

  const loadPromociones = async () => {
    try {
      const data = await promocionesService.getAll({
        licencia: licenciaFiltro === "all" ? undefined : licenciaFiltro,
      });
      setRows(data);
    } catch (error) {
      console.error(error);

      setNotification({
        open: true,
        message: "No se pudieron cargar las promociones",
        severity: "error",
      });
    }
  };

  const loadTarifasMatricula = async () => {
    try {
      const data = await tarifasMatriculaService.getAll();
      setTarifasMatricula(data);
    } catch (error) {
      console.error(error);
    }
  };

  useEffect(() => {
    loadPromociones();
  }, [licenciaFiltro]);

  useEffect(() => {
    loadTarifasMatricula();
  }, []);

  const licenciaSeleccionada = form.licenciasAplicables?.[0] || "";

  const tarifaLicenciaSeleccionada = useMemo(
    () =>
      tarifasMatricula.find(
        (tarifa) => tarifa.licencia === licenciaSeleccionada,
      ),
    [tarifasMatricula, licenciaSeleccionada],
  );

  const precioOriginalDesdeTarifa = Boolean(tarifaLicenciaSeleccionada);

  useEffect(() => {
    if (!open || editingId || !tarifaLicenciaSeleccionada) {
      return;
    }

    const precioTarifa = String(tarifaLicenciaSeleccionada.precio ?? "");

    setForm((prev) => {
      if (prev.precioOriginal === precioTarifa) {
        return prev;
      }

      return {
        ...prev,
        precioOriginal: precioTarifa,
      };
    });
  }, [open, editingId, tarifaLicenciaSeleccionada]);

  const filteredRows = useMemo(() => rows, [rows]);

  const resetForm = () => {
    setForm(emptyForm);

    setEditingId(null);

    setImagenFile(null);

    setPreviewImage("");

    setEliminarImagenActual(false);
  };

  const buildImageSrc = (ruta) => {
    if (!ruta) {
      return "";
    }

    if (ruta.startsWith("http://") || ruta.startsWith("https://")) {
      return ruta;
    }

    return ruta;
  };

  const handleOpenCreate = () => {
    resetForm();
    setOpen(true);
  };

  const handleLicenciasChange = (event) => {
    const licenciaBase = event.target.value;

    const tarifaSeleccionada = tarifasMatricula.find(
      (tarifa) => tarifa.licencia === licenciaBase,
    );

    setForm((prev) => ({
      ...prev,
      licenciasAplicables: licenciaBase ? [licenciaBase] : [],
      precioOriginal:
        tarifaSeleccionada?.precio !== undefined &&
        tarifaSeleccionada?.precio !== null
          ? String(tarifaSeleccionada.precio)
          : prev.precioOriginal,
    }));
  };

  const handleFileChange = (event) => {
    const file = event.target.files?.[0];

    if (!file) {
      return;
    }

    if (!TIPOS_IMAGEN_PERMITIDOS.includes(file.type)) {
      setNotification({
        open: true,
        message: "Formato no permitido. Usa PNG, JPG/JPEG o WEBP.",
        severity: "error",
      });

      event.target.value = "";
      return;
    }

    if (file.size > TAMANO_MAXIMO_IMAGEN) {
      setNotification({
        open: true,
        message: "La imagen supera 5 MB.",
        severity: "error",
      });

      event.target.value = "";
      return;
    }

    setImagenFile(file);

    setPreviewImage(URL.createObjectURL(file));

    setEliminarImagenActual(false);
  };

  const handleToggleEliminarImagen = () => {
    if (eliminarImagenActual) {
      setEliminarImagenActual(false);

      setPreviewImage(buildImageSrc(form.imagenRuta));

      return;
    }

    setImagenFile(null);

    setPreviewImage("");

    setForm((prev) => ({
      ...prev,
      imagenRuta: "",
    }));

    setEliminarImagenActual(true);
  };

  const handleEdit = (row) => {
    setEditingId(row.id);
    setForm({
      nombre: row.nombre || "",
      descripcion: row.descripcion || "",
      precioOriginal: row.precioOriginal || "",
      precioPromocional: row.precioPromocional || "",
      licenciasAplicables:
        row.licenciasAplicables && row.licenciasAplicables.length > 0
          ? [row.licenciasAplicables[0]]
          : ["B"],
      fechaInicio: row.fechaInicio ? row.fechaInicio.split("T")[0] : "",

      fechaFin: row.fechaFin ? row.fechaFin.split("T")[0] : "",
      activa: Boolean(row.activa),
      imagenRuta: row.imagenRuta || "",
      requiereCarnetEstudiante: Boolean(row.requiereCarnetEstudiante),
      requiereFidelidad: Boolean(row.requiereFidelidad),
      incluyePagoExamenGratis: Boolean(row.incluyePagoExamenGratis),
      incluirClasesGratis: Number(row.clasesGratisIncluidas || 0) > 0,
      clasesGratisIncluidas:
        row.clasesGratisIncluidas === null ||
        row.clasesGratisIncluidas === undefined
          ? ""
          : String(row.clasesGratisIncluidas),
      licenciaClasesGratis:
        row.licenciaClasesGratis ||
        (row.licenciasAplicables && row.licenciasAplicables[0]) ||
        "B",
      edadMinima:
        row.edadMinima === null || row.edadMinima === undefined
          ? ""
          : row.edadMinima,
      edadMaxima:
        row.edadMaxima === null || row.edadMaxima === undefined
          ? ""
          : row.edadMaxima,
    });
    setImagenFile(null);

    setEliminarImagenActual(false);

    setPreviewImage(buildImageSrc(row.imagenRuta));
    setOpen(true);
  };

  const handleDelete = (row) => {
    setConfirmDialog({
      open: true,
      action: "delete",
      promocionId: row.id,
      nombrePromocion: row.nombre,
      title: "Confirmar eliminación",
      message: `Vas a eliminar definitivamente la promoción "${row.nombre}" de Autoescuela Eguzkilore. Toda la información asociada será eliminada de forma permanente. Esta acción no podrá deshacerse. ¿Deseas continuar?`,
    });
  };

  const handleToggleActivo = (row) => {
    setConfirmDialog({
      open: true,
      action: row.activa ? "deactivate" : "activate",
      promocionId: row.id,
      nombrePromocion: row.nombre,
      title: row.activa ? "Confirmar desactivación" : "Confirmar activación",
      message: row.activa
        ? `Vas a desactivar la promoción "${row.nombre}" en Autoescuela Eguzkilore. No podrá utilizarse hasta su reactivación. ¿Deseas continuar?`
        : `Vas a reactivar la promoción "${row.nombre}" en Autoescuela Eguzkilore. Volverá a estar disponible de inmediato. ¿Deseas continuar?`,
    });
  };

  const closeConfirmDialog = () => {
    setConfirmDialog({
      open: false,
      action: null,
      promocionId: null,
      nombrePromocion: "",
      title: "",
      message: "",
    });
  };

  const handleConfirmAction = async () => {
    if (!confirmDialog.promocionId || !confirmDialog.action) {
      closeConfirmDialog();
      return;
    }

    try {
      if (confirmDialog.action === "delete") {
        await promocionesService.delete(confirmDialog.promocionId);
      }

      if (confirmDialog.action === "deactivate") {
        await promocionesService.deactivate(confirmDialog.promocionId);
      }

      if (confirmDialog.action === "activate") {
        await promocionesService.activate(confirmDialog.promocionId);
      }

      await loadPromociones();

      setNotification({
        open: true,
        message:
          confirmDialog.action === "delete"
            ? "Promoción eliminada correctamente"
            : confirmDialog.action === "deactivate"
              ? "Promoción desactivada correctamente"
              : "Promoción activada correctamente",
        severity: "success",
      });
    } catch (error) {
      console.error(error);

      setNotification({
        open: true,
        message: error.response?.data?.message || "Error procesando la acción",
        severity: "error",
      });
    } finally {
      closeConfirmDialog();
    }
  };

  const handleSave = async () => {
    try {
      if (
        form.incluirClasesGratis &&
        (!Number.isInteger(Number(form.clasesGratisIncluidas)) ||
          Number(form.clasesGratisIncluidas) <= 0)
      ) {
        setNotification({
          open: true,
          message:
            "Si activas clases gratis, debes indicar un número entero mayor que 0",
          severity: "error",
        });
        return;
      }

      const payload = {
        ...form,
        precioOriginal: Number(form.precioOriginal),
        precioPromocional: Number(form.precioPromocional),
        incluyePagoExamenGratis: Boolean(form.incluyePagoExamenGratis),
        incluirClasesGratis: Boolean(form.incluirClasesGratis),
        clasesGratisIncluidas: form.incluirClasesGratis
          ? Number(form.clasesGratisIncluidas)
          : 0,
        licenciaClasesGratis: form.incluirClasesGratis
          ? form.licenciaClasesGratis || licenciaSeleccionada || "B"
          : null,
        edadMinima:
          form.edadMinima === "" || form.edadMinima === null
            ? null
            : Number(form.edadMinima),
        edadMaxima:
          form.edadMaxima === "" || form.edadMaxima === null
            ? null
            : Number(form.edadMaxima),
      };

      if (editingId) {
        await promocionesService.update(
          editingId,
          payload,
          imagenFile,
          eliminarImagenActual,
        );
      } else {
        await promocionesService.create(payload, imagenFile);
      }

      await loadPromociones();
      setOpen(false);
      resetForm();
      setNotification({
        open: true,
        message: editingId
          ? "Promoción actualizada correctamente"
          : "Promoción creada correctamente",
        severity: "success",
      });
    } catch (error) {
      console.error(error);
      setNotification({
        open: true,
        message: error.response?.data?.message || "Error guardando promoción",
        severity: "error",
      });
    }
  };

  const columns = [
    {
      field: "nombre",
      headerName: "Nombre",
      flex: 1.5,
    },
    {
      field: "reglas",
      headerName: "Reglas",
      flex: 1.8,
      valueGetter: (_, row) => {
        const reglas = [];

        if (row.requiereCarnetEstudiante) {
          reglas.push("Carnet estudiante");
        }

        if (row.requiereFidelidad) {
          reglas.push("Fidelidad");
        }

        if (row.incluyePagoExamenGratis) {
          reglas.push("Pago examen gratis");
        }

        if (Number(row.clasesGratisIncluidas || 0) > 0) {
          reglas.push(
            `${row.clasesGratisIncluidas} clases gratis (${row.licenciaClasesGratis || "-"})`,
          );
        }

        if (row.edadMinima !== null && row.edadMinima !== undefined) {
          reglas.push(`Edad mínima ${row.edadMinima}`);
        }

        if (row.edadMaxima !== null && row.edadMaxima !== undefined) {
          reglas.push(`Edad máxima ${row.edadMaxima}`);
        }

        return reglas.length > 0 ? reglas.join(" | ") : "Público general";
      },
    },

    {
      field: "precioOriginal",
      headerName: "Precio Original",
      flex: 0.8,
      valueFormatter: (value) => `${value} €`,
    },

    {
      field: "precioPromocional",
      headerName: "Precio Oferta",
      flex: 0.8,
      valueFormatter: (value) => `${value} €`,
    },

    {
      field: "descuento",
      headerName: "Descuento",
      flex: 0.8,

      valueGetter: (_, row) => {
        const original = Number(row.precioOriginal);
        const promo = Number(row.precioPromocional);

        if (!original || !promo) {
          return "0%";
        }

        const descuento = ((original - promo) / original) * 100;

        return `${Math.round(descuento)}%`;
      },
    },

    {
      field: "licenciasAplicables",
      headerName: "Licencias",
      flex: 1.3,

      renderCell: (params) => (
        <Box
          sx={{
            display: "flex",
            flexDirection: "column",
            justifyContent: "flex-end", // Empuja los chips al fondo de la celda
            height: "100%", // Usa todo el alto disponible de la fila
            pb: 1.5, // Padding bottom opcional (8px) para separar del borde
          }}
        >
          <LicenseChipList values={params.row.licenciasAplicables} />
        </Box>
      ),
    },

    {
      field: "vigencia",
      headerName: "Vigencia",
      flex: 1.3,

      valueGetter: (_, row) => {
        const inicio = row.fechaInicio
          ? new Date(row.fechaInicio).toLocaleDateString("es-ES")
          : "-";

        const fin = row.fechaFin
          ? new Date(row.fechaFin).toLocaleDateString("es-ES")
          : "-";

        return `${inicio} - ${fin}`;
      },
    },

    {
      field: "activa",
      headerName: "Estado",
      flex: 0.7,
      renderCell: (params) => (
        <Chip
          size="small"
          label={params.value ? "Activa" : "Inactiva"}
          sx={{
            // Fondo según la opción
            backgroundColor: params.value ? "#e8f5e9" : "#ffebee",

            // Color de la letra según la opción
            color: params.value ? "#2e7d32" : "#c62828",

            // Borde según la opción (grosor, tipo y color)
            border: `1px solid ${params.value ? "#4caf50" : "#ef5350"}`,

            // Opcional: Asegura que si hay iconos o estados hover no rompan tus colores
            "& .MuiChip-label": {
              fontWeight: "medium",
            },
          }}
        />
      ),
    },

    {
      field: "acciones",
      headerName: "Acciones",
      width: 180,
      sortable: false,

      renderCell: (params) => (
        <Box
          sx={{
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            gap: 0.5,
            width: "100%",
          }}
        >
          <Tooltip title="Editar" arrow>
            <IconButton color="primary" onClick={() => handleEdit(params.row)}>
              <EditIcon />
            </IconButton>
          </Tooltip>

          <Tooltip title={params.row.activa ? "Desactivar" : "Activar"} arrow>
            <IconButton
              color={params.row.activa ? "warning" : "success"}
              onClick={() => handleToggleActivo(params.row)}
            >
              {params.row.activa ? <ToggleOffIcon /> : <ToggleOnIcon />}
            </IconButton>
          </Tooltip>

          <Tooltip title="Eliminar" arrow>
            <IconButton color="error" onClick={() => handleDelete(params.row)}>
              <DeleteIcon />
            </IconButton>
          </Tooltip>
        </Box>
      ),
    },
  ];

  return (
    <Box>
      <Box
        sx={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          mb: 2,
        }}
      >
        <Box>
          <Typography variant="h4">Promociones</Typography>

          <Typography color="text.secondary">
            Gestiona los descuentos temporales, campañas especiales y ofertas
            vigentes de la autoescuela.
          </Typography>
        </Box>
        <Button
          variant="contained"
          startIcon={<AddIcon />}
          onClick={handleOpenCreate}
        >
          Nueva promoción
        </Button>
      </Box>

      <Box sx={{ mb: 2 }}>
        <FormControl size="small" sx={{ minWidth: 240 }}>
          <InputLabel>Filtrar por licencia</InputLabel>
          <Select
            label="Filtrar por licencia"
            value={licenciaFiltro}
            onChange={(event) => setLicenciaFiltro(event.target.value)}
          >
            <MenuItem value="all">Todas</MenuItem>
            {LICENCIAS.map((licencia) => (
              <MenuItem key={licencia} value={licencia}>
                Permiso {licencia}
              </MenuItem>
            ))}
          </Select>
        </FormControl>
      </Box>

      <Box sx={{ height: 700 }}>
        <DataGrid
          rows={filteredRows}
          columns={columns}
          getRowId={(row) => row.id}
          disableRowSelectionOnClick
          pageSizeOptions={[10, 25, 50]}
          initialState={{
            pagination: { paginationModel: { pageSize: 10, page: 0 } },
            sorting: { sortModel: [{ field: "nombre", sort: "asc" }] },
          }}
        />
      </Box>

      <Dialog
        open={open}
        onClose={() => setOpen(false)}
        fullWidth
        maxWidth="lg"
      >
        <DialogTitle>
          {editingId ? "Editar promoción" : "Nueva promoción"}
        </DialogTitle>
        <DialogContent sx={{ pt: 1, display: "grid", gap: 2 }}>
          <Box
            sx={{
              display: "grid",
              gridTemplateColumns: { xs: "1fr", md: "1fr 1.5fr" },
              gap: 3,
              alignItems: "start",
              mt: 1,
            }}
          >
            <Box sx={{ display: "grid", gap: 2 }}>
              <TextField
                label="Nombre"
                fullWidth
                value={form.nombre}
                onChange={(event) =>
                  setForm((prev) => ({ ...prev, nombre: event.target.value }))
                }
              />
              <TextField
                label="Descripción"
                fullWidth
                multiline
                minRows={3}
                value={form.descripcion}
                onChange={(event) =>
                  setForm((prev) => ({
                    ...prev,
                    descripcion: event.target.value,
                  }))
                }
              />
              <FormControl fullWidth>
                <InputLabel>Licencias</InputLabel>

                <Select
                  label="Licencias"
                  value={licenciaSeleccionada}
                  onChange={handleLicenciasChange}
                >
                  {LICENCIAS.map((licencia) => (
                    <MenuItem key={licencia} value={licencia}>
                      {licencia}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
              <TextField
                label="Precio Original"
                type="number"
                fullWidth
                value={form.precioOriginal}
                InputProps={{
                  readOnly: precioOriginalDesdeTarifa,
                }}
                onChange={(event) =>
                  setForm((prev) => ({
                    ...prev,
                    precioOriginal: event.target.value,
                  }))
                }
              />
              <TextField
                label="Precio Promocional"
                type="number"
                fullWidth
                value={form.precioPromocional}
                onChange={(event) =>
                  setForm((prev) => ({
                    ...prev,
                    precioPromocional: event.target.value,
                  }))
                }
              />
              <Box
                sx={{
                  display: "grid",
                  gridTemplateColumns: "1fr 1fr",
                  gap: 2,
                }}
              >
                <TextField
                  label="Fecha Inicio"
                  type="date"
                  fullWidth
                  value={form.fechaInicio}
                  onChange={(event) =>
                    setForm((prev) => ({
                      ...prev,
                      fechaInicio: event.target.value,
                    }))
                  }
                  sx={{
                    "& input::-webkit-datetime-edit": {
                      color: form.fechaInicio ? "inherit" : "transparent",
                    },
                  }}
                />

                <TextField
                  label="Fecha Fin"
                  type="date"
                  fullWidth
                  value={form.fechaFin}
                  onChange={(event) =>
                    setForm((prev) => ({
                      ...prev,
                      fechaFin: event.target.value,
                    }))
                  }
                  sx={{
                    "& input::-webkit-datetime-edit": {
                      color: form.fechaFin ? "inherit" : "transparent",
                    },
                  }}
                />
              </Box>

              <FormControlLabel
                control={
                  <Checkbox
                    checked={Boolean(form.requiereCarnetEstudiante)}
                    onChange={(event) =>
                      setForm((prev) => ({
                        ...prev,
                        requiereCarnetEstudiante: event.target.checked,
                      }))
                    }
                  />
                }
                label="Requiere carnet de estudiante"
              />

              <FormControlLabel
                control={
                  <Checkbox
                    checked={Boolean(form.requiereFidelidad)}
                    onChange={(event) =>
                      setForm((prev) => ({
                        ...prev,
                        requiereFidelidad: event.target.checked,
                      }))
                    }
                  />
                }
                label="Requiere fidelidad (licencia aprobada previa)"
              />

              <FormControlLabel
                control={
                  <Checkbox
                    checked={Boolean(form.incluyePagoExamenGratis)}
                    onChange={(event) =>
                      setForm((prev) => ({
                        ...prev,
                        incluyePagoExamenGratis: event.target.checked,
                      }))
                    }
                  />
                }
                label="Incluye pago gratuito de examen (tipo POR_EXAMEN)"
              />

              <FormControlLabel
                control={
                  <Checkbox
                    checked={Boolean(form.incluirClasesGratis)}
                    onChange={(event) =>
                      setForm((prev) => ({
                        ...prev,
                        incluirClasesGratis: event.target.checked,
                        clasesGratisIncluidas: event.target.checked
                          ? prev.clasesGratisIncluidas
                          : "",
                        licenciaClasesGratis: event.target.checked
                          ? prev.licenciaClasesGratis ||
                            licenciaSeleccionada ||
                            "B"
                          : prev.licenciaClasesGratis,
                      }))
                    }
                  />
                }
                label="Incluir clases prácticas gratis"
              />

              {form.incluirClasesGratis ? (
                <Box
                  sx={{
                    display: "grid",
                    gridTemplateColumns: "1fr 1fr",
                    gap: 2,
                  }}
                >
                  <TextField
                    label="Número de clases gratis"
                    type="number"
                    fullWidth
                    value={form.clasesGratisIncluidas}
                    onChange={(event) =>
                      setForm((prev) => ({
                        ...prev,
                        clasesGratisIncluidas: event.target.value,
                      }))
                    }
                    inputProps={{ min: 1, step: 1 }}
                  />

                  <FormControl fullWidth>
                    <InputLabel>Licencia clases gratis</InputLabel>
                    <Select
                      label="Licencia clases gratis"
                      value={
                        form.licenciaClasesGratis || licenciaSeleccionada || "B"
                      }
                      onChange={(event) =>
                        setForm((prev) => ({
                          ...prev,
                          licenciaClasesGratis: event.target.value,
                        }))
                      }
                    >
                      {LICENCIAS.map((licencia) => (
                        <MenuItem key={licencia} value={licencia}>
                          {licencia}
                        </MenuItem>
                      ))}
                    </Select>
                  </FormControl>
                </Box>
              ) : null}

              <Box
                sx={{
                  display: "grid",
                  gridTemplateColumns: "1fr 1fr",
                  gap: 2,
                }}
              >
                <TextField
                  label="Edad mínima"
                  type="number"
                  fullWidth
                  value={form.edadMinima}
                  onChange={(event) =>
                    setForm((prev) => ({
                      ...prev,
                      edadMinima: event.target.value,
                    }))
                  }
                />

                <TextField
                  label="Edad máxima"
                  type="number"
                  fullWidth
                  value={form.edadMaxima}
                  onChange={(event) =>
                    setForm((prev) => ({
                      ...prev,
                      edadMaxima: event.target.value,
                    }))
                  }
                />
              </Box>
            </Box>
            <Box
              sx={{
                minHeight: 280,
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                justifyContent: "center",
                borderRadius: 2,
                backgroundColor: "#f6f6f6",
                p: 2,
                gap: 2,
              }}
            >
              {previewImage && !eliminarImagenActual ? (
                <img
                  src={previewImage}
                  alt="Vista previa promoción"
                  style={{
                    width: "90%",
                    maxHeight: "320px",
                    objectFit: "contain",
                    borderRadius: "8px",
                  }}
                />
              ) : (
                <Typography color="text.secondary">
                  No hay imagen seleccionada
                </Typography>
              )}

              <Button component="label" variant="outlined">
                {previewImage ? "Cambiar imagen" : "Añadir imagen"}

                <input
                  hidden
                  type="file"
                  accept=".png,.jpg,.jpeg,.webp"
                  onChange={handleFileChange}
                />
              </Button>

              {(previewImage || form.imagenRuta) && (
                <Button
                  color="error"
                  variant="contained"
                  onClick={handleToggleEliminarImagen}
                >
                  {eliminarImagenActual ? "Deshacer" : "Eliminar imagen"}
                </Button>
              )}
              <Typography variant="caption">
                Formatos: PNG, JPG/JPEG, WEBP. Tamaño máximo: 5 MB.
              </Typography>
            </Box>
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpen(false)}>Cancelar</Button>
          <Button variant="contained" onClick={handleSave}>
            Guardar
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog
        open={confirmDialog.open}
        onClose={closeConfirmDialog}
        fullWidth
        maxWidth="xs"
      >
        <DialogTitle>{confirmDialog.title}</DialogTitle>

        <DialogContent>
          <DialogContentText>{confirmDialog.message}</DialogContentText>
        </DialogContent>

        <DialogActions>
          <Button onClick={closeConfirmDialog}>Cancelar</Button>

          <Button
            variant="contained"
            color={confirmDialog.action === "activate" ? "success" : "error"}
            onClick={handleConfirmAction}
          >
            Confirmar
          </Button>
        </DialogActions>
      </Dialog>

      <Snackbar
        open={notification.open}
        autoHideDuration={3500}
        onClose={() => setNotification((prev) => ({ ...prev, open: false }))}
      >
        <Alert
          severity={notification.severity}
          variant="filled"
          onClose={() => setNotification((prev) => ({ ...prev, open: false }))}
        >
          {notification.message}
        </Alert>
      </Snackbar>
    </Box>
  );
}

import { useEffect, useMemo, useState } from "react";
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  Divider,
  Grid,
  MenuItem,
  Paper,
  Select,
  Stack,
  Typography,
  Link,
  Dialog,
  DialogActions,
  DialogContent,
  DialogContentText,
  DialogTitle,
} from "@mui/material";
import EventBusyIcon from "@mui/icons-material/EventBusy";
import EventAvailableIcon from "@mui/icons-material/EventAvailable";
import NavigateBeforeIcon from "@mui/icons-material/NavigateBefore";
import NavigateNextIcon from "@mui/icons-material/NavigateNext";
import CreditCardIcon from "@mui/icons-material/CreditCard";
import PersonIcon from "@mui/icons-material/Person";
import DirectionsCarIcon from "@mui/icons-material/DirectionsCar";

import { clasesPracticasPortalService } from "../../services/clasesPracticasPortalService";
import { useNavigate } from "react-router-dom";
import { LicenseChip } from "../../components/common/LicenseChip";
import { PracticalClassTypeChip } from "../../components/common/PracticalClassTypeChip";
import {
  addDaysToDateKey,
  dateFromKeyAtNoon,
  extractDateKey,
  formatDateValue,
  getWeekDayIdFromValue,
} from "../../utils/calendarDate";

const DAYS = [
  "Lunes",
  "Martes",
  "Miercoles",
  "Jueves",
  "Viernes",
  "Sabado",
  "Domingo",
];

const DAY_NAME_BY_ID = {
  1: "Lunes",
  2: "Martes",
  3: "Miercoles",
  4: "Jueves",
  5: "Viernes",
  6: "Sabado",
  7: "Domingo",
};

const STUDENT_AGENDA_PALETTE = [
  {
    bg: "#e9f2ff",
    border: "#9cc6ff",
    title: "#1e3a8a",
  },
  {
    bg: "#fff3e6",
    border: "#ffd39f",
    title: "#92400e",
  },
  {
    bg: "#e8f9f1",
    border: "#98e4be",
    title: "#166534",
  },
  {
    bg: "#f1ecff",
    border: "#c5b2ff",
    title: "#5b21b6",
  },
  {
    bg: "#e8f7fb",
    border: "#93dff0",
    title: "#0f4f66",
  },
];

const COMPLETED_CLASS_STATES = [
  "COMPLETADA",
  "REALIZADA",
  "FINALIZADA",
  "REGISTRADA",
];

const formatDateOnly = (value) => {
  const text = formatDateValue(value, {
    day: "numeric",
    month: "numeric",
    year: "numeric",
  });

  return text || "-";
};

const formatDate = (value) => {
  if (!value) return "-";
  return new Date(value).toLocaleString("es-ES", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
};

const formatHour = (value) => {
  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return "--:--";
  }

  return date.toLocaleTimeString("es-ES", {
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  });
};

const formatHourRange = (value, duracion = 45) => {
  const startDate = new Date(value);

  if (Number.isNaN(startDate.getTime())) {
    return "--:-- - --:--";
  }

  const endDate = new Date(startDate);
  endDate.setMinutes(endDate.getMinutes() + (Number(duracion) || 45));

  return `${formatHour(startDate)} - ${formatHour(endDate)}`;
};

const getAgendaStatusChipConfig = (status) => {
  const normalized = String(status || "").toUpperCase();

  if (normalized === "REGISTRADA") {
    return { label: "REGISTRADA", color: "success" };
  }

  if (normalized === "PENDIENTE_REGISTRO") {
    return { label: "PENDIENTE REGISTRO", color: "warning" };
  }

  if (normalized === "EN_CURSO") {
    return { label: "EN CURSO", color: "info" };
  }

  if (normalized === "COMPLETADA") {
    return { label: "COMPLETADA", color: "success" };
  }

  if (normalized === "CONFIRMADA") {
    return { label: "CONFIRMADA", color: "primary" };
  }

  if (normalized === "PROGRAMADA") {
    return { label: "PROGRAMADA", color: "default" };
  }

  return { label: normalized || "SIN ESTADO", color: "default" };
};

const getAgendaItemTypeChip = (type) => {
  if (type === "REALIZADA") {
    return { label: "EFECTUADA", color: "success" };
  }

  if (type === "SOLICITUD") {
    return { label: "SOLICITUD", color: "warning" };
  }

  return { label: "PROXIMA", color: "info" };
};

const getColorByAgendaItem = (item) => {
  const seed = String(item?.profesor?.id || item?.profesor?.nombre || item?.id);
  let hash = 0;

  for (let i = 0; i < seed.length; i += 1) {
    hash = (hash << 5) - hash + seed.charCodeAt(i);
    hash |= 0;
  }

  const index = Math.abs(hash) % STUDENT_AGENDA_PALETTE.length;
  return STUDENT_AGENDA_PALETTE[index];
};

const isCompletedWithRoadmap = (item) => {
  const status = String(item?.estado || "").toUpperCase();
  return COMPLETED_CLASS_STATES.includes(status) && Boolean(item?.hojaRutaId);
};

const isCompletedWithoutRoadmap = (item) => {
  const status = String(item?.estado || "").toUpperCase();
  return COMPLETED_CLASS_STATES.includes(status) && !item?.hojaRutaId;
};

const combineDateAndHour = (weekStart, dayIndex, hourText) => {
  const weekStartKey = extractDateKey(weekStart);
  const dayKey = addDaysToDateKey(weekStartKey, dayIndex);
  const date = dateFromKeyAtNoon(dayKey);

  if (!date) {
    return null;
  }

  const [hh, mm] = hourText.split(":").map(Number);
  date.setHours(hh, mm, 0, 0);

  return date;
};

const canStudentCancelClass = (clase) => {
  const status = String(clase?.estado || "").toUpperCase();

  if (!["PROGRAMADA", "CONFIRMADA"].includes(status)) {
    return false;
  }

  const classDate = new Date(clase?.fecha);

  if (Number.isNaN(classDate.getTime())) {
    return false;
  }

  const diffMs = classDate.getTime() - Date.now();
  return diffMs > 24 * 60 * 60 * 1000;
};

const hasPaidIndividualClass = (clase) => {
  const metodoPago = String(clase?.metodoPago || "").toUpperCase();
  const estadoPago = String(clase?.pagoClase?.estado || "").toUpperCase();

  return metodoPago === "INDIVIDUAL" && estadoPago === "PAGADO";
};

const isLessThan24h = (clase) => {
  const classDate = new Date(clase?.fecha);

  if (Number.isNaN(classDate.getTime())) {
    return false;
  }

  return classDate.getTime() - Date.now() <= 24 * 60 * 60 * 1000;
};

const CLASS_TYPE_LABELS = {
  CIRCULACION: "Circulacion",
  PISTA: "Pista (Circuito)",
};

export default function ReservarClase() {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [weekOffset, setWeekOffset] = useState(0);
  const [context, setContext] = useState(null);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  const [step, setStep] = useState("seleccion");
  const [selectedDay, setSelectedDay] = useState(0);
  const [selectedHour, setSelectedHour] = useState("");
  const [metodoPago, setMetodoPago] = useState("INDIVIDUAL");
  const [selectedBonoId, setSelectedBonoId] = useState("");
  const [selectedClassType, setSelectedClassType] = useState("CIRCULACION");
  const [penaltyDialogOpen, setPenaltyDialogOpen] = useState(false);
  const [penaltyTargetClassId, setPenaltyTargetClassId] = useState(null);

  const loadContext = async (offset = weekOffset) => {
    setLoading(true);
    setError("");

    try {
      const data =
        await clasesPracticasPortalService.getStudentBookingContext(offset);
      setContext(data);
      const availableClassTypes = Array.isArray(
        data?.elegibilidad?.tiposClaseDisponibles,
      )
        ? data.elegibilidad.tiposClaseDisponibles
        : ["CIRCULACION"];
      setSelectedClassType(availableClassTypes[0] || "CIRCULACION");

      const bonos = data?.pago?.bonosDisponibles || [];
      if (bonos.length > 0) {
        setMetodoPago("BONO");
        setSelectedBonoId(bonos[0].id);
      } else {
        setMetodoPago("INDIVIDUAL");
        setSelectedBonoId("");
      }

      const firstDay = (data?.calendarioSemana?.dias || []).findIndex(
        (day) => day.disponibles > 0,
      );
      const safeDay = firstDay >= 0 ? firstDay : 0;
      setSelectedDay(safeDay);

      const firstHour =
        data?.calendarioSemana?.dias?.[safeDay]?.slots?.find(
          (slot) => slot.disponible,
        )?.hora || "";
      setSelectedHour(firstHour);
    } catch (loadError) {
      setError(
        loadError.response?.data?.message ||
          "No se pudo cargar el panel de solicitud de clases",
      );
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadContext(weekOffset);
  }, [weekOffset]);

  const days = context?.calendarioSemana?.dias || [];
  const currentDay = days[selectedDay] || null;

  const agendaWeekDays = useMemo(() => {
    const weekStartKey = extractDateKey(context?.calendarioSemana?.inicio);

    if (!weekStartKey) {
      return Object.entries(DAY_NAME_BY_ID).map(([id, label]) => ({
        id: Number(id),
        label,
        date: null,
      }));
    }

    return Object.entries(DAY_NAME_BY_ID).map(([id, label]) => {
      const dayOffset = Number(id) - 1;
      const date = dateFromKeyAtNoon(addDaysToDateKey(weekStartKey, dayOffset));

      return {
        id: Number(id),
        label,
        date,
      };
    });
  }, [context?.calendarioSemana?.inicio]);

  const agendaByDay = useMemo(() => {
    const map = new Map();
    agendaWeekDays.forEach((day) => map.set(day.id, []));

    const weekStartKey = extractDateKey(context?.calendarioSemana?.inicio);
    const weekEndKey = extractDateKey(context?.calendarioSemana?.fin);

    const isInsideVisibleWeek = (value) => {
      const classDateKey = extractDateKey(value);

      if (!classDateKey || !weekStartKey || !weekEndKey) {
        return false;
      }

      return classDateKey >= weekStartKey && classDateKey <= weekEndKey;
    };

    const classesMap = new Map();
    const now = new Date();

    (context?.solicitudesPendientes || []).forEach((item) => {
      if (!isInsideVisibleWeek(item?.fecha)) {
        return;
      }

      classesMap.set(item.id, {
        ...item,
        agendaType: "SOLICITUD",
      });
    });

    (context?.proximasClases || []).forEach((item) => {
      if (!isInsideVisibleWeek(item?.fecha)) {
        return;
      }

      const classDate = new Date(item.fecha);
      classesMap.set(item.id, {
        ...item,
        agendaType: classDate < now ? "REALIZADA" : "PROXIMA",
      });
    });

    for (const item of classesMap.values()) {
      const classDate = new Date(item.fecha);

      if (Number.isNaN(classDate.getTime())) {
        continue;
      }

      const dayId = getWeekDayIdFromValue(classDate);

      if (!map.has(dayId)) {
        continue;
      }

      map.get(dayId).push(item);
    }

    for (const day of agendaWeekDays) {
      const sorted = (map.get(day.id) || []).sort(
        (a, b) => new Date(a.fecha).getTime() - new Date(b.fecha).getTime(),
      );
      map.set(day.id, sorted);
    }

    return map;
  }, [agendaWeekDays, context?.proximasClases, context?.solicitudesPendientes]);

  const selectedDate = useMemo(() => {
    if (!context?.calendarioSemana?.inicio || !selectedHour) {
      return null;
    }

    return combineDateAndHour(
      context.calendarioSemana.inicio,
      selectedDay,
      selectedHour,
    );
  }, [context?.calendarioSemana?.inicio, selectedDay, selectedHour]);

  const handleNextStep = () => {
    if (!selectedHour || !selectedDate) {
      setError("Selecciona primero una fecha y una hora disponible");
      return;
    }

    setError("");
    setStep("resumen");
  };

  const handleSubmitRequest = async () => {
    if (!selectedDate) {
      setError("No hay fecha seleccionada");
      return;
    }

    setSaving(true);
    setError("");

    try {
      await clasesPracticasPortalService.createStudentRequest({
        fecha: selectedDate.toISOString(),
        metodoPago,
        compraBonoId: metodoPago === "BONO" ? selectedBonoId : null,
        tipoClasePractica: selectedClassType,
      });

      setSuccess("Solicitud enviada correctamente al profesor");
      setStep("seleccion");
      await loadContext(weekOffset);
    } catch (requestError) {
      setError(
        requestError.response?.data?.message || "No se pudo solicitar la clase",
      );
    } finally {
      setSaving(false);
    }
  };

  const cancelarSolicitud = async (id, options = {}) => {
    try {
      await clasesPracticasPortalService.cancelStudentRequest(id, options);
      setSuccess("Solicitud cancelada correctamente");
      await loadContext(weekOffset);
    } catch (cancelError) {
      setError(
        cancelError.response?.data?.message ||
          "No se pudo cancelar la solicitud",
      );
    }
  };

  const handleAskCancel = (item) => {
    if (hasPaidIndividualClass(item) && isLessThan24h(item)) {
      setPenaltyTargetClassId(item.id);
      setPenaltyDialogOpen(true);
      return;
    }

    cancelarSolicitud(item.id);
  };

  const handleConfirmPenaltyCancel = async () => {
    if (!penaltyTargetClassId) {
      setPenaltyDialogOpen(false);
      return;
    }

    setPenaltyDialogOpen(false);
    await cancelarSolicitud(penaltyTargetClassId, {
      confirmPenalty: true,
    });
    setPenaltyTargetClassId(null);
  };

  if (loading) {
    return <Typography>Cargando solicitud de clases...</Typography>;
  }

  const elegibilidad = context?.elegibilidad;
  const bloqueos = Array.isArray(elegibilidad?.bloqueos)
    ? elegibilidad.bloqueos.filter(Boolean)
    : [];
  const mensajeBloqueoPrincipal =
    bloqueos[0] ||
    "Para solicitar clase práctica necesitas tener el examen teórico en estado APTO.";

  return (
    <Box sx={{ display: "flex", flexDirection: "column", gap: 2 }}>
      <Box>
        <Typography variant="h4" fontWeight={800}>
          Solicitud de clase práctica
        </Typography>
        <Typography color="text.secondary">
          Reserva una franja en la agenda de tu profesor y envía la solicitud
          para confirmación.
        </Typography>
      </Box>

      {error ? <Alert severity="error">{error}</Alert> : null}
      {success ? <Alert severity="success">{success}</Alert> : null}

      {!elegibilidad?.permitido ? (
        <Card sx={{ border: "2px solid #f59e0b", backgroundColor: "#fff7ed" }}>
          <CardContent>
            <Stack direction="row" spacing={1.5} alignItems="center">
              <EventBusyIcon color="warning" />
              <Typography variant="h6" fontWeight={800}>
                Aún no puedes reservar clases prácticas
              </Typography>
            </Stack>
            <Typography sx={{ mt: 1 }}>{mensajeBloqueoPrincipal}</Typography>

            {bloqueos.length > 1 ? (
              <Typography sx={{ mt: 0.75 }} color="text.secondary">
                {bloqueos.slice(1).join(" · ")}
              </Typography>
            ) : null}

            <Stack
              direction="row"
              spacing={1}
              sx={{ mt: 2 }}
              useFlexGap
              flexWrap="wrap"
            >
              <Chip
                color="info"
                label={`Vidas disponibles: ${elegibilidad?.vidas?.disponibles ?? 0}`}
                sx={{ fontSize: 16, px: 1, py: 2.2, fontWeight: 800 }}
              />

              {elegibilidad?.examenTeoricoProgramado?.fecha ? (
                <Chip
                  color="secondary"
                  label={`Tu teórico está programado: ${formatDate(elegibilidad.examenTeoricoProgramado.fecha)}`}
                />
              ) : null}
            </Stack>
          </CardContent>
        </Card>
      ) : null}

      <Card>
        <CardContent>
          <Stack
            direction="row"
            spacing={1}
            alignItems="center"
            useFlexGap
            flexWrap="wrap"
          >
            <Chip
              icon={<EventAvailableIcon />}
              color="success"
              label={`Vidas restantes: ${elegibilidad?.vidas?.disponibles ?? 0}`}
              sx={{ fontWeight: 700 }}
            />
            <Chip
              label={`Profesor: ${context?.calendarioSemana?.profesor?.nombre || "Sin asignar"}`}
              color="primary"
              variant="outlined"
            />
            <Chip
              label={`Precio clase: ${Number(context?.pago?.precioClase || 35).toFixed(2)} EUR`}
              color="default"
            />
          </Stack>
        </CardContent>
      </Card>

      {elegibilidad?.permitido ? (
        <>
          {step === "seleccion" ? (
            <Grid container spacing={2}>
              <Grid item xs={12} md={7}>
                <Paper sx={{ p: 2, border: "1px solid #e2e8f0" }}>
                  <Box
                    sx={{
                      mb: 1,
                      display: "grid",
                      gridTemplateColumns: "1fr auto 1fr",
                      alignItems: "center",
                      gap: 1,
                    }}
                  >
                    <Box sx={{ display: "flex", justifyContent: "flex-start" }}>
                      <Button
                        startIcon={<NavigateBeforeIcon />}
                        onClick={() => setWeekOffset((prev) => prev - 1)}
                      >
                        Semana anterior
                      </Button>
                    </Box>

                    <Typography
                      fontWeight={700}
                      sx={{ textAlign: "center", whiteSpace: "nowrap" }}
                    >
                      {formatDateOnly(context?.calendarioSemana?.inicio)} -{" "}
                      {formatDateOnly(context?.calendarioSemana?.fin)}
                    </Typography>

                    <Box sx={{ display: "flex", justifyContent: "flex-end" }}>
                      <Button
                        endIcon={<NavigateNextIcon />}
                        onClick={() => setWeekOffset((prev) => prev + 1)}
                      >
                        Próxima semana
                      </Button>
                    </Box>
                  </Box>

                  <Divider sx={{ mb: 1.5 }} />

                  <Grid container spacing={1}>
                    {days.map((day, index) => (
                      <Grid key={day.diaSemana} item xs={12} sm={6} md={4}>
                        <Card
                          onClick={() => {
                            setSelectedDay(index);
                            const firstAvailable =
                              day.slots.find((slot) => slot.disponible)?.hora ||
                              "";
                            setSelectedHour(firstAvailable);
                          }}
                          sx={{
                            cursor: "pointer",
                            border:
                              selectedDay === index
                                ? "2px solid #2563eb"
                                : "1px solid #e2e8f0",
                            backgroundColor:
                              selectedDay === index ? "#eff6ff" : "#fff",
                          }}
                        >
                          <CardContent sx={{ py: 1.2 }}>
                            <Typography fontWeight={700}>
                              {DAY_NAME_BY_ID[day.diaSemana] || DAYS[index]}
                            </Typography>
                            <Typography
                              variant="caption"
                              color="text.secondary"
                            >
                              {formatDateOnly(
                                addDaysToDateKey(
                                  extractDateKey(
                                    context?.calendarioSemana?.inicio,
                                  ),
                                  day.diaSemana - 1,
                                ),
                              )}
                            </Typography>
                            <Typography variant="body2" color="text.secondary">
                              {day.disponibles}/{day.totalSlots} huecos
                            </Typography>
                          </CardContent>
                        </Card>
                      </Grid>
                    ))}
                  </Grid>
                </Paper>
              </Grid>

              <Grid item xs={12} md={5}>
                <Paper sx={{ p: 2, border: "1px solid #e2e8f0" }}>
                  <Typography variant="h6" fontWeight={800}>
                    Horas disponibles (
                    {currentDay
                      ? DAY_NAME_BY_ID[currentDay.diaSemana] ||
                        DAYS[selectedDay]
                      : "-"}
                    )
                  </Typography>

                  <Box
                    sx={{
                      display: "grid",
                      gridTemplateColumns: "repeat(5, minmax(0, 1fr))",
                      gap: 1,
                      mt: 1.5,
                    }}
                  >
                    {(currentDay?.slots || []).map((slot) => (
                      <Button
                        key={slot.hora}
                        variant={
                          selectedHour === slot.hora ? "contained" : "outlined"
                        }
                        disabled={!slot.disponible}
                        color={slot.disponible ? "primary" : "error"}
                        sx={
                          !slot.disponible
                            ? {
                                borderColor: "#ef4444",
                                color: "#ef4444",
                                backgroundColor: "#fef2f2",
                              }
                            : undefined
                        }
                        onClick={() => setSelectedHour(slot.hora)}
                      >
                        {slot.hora}
                      </Button>
                    ))}
                  </Box>

                  <Typography
                    variant="caption"
                    color="text.secondary"
                    sx={{ mt: 1, display: "block" }}
                  >
                    Las horas en rojo están ocupadas y no se pueden solicitar.
                  </Typography>

                  <Button
                    fullWidth
                    sx={{ mt: 2 }}
                    variant="contained"
                    onClick={handleNextStep}
                  >
                    Siguiente
                  </Button>
                </Paper>
              </Grid>
            </Grid>
          ) : (
            <Paper sx={{ p: 2, border: "1px solid #e2e8f0" }}>
              <Typography variant="h6" fontWeight={800}>
                Resumen de solicitud
              </Typography>
              <Typography sx={{ mt: 1 }}>
                Fecha y hora: <b>{formatDate(selectedDate)}</b>
              </Typography>
              <Typography>
                Profesor: <b>{context?.calendarioSemana?.profesor?.nombre}</b>
              </Typography>
              <Typography>
                Duración: <b>45 minutos</b>
              </Typography>
              <Typography>
                Tipo de clase:{" "}
                <b>
                  {CLASS_TYPE_LABELS[selectedClassType] || selectedClassType}
                </b>
              </Typography>

              <Box sx={{ mt: 1.5 }}>
                <Typography
                  variant="body2"
                  color="text.secondary"
                  sx={{ mb: 0.8 }}
                >
                  Modalidad de clase
                </Typography>
                <Select
                  fullWidth
                  value={selectedClassType}
                  onChange={(event) => setSelectedClassType(event.target.value)}
                >
                  {(
                    context?.elegibilidad?.tiposClaseDisponibles || [
                      "CIRCULACION",
                    ]
                  ).map((tipo) => (
                    <MenuItem key={tipo} value={tipo}>
                      {CLASS_TYPE_LABELS[tipo] || tipo}
                    </MenuItem>
                  ))}
                </Select>
              </Box>

              <Divider sx={{ my: 2 }} />

              <Typography variant="h6" fontWeight={800}>
                Forma de pago
              </Typography>

              <Stack direction="row" spacing={1} sx={{ mt: 1 }}>
                <Button
                  variant={metodoPago === "BONO" ? "contained" : "outlined"}
                  onClick={() => setMetodoPago("BONO")}
                  disabled={
                    (context?.pago?.bonosDisponibles || []).length === 0
                  }
                >
                  Bono
                </Button>
                <Button
                  variant={
                    metodoPago === "INDIVIDUAL" ? "contained" : "outlined"
                  }
                  onClick={() => setMetodoPago("INDIVIDUAL")}
                  startIcon={<CreditCardIcon />}
                >
                  Clase individual
                </Button>
              </Stack>

              {metodoPago === "BONO" ? (
                <Box sx={{ mt: 1.5 }}>
                  <Select
                    fullWidth
                    value={selectedBonoId}
                    onChange={(event) => setSelectedBonoId(event.target.value)}
                  >
                    {(context?.pago?.bonosDisponibles || []).map((bono) => (
                      <MenuItem value={bono.id} key={bono.id}>
                        {bono.nombre} ({bono.clasesDisponibles} clases
                        restantes: {bono.clasesConsumidas} consumidas y{" "}
                        {bono.clasesSolicitadas} solicitadas)
                      </MenuItem>
                    ))}
                  </Select>
                </Box>
              ) : (
                <Alert sx={{ mt: 1.5 }} severity="info">
                  El pago quedará pendiente al confirmar el profesor y deberá
                  abonarse mínimo 24h antes.
                </Alert>
              )}

              <Stack direction="row" spacing={1} sx={{ mt: 2 }}>
                <Button variant="outlined" onClick={() => setStep("seleccion")}>
                  Volver
                </Button>
                <Button
                  variant="contained"
                  onClick={handleSubmitRequest}
                  disabled={saving}
                >
                  Solicitar clase
                </Button>
              </Stack>
            </Paper>
          )}

          <Paper sx={{ p: 2, border: "1px solid #e2e8f0" }}>
            <Stack
              direction={{ xs: "column", md: "row" }}
              justifyContent="space-between"
              alignItems={{ xs: "flex-start", md: "center" }}
              spacing={1}
            >
              <Box>
                <Typography variant="h6" fontWeight={800}>
                  Agenda de mis clases
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  Vista semanal con próximas clases, solicitudes y clases
                  efectuadas.
                </Typography>
              </Box>

              <Stack direction="row" spacing={0.8} useFlexGap flexWrap="wrap">
                <Chip size="small" label="Próxima" color="info" />
                <Chip size="small" label="Solicitud" color="warning" />
                <Chip size="small" label="Efectuada" color="success" />
              </Stack>
            </Stack>

            <Box
              sx={{
                display: "grid",
                gridTemplateColumns: {
                  xs: "1fr",
                  md: "repeat(7, minmax(0, 1fr))",
                },
                gap: 1,
                mt: 1.5,
              }}
            >
              {agendaWeekDays.map((day) => {
                const dayClasses = agendaByDay.get(day.id) || [];

                return (
                  <Box
                    key={day.id}
                    sx={{
                      border: "1px solid #e2e8f0",
                      borderRadius: 1,
                      p: 1,
                      minHeight: 220,
                      backgroundColor: "#f8fafc",
                    }}
                  >
                    <Typography fontWeight={700} variant="body2">
                      {day.label}
                    </Typography>
                    <Typography
                      variant="caption"
                      color="text.secondary"
                      sx={{ display: "block", mb: 1 }}
                    >
                      {formatDateOnly(day.date)}
                    </Typography>

                    <Stack spacing={0.8}>
                      {dayClasses.length ? (
                        dayClasses.map((item) => {
                          const color = getColorByAgendaItem(item);
                          const typeChip = getAgendaItemTypeChip(
                            item.agendaType,
                          );
                          const statusChip = getAgendaStatusChipConfig(
                            item.estado,
                          );

                          return (
                            <Box
                              key={item.id}
                              sx={{
                                border: "1px solid",
                                borderColor: color.border,
                                borderRadius: 1.5,
                                p: 0.9,
                                bgcolor: color.bg,
                              }}
                            >
                              <Typography
                                variant="caption"
                                fontWeight={700}
                                sx={{ color: color.title }}
                              >
                                {formatHourRange(item.fecha, item.duracion)}
                              </Typography>

                              <Stack
                                direction="row"
                                spacing={0.5}
                                alignItems="center"
                                sx={{ mt: 0.3 }}
                              >
                                <PersonIcon
                                  sx={{
                                    fontSize: 14,
                                    color: color.title,
                                  }}
                                />
                                <Typography
                                  variant="caption"
                                  fontWeight={700}
                                  sx={{ color: color.title }}
                                >
                                  {item.profesor?.nombre || "Profesor"}
                                </Typography>
                              </Stack>

                              <Stack
                                direction="row"
                                spacing={0.5}
                                alignItems="center"
                                sx={{ mt: 0.2 }}
                              >
                                <DirectionsCarIcon
                                  sx={{ fontSize: 13, color: "text.secondary" }}
                                />
                                <Typography
                                  variant="caption"
                                  color="text.secondary"
                                >
                                  {item.vehiculo?.marca || "Vehiculo"}{" "}
                                  {item.vehiculo?.modelo || ""}
                                </Typography>
                              </Stack>

                              <Stack
                                direction="row"
                                spacing={0.5}
                                sx={{ mt: 0.5 }}
                              >
                                <LicenseChip
                                  value={item.vehiculo?.tipoPermiso || "-"}
                                  size="small"
                                />
                                <PracticalClassTypeChip
                                  value={
                                    item.tipoClasePractica || "CIRCULACION"
                                  }
                                  size="small"
                                  sx={{ height: 20, fontSize: 10 }}
                                />
                                <Chip
                                  size="small"
                                  color={typeChip.color}
                                  label={typeChip.label}
                                  sx={{ height: 20, fontSize: 10 }}
                                />
                                <Chip
                                  size="small"
                                  color={statusChip.color}
                                  label={statusChip.label}
                                  sx={{ height: 20, fontSize: 10 }}
                                />
                              </Stack>

                              <Stack sx={{ mt: 0.6 }}>
                                {canStudentCancelClass(item) ||
                                (hasPaidIndividualClass(item) &&
                                  isLessThan24h(item)) ? (
                                  <Button
                                    color="error"
                                    size="small"
                                    onClick={() => handleAskCancel(item)}
                                    sx={{
                                      px: 0,
                                      justifyContent: "flex-start",
                                      minWidth: "auto",
                                    }}
                                  >
                                    Cancelar
                                  </Button>
                                ) : null}

                                {isCompletedWithRoadmap(item) ? (
                                  <Link
                                    component="button"
                                    variant="caption"
                                    onClick={() =>
                                      navigate(
                                        `/hojas-ruta?roadmapId=${item.hojaRutaId}`,
                                      )
                                    }
                                    sx={{ textAlign: "left" }}
                                  >
                                    Ver hoja de ruta
                                  </Link>
                                ) : null}

                                {isCompletedWithoutRoadmap(item) ? (
                                  <Typography
                                    variant="caption"
                                    color="warning.main"
                                  >
                                    Hoja de ruta pendiente de completar por el
                                    profesor.
                                  </Typography>
                                ) : null}

                                {!canStudentCancelClass(item) &&
                                !isCompletedWithRoadmap(item) &&
                                ["PROGRAMADA", "CONFIRMADA"].includes(
                                  String(item?.estado || "").toUpperCase(),
                                ) ? (
                                  <Typography
                                    variant="caption"
                                    color="text.secondary"
                                  >
                                    Menos de 24h
                                  </Typography>
                                ) : null}
                              </Stack>
                            </Box>
                          );
                        })
                      ) : (
                        <Typography variant="caption" color="text.secondary">
                          Sin clases
                        </Typography>
                      )}
                    </Stack>
                  </Box>
                );
              })}
            </Box>
          </Paper>
        </>
      ) : null}

      <Dialog
        open={penaltyDialogOpen}
        onClose={() => setPenaltyDialogOpen(false)}
      >
        <DialogTitle>Cancelación con penalización</DialogTitle>
        <DialogContent>
          <DialogContentText>
            Si cancelas esta clase con menos de 24 horas de antelación, no se
            devolverá el importe. La factura quedará en estado PENALIZACIÓN.
            ¿Quieres continuar?
          </DialogContentText>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setPenaltyDialogOpen(false)}>Volver</Button>
          <Button color="error" onClick={handleConfirmPenaltyCancel}>
            Confirmar cancelación
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
}

import { useEffect, useMemo, useState } from "react";

import {
  Alert,
  Box,
  Button,
  Checkbox,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogContentText,
  DialogTitle,
  FormControl,
  IconButton,
  InputLabel,
  ListItemText,
  Menu,
  MenuItem,
  Select,
  Snackbar,
  TextField,
  Typography,
} from "@mui/material";
import { DataGrid } from "@mui/x-data-grid";
import AddIcon from "@mui/icons-material/Add";
import DeleteIcon from "@mui/icons-material/Delete";
import DownloadIcon from "@mui/icons-material/Download";
import EditIcon from "@mui/icons-material/Edit";
import ToggleOffIcon from "@mui/icons-material/ToggleOff";
import ToggleOnIcon from "@mui/icons-material/ToggleOn";

import Tooltip from "@mui/material/Tooltip"; // Asegúrate de importar el componente

import { tarifasConceptoService } from "../../services/tarifasConceptoService";
import { LicenseChip } from "../../components/common/LicenseChip";
import { exportTarifasConceptoExcel } from "../../utils/exportTarifasConceptoExcel";
import { exportTarifasConceptoPdf } from "../../utils/exportTarifasConceptoPdf";

const PERMISOS = ["A", "A1", "A2", "B", "C", "D", "E"];
const TIPOS = ["FIJO", "VARIABLE", "POR_CLASE", "POR_EXAMEN"];

const emptyForm = {
  permisos: ["B"],
  concepto: "",
  precio: "",
  tipo: "FIJO",
  descripcion: "",
  activa: true,
};

export default function TarifasConcepto() {
  const [rows, setRows] = useState([]);
  const [open, setOpen] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(emptyForm);
  const [permisoFiltro, setPermisoFiltro] = useState("all");
  const [tipoFiltro, setTipoFiltro] = useState("all");
  const [estadoFiltro, setEstadoFiltro] = useState("all");
  const [exportAnchorEl, setExportAnchorEl] = useState(null);
  const [notification, setNotification] = useState({
    open: false,
    message: "",
    severity: "success",
  });
  const [confirmDialog, setConfirmDialog] = useState({
    open: false,
    action: null,
    tarifaId: null,
    title: "",
    message: "",
  });

  const loadTarifas = async () => {
    try {
      const data = await tarifasConceptoService.getAll({
        permiso: permisoFiltro === "all" ? undefined : permisoFiltro,
        tipo: tipoFiltro === "all" ? undefined : tipoFiltro,
        activa: estadoFiltro === "all" ? undefined : estadoFiltro === "activos",
      });
      setRows(data);
    } catch (error) {
      console.error(error);
      setNotification({
        open: true,
        message: "No se pudieron cargar los precios por permiso",
        severity: "error",
      });
    }
  };

  useEffect(() => {
    loadTarifas();
  }, [permisoFiltro, tipoFiltro, estadoFiltro]);

  const filteredRows = useMemo(() => rows, [rows]);

  const resetForm = () => {
    setForm(emptyForm);
    setEditingId(null);
  };

  const handleOpenCreate = () => {
    resetForm();
    setOpen(true);
  };

  const handleEdit = (row) => {
    setEditingId(row.id);
    setForm({
      permisos: [row.permiso || "B"],
      concepto: row.concepto || "",
      precio: row.precio ?? "",
      tipo: row.tipo || "FIJO",
      descripcion: row.descripcion || "",
      activa: Boolean(row.activa),
    });
    setOpen(true);
  };

  const buildConfirm = ({ action, tarifaId, title, message }) => {
    setConfirmDialog({ open: true, action, tarifaId, title, message });
  };

  const handleDelete = (row) => {
    buildConfirm({
      action: "delete",
      tarifaId: row.id,
      title: "Confirmar eliminación",
      message: `Vas a desactivar la tarifa "${row.concepto}" para el permiso ${row.permiso}. Deseas continuar?`,
    });
  };

  const handleToggleActivo = (row) => {
    buildConfirm({
      action: row.activa ? "deactivate" : "activate",
      tarifaId: row.id,
      title: row.activa ? "Confirmar desactivación" : "Confirmar activación",
      message: row.activa
        ? `Vas a desactivar la tarifa "${row.concepto}" del permiso ${row.permiso}.`
        : `Vas a reactivar la tarifa "${row.concepto}" del permiso ${row.permiso}.`,
    });
  };

  const closeConfirmDialog = () => {
    setConfirmDialog({
      open: false,
      action: null,
      tarifaId: null,
      title: "",
      message: "",
    });
  };

  const handleConfirmAction = async () => {
    if (!confirmDialog.tarifaId || !confirmDialog.action) {
      closeConfirmDialog();
      return;
    }

    try {
      if (confirmDialog.action === "delete") {
        await tarifasConceptoService.delete(confirmDialog.tarifaId);
      }

      if (confirmDialog.action === "deactivate") {
        await tarifasConceptoService.deactivate(confirmDialog.tarifaId);
      }

      if (confirmDialog.action === "activate") {
        await tarifasConceptoService.activate(confirmDialog.tarifaId);
      }

      await loadTarifas();

      setNotification({
        open: true,
        message:
          confirmDialog.action === "delete"
            ? "Tarifa desactivada correctamente"
            : confirmDialog.action === "deactivate"
              ? "Tarifa desactivada correctamente"
              : "Tarifa activada correctamente",
        severity: "success",
      });
    } catch (error) {
      console.error(error);
      setNotification({
        open: true,
        message: error.response?.data?.message || "Error procesando la acción",
        severity: "error",
      });
    } finally {
      closeConfirmDialog();
    }
  };

  const handleSave = async () => {
    try {
      const permisos = Array.isArray(form.permisos) ? form.permisos : [];

      const payload = {
        ...form,
        permiso: editingId ? permisos[0] : permisos,
        precio: Number(form.precio),
      };

      delete payload.permisos;

      if (editingId) {
        await tarifasConceptoService.update(editingId, payload);
      } else {
        await tarifasConceptoService.create(payload);
      }

      await loadTarifas();
      setOpen(false);
      resetForm();
      setNotification({
        open: true,
        message: editingId
          ? "Precio actualizado correctamente"
          : permisos.length > 1
            ? "Precios creados correctamente"
            : "Precio creado correctamente",
        severity: "success",
      });
    } catch (error) {
      console.error(error);
      setNotification({
        open: true,
        message: error.response?.data?.message || "Error guardando precio",
        severity: "error",
      });
    }
  };

  const columns = [
    {
      field: "permiso",
      headerName: "Permiso",
      flex: 1,
      renderCell: (params) => <LicenseChip value={params.value} />,
    },
    {
      field: "concepto",
      headerName: "Concepto",
      flex: 2,
    },
    {
      field: "precio",
      headerName: "Precio",
      flex: 1,
      valueFormatter: (value) => `${value} €`,
    },
    {
      field: "tipo",
      headerName: "Tipo",
      flex: 1,
    },
    {
      field: "descripcion",
      headerName: "Descripción",
      flex: 2,
      valueGetter: (value, row) => row.descripcion || "-",
    },
    {
      field: "activa",
      headerName: "Estado",
      flex: 1,
      renderCell: (params) => (
        <Chip
          size="small"
          label={params.value ? "Activo" : "Inactivo"}
          sx={{
            // Fondo según la opción
            backgroundColor: params.value ? "#e8f5e9" : "#ffebee",

            // Color de la letra según la opción
            color: params.value ? "#2e7d32" : "#c62828",

            // Borde según la opción (grosor, tipo y color)
            border: `1px solid ${params.value ? "#4caf50" : "#ef5350"}`,

            // Opcional: Asegura que si hay iconos o estados hover no rompan tus colores
            "& .MuiChip-label": {
              fontWeight: "medium",
            },
          }}
        />
      ),
    },
    {
      field: "acciones",
      headerName: "Acciones",
      width: 180,
      sortable: false,
      renderCell: (params) => (
        <Box sx={{ display: "flex", gap: 1, mt: 1 }}>
          <Tooltip title="Editar" arrow>
            <IconButton color="primary" onClick={() => handleEdit(params.row)}>
              <EditIcon />
            </IconButton>
          </Tooltip>

          <Tooltip title={params.row.activa ? "Desactivar" : "Activar"} arrow>
            <IconButton
              onClick={() => handleToggleActivo(params.row)}
              color={params.row.activa ? "warning" : "success"}
            >
              {params.row.activa ? <ToggleOffIcon /> : <ToggleOnIcon />}
            </IconButton>
          </Tooltip>

          <Tooltip title="Eliminar" arrow>
            <IconButton onClick={() => handleDelete(params.row)} color="error">
              <DeleteIcon />
            </IconButton>
          </Tooltip>
        </Box>
      ),
    },
  ];

  const exportMenuOpen = Boolean(exportAnchorEl);

  const handleExportExcel = () => {
    exportTarifasConceptoExcel(filteredRows);
    setExportAnchorEl(null);
  };

  const handleExportPdf = () => {
    exportTarifasConceptoPdf(filteredRows);
    setExportAnchorEl(null);
  };

  return (
    <Box>
      <Box
        sx={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          mb: 2,
        }}
      >
        <Box>
          <Typography variant="h4" fontWeight="bold">
            Tarifas por permisos
          </Typography>
          <Typography color="text.secondary">
            Establece y revisa las tasas correspondientes a la formación y
            gestión específica de cada tipo de carné de conducir.
          </Typography>
        </Box>

        <Box sx={{ display: "flex", gap: 2, alignItems: "center" }}>
          <FormControl size="small" sx={{ minWidth: 160 }}>
            <InputLabel>Permiso</InputLabel>
            <Select
              label="Permiso"
              value={permisoFiltro}
              onChange={(event) => setPermisoFiltro(event.target.value)}
            >
              <MenuItem value="all">Todos</MenuItem>
              {PERMISOS.map((permiso) => (
                <MenuItem key={permiso} value={permiso}>
                  {permiso}
                </MenuItem>
              ))}
            </Select>
          </FormControl>

          <FormControl size="small" sx={{ minWidth: 180 }}>
            <InputLabel>Tipo</InputLabel>
            <Select
              label="Tipo"
              value={tipoFiltro}
              onChange={(event) => setTipoFiltro(event.target.value)}
            >
              <MenuItem value="all">Todos</MenuItem>
              {TIPOS.map((tipo) => (
                <MenuItem key={tipo} value={tipo}>
                  {tipo}
                </MenuItem>
              ))}
            </Select>
          </FormControl>

          <FormControl size="small" sx={{ minWidth: 180 }}>
            <InputLabel>Estado</InputLabel>
            <Select
              label="Estado"
              value={estadoFiltro}
              onChange={(event) => setEstadoFiltro(event.target.value)}
            >
              <MenuItem value="all">Todos</MenuItem>
              <MenuItem value="activos">Activos</MenuItem>
              <MenuItem value="inactivos">Inactivos</MenuItem>
            </Select>
          </FormControl>

          <Button
            variant="contained"
            startIcon={<AddIcon />}
            onClick={handleOpenCreate}
          >
            Nuevo precio
          </Button>

          <Button
            variant="contained"
            startIcon={<DownloadIcon />}
            onClick={(event) => setExportAnchorEl(event.currentTarget)}
          >
            Exportar
          </Button>

          <Menu
            anchorEl={exportAnchorEl}
            open={exportMenuOpen}
            onClose={() => setExportAnchorEl(null)}
          >
            <MenuItem onClick={handleExportExcel}>Exportar a Excel</MenuItem>
            <MenuItem onClick={handleExportPdf}>Exportar a PDF</MenuItem>
          </Menu>
        </Box>
      </Box>

      <Box sx={{ height: 700 }}>
        <DataGrid
          rows={filteredRows}
          columns={columns}
          getRowId={(row) => row.id}
          disableRowSelectionOnClick
          pageSizeOptions={[10, 25, 50]}
          initialState={{
            pagination: { paginationModel: { pageSize: 10, page: 0 } },
            sorting: { sortModel: [{ field: "permiso", sort: "asc" }] },
          }}
        />
      </Box>

      <Dialog
        open={open}
        onClose={() => setOpen(false)}
        fullWidth
        maxWidth="sm"
      >
        <DialogTitle>
          {editingId ? "Editar precio" : "Nuevo precio"}
        </DialogTitle>
        <DialogContent sx={{ pt: 1, display: "grid", gap: 2 }}>
          <FormControl fullWidth sx={{ mt: 2 }}>
            <InputLabel>Permiso</InputLabel>
            <Select
              multiple={!editingId}
              label="Permiso"
              value={form.permisos}
              renderValue={(selected) =>
                Array.isArray(selected) ? selected.join(", ") : ""
              }
              onChange={(event) =>
                setForm((prev) => ({
                  ...prev,
                  permisos:
                    typeof event.target.value === "string"
                      ? event.target.value.split(",")
                      : event.target.value,
                }))
              }
            >
              {PERMISOS.map((permiso) => (
                <MenuItem key={permiso} value={permiso}>
                  {!editingId ? (
                    <>
                      <Checkbox checked={form.permisos.includes(permiso)} />
                      <ListItemText primary={permiso} />
                    </>
                  ) : (
                    permiso
                  )}
                </MenuItem>
              ))}
            </Select>
          </FormControl>

          <TextField
            label="Concepto"
            fullWidth
            value={form.concepto}
            onChange={(event) =>
              setForm((prev) => ({ ...prev, concepto: event.target.value }))
            }
          />

          <TextField
            label="Precio"
            type="number"
            fullWidth
            value={form.precio}
            onChange={(event) =>
              setForm((prev) => ({ ...prev, precio: event.target.value }))
            }
          />

          <FormControl fullWidth>
            <InputLabel>Tipo</InputLabel>
            <Select
              label="Tipo"
              value={form.tipo}
              onChange={(event) =>
                setForm((prev) => ({ ...prev, tipo: event.target.value }))
              }
            >
              {TIPOS.map((tipo) => (
                <MenuItem key={tipo} value={tipo}>
                  {tipo}
                </MenuItem>
              ))}
            </Select>
          </FormControl>

          <TextField
            label="Descripción"
            fullWidth
            multiline
            minRows={2}
            value={form.descripcion}
            onChange={(event) =>
              setForm((prev) => ({ ...prev, descripcion: event.target.value }))
            }
          />

          <FormControl fullWidth>
            <InputLabel>Estado</InputLabel>
            <Select
              label="Estado"
              value={form.activa ? "true" : "false"}
              onChange={(event) =>
                setForm((prev) => ({
                  ...prev,
                  activa: event.target.value === "true",
                }))
              }
            >
              <MenuItem value="true">Activo</MenuItem>
              <MenuItem value="false">Inactivo</MenuItem>
            </Select>
          </FormControl>
        </DialogContent>

        <DialogActions>
          <Button onClick={() => setOpen(false)}>Cancelar</Button>
          <Button variant="contained" onClick={handleSave}>
            Guardar
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog
        open={confirmDialog.open}
        onClose={closeConfirmDialog}
        fullWidth
        maxWidth="xs"
      >
        <DialogTitle>{confirmDialog.title}</DialogTitle>
        <DialogContent>
          <DialogContentText>{confirmDialog.message}</DialogContentText>
        </DialogContent>
        <DialogActions>
          <Button onClick={closeConfirmDialog}>Cancelar</Button>
          <Button
            variant="contained"
            color={confirmDialog.action === "activate" ? "success" : "error"}
            onClick={handleConfirmAction}
          >
            Confirmar
          </Button>
        </DialogActions>
      </Dialog>

      <Snackbar
        open={notification.open}
        autoHideDuration={3500}
        onClose={() => setNotification((prev) => ({ ...prev, open: false }))}
      >
        <Alert
          severity={notification.severity}
          variant="filled"
          onClose={() => setNotification((prev) => ({ ...prev, open: false }))}
        >
          {notification.message}
        </Alert>
      </Snackbar>
    </Box>
  );
}

import { useEffect, useState } from "react";

import {
  Button,
  Box,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  Divider,
  Grid,
  Stack,
  Typography,
} from "@mui/material";

import SchoolIcon from "@mui/icons-material/School";
import CheckCircleIcon from "@mui/icons-material/CheckCircle";
import ArrowForwardIcon from "@mui/icons-material/ArrowForward";
import { useNavigate } from "react-router-dom";

import { temariosService } from "../../services/temariosService";
import TemarioHero from "./TemarioHero";
import { matriculasService } from "../../services/matriculasService";

import AccesoRestringidoMatricula from "../../components/matricula/AccesoRestringidoMatricula";

export default function TemarioAlumno() {
  const [temarios, setTemarios] = useState([]);
  const [loading, setLoading] = useState(true);
  const [matricula, setMatricula] = useState(null);

  const navigate = useNavigate();

  useEffect(() => {
    const loadTemarios = async () => {
      try {
        const matriculaData = await matriculasService.getMine();

        setMatricula(matriculaData);
        const data = await temariosService.getMine();
        setTemarios(data || []);
      } catch (error) {
        console.error("Error cargando temarios del alumno:", error);
      } finally {
        setLoading(false);
      }
    };

    loadTemarios();
  }, []);
  if (matricula && matricula.estado !== "PAGADA") {
    return <AccesoRestringidoMatricula matricula={matricula} />;
  }

  return (
    <Box sx={{ display: "flex", flexDirection: "column", gap: 3 }}>
      <TemarioHero mode="student" />

      <Box>
        <Typography variant="h4" fontWeight={900} sx={{ mb: 1, mt: -2 }}>
          Temario de tu permiso
        </Typography>
        <Typography variant="body1" color="text.secondary">
          Aquí tienes los bloques teóricos de tu licencia objetivo, ordenados
          para ir estudiando progresivamente.
        </Typography>
      </Box>

      {loading ? (
        <Box sx={{ display: "flex", justifyContent: "center", py: 4 }}>
          <CircularProgress />
        </Box>
      ) : (
        <Grid container spacing={3} sx={{ justifyContent: "flex-start" }}>
          {temarios.length === 0 && (
            <Grid size={{ xs: 12, sm: 6, md: 3 }}>
              <Card sx={{ borderRadius: 3, border: "1px solid #e2e8f0" }}>
                <CardContent
                  sx={{
                    display: "flex",
                    flexDirection: "column",
                    height: "100%",
                  }}
                >
                  <Typography color="text.secondary">
                    No hay temas asignados para tu permiso todavía.
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
          )}

          {temarios.map((temario) => (
            <Grid
              key={temario.id}
              size={{ xs: 12, sm: 6, md: 3 }}
              sx={{
                width: 330,
              }}
            >
              <Card
                sx={{
                  width: 390,
                  height: 320,
                  display: "flex",
                  flexDirection: "column",
                  borderRadius: 3,
                  border: "1px solid #e2e8f0",
                  boxShadow: "0 18px 36px rgba(15, 23, 42, 0.08)",
                  transition: "transform 0.2s ease",
                  "&:hover": {
                    transform: "translateY(-2px)",
                  },
                }}
              >
                <CardContent>
                  <Box
                    sx={{
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "space-between",
                      mb: 2,
                    }}
                  >
                    <Chip
                      icon={<SchoolIcon fontSize="small" />}
                      label={`Tema ${temario.orden ?? "-"}`}
                      color="primary"
                      variant="outlined"
                    />
                    <Chip
                      label={temario.revisado ? "Revisado" : "Pendiente"}
                      color={temario.revisado ? "success" : "warning"}
                      size="small"
                    />
                  </Box>

                  <Typography
                    variant="h6"
                    fontWeight={800}
                    sx={{
                      mb: 0.5, // Reducido para acercar la descripción hacia arriba
                      display: "-webkit-box",
                      WebkitLineClamp: 2,
                      WebkitBoxOrient: "vertical",
                      overflow: "hidden",
                    }}
                  >
                    {temario.titulo}
                  </Typography>

                  <Typography
                    variant="body2"
                    color="text.secondary"
                    sx={{
                      mb: 4, // Aumentado para generar la línea en blanco con el siguiente bloque
                      display: "-webkit-box",
                      WebkitLineClamp: 3, // Aumentado a 3 para que el texto de la imagen no se corte
                      WebkitBoxOrient: "vertical",
                      overflow: "hidden",
                    }}
                  >
                    {temario.descripcion ||
                      "El contenido teórico de este tema se irá desarrollando en próximas entregas."}
                  </Typography>

                  <Divider sx={{ my: 2 }} />

                  <Box
                    sx={{
                      display: "flex",
                      flexDirection: "column",
                      flex: 1,
                      gap: 2,
                      color: "#0f172a",
                    }}
                  >
                    <Stack
                      direction="row"
                      sx={{
                        alignItems: "center",
                        justifyContent: "space-between",
                      }}
                    >
                      <Box
                        sx={{ display: "flex", alignItems: "center", gap: 1.5 }}
                      >
                        <Typography
                          variant="body2"
                          fontWeight={700}
                          sx={{ color: "text.secondary" }}
                        >
                          Estado del tema:
                        </Typography>

                        <Box
                          sx={{
                            display: "inline-flex",
                            alignItems: "center",
                            gap: 0.75,
                            color: temario.revisado ? "#15803d" : "#b45309",
                            fontWeight: 700,
                            fontSize: "0.875rem", // Para emparejar el tamaño con el variant="body2"
                          }}
                        >
                          {temario.revisado ? "Revisado" : "Por empezar"}
                        </Box>
                      </Box>
                    </Stack>
                    <Box sx={{ mt: "auto" }}>
                      <Button
                        fullWidth
                        variant="contained"
                        endIcon={<ArrowForwardIcon />}
                        onClick={() => navigate(`/temario/${temario.id}`)}
                      >
                        Entrar al tema
                      </Button>
                    </Box>
                  </Box>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>
      )}
    </Box>
  );
}

import { useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";

import {
  Alert,
  Box,
  Button,
  Dialog,
  DialogActions,
  IconButton,
  DialogContent,
  DialogTitle,
  DialogContentText,
  FormControl,
  InputLabel,
  MenuItem,
  Select,
  Snackbar,
  TextField,
  Typography,
} from "@mui/material";
import { DataGrid } from "@mui/x-data-grid";
import EditIcon from "@mui/icons-material/Edit";
import DeleteIcon from "@mui/icons-material/Delete";
import AddIcon from "@mui/icons-material/Add";
import OpenInNewIcon from "@mui/icons-material/OpenInNew";
import Tooltip from "@mui/material/Tooltip"; // Asegúrate de importar el componente

import VisibilityIcon from "@mui/icons-material/Visibility"; // Manteniendo el icono de ojo original

import { temariosService } from "../../services/temariosService";
import { LicenseChipList } from "../../components/common/LicenseChip";
import TemarioHero from "./TemarioHero";

const LICENCIAS = ["B", "A1", "A2", "A", "C", "D", "E"];
const LICENCIAS_MOTO = ["A1", "A2", "A"];

const LICENCIAS_FILTRO = [
  { value: "B", label: "B Turismos" },
  { value: "A_MOTOS", label: "A1, A2 y A Motocicletas" },
  { value: "C", label: "C Camiones" },
  { value: "D", label: "D Autobuses" },
  { value: "E", label: "E Remolques y Conjuntos de Vehiculos" },
];

const toLicenciasArray = (valor) => {
  if (Array.isArray(valor)) return valor;
  if (typeof valor === "string" && valor.trim()) return [valor.trim()];
  return [];
};

const emptyForm = {
  titulo: "",
  descripcion: "",
  tipoLicenciaObjetivo: ["B"],
  orden: 0,
};

export default function Temarios() {
  const navigate = useNavigate();
  const [rows, setRows] = useState([]);
  const [filtroLicencia, setFiltroLicencia] = useState("");
  const [open, setOpen] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(emptyForm);
  const [notification, setNotification] = useState({
    open: false,
    message: "",
    severity: "success",
  });

  const [confirmDialog, setConfirmDialog] = useState({
    open: false,
    action: null,
    temarioId: null,
    tituloTemario: "",
    title: "",
    message: "",
  });

  const loadTemarios = async () => {
    try {
      const data = await temariosService.getAll();
      setRows(data);
    } catch (error) {
      console.error(error);
      setNotification({
        open: true,
        message: "No se pudieron cargar los temarios",
        severity: "error",
      });
    }
  };

  useEffect(() => {
    loadTemarios();
  }, []);

  const filteredRows = useMemo(() => {
    if (!filtroLicencia) return rows;

    return rows.filter((row) => {
      const licencias = toLicenciasArray(row.tipoLicenciaObjetivo);

      if (filtroLicencia === "A_MOTOS") {
        return licencias.some((licencia) => LICENCIAS_MOTO.includes(licencia));
      }

      return licencias.includes(filtroLicencia);
    });
  }, [rows, filtroLicencia]);

  const resetForm = () => {
    setForm(emptyForm);
    setEditingId(null);
  };

  const handleOpenCreate = () => {
    resetForm();
    setOpen(true);
  };

  const handleEdit = (row) => {
    setEditingId(row.id);
    setForm({
      titulo: row.titulo || "",
      descripcion: row.descripcion || "",
      tipoLicenciaObjetivo: toLicenciasArray(row.tipoLicenciaObjetivo),
      orden: row.orden ?? 0,
      documentacionRuta: row.documentacionRuta || "",
      claseDirectoVideoUrl: row.claseDirectoVideoUrl || "",
    });
    setOpen(true);
  };

  const handleDelete = async (row) => {
    const tituloTemario = row?.titulo || "este temario";

    setConfirmDialog({
      open: true,
      action: "delete",
      temarioId: row.id,
      tituloTemario,
      title: "Confirmar eliminación",
      message: `Vas a eliminar definitivamente el temario "${tituloTemario}" de Autoescuela Eguzkilore. Todo el contenido asociado será eliminado de forma permanente. Esta acción no podrá deshacerse. ¿Deseas continuar?`,
    });
  };

  const closeConfirmDialog = () => {
    setConfirmDialog({
      open: false,
      action: null,
      temarioId: null,
      tituloTemario: "",
      title: "",
      message: "",
    });
  };

  const handleConfirmAction = async () => {
    if (!confirmDialog.temarioId) {
      closeConfirmDialog();
      return;
    }

    try {
      await temariosService.delete(confirmDialog.temarioId);

      await loadTemarios();

      setNotification({
        open: true,
        message: "Temario eliminado correctamente",
        severity: "success",
      });
    } catch (error) {
      console.error(error);

      setNotification({
        open: true,
        message: error.response?.data?.message || "Error eliminando temario",
        severity: "error",
      });
    } finally {
      closeConfirmDialog();
    }
  };

  const handleSave = async () => {
    try {
      const payload = {
        ...form,
        tipoLicenciaObjetivo: toLicenciasArray(form.tipoLicenciaObjetivo),
        orden: Number(form.orden),
        documentacionRuta: form.documentacionRuta || "",
        claseDirectoVideoUrl: form.claseDirectoVideoUrl || "",
      };

      if (editingId) {
        await temariosService.update(editingId, payload);
      } else {
        await temariosService.create(payload);
      }

      await loadTemarios();
      setOpen(false);
      resetForm();
      setNotification({
        open: true,
        message: editingId
          ? "Temario actualizado correctamente"
          : "Temario creado correctamente",
        severity: "success",
      });
    } catch (error) {
      console.error(error);
      setNotification({
        open: true,
        message: error.response?.data?.message || "Error guardando temario",
        severity: "error",
      });
    }
  };

  const columns = [
    { field: "titulo", headerName: "Título", flex: 1.2 },
    {
      field: "tipoLicenciaObjetivo",
      headerName: "Permisos",
      flex: 1,
      renderCell: (params) => {
        const licencias = toLicenciasArray(params.row.tipoLicenciaObjetivo);
        return <LicenseChipList values={licencias} />;
      },
    },
    { field: "orden", headerName: "Orden", flex: 0.6 },
    {
      field: "descripcion",
      headerName: "Descripción",
      flex: 1.6,
      renderCell: (params) => (
        <Box
          sx={{
            display: "flex",
            alignItems: "center",
            height: "100%",
            width: "100%",
          }}
        >
          <Typography variant="body2" noWrap>
            {params.row.descripcion || "Sin descripción"}
          </Typography>
        </Box>
      ),
    },
    {
      field: "acciones",
      headerName: "Acciones",
      width: 200,
      sortable: false,
      renderCell: (params) => (
        <Box
          sx={{
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            width: "100%",
            gap: 0.5,
            mt: 1,
          }}
        >
          <Tooltip title="Ver detalle" arrow>
            <IconButton
              color="primary"
              onClick={() => navigate(`/temarios/${params.row.id}`)}
            >
              <VisibilityIcon />
            </IconButton>
          </Tooltip>

          <Tooltip title="Editar" arrow>
            <IconButton color="primary" onClick={() => handleEdit(params.row)}>
              <EditIcon />
            </IconButton>
          </Tooltip>

          <Tooltip title="Eliminar" arrow>
            <IconButton color="error" onClick={() => handleDelete(params.row)}>
              <DeleteIcon />
            </IconButton>
          </Tooltip>
        </Box>
      ),
    },
  ];

  return (
    <Box>
      <TemarioHero mode="admin" />

      <Box
        sx={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          mb: 2,
        }}
      >
        <Box>
          <Typography variant="h4" fontWeight="bold">
            Temarios
          </Typography>
          <Typography color="text.secondary">
            Gestión de contenido teórico asociado al permiso objetivo.
          </Typography>
        </Box>
        <Box
          sx={{
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            mb: 1,
          }}
        >
          <Box
            sx={{
              display: "flex",
              alignItems: "center",
              gap: 2,
              width: "100%",
              maxWidth: 560,
              justifyContent: "center",
            }}
          >
            <Typography variant="subtitle1" fontWeight={600} sx={{ mt: 3 }}>
              Licencia
            </Typography>

            <FormControl size="small" sx={{ minWidth: 340, mt: 3 }}>
              <InputLabel id="filtro-licencia-label">Licencia</InputLabel>
              <Select
                labelId="filtro-licencia-label"
                label="Licencia"
                value={filtroLicencia}
                onChange={(event) => setFiltroLicencia(event.target.value)}
              >
                <MenuItem value="">Todas</MenuItem>
                {LICENCIAS_FILTRO.map((licencia) => (
                  <MenuItem key={licencia.value} value={licencia.value}>
                    {licencia.label}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          </Box>
        </Box>
        <Button
          variant="contained"
          startIcon={<AddIcon />}
          onClick={handleOpenCreate}
        >
          Nuevo temario
        </Button>
      </Box>

      <Box sx={{ height: 700 }}>
        <DataGrid
          rows={filteredRows}
          columns={columns}
          getRowId={(row) => row.id}
          disableRowSelectionOnClick
          pageSizeOptions={[10, 25, 50]}
          initialState={{
            pagination: { paginationModel: { pageSize: 10, page: 0 } },
            sorting: { sortModel: [{ field: "orden", sort: "asc" }] },
          }}
        />
      </Box>

      <Dialog
        open={open}
        onClose={() => setOpen(false)}
        fullWidth
        maxWidth="sm"
      >
        <DialogTitle>
          {editingId ? "Editar temario" : "Nuevo temario"}
        </DialogTitle>
        <DialogContent sx={{ pt: 1, display: "grid", gap: 2 }}>
          <TextField
            sx={{ mt: 2 }}
            label="Título"
            fullWidth
            value={form.titulo}
            onChange={(event) =>
              setForm((prev) => ({ ...prev, titulo: event.target.value }))
            }
          />
          <TextField
            label="Descripción"
            fullWidth
            multiline
            minRows={3}
            value={form.descripcion}
            onChange={(event) =>
              setForm((prev) => ({ ...prev, descripcion: event.target.value }))
            }
          />
          <FormControl fullWidth>
            <InputLabel id="permisos-label">Permisos</InputLabel>
            <Select
              labelId="permisos-label"
              multiple
              label="Permisos"
              value={form.tipoLicenciaObjetivo}
              renderValue={(selected) => selected.join(", ")}
              onChange={(event) => {
                const value = event.target.value;
                setForm((prev) => ({
                  ...prev,
                  tipoLicenciaObjetivo:
                    typeof value === "string" ? value.split(",") : value,
                }));
              }}
            >
              {LICENCIAS.map((licencia) => (
                <MenuItem key={licencia} value={licencia}>
                  {licencia}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
          <TextField
            label="Orden"
            type="number"
            fullWidth
            value={form.orden}
            onChange={(event) =>
              setForm((prev) => ({ ...prev, orden: event.target.value }))
            }
          />
          <TextField
            label="Documentación PDF (ruta o URL)"
            fullWidth
            value={form.documentacionRuta || ""}
            onChange={(event) =>
              setForm((prev) => ({
                ...prev,
                documentacionRuta: event.target.value,
              }))
            }
          />
          <TextField
            label="URL de la clase en directo (YouTube)"
            fullWidth
            value={form.claseDirectoVideoUrl || ""}
            onChange={(event) =>
              setForm((prev) => ({
                ...prev,
                claseDirectoVideoUrl: event.target.value,
              }))
            }
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpen(false)}>Cancelar</Button>
          <Button variant="contained" onClick={handleSave}>
            Guardar
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog
        open={confirmDialog.open}
        onClose={closeConfirmDialog}
        fullWidth
        maxWidth="xs"
      >
        <DialogTitle>{confirmDialog.title}</DialogTitle>

        <DialogContent>
          <DialogContentText>{confirmDialog.message}</DialogContentText>
        </DialogContent>

        <DialogActions>
          <Button onClick={closeConfirmDialog}>Cancelar</Button>

          <Button
            variant="contained"
            color="error"
            onClick={handleConfirmAction}
          >
            Confirmar
          </Button>
        </DialogActions>
      </Dialog>

      <Snackbar
        open={notification.open}
        autoHideDuration={3500}
        onClose={() => setNotification((prev) => ({ ...prev, open: false }))}
      >
        <Alert
          severity={notification.severity}
          variant="filled"
          onClose={() => setNotification((prev) => ({ ...prev, open: false }))}
        >
          {notification.message}
        </Alert>
      </Snackbar>
    </Box>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";

import {
  Alert,
  Box,
  Button,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogContentText,
  DialogTitle,
  FormControl,
  FormControlLabel,
  IconButton,
  MenuItem,
  Radio,
  RadioGroup,
  Select,
  Snackbar,
  Stack,
  TextField,
  Typography,
} from "@mui/material";
import { DataGrid } from "@mui/x-data-grid";
import AddIcon from "@mui/icons-material/Add";
import EditIcon from "@mui/icons-material/Edit";
import ToggleOnIcon from "@mui/icons-material/ToggleOn";
import ToggleOffIcon from "@mui/icons-material/ToggleOff";
import DeleteIcon from "@mui/icons-material/Delete";
import CloudUploadIcon from "@mui/icons-material/CloudUpload";
import UndoIcon from "@mui/icons-material/Undo";
import Tooltip from "@mui/material/Tooltip"; // Asegúrate de importar el componente
import * as XLSX from "xlsx";

import { preguntasDGTService } from "../../services/preguntasDGTService";
import { LicenseChipList } from "../../components/common/LicenseChip";
import { exportPreguntasDGTTemplateExcel } from "../../utils/exportPreguntasDGTTemplateExcel";

const LICENCIAS = ["B", "A1", "A2", "A", "C", "D", "E"];
const TAMANO_MAXIMO_IMAGEN = 5 * 1024 * 1024;
const TIPOS_IMAGEN_PERMITIDOS = ["image/png", "image/jpeg", "image/webp"];
const IMPORT_REQUIRED_COLUMNS = [
  "LICENCIAS",
  "ENUNCIADO",
  "RESPUESTA_1",
  "RESPUESTA_2",
  "RESPUESTA_3",
  "RESPUESTA_CORRECTA",
];

const createEmptyForm = (defaultEnunciado = "") => ({
  licencia: ["B"],
  enunciado: defaultEnunciado,
  explicacion: "",
  activa: true,
  imagenRuta: "",
  respuestas: [
    { texto: "", correcta: true },
    { texto: "", correcta: false },
    { texto: "", correcta: false },
  ],
});

const normalizeRows = (rows = []) => {
  return rows.map((row) => ({
    ...row,
    respuestas: Array.isArray(row.respuestas)
      ? [...row.respuestas].sort((a, b) => (a.orden || 0) - (b.orden || 0))
      : [],
  }));
};

export default function TestDGTAdmin() {
  const [rows, setRows] = useState([]);
  const [licenciaFiltro, setLicenciaFiltro] = useState("all");
  const [open, setOpen] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(createEmptyForm());
  const [nextPreguntaId, setNextPreguntaId] = useState("");
  const [importingExcel, setImportingExcel] = useState(false);
  const [imagenFile, setImagenFile] = useState(null);
  const [previewImage, setPreviewImage] = useState("");
  const [eliminarImagenActual, setEliminarImagenActual] = useState(false);
  const importInputRef = useRef(null);

  const [notification, setNotification] = useState({
    open: false,
    message: "",
    severity: "success",
  });

  const [confirmDialog, setConfirmDialog] = useState({
    open: false,
    action: null,
    id: null,
    title: "",
    message: "",
  });

  const loadPreguntas = async () => {
    try {
      const data = await preguntasDGTService.getAll({
        licencia: licenciaFiltro === "all" ? undefined : licenciaFiltro,
      });
      setRows(normalizeRows(data));
    } catch (error) {
      console.error(error);
      setNotification({
        open: true,
        message: "No se pudo cargar el banco de preguntas DGT",
        severity: "error",
      });
    }
  };

  const loadNextId = async () => {
    try {
      const data = await preguntasDGTService.getNextId();
      setNextPreguntaId(data?.id || "");
    } catch {
      setNextPreguntaId("");
    }
  };

  useEffect(() => {
    loadPreguntas();
    loadNextId();
  }, [licenciaFiltro]);

  const filteredRows = useMemo(() => rows, [rows]);

  const resetForm = (defaultEnunciado = "") => {
    setForm(createEmptyForm(defaultEnunciado));
    setImagenFile(null);
    setPreviewImage("");
    setEliminarImagenActual(false);
    setEditingId(null);
  };

  const handleOpenCreate = () => {
    const suggestedPrefix = nextPreguntaId ? `${nextPreguntaId} ` : "";
    resetForm(suggestedPrefix);
    setOpen(true);
  };

  const handleEdit = (row) => {
    const respuestas = (row.respuestas || []).slice(0, 4);

    while (respuestas.length < 3) {
      respuestas.push({ texto: "", correcta: false });
    }

    const indiceCorrecta = respuestas.findIndex(
      (respuesta) => respuesta.correcta,
    );

    setForm({
      licencia:
        Array.isArray(row.licencia) && row.licencia.length > 0
          ? row.licencia
          : ["B"],
      enunciado: row.enunciado || "",
      explicacion: row.explicacion || "",
      activa: Boolean(row.activa),
      imagenRuta: row.imagenRuta || "",
      respuestas: respuestas.map((item, index) => ({
        texto: item.texto || "",
        correcta: index === (indiceCorrecta >= 0 ? indiceCorrecta : 0),
      })),
    });
    setImagenFile(null);
    setPreviewImage(row.imagenRuta || "");
    setEliminarImagenActual(false);
    setEditingId(row.id);
    setOpen(true);
  };

  const handleLicenciasChange = (value) => {
    const licencias = typeof value === "string" ? value.split(",") : value;

    setForm((prev) => ({
      ...prev,
      licencia: licencias,
    }));
  };

  const handleSetRespuestaText = (index, value) => {
    setForm((prev) => ({
      ...prev,
      respuestas: prev.respuestas.map((respuesta, i) =>
        i === index ? { ...respuesta, texto: value } : respuesta,
      ),
    }));
  };

  const handleSetCorrecta = (index) => {
    setForm((prev) => ({
      ...prev,
      respuestas: prev.respuestas.map((respuesta, i) => ({
        ...respuesta,
        correcta: i === index,
      })),
    }));
  };

  const handleAddRespuesta = () => {
    setForm((prev) => {
      if (prev.respuestas.length >= 4) {
        return prev;
      }

      return {
        ...prev,
        respuestas: [...prev.respuestas, { texto: "", correcta: false }],
      };
    });
  };

  const handleRemoveRespuesta = (index) => {
    setForm((prev) => {
      if (prev.respuestas.length <= 3) {
        return prev;
      }

      const nuevasRespuestas = prev.respuestas.filter((_, i) => i !== index);

      if (!nuevasRespuestas.some((respuesta) => respuesta.correcta)) {
        nuevasRespuestas[0] = {
          ...nuevasRespuestas[0],
          correcta: true,
        };
      }

      return {
        ...prev,
        respuestas: nuevasRespuestas,
      };
    });
  };

  const handleImagenChange = (event) => {
    const file = event.target.files?.[0];

    if (!file) {
      return;
    }

    if (!TIPOS_IMAGEN_PERMITIDOS.includes(file.type)) {
      setNotification({
        open: true,
        message: "Formato de imagen no permitido. Usa png, jpg o webp.",
        severity: "error",
      });
      return;
    }

    if (file.size > TAMANO_MAXIMO_IMAGEN) {
      setNotification({
        open: true,
        message: "La imagen supera 5 MB.",
        severity: "error",
      });
      return;
    }

    setImagenFile(file);
    setPreviewImage(URL.createObjectURL(file));
    setEliminarImagenActual(false);
  };

  const handleToggleEliminarImagen = () => {
    if (eliminarImagenActual) {
      setEliminarImagenActual(false);
      setPreviewImage(form.imagenRuta || "");
      return;
    }

    setImagenFile(null);
    setPreviewImage("");
    setEliminarImagenActual(true);
  };

  const openConfirm = (action, row) => {
    const byAction = {
      activate: {
        title: "Confirmar activación",
        message:
          "Vas a activar esta pregunta para que pueda entrar en los exámenes DGT. ¿Deseas continuar?",
      },
      deactivate: {
        title: "Confirmar desactivación",
        message:
          "Vas a desactivar esta pregunta y dejará de aparecer en la generación de exámenes. ¿Deseas continuar?",
      },
      delete: {
        title: "Confirmar baja lógica",
        message:
          "Esta acción desactivará la pregunta. Podrás reactivarla más adelante desde el listado. ¿Deseas continuar?",
      },
    };

    setConfirmDialog({
      open: true,
      action,
      id: row.id,
      title: byAction[action].title,
      message: byAction[action].message,
    });
  };

  const closeConfirm = () => {
    setConfirmDialog({
      open: false,
      action: null,
      id: null,
      title: "",
      message: "",
    });
  };

  const validateForm = () => {
    if (!Array.isArray(form.licencia) || form.licencia.length === 0) {
      return "Debes seleccionar al menos una licencia";
    }

    if (!form.enunciado.trim()) {
      return "El enunciado es obligatorio";
    }

    if (form.respuestas.length < 3 || form.respuestas.length > 4) {
      return "Debes informar entre 3 y 4 respuestas";
    }

    const respuestasVacias = form.respuestas.some((item) => !item.texto.trim());

    if (respuestasVacias) {
      return "Debes completar todas las respuestas";
    }

    const correctas = form.respuestas.filter((item) => item.correcta).length;

    if (correctas !== 1) {
      return "Debe haber exactamente una respuesta correcta";
    }

    return "";
  };

  const handleSave = async () => {
    const validationError = validateForm();

    if (validationError) {
      setNotification({
        open: true,
        message: validationError,
        severity: "error",
      });
      return;
    }

    const payload = {
      licencia: form.licencia,
      enunciado: form.enunciado.trim(),
      explicacion: form.explicacion.trim(),
      activa: form.activa,
      respuestas: form.respuestas.map((respuesta, index) => ({
        texto: respuesta.texto.trim(),
        correcta: respuesta.correcta,
        orden: index + 1,
      })),
    };

    try {
      if (editingId) {
        await preguntasDGTService.update(
          editingId,
          payload,
          imagenFile,
          eliminarImagenActual,
        );
      } else {
        await preguntasDGTService.create(payload, imagenFile);
      }

      await loadPreguntas();
      await loadNextId();
      setOpen(false);
      resetForm();
      setNotification({
        open: true,
        message: editingId
          ? "Pregunta actualizada correctamente"
          : "Pregunta creada correctamente",
        severity: "success",
      });
    } catch (error) {
      console.error(error);
      setNotification({
        open: true,
        message:
          error.response?.data?.message || "No se pudo guardar la pregunta",
        severity: "error",
      });
    }
  };

  const parseLicencias = (value, rowIndex) => {
    const licencias = String(value || "")
      .split(",")
      .map((item) => item.trim().toUpperCase())
      .filter(Boolean);

    if (licencias.length === 0) {
      throw new Error(
        `Fila ${rowIndex}: Debes informar al menos una licencia en la columna LICENCIAS.`,
      );
    }

    const invalidas = licencias.filter((item) => !LICENCIAS.includes(item));

    if (invalidas.length > 0) {
      throw new Error(
        `Fila ${rowIndex}: Licencias no válidas: ${invalidas.join(", ")}.`,
      );
    }

    return [...new Set(licencias)];
  };

  const parseCorrectaIndex = (row, respuestas, rowIndex) => {
    const correctaRaw = String(row.RESPUESTA_CORRECTA || "").trim();

    if (!correctaRaw) {
      throw new Error(
        `Fila ${rowIndex}: Debes informar RESPUESTA_CORRECTA con 1-4 o texto de respuesta.`,
      );
    }

    const maybeNumber = Number(correctaRaw);

    if (Number.isInteger(maybeNumber)) {
      const idx = maybeNumber - 1;

      if (idx < 0 || idx >= respuestas.length) {
        throw new Error(
          `Fila ${rowIndex}: RESPUESTA_CORRECTA fuera de rango para las respuestas informadas.`,
        );
      }

      return idx;
    }

    const idxByText = respuestas.findIndex(
      (respuesta) =>
        respuesta.texto.toLowerCase() === correctaRaw.toLowerCase(),
    );

    if (idxByText < 0) {
      throw new Error(
        `Fila ${rowIndex}: RESPUESTA_CORRECTA no coincide con ninguna respuesta.`,
      );
    }

    return idxByText;
  };

  const handleImportExcel = async (event) => {
    const file = event.target.files?.[0];

    if (!file) {
      return;
    }

    try {
      setImportingExcel(true);

      const arrayBuffer = await file.arrayBuffer();
      const workbook = XLSX.read(arrayBuffer, { type: "array" });
      const sheetName = workbook.SheetNames[0];

      if (!sheetName) {
        throw new Error("El archivo no contiene hojas para importar.");
      }

      const worksheet = workbook.Sheets[sheetName];
      const rowsExcel = XLSX.utils.sheet_to_json(worksheet, {
        defval: "",
      });

      if (!rowsExcel.length) {
        throw new Error("El Excel está vacío.");
      }

      const firstRow = rowsExcel[0] || {};
      const missingColumns = IMPORT_REQUIRED_COLUMNS.filter(
        (column) => !(column in firstRow),
      );

      if (missingColumns.length > 0) {
        throw new Error(
          `Faltan columnas obligatorias: ${missingColumns.join(", ")}.`,
        );
      }

      const errores = [];
      let creadas = 0;

      for (let idx = 0; idx < rowsExcel.length; idx += 1) {
        const row = rowsExcel[idx];
        const rowIndex = idx + 2;

        try {
          const licencias = parseLicencias(row.LICENCIAS, rowIndex);
          const enunciado = String(row.ENUNCIADO || "").trim();
          const explicacion = String(row.EXPLICACION || "").trim();

          if (!enunciado) {
            throw new Error(
              `Fila ${rowIndex}: Debes informar el enunciado de la pregunta.`,
            );
          }

          const respuestasText = [
            String(row.RESPUESTA_1 || "").trim(),
            String(row.RESPUESTA_2 || "").trim(),
            String(row.RESPUESTA_3 || "").trim(),
            String(row.RESPUESTA_4 || "").trim(),
          ].filter(Boolean);

          if (respuestasText.length < 3 || respuestasText.length > 4) {
            throw new Error(
              `Fila ${rowIndex}: Debes informar entre 3 y 4 respuestas.`,
            );
          }

          const respuestas = respuestasText.map((texto, respIndex) => ({
            texto,
            correcta: false,
            orden: respIndex + 1,
          }));

          const idxCorrecta = parseCorrectaIndex(row, respuestas, rowIndex);
          respuestas[idxCorrecta].correcta = true;

          await preguntasDGTService.create({
            licencia: licencias,
            enunciado,
            explicacion,
            activa: true,
            respuestas,
          });

          creadas += 1;
        } catch (error) {
          errores.push(error.message);
        }
      }

      await loadPreguntas();
      await loadNextId();

      if (errores.length > 0) {
        setNotification({
          open: true,
          severity: "warning",
          message: `Importación parcial: ${creadas} creadas, ${errores.length} con error. Primer error: ${errores[0]}`,
        });
      } else {
        setNotification({
          open: true,
          severity: "success",
          message: `Importación completada: ${creadas} pregunta(s) creada(s).`,
        });
      }
    } catch (error) {
      setNotification({
        open: true,
        severity: "error",
        message:
          error?.message || "No se pudo importar el Excel de preguntas DGT.",
      });
    } finally {
      setImportingExcel(false);

      if (event.target) {
        event.target.value = "";
      }
    }
  };

  const handleConfirmAction = async () => {
    if (!confirmDialog.id || !confirmDialog.action) {
      closeConfirm();
      return;
    }

    try {
      if (confirmDialog.action === "activate") {
        await preguntasDGTService.activate(confirmDialog.id);
      }

      if (confirmDialog.action === "deactivate") {
        await preguntasDGTService.deactivate(confirmDialog.id);
      }

      if (confirmDialog.action === "delete") {
        await preguntasDGTService.delete(confirmDialog.id);
      }

      await loadPreguntas();

      setNotification({
        open: true,
        message: "Operación realizada correctamente",
        severity: "success",
      });
    } catch (error) {
      console.error(error);
      setNotification({
        open: true,
        message:
          error.response?.data?.message || "No se pudo completar la operación",
        severity: "error",
      });
    } finally {
      closeConfirm();
    }
  };

  const columns = [
    {
      field: "id",
      headerName: "ID",
      flex: 0.9,
    },
    {
      field: "enunciado",
      headerName: "Enunciado",
      flex: 2,
      renderCell: (params) => (
        <Box
          sx={{
            display: "flex",
            alignItems: "flex-start",
            height: "100%",
            pt: 1.5,
          }}
        >
          <Typography variant="body2" noWrap title={params.row.enunciado}>
            {params.row.enunciado}
          </Typography>
        </Box>
      ),
    },
    {
      field: "licencia",
      headerName: "Licencia",
      flex: 1.15,
      renderCell: (params) => (
        <Box
          sx={{
            display: "flex",
            flexDirection: "column",
            justifyContent: "flex-end", // Empuja los chips al fondo de la celda
            height: "100%", // Usa todo el alto disponible de la fila
            pb: 1.5, // Padding bottom opcional (8px) para separar del borde
          }}
        >
          <LicenseChipList values={params.row.licencia} />
        </Box>
      ),
    },
    {
      field: "activa",
      headerName: "Estado",
      flex: 0.8,
      renderCell: (params) => (
        <Chip
          size="small"
          label={params.value ? "Activa" : "Inactiva"}
          sx={{
            // Fondo según la opción
            backgroundColor: params.value ? "#e8f5e9" : "#ffebee",

            // Color de la letra según la opción
            color: params.value ? "#2e7d32" : "#c62828",

            // Borde según la opción (grosor, tipo y color)
            border: `1px solid ${params.value ? "#4caf50" : "#ef5350"}`,

            // Opcional: Asegura que si hay iconos o estados hover no rompan tus colores
            "& .MuiChip-label": {
              fontWeight: "medium",
            },
          }}
        />
      ),
    },
    {
      field: "acciones",
      headerName: "Acciones",
      width: 180,
      sortable: false,
      renderCell: (params) => (
        <Box sx={{ display: "flex", gap: 0.5 }}>
          <Tooltip title="Editar" arrow>
            <IconButton color="primary" onClick={() => handleEdit(params.row)}>
              <EditIcon />
            </IconButton>
          </Tooltip>

          {params.row.activa ? (
            <Tooltip title="Desactivar" arrow>
              <IconButton
                color="warning"
                onClick={() => openConfirm("deactivate", params.row)}
              >
                <ToggleOffIcon />
              </IconButton>
            </Tooltip>
          ) : (
            <Tooltip title="Activar" arrow>
              <IconButton
                color="success"
                onClick={() => openConfirm("activate", params.row)}
              >
                <ToggleOnIcon />
              </IconButton>
            </Tooltip>
          )}

          <Tooltip title="Eliminar" arrow>
            <IconButton
              color="error"
              onClick={() => openConfirm("delete", params.row)}
            >
              <DeleteIcon />
            </IconButton>
          </Tooltip>
        </Box>
      ),
    },
  ];

  return (
    <Box>
      <Box
        sx={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          mb: 2,
          gap: 2,
          flexWrap: "wrap",
        }}
      >
        <Box>
          <Typography variant="h4" fontWeight={800}>
            Banco de preguntas DGT
          </Typography>
          <Typography color="text.secondary">
            Consulta y actualiza el repositorio oficial de test y preguntas para
            la preparación del examen teórico.
          </Typography>
        </Box>

        <Stack direction="row" spacing={1.5} useFlexGap flexWrap="wrap">
          <FormControl size="small" sx={{ minWidth: 220 }}>
            <Select
              value={licenciaFiltro}
              onChange={(event) => setLicenciaFiltro(event.target.value)}
            >
              <MenuItem value="all">Todas las licencias</MenuItem>
              {LICENCIAS.map((licencia) => (
                <MenuItem key={licencia} value={licencia}>
                  Permiso {licencia}
                </MenuItem>
              ))}
            </Select>
          </FormControl>

          <Button variant="outlined" onClick={exportPreguntasDGTTemplateExcel}>
            Descargar plantilla Excel
          </Button>

          <Button
            variant="outlined"
            component="label"
            disabled={importingExcel}
          >
            {importingExcel ? "Importando..." : "Importar Excel"}
            <input
              ref={importInputRef}
              hidden
              type="file"
              accept=".xlsx,.xls"
              onChange={handleImportExcel}
            />
          </Button>

          <Button
            variant="contained"
            startIcon={<AddIcon />}
            onClick={handleOpenCreate}
          >
            Nueva pregunta
          </Button>
        </Stack>
      </Box>

      <Box sx={{ height: 700 }}>
        <DataGrid
          rows={filteredRows}
          columns={columns}
          getRowId={(row) => row.id}
          disableRowSelectionOnClick
          pageSizeOptions={[10, 25, 50]}
          initialState={{
            pagination: {
              paginationModel: {
                pageSize: 10,
                page: 0,
              },
            },
            sorting: {
              sortModel: [{ field: "enunciado", sort: "asc" }],
            },
          }}
        />
      </Box>

      <Dialog
        open={open}
        onClose={() => setOpen(false)}
        maxWidth="md"
        fullWidth
      >
        <DialogTitle>
          {editingId ? "Editar pregunta" : "Nueva pregunta"}
        </DialogTitle>

        <DialogContent sx={{ display: "grid", gap: 2, pt: 1 }}>
          <FormControl fullWidth size="small">
            <Select
              multiple
              value={form.licencia}
              onChange={(event) => handleLicenciasChange(event.target.value)}
              renderValue={(selected) => selected.join(", ")}
            >
              {LICENCIAS.map((licencia) => (
                <MenuItem key={licencia} value={licencia}>
                  Permiso {licencia}
                </MenuItem>
              ))}
            </Select>
          </FormControl>

          {!editingId && nextPreguntaId ? (
            <Alert severity="info">
              ID asignado en el alta: <strong>{nextPreguntaId}</strong>
            </Alert>
          ) : null}

          <Stack spacing={1}>
            {previewImage && !eliminarImagenActual ? (
              <Box
                component="img"
                src={previewImage}
                alt="Vista previa de la imagen"
                sx={{
                  width: "100%",
                  maxWidth: 360,
                  borderRadius: 2,
                  border: "1px solid #e2e8f0",
                }}
              />
            ) : (
              <Typography variant="body2" color="text.secondary">
                No hay imagen seleccionada.
              </Typography>
            )}

            <Stack direction="row" spacing={1}>
              <Button
                variant="outlined"
                component="label"
                startIcon={<CloudUploadIcon />}
              >
                {previewImage ? "Cambiar imagen" : "Añadir imagen"}
                <input
                  hidden
                  accept="image/png,image/jpeg,image/webp"
                  type="file"
                  onChange={handleImagenChange}
                />
              </Button>

              {(previewImage || form.imagenRuta) && editingId ? (
                <Button
                  variant="contained"
                  color={eliminarImagenActual ? "warning" : "error"}
                  startIcon={
                    eliminarImagenActual ? <UndoIcon /> : <DeleteIcon />
                  }
                  onClick={handleToggleEliminarImagen}
                >
                  {eliminarImagenActual ? "Deshacer" : "Eliminar imagen"}
                </Button>
              ) : null}
            </Stack>
          </Stack>

          <TextField
            label="Enunciado"
            value={form.enunciado}
            onChange={(event) =>
              setForm((prev) => ({
                ...prev,
                enunciado: event.target.value,
              }))
            }
            multiline
            minRows={2}
            fullWidth
          />

          <TextField
            label="Explicación (opcional)"
            value={form.explicacion}
            onChange={(event) =>
              setForm((prev) => ({
                ...prev,
                explicacion: event.target.value,
              }))
            }
            multiline
            minRows={2}
            fullWidth
          />

          <FormControl>
            <Typography variant="subtitle2" sx={{ mb: 1 }}>
              Selecciona la respuesta correcta (3 o 4 respuestas)
            </Typography>

            <RadioGroup
              value={String(form.respuestas.findIndex((item) => item.correcta))}
              onChange={(event) =>
                handleSetCorrecta(Number(event.target.value))
              }
            >
              {form.respuestas.map((respuesta, index) => (
                <Box key={`respuesta-${index}`} sx={{ mb: 1.25 }}>
                  <FormControlLabel
                    value={String(index)}
                    control={<Radio />}
                    label={`Respuesta ${index + 1}`}
                  />
                  <TextField
                    fullWidth
                    size="small"
                    value={respuesta.texto}
                    onChange={(event) =>
                      handleSetRespuestaText(index, event.target.value)
                    }
                    placeholder={`Texto de la respuesta ${index + 1}`}
                  />

                  {form.respuestas.length > 3 ? (
                    <Box sx={{ mt: 1 }}>
                      <Button
                        size="small"
                        color="error"
                        onClick={() => handleRemoveRespuesta(index)}
                      >
                        Eliminar respuesta
                      </Button>
                    </Box>
                  ) : null}
                </Box>
              ))}
            </RadioGroup>

            <Button
              sx={{ mt: 1 }}
              size="small"
              onClick={handleAddRespuesta}
              disabled={form.respuestas.length >= 4}
            >
              Añadir cuarta respuesta
            </Button>
          </FormControl>
        </DialogContent>

        <DialogActions>
          <Button onClick={() => setOpen(false)}>Cancelar</Button>
          <Button onClick={handleSave} variant="contained">
            {editingId ? "Guardar cambios" : "Crear pregunta"}
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog open={confirmDialog.open} onClose={closeConfirm}>
        <DialogTitle>{confirmDialog.title}</DialogTitle>
        <DialogContent>
          <DialogContentText>{confirmDialog.message}</DialogContentText>
        </DialogContent>
        <DialogActions>
          <Button onClick={closeConfirm}>Cancelar</Button>
          <Button
            onClick={handleConfirmAction}
            variant="contained"
            color="error"
          >
            Confirmar
          </Button>
        </DialogActions>
      </Dialog>

      <Snackbar
        open={notification.open}
        autoHideDuration={3500}
        onClose={() => setNotification((prev) => ({ ...prev, open: false }))}
      >
        <Alert
          severity={notification.severity}
          variant="filled"
          onClose={() => setNotification((prev) => ({ ...prev, open: false }))}
        >
          {notification.message}
        </Alert>
      </Snackbar>
    </Box>
  );
}

import { useMemo, useState } from "react";

import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  Divider,
  FormControl,
  FormControlLabel,
  MenuItem,
  Radio,
  RadioGroup,
  Select,
  Stack,
  Typography,
} from "@mui/material";

import QuizIcon from "@mui/icons-material/Quiz";
import TimerIcon from "@mui/icons-material/Timer";
import RestartAltIcon from "@mui/icons-material/RestartAlt";

import { preguntasDGTService } from "../../services/preguntasDGTService";

const LICENCIAS = ["B", "A1", "A2", "A", "C", "D", "E"];

const formatDuration = (seconds) => {
  const min = Math.floor(seconds / 60)
    .toString()
    .padStart(2, "0");
  const sec = Math.floor(seconds % 60)
    .toString()
    .padStart(2, "0");

  return `${min}:${sec}`;
};

export default function TestDGTAlumno({ defaultLicencia = "B" }) {
  const [licencia, setLicencia] = useState(defaultLicencia || "B");
  const [loading, setLoading] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [preguntas, setPreguntas] = useState([]);
  const [respuestas, setRespuestas] = useState({});
  const [error, setError] = useState("");
  const [resultado, setResultado] = useState(null);
  const [startedAt, setStartedAt] = useState(null);

  const totalRespondidas = Object.keys(respuestas).length;
  const examenCompleto =
    preguntas.length > 0 && totalRespondidas === preguntas.length;

  const duracionSegundos = useMemo(() => {
    if (!startedAt) {
      return 0;
    }

    return Math.max(0, Math.floor((Date.now() - startedAt) / 1000));
  }, [startedAt, totalRespondidas, submitting, loading]);

  const correccionByPregunta = useMemo(() => {
    if (!resultado?.correccion || !Array.isArray(resultado.correccion)) {
      return new Map();
    }

    return new Map(resultado.correccion.map((item) => [item.preguntaId, item]));
  }, [resultado]);

  const getColorRespuesta = (preguntaId, respuestaId) => {
    if (!resultado) {
      return null;
    }

    const detalle = correccionByPregunta.get(preguntaId);

    if (!detalle) {
      return null;
    }

    if (detalle.esCorrecta && detalle.respuestaCorrectaId === respuestaId) {
      return "success";
    }

    if (!detalle.esCorrecta && detalle.respuestaAlumnoId === respuestaId) {
      return "error";
    }

    if (!detalle.esCorrecta && detalle.respuestaCorrectaId === respuestaId) {
      return "success";
    }

    return null;
  };

  const isPreguntaFallada = (preguntaId) => {
    if (!resultado) {
      return false;
    }

    const detalle = correccionByPregunta.get(preguntaId);

    return Boolean(detalle && !detalle.esCorrecta);
  };

  const sanitizarPreguntas = (items = []) => {
    return items.map((item) => ({
      id: item.id,
      enunciado: item.enunciado,
      explicacion: item.explicacion,
      imagenRuta: item.imagenRuta,
      respuestas: (item.respuestas || []).map((respuesta) => ({
        id: respuesta.id,
        texto: respuesta.texto,
        orden: respuesta.orden,
      })),
    }));
  };

  const handleGenerar = async () => {
    try {
      setLoading(true);
      setError("");
      setResultado(null);
      setRespuestas({});

      const data = await preguntasDGTService.generarExamen(licencia);
      const preguntasSanitizadas = sanitizarPreguntas(data);

      setPreguntas(preguntasSanitizadas);
      setStartedAt(Date.now());
    } catch (requestError) {
      console.error(requestError);
      setError(
        requestError.response?.data?.message ||
          "No se pudo generar el examen DGT para la licencia seleccionada.",
      );
    } finally {
      setLoading(false);
    }
  };

  const handleSeleccion = (preguntaId, respuestaId) => {
    setRespuestas((prev) => ({
      ...prev,
      [preguntaId]: respuestaId,
    }));
  };

  const handleCorregir = async () => {
    if (!examenCompleto) {
      return;
    }

    try {
      setSubmitting(true);
      setError("");

      const payload = {
        licencia,
        preguntas: preguntas.map((pregunta) => pregunta.id),
        respuestasAlumno: preguntas.map((pregunta) => ({
          preguntaId: pregunta.id,
          respuestaId: respuestas[pregunta.id],
        })),
      };

      const data = await preguntasDGTService.corregirExamen(payload);

      setResultado(data);
    } catch (requestError) {
      console.error(requestError);
      setError(
        requestError.response?.data?.message ||
          "No se pudo corregir el examen. Inténtalo de nuevo.",
      );
    } finally {
      setSubmitting(false);
    }
  };

  const handleReiniciar = () => {
    setPreguntas([]);
    setRespuestas({});
    setResultado(null);
    setError("");
    setStartedAt(null);
  };

  return (
    <Box sx={{ display: "flex", flexDirection: "column", gap: 3 }}>
      <Card
        sx={{
          borderRadius: 2,
          background:
            "linear-gradient(120deg, rgba(15,23,42,0.97) 0%, rgba(30,64,175,0.9) 100%)",
          color: "#fff",
        }}
      >
        <CardContent>
          <Stack
            direction={{ xs: "column", md: "row" }}
            justifyContent="space-between"
            alignItems={{ xs: "flex-start", md: "center" }}
            spacing={2}
          >
            <Box>
              <Typography variant="h4" fontWeight={900}>
                Simulador Test DGT
              </Typography>
              <Typography sx={{ opacity: 0.9, mt: 1 }}>
                Genera un examen oficial de 30 preguntas y corrígelo al
                instante.
              </Typography>
            </Box>

            <Stack
              direction="row"
              spacing={1}
              alignItems="center"
              useFlexGap
              flexWrap="wrap"
            >
              {/* 1. TIEMPO: Cambiado a Button (deshabilitado el click) para igualar el tamaño perfectamente */}
              <Button
                component="div" // Evita que actúe como un botón interactivo real
                startIcon={<TimerIcon fontSize="small" />}
                sx={{
                  width: 180,
                  height: 40,
                  textTransform: "none", // Evita mayúsculas automáticas
                  backgroundColor: "rgba(255,255,255,0.15)",
                  color: "#fff",
                  borderRadius: 1, // Bordes sutiles para emparejar con Select y Button
                  cursor: "default",
                  "&:hover": { backgroundColor: "rgba(255,255,255,0.15)" },
                }}
              >
                Tiempo {formatDuration(duracionSegundos)}
              </Button>

              {/* 2. LICENCIA SELECT */}
              <FormControl size="small" sx={{ width: 180, height: 40 }}>
                <Select
                  value={licencia}
                  onChange={(event) => setLicencia(event.target.value)}
                  sx={{
                    height: "100%", // Obliga al Select a tomar los 40px del FormControl
                    color: "#fff",
                    ".MuiOutlinedInput-notchedOutline": {
                      borderColor: "rgba(255,255,255,0.4)",
                    },
                    "&.Mui-focused .MuiOutlinedInput-notchedOutline": {
                      borderColor: "#fff",
                    },
                    ".MuiSvgIcon-root": {
                      color: "#fff",
                    },
                  }}
                >
                  {LICENCIAS.map((item) => (
                    <MenuItem key={item} value={item}>
                      Permiso {item}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>

              {/* 3. BOTÓN GENERAR EXAMEN */}
              <Button
                variant="contained"
                color="warning"
                startIcon={<QuizIcon />}
                onClick={handleGenerar}
                disabled={loading || submitting}
                sx={{
                  width: 180,
                  height: 40,
                  textTransform: "none", // Opcional: mantiene el texto en minúsculas/mayúsculas naturales
                }}
              >
                {loading ? "Generando..." : "Generar examen"}
              </Button>
            </Stack>
          </Stack>
        </CardContent>
      </Card>

      {error && <Alert severity="error">{error}</Alert>}

      {loading && (
        <Box sx={{ display: "flex", justifyContent: "center", py: 6 }}>
          <CircularProgress />
        </Box>
      )}

      {!loading && preguntas.length > 0 && (
        <Stack spacing={2}>
          <Typography variant="h6" fontWeight={800}>
            Examen generado: {preguntas.length} preguntas
          </Typography>

          {preguntas.map((pregunta, index) => {
            const preguntaFallada = isPreguntaFallada(pregunta.id);

            return (
              <Card
                key={pregunta.id}
                sx={
                  preguntaFallada
                    ? {
                        borderRadius: 3,
                        backgroundColor: "#fff7ed",
                        border: "1px solid #fed7aa",
                      }
                    : { borderRadius: 3 }
                }
              >
                <CardContent>
                  <Box
                    sx={{
                      display: "flex",
                      justifyContent: "space-between",
                      alignItems: "flex-start",
                      gap: 2,
                      mb: 1.25,
                    }}
                  >
                    <Typography variant="subtitle1" fontWeight={700}>
                      {index + 1}. {pregunta.enunciado}
                    </Typography>
                    {preguntaFallada ? (
                      <Typography
                        variant="body2"
                        fontWeight={700}
                        sx={{ color: "error.main", whiteSpace: "nowrap" }}
                      >
                        Pregunta fallada
                      </Typography>
                    ) : null}
                  </Box>

                  {pregunta.imagenRuta ? (
                    <Box
                      component="img"
                      src={pregunta.imagenRuta}
                      alt={`Imagen pregunta ${index + 1}`}
                      sx={{
                        width: "100%",
                        maxWidth: 420,
                        borderRadius: 2,
                        mb: 1.5,
                        border: "1px solid #e2e8f0",
                      }}
                    />
                  ) : null}

                  <FormControl>
                    <RadioGroup
                      sx={{ ml: 2, mt: 10 }}
                      value={respuestas[pregunta.id] || ""}
                      onChange={(event) =>
                        handleSeleccion(pregunta.id, event.target.value)
                      }
                      disabled={Boolean(resultado)}
                    >
                      {pregunta.respuestas.map((respuesta) => {
                        const color = getColorRespuesta(
                          pregunta.id,
                          respuesta.id,
                        );

                        return (
                          <FormControlLabel
                            key={respuesta.id}
                            value={respuesta.id}
                            control={<Radio color={color || "primary"} />}
                            label={respuesta.texto}
                            sx={
                              color === "success"
                                ? {
                                    color: "success.main",
                                    "& .MuiFormControlLabel-label": {
                                      fontWeight: 700,
                                    },
                                  }
                                : color === "error"
                                  ? {
                                      color: "error.main",
                                      "& .MuiFormControlLabel-label": {
                                        fontWeight: 700,
                                      },
                                    }
                                  : undefined
                            }
                          />
                        );
                      })}
                    </RadioGroup>
                  </FormControl>

                  {index < preguntas.length - 1 && <Divider sx={{ mt: 1.5 }} />}
                </CardContent>
              </Card>
            );
          })}

          <Stack direction={{ xs: "column", sm: "row" }} spacing={1.5}>
            <Button
              variant="contained"
              onClick={handleCorregir}
              disabled={!examenCompleto || submitting}
            >
              {submitting ? "Corrigiendo..." : "Corregir examen"}
            </Button>

            <Button
              variant="outlined"
              onClick={handleReiniciar}
              startIcon={<RestartAltIcon />}
            >
              Reiniciar
            </Button>
          </Stack>

          {!examenCompleto && (
            <Typography variant="body2" color="text.secondary">
              Responde todas las preguntas antes de corregir.
            </Typography>
          )}
        </Stack>
      )}

      {resultado && (
        <Card sx={{ borderRadius: 3, border: "1px solid #e2e8f0" }}>
          <CardContent>
            <Typography variant="h6" fontWeight={800} sx={{ mb: 1 }}>
              Resultado del examen
            </Typography>
            <Stack direction="row" spacing={1} sx={{ mb: 1.5 }}>
              <Chip label={`Aciertos: ${resultado.aciertos}`} color="success" />
              <Chip label={`Fallos: ${resultado.fallos}`} color="error" />
              <Chip
                label={resultado.aprobado ? "APROBADO" : "SUSPENDIDO"}
                color={resultado.aprobado ? "success" : "error"}
              />
            </Stack>
            <Alert severity={resultado.aprobado ? "success" : "warning"}>
              {resultado.aprobado
                ? "Buen trabajo. Has superado el umbral del test DGT."
                : "Todavía no llegas al mínimo. Revisa teoría y vuelve a intentarlo."}
            </Alert>
          </CardContent>
        </Card>
      )}
    </Box>
  );
}

import { useEffect, useMemo, useState } from "react";
import {
  Alert,
  Box,
  Button,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  DialogContentText,
  FormControlLabel,
  FormControl,
  IconButton,
  InputLabel,
  MenuItem,
  Paper,
  Select,
  Snackbar,
  Radio,
  RadioGroup,
  Stack,
  TextField,
  Typography,
  Chip,
  LinearProgress,
} from "@mui/material";
import { DataGrid } from "@mui/x-data-grid";
import EditIcon from "@mui/icons-material/Edit";
import DeleteIcon from "@mui/icons-material/Delete";
import ToggleOffIcon from "@mui/icons-material/ToggleOff";
import ToggleOnIcon from "@mui/icons-material/ToggleOn";
import CheckCircleIcon from "@mui/icons-material/CheckCircle";
import CloudUploadIcon from "@mui/icons-material/CloudUpload";
import DeleteForeverIcon from "@mui/icons-material/DeleteForever";
import UndoIcon from "@mui/icons-material/Undo";
import FactCheckIcon from "@mui/icons-material/FactCheck";
import { vehiculosService } from "../../services/vehiculosService";
import { LicenseChip } from "../../components/common/LicenseChip";

import Tooltip from "@mui/material/Tooltip"; // Asegúrate de importar el componente

import DownloadIcon from "@mui/icons-material/Download";
import Menu from "@mui/material/Menu";

import { exportVehiculosExcel } from "../../utils/exportVehiculosExcel";

import { exportVehiculosPdf } from "../../utils/exportVehiculosPdf";

const PERMISOS = ["B", "A1", "A2", "A", "C", "D", "E"];
const TAMANO_MAXIMO_IMAGEN = 5 * 1024 * 1024;
const TIPOS_IMAGEN_PERMITIDOS = ["image/png", "image/jpeg", "image/webp"];

const formatDateForInput = (value) => {
  if (!value) {
    return "";
  }

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return "";
  }

  return date.toISOString().slice(0, 10);
};

const formatDateLabel = (value) => {
  if (!value) {
    return "-";
  }

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return "-";
  }

  return date.toLocaleDateString("es-ES");
};

const formDataVehiculo = (vehiculo, imagenFile, eliminarImagen) => {
  const data = new FormData();

  data.append("matricula", vehiculo.matricula?.trim().toUpperCase() || "");
  data.append("marca", vehiculo.marca?.trim() || "");
  data.append("modelo", vehiculo.modelo?.trim() || "");
  data.append("tipoPermiso", vehiculo.tipoPermiso || "");
  data.append("fechaUltimaItv", vehiculo.fechaUltimaItv || "");

  if (imagenFile) {
    data.append("imagen", imagenFile);
  }

  if (eliminarImagen) {
    data.append("eliminarImagen", "true");
  }

  return data;
};

export default function Vehiculos() {
  const [rows, setRows] = useState([]);
  const [open, setOpen] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [openDetail, setOpenDetail] = useState(false);
  const [loadingDetail, setLoadingDetail] = useState(false);
  const [selectedVehiculo, setSelectedVehiculo] = useState(null);
  const [permisoFiltro, setPermisoFiltro] = useState("all");
  const [estadoFiltro, setEstadoFiltro] = useState("activos");

  const [exportAnchor, setExportAnchor] = useState(null);

  const [nuevoVehiculo, setNuevoVehiculo] = useState({
    matricula: "",
    marca: "",
    modelo: "",
    tipoPermiso: "B",
    fechaUltimaItv: "",
    imagenRuta: "",
    activo: true,
  });

  const [imagenFile, setImagenFile] = useState(null);
  const [previewImage, setPreviewImage] = useState("");
  const [eliminarImagenActual, setEliminarImagenActual] = useState(false);

  const [notification, setNotification] = useState({
    open: false,
    message: "",
    severity: "success",
  });

  const [confirmDialog, setConfirmDialog] = useState({
    open: false,
    action: null,
    vehiculoId: null,
    matricula: "",
    title: "",
    message: "",
  });

  const [deactivateModal, setDeactivateModal] = useState({
    open: false,
    loading: false,
    vehiculo: null,
    clasesAfectadas: [],
  });
  const [reasignacionesDeactivacion, setReasignacionesDeactivacion] = useState(
    {},
  );

  const buildImageSrc = (ruta) => {
    if (!ruta) {
      return "";
    }

    if (ruta.startsWith("http://") || ruta.startsWith("https://")) {
      return ruta;
    }

    return ruta;
  };

  const loadVehiculos = async () => {
    try {
      const data = await vehiculosService.getAll();
      setRows(data);
    } catch (error) {
      console.error(error);
      setNotification({
        open: true,
        message: "No se pudo cargar el listado de vehículos",
        severity: "error",
      });
    }
  };

  useEffect(() => {
    loadVehiculos();
  }, []);

  useEffect(() => {
    return () => {
      if (previewImage?.startsWith("blob:")) {
        URL.revokeObjectURL(previewImage);
      }
    };
  }, [previewImage]);

  const filteredRows = useMemo(() => {
    return rows.filter((row) => {
      const matchesPermiso =
        !permisoFiltro || permisoFiltro === "all"
          ? true
          : row.tipoPermiso === permisoFiltro;

      const isActive = row.activo !== false;
      const matchesEstado =
        estadoFiltro === "todos"
          ? true
          : estadoFiltro === "activos"
            ? isActive
            : !isActive;

      return matchesPermiso && matchesEstado;
    });
  }, [rows, permisoFiltro, estadoFiltro]);

  const resetForm = () => {
    setNuevoVehiculo({
      matricula: "",
      marca: "",
      modelo: "",
      tipoPermiso: "B",
      fechaUltimaItv: "",
      imagenRuta: "",
      activo: true,
    });

    if (previewImage?.startsWith("blob:")) {
      URL.revokeObjectURL(previewImage);
    }

    setPreviewImage("");
    setImagenFile(null);
    setEliminarImagenActual(false);
  };

  const handleFileChange = (event) => {
    const file = event.target.files?.[0];

    if (!file) {
      return;
    }

    if (!TIPOS_IMAGEN_PERMITIDOS.includes(file.type)) {
      setNotification({
        open: true,
        message: "Formato no permitido. Usa PNG, JPG/JPEG o WEBP.",
        severity: "error",
      });
      event.target.value = "";
      return;
    }

    if (file.size > TAMANO_MAXIMO_IMAGEN) {
      setNotification({
        open: true,
        message: "La imagen supera 5 MB. Selecciona un archivo más pequeño.",
        severity: "error",
      });
      event.target.value = "";
      return;
    }

    if (previewImage?.startsWith("blob:")) {
      URL.revokeObjectURL(previewImage);
    }

    setImagenFile(file);
    setPreviewImage(URL.createObjectURL(file));
    setEliminarImagenActual(false);
  };

  const handleToggleEliminarImagen = () => {
    if (eliminarImagenActual) {
      setEliminarImagenActual(false);
      setPreviewImage(buildImageSrc(nuevoVehiculo.imagenRuta));
      return;
    }

    if (previewImage?.startsWith("blob:")) {
      URL.revokeObjectURL(previewImage);
    }

    setImagenFile(null);
    setPreviewImage("");
    setNuevoVehiculo((prev) => ({ ...prev, imagenRuta: "" }));
    setEliminarImagenActual(true);
  };

  const saveVehiculo = async () => {
    try {
      if (!nuevoVehiculo.matricula?.trim()) {
        setNotification({
          open: true,
          message: "La matrícula es obligatoria",
          severity: "error",
        });
        return;
      }

      if (!nuevoVehiculo.tipoPermiso?.trim()) {
        setNotification({
          open: true,
          message: "El tipo de permiso es obligatorio",
          severity: "error",
        });
        return;
      }

      const targetId = editingId;
      const payload = formDataVehiculo(
        nuevoVehiculo,
        imagenFile,
        Boolean(targetId) && eliminarImagenActual,
      );

      const vehiculoGuardado = targetId
        ? await vehiculosService.update(targetId, payload)
        : await vehiculosService.create(payload);

      if (targetId) {
        setRows((prevRows) =>
          prevRows.map((row) =>
            row.id === targetId ? { ...row, ...vehiculoGuardado } : row,
          ),
        );

        if (
          selectedVehiculo &&
          String(selectedVehiculo.id) === String(targetId)
        ) {
          setSelectedVehiculo((prev) => ({
            ...prev,
            ...vehiculoGuardado,
            imagenRuta: vehiculoGuardado.imagenRuta ?? null,
          }));
        }
      }

      setOpen(false);
      setEditingId(null);
      resetForm();
      await loadVehiculos();

      if (
        targetId &&
        openDetail &&
        String(selectedVehiculo?.id || "") === String(targetId)
      ) {
        try {
          const detalleActualizado = await vehiculosService.getById(targetId);
          setSelectedVehiculo(detalleActualizado || vehiculoGuardado);
        } catch (error) {
          console.error(error);
        }
      }

      setNotification({
        open: true,
        message: editingId
          ? "Vehículo actualizado correctamente"
          : "Vehículo creado correctamente",
        severity: "success",
      });
    } catch (error) {
      console.error(error);
      setNotification({
        open: true,
        message:
          error.response?.data?.message ||
          (editingId
            ? "Error actualizando vehículo"
            : "Error creando vehículo"),
        severity: "error",
      });
    }
  };

  const handleEdit = (row) => {
    setEditingId(row.id);
    setNuevoVehiculo({
      matricula: row.matricula || "",
      marca: row.marca || "",
      modelo: row.modelo || "",
      tipoPermiso: row.tipoPermiso || "B",
      fechaUltimaItv: formatDateForInput(row.fechaUltimaItv),
      imagenRuta: row.imagenRuta || "",
      activo: row.activo,
    });

    setImagenFile(null);
    setEliminarImagenActual(false);
    if (previewImage?.startsWith("blob:")) {
      URL.revokeObjectURL(previewImage);
    }
    setPreviewImage(buildImageSrc(row.imagenRuta));
    setOpen(true);
  };

  const handleDeactivate = async (row) => {
    try {
      const impacto = await vehiculosService.getDeactivationImpact(row.id);

      if (!impacto?.clasesAfectadas?.length) {
        setConfirmDialog({
          open: true,
          action: "deactivate",
          vehiculoId: row.id,
          matricula: row.matricula,
          title: "Confirmar desactivación",
          message: `Vas a desactivar el vehículo ${row.matricula} en la plataforma Autoescuela Eguzkilore. No podrá ser utilizado hasta su reactivación. ¿Deseas continuar?`,
        });
        return;
      }

      const valoresIniciales = {};
      impacto.clasesAfectadas.forEach((item) => {
        valoresIniciales[item.claseId] = {
          nuevoVehiculoId: "",
          kmActualesNuevoVehiculo: "",
          combustibleActualPctNuevoVehiculo: "",
          enCurso: Boolean(item.enCurso),
        };
      });

      setReasignacionesDeactivacion(valoresIniciales);
      setDeactivateModal({
        open: true,
        loading: false,
        vehiculo: impacto.vehiculo,
        clasesAfectadas: impacto.clasesAfectadas,
      });
    } catch (error) {
      setNotification({
        open: true,
        message:
          error.response?.data?.message ||
          "No se pudo cargar el impacto de desactivación del vehículo",
        severity: "error",
      });
    }
  };

  const closeDeactivateModal = () => {
    setDeactivateModal({
      open: false,
      loading: false,
      vehiculo: null,
      clasesAfectadas: [],
    });
    setReasignacionesDeactivacion({});
  };

  const handleConfirmDeactivateWithReassignment = async () => {
    if (!deactivateModal.vehiculo?.id) {
      return;
    }

    const reasignaciones = [];

    for (const clase of deactivateModal.clasesAfectadas) {
      const item = reasignacionesDeactivacion[clase.claseId] || {};

      if (!item.nuevoVehiculoId) {
        setNotification({
          open: true,
          message: "Debes reasignar todas las clases antes de desactivar",
          severity: "error",
        });
        return;
      }

      if (clase.enCurso) {
        const km = Number(item.kmActualesNuevoVehiculo);
        const combustible = Number(item.combustibleActualPctNuevoVehiculo);

        if (!Number.isInteger(km) || km < 0) {
          setNotification({
            open: true,
            message:
              "Debes informar un kilometraje válido para todas las clases en curso",
            severity: "error",
          });
          return;
        }

        if (
          !Number.isInteger(combustible) ||
          combustible < 0 ||
          combustible > 100
        ) {
          setNotification({
            open: true,
            message:
              "Debes informar un combustible válido (0-100) para todas las clases en curso",
            severity: "error",
          });
          return;
        }
      }

      reasignaciones.push({
        claseId: clase.claseId,
        nuevoVehiculoId: item.nuevoVehiculoId,
        kmActualesNuevoVehiculo: item.kmActualesNuevoVehiculo,
        combustibleActualPctNuevoVehiculo:
          item.combustibleActualPctNuevoVehiculo,
      });
    }

    try {
      setDeactivateModal((prev) => ({ ...prev, loading: true }));
      await vehiculosService.deactivateWithReassignment(
        deactivateModal.vehiculo.id,
        reasignaciones,
      );
      await loadVehiculos();
      closeDeactivateModal();
      setNotification({
        open: true,
        message:
          "Vehículo desactivado correctamente con reasignación de clases obligatoria",
        severity: "success",
      });
    } catch (error) {
      setNotification({
        open: true,
        message:
          error.response?.data?.message ||
          "No se pudo completar la desactivación con reasignación",
        severity: "error",
      });
    } finally {
      setDeactivateModal((prev) => ({ ...prev, loading: false }));
    }
  };

  const handleActivate = async (row) => {
    setConfirmDialog({
      open: true,
      action: "activate",
      vehiculoId: row.id,
      matricula: row.matricula,
      title: "Confirmar activación",
      message: `Vas a reactivar el vehículo ${row.matricula} en la plataforma Autoescuela Eguzkilore. Volverá a estar disponible de inmediato. ¿Deseas continuar?`,
    });
  };

  const closeConfirmDialog = () => {
    setConfirmDialog({
      open: false,
      action: null,
      vehiculoId: null,
      matricula: "",
      title: "",
      message: "",
    });
  };

  const handleConfirmAction = async () => {
    if (!confirmDialog.vehiculoId || !confirmDialog.action) {
      closeConfirmDialog();
      return;
    }

    try {
      if (confirmDialog.action === "deactivate") {
        await vehiculosService.deactivate(confirmDialog.vehiculoId);
      }

      if (confirmDialog.action === "activate") {
        await vehiculosService.activate(confirmDialog.vehiculoId);
      }

      await loadVehiculos();

      setNotification({
        open: true,
        message:
          confirmDialog.action === "deactivate"
            ? "Vehículo desactivado correctamente"
            : "Vehículo activado correctamente",
        severity: "success",
      });
    } catch (error) {
      console.error(error);

      setNotification({
        open: true,
        message:
          confirmDialog.action === "deactivate"
            ? "Error desactivando vehículo"
            : "Error activando vehículo",
        severity: "error",
      });
    } finally {
      closeConfirmDialog();
    }
  };

  const handleOpenDetail = async (row) => {
    setOpenDetail(true);
    setLoadingDetail(true);
    setSelectedVehiculo(row);

    try {
      const detalle = await vehiculosService.getById(row.id);
      setSelectedVehiculo(detalle);
    } catch (error) {
      console.error(error);
      setNotification({
        open: true,
        message: "No se pudo cargar el detalle del vehículo",
        severity: "error",
      });
    } finally {
      setLoadingDetail(false);
    }
  };

  const handlePayItv = async (row) => {
    try {
      const result = await vehiculosService.payItv(row.id);
      await loadVehiculos();
      setNotification({
        open: true,
        message: result?.message || "Pago de revisión ITV registrado",
        severity: "success",
      });
    } catch (error) {
      setNotification({
        open: true,
        message:
          error.response?.data?.message ||
          "No se pudo registrar el pago de revisión ITV",
        severity: "error",
      });
    }
  };

  const columns = [
    { field: "matricula", headerName: "Matrícula", flex: 1 },
    { field: "marca", headerName: "Marca", flex: 1 },
    { field: "modelo", headerName: "Modelo", flex: 1 },
    {
      field: "tipoPermiso",
      headerName: "Permiso",
      flex: 0.7,
      renderCell: (params) => <LicenseChip value={params.value} />,
    },
    {
      field: "numeroClasesRealizadas",
      headerName: "Nº Clases",
      width: 120,
      valueGetter: (_, row) => Number(row.numeroClasesRealizadas || 0),
    },
    {
      field: "kmActuales",
      headerName: "KMs actuales",
      width: 140,
      valueGetter: (_, row) => row.kmActuales ?? 0,
    },
    {
      field: "fechaUltimaItv",
      headerName: "Fecha última ITV",
      width: 160,
      valueGetter: (_, row) => formatDateLabel(row.fechaUltimaItv),
    },
    {
      field: "itvPendiente",
      headerName: "Revisión ITV",
      width: 160,
      renderCell: (params) =>
        params.row.itvPendiente ? (
          <Chip label="Pendiente" color="warning" size="small" />
        ) : (
          <Chip
            label="Vigente"
            sx={{
              width: "fit-content",
              backgroundColor: "#fffbeb", // Fondo original
              borderColor: "#facc15", // Borde original
              borderStyle: "solid",
              borderRadius: "15px",
              borderWidth: "2px",
              color: "#ca8a04", // Texto original
              "& .MuiChip-label": {
                fontWeight: "bold",
              },
              // 👇 ESTO ES LO QUE DEBES AÑADIR PARA EL HOVER
              "&:hover": {
                backgroundColor: "#fef08a", // Fondo al pasar el ratón (un amarillo un poco más oscuro)
                borderColor: "#eab308", // Borde al pasar el ratón (opcional)
                color: "#854d0e", // Texto al pasar el ratón (opcional)
              },
            }}
          />
        ),
    },
    {
      field: "combustibleActualPct",
      headerName: "Combustible",
      width: 170,
      renderCell: (params) => {
        const value = Number(params.row.combustibleActualPct ?? 0);

        return (
          <Stack sx={{ width: "100%", py: 1 }} spacing={0.4}>
            <Typography variant="caption" fontWeight={700}>
              {Math.max(0, Math.min(100, value))}%
            </Typography>
            <LinearProgress
              variant="determinate"
              value={Math.max(0, Math.min(100, value))}
              color={value < 20 ? "error" : value < 40 ? "warning" : "success"}
              sx={{ height: 7, borderRadius: 999 }}
            />
          </Stack>
        );
      },
    },

    {
      field: "activo",
      headerName: "Estado",
      width: 130,
      renderCell: (params) => (
        <Chip
          label={(params.row.activo ?? true) ? "Activo" : "Inactivo"}
          size="small"
          sx={{
            // 1. Estilos si está Activo
            ...((params.row.activo ?? true) && {
              backgroundColor: "#e8f5e9", // Fondo verde claro
              color: "#2e7d32", // Texto verde oscuro
              border: "1px solid #2e7d32", // Borde verde
            }),
            // 2. Estilos si está Inactivo
            ...(!(params.row.activo ?? true) && {
              backgroundColor: "#ffebee", // Fondo rojo claro
              color: "#c62828", // Texto rojo oscuro
              border: "1px solid #c62828", // Borde rojo
            }),
            fontWeight: "bold", // Estilo común para ambos estados (opcional)
          }}
        />
      ),
    },
    {
      field: "acciones",
      headerName: "Acciones",
      width: 130,
      sortable: false,
      renderCell: (params) => (
        <>
          <Tooltip title="Editar" arrow>
            <IconButton
              color="primary"
              onClick={(event) => {
                event.stopPropagation();
                handleEdit(params.row);
              }}
            >
              <EditIcon />
            </IconButton>
          </Tooltip>

          <Tooltip title={params.row.activo ? "Desactivar" : "Activar"} arrow>
            {params.row.activo ? (
              <IconButton
                color="warning"
                onClick={(event) => {
                  event.stopPropagation();
                  handleDeactivate(params.row);
                }}
              >
                <ToggleOffIcon />
              </IconButton>
            ) : (
              <IconButton
                color="success"
                onClick={(event) => {
                  event.stopPropagation();
                  handleActivate(params.row);
                }}
              >
                <ToggleOnIcon />
              </IconButton>
            )}
          </Tooltip>

          {params.row.itvPendiente ? (
            <Tooltip title="Registrar pago revisión ITV" arrow>
              <IconButton
                color="info"
                onClick={(event) => {
                  event.stopPropagation();
                  handlePayItv(params.row);
                }}
              >
                <FactCheckIcon />
              </IconButton>
            </Tooltip>
          ) : null}
        </>
      ),
    },
  ];

  const openExportMenu = (event) => {
    setExportAnchor(event.currentTarget);
  };

  const closeExportMenu = () => {
    setExportAnchor(null);
  };

  const handleExportExcel = () => {
    exportVehiculosExcel(filteredRows);

    closeExportMenu();
  };

  const handleExportPdf = () => {
    exportVehiculosPdf(filteredRows);

    closeExportMenu();
  };

  const readOnlyFieldSx = {
    "& .MuiInputBase-input": {
      cursor: "default",
      caretColor: "transparent",
      userSelect: "none",
    },
    "& .MuiOutlinedInput-root": {
      backgroundColor: "action.hover",
    },
  };

  return (
    <Box>
      <Typography variant="h4" fontWeight="bold" mb={4}>
        Gestión de Vehículos
      </Typography>
      <Typography color="text.secondary" sx={{ mb: 2 }}>
        Controla la flota de la autoescuela, el estado de los automóviles, las
        revisiones periódicas de la ITV y el mantenimiento.
      </Typography>

      <Box sx={{ display: "flex", gap: 2, mb: 3, flexWrap: "wrap" }}>
        <Button
          variant="contained"
          onClick={() => {
            setEditingId(null);
            resetForm();
            setOpen(true);
          }}
        >
          Nuevo Vehículo
        </Button>

        <RadioGroup
          row
          value={estadoFiltro}
          onChange={(event) => setEstadoFiltro(event.target.value)}
          sx={{ alignItems: "center" }}
        >
          <FormControlLabel
            value="activos"
            control={<Radio />}
            label="Activos"
          />
          <FormControlLabel
            value="inactivos"
            control={<Radio />}
            label="Inactivos"
          />
          <FormControlLabel value="todos" control={<Radio />} label="Todos" />
        </RadioGroup>

        <FormControl size="small" sx={{ minWidth: 220, mt: 0.5 }}>
          <InputLabel>Permiso</InputLabel>
          <Select
            label="Permiso"
            value={permisoFiltro}
            onChange={(event) => setPermisoFiltro(event.target.value)}
          >
            <MenuItem value="all">Todos</MenuItem>
            {PERMISOS.map((permiso) => (
              <MenuItem key={permiso} value={permiso}>
                {permiso}
              </MenuItem>
            ))}
          </Select>
        </FormControl>

        <Button
          variant="outlined"
          startIcon={<DownloadIcon />}
          onClick={openExportMenu}
        >
          Exportar
        </Button>

        <Menu
          anchorEl={exportAnchor}
          open={Boolean(exportAnchor)}
          onClose={closeExportMenu}
        >
          <MenuItem onClick={handleExportExcel}>Exportar a Excel</MenuItem>

          <MenuItem onClick={handleExportPdf}>Exportar a PDF</MenuItem>
        </Menu>
      </Box>

      <Paper sx={{ height: 700, p: 2 }}>
        <DataGrid
          rows={filteredRows}
          columns={columns}
          getRowId={(row) => row.id}
          disableRowSelectionOnClick
          pageSizeOptions={[10, 25, 50]}
          initialState={{
            pagination: { paginationModel: { pageSize: 10, page: 0 } },
            sorting: { sortModel: [{ field: "matricula", sort: "asc" }] },
          }}
          onRowClick={(params) => handleOpenDetail(params.row)}
        />
      </Paper>

      <Dialog
        open={open}
        onClose={() => setOpen(false)}
        fullWidth
        maxWidth="lg"
      >
        <DialogTitle>
          {editingId ? "Editar Vehículo" : "Crear Vehículo"}
        </DialogTitle>

        <DialogContent>
          <Box
            sx={{
              display: "grid",
              gridTemplateColumns: { xs: "1fr", md: "1fr 1.2fr" },
              gap: 3,
              alignItems: "start",
            }}
          >
            <Box sx={{ display: "grid", gap: 2, mt: 2 }}>
              <TextField
                fullWidth
                required
                label="Matrícula"
                placeholder="1234ABC"
                value={nuevoVehiculo.matricula}
                onChange={(e) =>
                  setNuevoVehiculo({
                    ...nuevoVehiculo,
                    matricula: e.target.value.toUpperCase(),
                  })
                }
                InputProps={{
                  sx: {
                    fontSize: "1.05rem",
                    fontWeight: 600,
                    letterSpacing: "0.08em",
                  },
                }}
                InputLabelProps={{
                  shrink: true,
                  sx: {
                    fontSize: "0.9rem",
                  },
                }}
              />

              <TextField
                fullWidth
                label="Marca"
                value={nuevoVehiculo.marca}
                onChange={(e) =>
                  setNuevoVehiculo({
                    ...nuevoVehiculo,
                    marca: e.target.value,
                  })
                }
              />

              <TextField
                fullWidth
                label="Modelo"
                value={nuevoVehiculo.modelo}
                onChange={(e) =>
                  setNuevoVehiculo({
                    ...nuevoVehiculo,
                    modelo: e.target.value,
                  })
                }
              />

              <Select
                fullWidth
                value={nuevoVehiculo.tipoPermiso}
                onChange={(e) =>
                  setNuevoVehiculo({
                    ...nuevoVehiculo,
                    tipoPermiso: e.target.value,
                  })
                }
              >
                {PERMISOS.map((permiso) => (
                  <MenuItem key={permiso} value={permiso}>
                    {permiso}
                  </MenuItem>
                ))}
              </Select>

              <TextField
                fullWidth
                size="small"
                type="date"
                label="Fecha última ITV"
                value={nuevoVehiculo.fechaUltimaItv}
                onChange={(e) =>
                  setNuevoVehiculo({
                    ...nuevoVehiculo,
                    fechaUltimaItv: e.target.value,
                  })
                }
                helperText="Formato: dd/mm/aaaa"
                InputLabelProps={{ shrink: true }}
                slotProps={{
                  inputLabel: { shrink: true },
                }}
              />
            </Box>

            <Box
              sx={{
                minHeight: 320,
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                justifyContent: "center",
                borderRadius: 2,
                backgroundColor: "#f6f6f6",
                p: 2,
                gap: 2,
              }}
            >
              {previewImage && !eliminarImagenActual ? (
                <Box
                  component="img"
                  src={previewImage}
                  alt="Vista previa del vehículo"
                  sx={{
                    width: "100%",
                    maxHeight: 360,
                    objectFit: "contain",
                    borderRadius: 1,
                  }}
                />
              ) : nuevoVehiculo.imagenRuta && !eliminarImagenActual ? (
                <Box
                  component="img"
                  src={buildImageSrc(nuevoVehiculo.imagenRuta)}
                  alt="Imagen del vehículo"
                  sx={{
                    width: "100%",
                    maxHeight: 360,
                    objectFit: "contain",
                    borderRadius: 1,
                  }}
                />
              ) : (
                <Typography variant="body2" color="text.secondary">
                  {editingId
                    ? "No hay imagen asociada actualmente."
                    : "Aún no has añadido ninguna imagen."}
                </Typography>
              )}

              <Box
                sx={{
                  display: "flex",
                  flexWrap: "wrap",
                  gap: 1.5,
                  justifyContent: "center",
                }}
              >
                <Button
                  component="label"
                  variant="outlined"
                  startIcon={<CloudUploadIcon />}
                  sx={{
                    minWidth: 170,
                    borderRadius: 2.5,
                    textTransform: "none",
                    fontWeight: 700,
                    background:
                      "linear-gradient(135deg, #ffffff 0%, #edf6ff 100%)",
                    borderColor: "#1e88e5",
                    color: "#1565c0",
                    boxShadow: "0 2px 8px rgba(30,136,229,0.12)",
                    px: 2,
                    py: 1,
                    "&:hover": {
                      background:
                        "linear-gradient(135deg, #eef7ff 0%, #dfefff 100%)",
                      borderColor: "#1565c0",
                    },
                  }}
                >
                  {imagenFile || previewImage || nuevoVehiculo.imagenRuta
                    ? "Cambiar imagen"
                    : "Añadir imagen"}
                  <input
                    type="file"
                    hidden
                    accept=".png,.jpg,.jpeg,.webp"
                    onChange={handleFileChange}
                  />
                </Button>

                {editingId && (previewImage || nuevoVehiculo.imagenRuta) ? (
                  <Button
                    variant={eliminarImagenActual ? "contained" : "contained"}
                    color={eliminarImagenActual ? "warning" : "error"}
                    startIcon={
                      eliminarImagenActual ? (
                        <UndoIcon />
                      ) : (
                        <DeleteForeverIcon />
                      )
                    }
                    onClick={handleToggleEliminarImagen}
                    sx={{
                      minWidth: 185,
                      borderRadius: 2.5,
                      textTransform: "none",
                      fontWeight: 700,
                      background: eliminarImagenActual
                        ? "linear-gradient(135deg, #ffb300 0%, #ff8f00 100%)"
                        : "linear-gradient(135deg, #ff9800 0%, #f57c00 100%)",
                      boxShadow: "0 8px 18px rgba(245, 124, 0, 0.24)",
                      px: 2,
                      py: 1,
                      "&:hover": {
                        filter: "brightness(1.03)",
                      },
                    }}
                  >
                    {eliminarImagenActual
                      ? "Deshacer eliminación"
                      : "Eliminar imagen"}
                  </Button>
                ) : null}
              </Box>

              <Typography variant="caption" display="block">
                Formatos: PNG, JPG/JPEG, WEBP. Tamaño máximo: 5 MB.
              </Typography>

              {eliminarImagenActual ? (
                <Typography
                  variant="caption"
                  color="warning.main"
                  display="block"
                >
                  La imagen actual se eliminará al guardar.
                </Typography>
              ) : null}
            </Box>
          </Box>
        </DialogContent>

        <DialogActions>
          <Button onClick={() => setOpen(false)}>Cancelar</Button>
          <Button variant="contained" onClick={saveVehiculo}>
            {editingId ? "Actualizar" : "Guardar"}
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog
        open={openDetail}
        onClose={() => setOpenDetail(false)}
        fullWidth
        maxWidth="lg"
      >
        <DialogTitle>Detalle del Vehículo</DialogTitle>

        <DialogContent>
          {loadingDetail ? (
            <Box sx={{ display: "flex", justifyContent: "center", py: 4 }}>
              <CircularProgress />
            </Box>
          ) : (
            <Box
              sx={{
                display: "grid",
                gridTemplateColumns: { xs: "1fr", md: "1fr 1.2fr" },
                gap: 3,
                alignItems: "start",
              }}
            >
              <Box sx={{ display: "grid", gap: 2, mt: 2 }}>
                <TextField
                  label="Matrícula"
                  value={selectedVehiculo?.matricula || ""}
                  InputProps={{
                    readOnly: true,
                    sx: {
                      fontSize: "1.05rem",
                      fontWeight: 600,
                      letterSpacing: "0.08em",
                    },
                  }}
                  InputLabelProps={{
                    shrink: true,
                    sx: {
                      fontSize: "0.9rem",
                    },
                  }}
                  sx={readOnlyFieldSx}
                  fullWidth
                />

                <TextField
                  label="Marca"
                  value={selectedVehiculo?.marca || ""}
                  InputProps={{
                    readOnly: true,
                    tabIndex: -1,
                  }}
                  sx={readOnlyFieldSx}
                  fullWidth
                />

                <TextField
                  label="Modelo"
                  value={selectedVehiculo?.modelo || ""}
                  InputProps={{
                    readOnly: true,
                    tabIndex: -1,
                  }}
                  sx={readOnlyFieldSx}
                  fullWidth
                />

                <TextField
                  label="Permiso"
                  value={selectedVehiculo?.tipoPermiso || ""}
                  InputProps={{
                    readOnly: true,
                    tabIndex: -1,
                  }}
                  sx={readOnlyFieldSx}
                  fullWidth
                />

                <TextField
                  label="Combustible"
                  value={`${Math.max(Number(selectedVehiculo?.combustibleActualPct || 0), 0)}%`}
                  InputProps={{
                    readOnly: true,
                    tabIndex: -1,
                  }}
                  sx={readOnlyFieldSx}
                  fullWidth
                />

                <TextField
                  label="Número de clases realizadas"
                  value={Number(selectedVehiculo?.numeroClasesRealizadas || 0)}
                  InputProps={{
                    readOnly: true,
                    tabIndex: -1,
                  }}
                  sx={readOnlyFieldSx}
                  fullWidth
                />

                <TextField
                  label="Fecha última ITV"
                  value={formatDateLabel(selectedVehiculo?.fechaUltimaItv)}
                  InputProps={{
                    readOnly: true,
                    tabIndex: -1,
                  }}
                  sx={readOnlyFieldSx}
                  fullWidth
                />

                <TextField
                  label="Estado"
                  value={selectedVehiculo?.activo ? "Activo" : "Inactivo"}
                  InputProps={{
                    readOnly: true,
                    tabIndex: -1,
                  }}
                  sx={readOnlyFieldSx}
                  fullWidth
                />
              </Box>

              <Box
                sx={{
                  minHeight: 320,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  borderRadius: 2,
                  backgroundColor: "#f6f6f6",
                  p: 1.5,
                }}
              >
                {selectedVehiculo?.imagenRuta ? (
                  <Box
                    component="img"
                    src={buildImageSrc(selectedVehiculo.imagenRuta)}
                    alt={`Vehículo ${selectedVehiculo?.matricula || ""}`}
                    sx={{
                      width: "100%",
                      maxHeight: 460,
                      objectFit: "contain",
                      borderRadius: 1,
                    }}
                  />
                ) : (
                  <Typography variant="body2" color="text.secondary">
                    Este vehículo no tiene imagen asociada.
                  </Typography>
                )}
              </Box>
            </Box>
          )}
        </DialogContent>

        <DialogActions>
          <Button
            variant="contained"
            onClick={() => {
              if (selectedVehiculo) {
                handleEdit(selectedVehiculo);
              }
            }}
            disabled={!selectedVehiculo || loadingDetail}
          >
            Editar vehículo
          </Button>
          <Button onClick={() => setOpenDetail(false)}>Cerrar</Button>
        </DialogActions>
      </Dialog>

      <Dialog
        open={confirmDialog.open}
        onClose={closeConfirmDialog}
        fullWidth
        maxWidth="xs"
      >
        <DialogTitle>{confirmDialog.title}</DialogTitle>

        <DialogContent>
          <DialogContentText>{confirmDialog.message}</DialogContentText>
        </DialogContent>

        <DialogActions>
          <Button onClick={closeConfirmDialog}>Cancelar</Button>

          <Button
            variant="contained"
            color={confirmDialog.action === "deactivate" ? "error" : "success"}
            onClick={handleConfirmAction}
          >
            Confirmar
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog
        open={deactivateModal.open}
        onClose={deactivateModal.loading ? () => {} : closeDeactivateModal}
        fullWidth
        maxWidth="md"
      >
        <DialogTitle>
          Reasignación obligatoria para desactivar vehículo
        </DialogTitle>
        <DialogContent sx={{ display: "grid", gap: 2, pt: 1 }}>
          <DialogContentText>
            Debes reasignar todas las clases futuras/en curso antes de finalizar
            la desactivación del vehículo
            {` ${deactivateModal.vehiculo?.matricula || ""}`}. Para clases en
            curso también debes informar kilometraje y combustible del vehículo
            de reemplazo.
          </DialogContentText>

          {deactivateModal.clasesAfectadas.map((clase) => {
            const item = reasignacionesDeactivacion[clase.claseId] || {};

            return (
              <Box
                key={clase.claseId}
                sx={{
                  border: "1px solid",
                  borderColor: "divider",
                  borderRadius: 1,
                  p: 2,
                  display: "grid",
                  gap: 1.5,
                }}
              >
                <Typography variant="body2" fontWeight={700}>
                  Clase {new Date(clase.fecha).toLocaleString("es-ES")} |
                  Alumno: {clase.alumnoNombre} | Permiso: {clase.permiso}
                  {clase.enCurso ? " | EN CURSO" : ""}
                </Typography>

                <FormControl fullWidth size="small">
                  <InputLabel>Nuevo vehículo</InputLabel>
                  <Select
                    label="Nuevo vehículo"
                    value={item.nuevoVehiculoId || ""}
                    onChange={(event) =>
                      setReasignacionesDeactivacion((prev) => ({
                        ...prev,
                        [clase.claseId]: {
                          ...prev[clase.claseId],
                          nuevoVehiculoId: event.target.value,
                        },
                      }))
                    }
                  >
                    {clase.opciones.map((opcion) => (
                      <MenuItem key={opcion.id} value={opcion.id}>
                        {opcion.matricula} - {opcion.marca || ""}{" "}
                        {opcion.modelo || ""}
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>

                {clase.enCurso ? (
                  <Box
                    sx={{
                      display: "grid",
                      gridTemplateColumns: "1fr 1fr",
                      gap: 1.5,
                    }}
                  >
                    <TextField
                      size="small"
                      label="Km nuevo vehículo"
                      type="number"
                      value={item.kmActualesNuevoVehiculo || ""}
                      onChange={(event) =>
                        setReasignacionesDeactivacion((prev) => ({
                          ...prev,
                          [clase.claseId]: {
                            ...prev[clase.claseId],
                            kmActualesNuevoVehiculo: event.target.value,
                          },
                        }))
                      }
                    />
                    <TextField
                      size="small"
                      label="Combustible nuevo vehículo (%)"
                      type="number"
                      value={item.combustibleActualPctNuevoVehiculo || ""}
                      onChange={(event) =>
                        setReasignacionesDeactivacion((prev) => ({
                          ...prev,
                          [clase.claseId]: {
                            ...prev[clase.claseId],
                            combustibleActualPctNuevoVehiculo:
                              event.target.value,
                          },
                        }))
                      }
                    />
                  </Box>
                ) : null}
              </Box>
            );
          })}
        </DialogContent>
        <DialogActions>
          <Button
            onClick={closeDeactivateModal}
            disabled={deactivateModal.loading}
          >
            Cancelar
          </Button>
          <Button
            variant="contained"
            color="error"
            onClick={handleConfirmDeactivateWithReassignment}
            disabled={deactivateModal.loading}
          >
            {deactivateModal.loading ? "Guardando..." : "Guardar y desactivar"}
          </Button>
        </DialogActions>
      </Dialog>

      <Snackbar
        open={notification.open}
        autoHideDuration={4000}
        onClose={() => setNotification({ ...notification, open: false })}
        anchorOrigin={{ vertical: "top", horizontal: "right" }}
      >
        <Alert
          severity={notification.severity}
          variant="filled"
          onClose={() => setNotification({ ...notification, open: false })}
        >
          {notification.message}
        </Alert>
      </Snackbar>
    </Box>
  );
}
